{"assumptions":[],"created_at":"2026-10-27T10:52:57.734875+00:00","domain":"probability theory","id":"claim_02f0dc2aa6bfd7e4182c82fb7aeb04d3db182eae254d2f0a7a4bf56490fd327b","kind":"definition","schema_version":1,"statement":"[Definition 21 of arXiv:2609.02755, 'The Sharp Rate of Probabilistically Strong Convergence to the KPZ Equation'] We define the linear map $\tilde\Delta^\partial : \scal{\tcT} \to \scal{\tcT} \otimes \scal{\tcT_1}$ recursively via
	\begin{align*}
		&\tilde \Delta^\partial \<bs(2)0> = \<s(1)0> \otimes \partial \, \<b1> + \<b1> \otimes \partial \, \<s(1)0>, \qquad && \tilde \Delta^\partial \<ps(2)0> = \<s(1)0> \otimes \partial \, \<p1> + \<p1> \otimes \partial \, \<s(1)0>,
		\\
		&\tilde \Delta^\partial \<b0> = 0, \qquad &&\tilde \Delta^\partial \<p0> = 0,
		\\
		& \tilde \Delta^\partial \<s(1)0> = \mathbf{1} \otimes \partial \, \<s(1)0>, \qquad && \tilde \Delta^\partial X^k = 0,
		\\
		&\tilde \Delta^\partial \tau \sigma = \tilde \Delta^\partial \tau \tilde \Delta \sigma + \tilde \Delta \tau \tilde \Delta^\partial \sigma,
		\\
		&\tilde \Delta^\partial \mcI_\mfl^k \tau = (\mcI_\mfl^k \otimes \id) \tilde \Delta^\partial \tau + \sum_{|j|_\mfs < o(\mcI_\mfl^k \tau) } \frac{X^j}{j!} \otimes \mcI_{(\mfl, \partial)}^{k+j} \tau.
	\end{align*}
	For each $x,y \in \mbR^d$, we also define a linear map ${\chi}_x^y : \langle \tcT_1 \rangle \to \mbR$ as follows. For each $\mfl \in \mfL_+, \mft \in \mfL_-$ we set
	\begin{align*}
		\chi_z^{z'} (\mcI_{(\mfl, \partial)}^k \sigma) &= k! \mcQ_{X^k} [ J^\mfl(z') H_{\sigma; \eps, \delta}^{z, g}(z') + \mathcal{N}_{\gamma_{\sigma}}^{\mfl} H_{\sigma; \eps, \delta}^{z, g}(z')] 
		\\
		& \qquad - \sum_{|l|_\mfs < |\mcI_{\mfl}^k \sigma|_\mfs} \frac{(z'-z)^l}{l!} D^{k+l} K_\mfl \ast \mcR H_{\sigma; \eps, \delta}^{z, g}(z).
	\end{align*}
	We also define
	\begin{align*}
		\chi_z^{z'}(\Xi_{(\mft, \partial)}) &= \begin{cases}
			g_\eps(z') \qquad & \text{ if } \mft = \<b0>,
			\\
			g_{\delta}(z') \qquad & \text{ if } \mft = \<p0>,
			\\
			\eps^{-1/2} \partial_x K \ast g_{\eps, \delta}(z') \qquad & \text{ if } \mft = \<s(1)0>.
		\end{cases}
	\end{align*}
	Finally, we extend this definition by declaring that for $\eta \in \mcT_+$ we have
	\begin{align*}
		\chi_z^{z'}(\mcI_{(\mfl, \partial)}^k \sigma \cdot \eta) = \chi_z^{z'}(\mcI_{(\mfl, \partial)}^k \sigma) \cdot \gamma_{z'z}(\eta)
	\end{align*}
	where $\gamma_{z'z}$ is the element of $\mathcal{G}_+$ corresponding to $\Gamma_{z'z}$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:45:02.037143+00:00","domain":"probability theory","id":"claim_02f2c34bd4347fcd4ecab5f08ffc16959d24706c53ad3313bf5e3848ea0fae0c","kind":"definition","schema_version":1,"statement":"[Defn of arXiv:2601.00119, 'The largest common subtree of two random trees'] Let $\mu$ be a measure on $\mathbb{N}$. A random plane tree $\tau$ is called a \emph{Bienaym\'{e} tree with offspring distribution $\mu$} if it satisfies the following properties:
\begin{enumerate}
    \item[(a)] The law of $\mathrm{k}_\varnothing(\tau)$ is $\mu$.
    \item[(b)] For all $k \geq 1$ such that $\mu(k) > 0$, conditionally given that $\mathrm{k}_\varnothing(\tau) = k$, the subtrees $\theta_1\tau,...,\theta_k\tau$ are i.i.d.~and with the same law as $\tau$.
\end{enumerate}
We frequently call (b) \emph{the branching property} of Bienaymé trees. If $\sum_{k \geq 0} k\mu(k) = 1$ and $\mu(0) > 0$, then we call $\tau$ and $\mu$ \emph{critical}, and it is well-known that $\tau$ is almost surely finite.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:48:43.520276+00:00","domain":"probability theory","id":"claim_02fa20597a16b375bdbe4023d6df6e4a1e97c535e09d5c9619a1ea73b3ac970a","kind":"concept","schema_version":1,"statement":"[Proposition 2 of arXiv:2608.06646, 'Three-dimensional stochastic wave equation with non-Lipschitz coefficients'] Assume that $b$ and $\sigma$ are globally Lipschitz with Lipschitz constants $L_b$ and $L_\sigma$, respectively. Assume further that the initial condition $u_0$ is bounded with bounded derivatives and that $v_0$ is bounded. Under assumption~\eqref{E:ZeroOrderDifference}, there exists a unique random field solution $u$ to the stochastic wave equation~\eqref{E:SWE} such that, for all $p\ge 2$ and $T>0$,
    \begin{equation} 
        \sup_{(t,x)\in [0,T]\times \mathbb{R}^3}\mathbb{E}|u(t,x)|^p
        \le (3M)^{\frac{p}{2}} e^{cp\beta_0 T}.
    \end{equation}
    Here 
    \begin{equation}
    M=3\lr{T\|v_0\|_{L^\infty(\R^3)}+\|u_0\|_{L^\infty(\R^3)}+T\|\nabla u_0\|_{L^\infty(\R^3)}}^2 +Cp|\sigma(0)|^2\frac{T^{\nu+1}}{\nu+1}+C|b(0)|^2T^4\,,
\end{equation}

  and 
  $\beta_0 = C L_b^{1/2} + C p^{1/(\nu+1)} L_\sigma^{2/(\nu+1)}$, and the parameter $\nu$ is defined in~\eqref{E:ZeroOrderDifference}. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:35:10.795489+00:00","domain":"probability theory","id":"claim_02fd3993776542ab81cf4b7986f445efd2d64efd263c2ca35a5ca5dcfca2fd02","kind":"lemma","schema_version":1,"statement":"[Lemme 43 of arXiv:2604.00635, 'Large deviations of the periodic Toda chain'] Let $p \in \mathbb{N}$, $0 < \eps \leq \frac{1}{2}$ $\kappa>0$, let $V$ satisfy \ref{potentialh1} and \ref{potentialh2} and let $W$
be as introduced in \eqref{Wchoice}. 
Then, there exists $C>0$ such that the $N$-fold integral introduced in \eqref{definition integrale BN contrainte}
admits the upper bound $B_{N, \mathsf{c}}^{(p)}[W+\tfrac{\kappa}{4}V]\,  \leq \,  \mathrm{e}^{ C N^{ \frac{7}{8} }  }$ for $N$ large enough. This $C$ may depend on $p$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T02:04:40.964372+00:00","domain":"probability theory","id":"claim_0301d2f75636ddd91fe641238d6c80f0951a839cb0a84dd8a7ad00b21c6aebaf","kind":"concept","schema_version":1,"statement":"[Theorem T:L2Lim of arXiv:2412.03521, 'On ergodic properties of stochastic PDEs'] Suppose that conditions~(it:i-InvMea of the paper) and~(it:iii-InvMea of the paper) of
  Theorem~(T:InvMea of the paper) hold. Let the following condition~(it:ii'-InvMea of the paper)
  replace condition~(it:ii-InvMea of the paper) of Theorem~(T:InvMea of the paper):

  \begin{enumerate}[wide, labelwidth=!, labelindent=0pt, label=\emph{(\roman*')}]
    \setcounter{enumi}{1}
    \setlength\itemsep{.1in}

    \item For $t \ge 0$, $x \in \mathbb{R}$ and a Borel measure
      $\mu$ on $\mathbb{R}^d$, let $J_0(t,x;\mu)$ be the solution to the homegenous
      equation (see~(equation E:def-J0 of the paper)). We assume that the following limit
      exists:
      \begin{align}
        \lim_{t\to\infty} \sup_{x\in\mathbb{R}^d} \left| J_0(t,x;\mu)\right| <\infty.
      \end{align}

  \end{enumerate}

  \noindent We also assume that the nonnegative weight function $\rho$ is an
  element in $L^1(\mathbb{R}^d)$, which does not necessarily need to be admissible (see
  Definition~(D:Rho of the paper)). Recall that $u(t,\cdot)$ is the solution
  to~(equation E:SHE of the paper). Then the following existence and uniqueness statements hold:

  \begin{enumerate}[wide, labelwidth=!, labelindent=0pt, label=\emph{(\arabic*)}]
    \setlength\itemsep{.1in}

    \item There exists a random field $Z=\{Z(x);\;x\in\mathbb{R}^d\}$
      such that $Z(\cdot)\in L_\rho^2(\mathbb{R}^d)$ a.s. and
      \begin{equation}
        u(t,\cdot) \stackrel{\text{(d)}}{\longrightarrow} Z,
          \quad \text{as $t\to\infty$,}
          \quad \text{in $L_\rho^2(\mathbb{R}^d)$.}
      \end{equation}

    \item Suppose $u_1$ and $u_2$ are two solutions
      to~(equation E:SHE of the paper) starting from $\mu_1$ and $\mu_2$, respectively. Assume
      that both $\mu_i$ satisfy~(equation E:InitData-Limit of the paper). Let $Z_1$ and $Z_2$ be
      the respective limiting random fields given in part~(it:L2Lim-1 of the paper). Then
