{"assumptions":[],"created_at":"2026-10-27T06:06:21.751381+00:00","domain":"probability theory","id":"claim_0379db9f2a8e67ce052f8e3150034610949a1f0fb44c5cb1a77240edc0889f33","kind":"lemma","schema_version":1,"statement":"[Lemma 49 of arXiv:2607.21374, 'Local structure at the maximum and sharp persistence asymptotics of rough fractional Brown'] Let \(F\subset(0,\infty)\cap\mathbb D\) be finite and nonempty, let
\(x\geq0\), and put
\begin{equation}
  \begin{aligned}
    Q_{F,x}
    &:=\mathcal L(G\mid G_s\geq-x,\ s\in F),\\
    g_{F,x}(t)&:=\EE_{Q_{F,x}}G_t,
    &\qquad
    Z_{F,x}(t)&:=G_t-g_{F,x}(t).
  \end{aligned}

\end{equation}
There are coefficients \(\lambda_{F,x}(s)\geq0\), \(s\in F\), such that
\begin{equation}
  g_{F,x}(t)
  =\sum_{s\in F}\lambda_{F,x}(s)K_H(t,s).

\end{equation}
Uniformly in \(F\) and \(x\geq0\),
\begin{equation}
  0\leq g_{F,x}(t)\leq g_{F,0}(t)\leq C_H|t|^H,
  \qquad t\in\mathbb R.

\end{equation}
For every \(0<a<R<\infty\), there is \(C_{H,a,R}<\infty\) such that
\begin{equation}
  |g_{F,x}(t)-g_{F,x}(s)|
  \leq C_{H,a,R}|t-s|^{2H},
  \qquad s,t\in[a,R].

\end{equation}
Consequently, for every \(R<\infty\),
\begin{equation}
  \lim_{\delta\downarrow0}\sup_{F,x}
  \sup_{\substack{s,t\in[0,R]\\|s-t|\leq\delta}}
  |g_{F,x}(t)-g_{F,x}(s)|=0,

\end{equation}
and, for every \(\varepsilon>0\),
\begin{equation}
  \lim_{\delta\downarrow0}\sup_{F,x}
  Q_{F,x}\left(
    \sup_{\substack{s,t\in[0,R]\\|s-t|\leq\delta}}
    |Z_{F,x}(t)-Z_{F,x}(s)|>\varepsilon
  \right)=0.

\end{equation}

For \(T>0\) and \(x>0\), these bounds pass to
\begin{equation}
  \mathbb P_{T,x}
  =\mathcal L(B\mid M_T\leq x)

\end{equation}
by dense finite-grid hard-wall approximation.  In particular, for every
\(A,R<\infty\), the laws of \(x-B\) on \(C([0,R])\), under
\(\mathbb P_{T,x}\) with \(T\geq R\) and \(0<x\leq A\), are tight uniformly
in \(T\) and \(x\).","status":"unverified"}

