    		e^{- t  c _i } 
    		\prod_{j = 0 \atop j \ne i}^\infty 
				\frac{ c _{j}}{ c _{j}- c _{i}}
			=
				o( e^{ - t  c _n } )
		,
			\qquad
			t \to \infty

