{"assumptions":[],"created_at":"2026-10-26T19:34:09.923946+00:00","domain":"probability theory","id":"claim_054244f78ba3681c340daf1e0d53633855991a8a7f5e1297f3726667bef430bb","kind":"concept","schema_version":1,"statement":"[Thm 1 of arXiv:2603.27433, 'The $k$-cycle shuffling with repeated cards'] Let $(n_N)_{N\ge 1},(k_N)_{N\ge 1}$, and $(t_N)_{N\ge 1}$ be sequences of positive integers, such that $\lim_{N\rightarrow\infty}n_N=\infty$. For all $N\ge 1$, let $t'_N:=t_N-\frac{n_N\log n_N}{k_N}$. Also, let $P_{n_N,k_N}^{*t_N}$ be defined as in \Cref{defi: Pnk and its convolution}, and $\nu_{n_N,k_N}^{t_N}$ be defined as in \Cref{defi: construction of nu}. 
\begin{enumerate}
\item Suppose that 
\begin{enumerate}
\item $k_N\ge 2$ for all $N\ge 1$, and $\lim_{N\rightarrow\infty}\frac{k_N\log n_N}{n_N}=0$.
\item $t_N'=cn_N/k_N$, where $c\in\R$ is an absolute constant.
\end{enumerate}
Then, we have
$$\lim_{N\rightarrow\infty}d_{TV}(P_{n_N,k_N}^{*t_N},\nu_{n_N,k_N}^{t_N})=0.$$ 

\item Suppose that 
\begin{enumerate}
\item $k_N\ge 2$ for all $N\ge 1$, and $\limsup_{N\rightarrow\infty}\log_{n_N}k_N\le c_0$, where $c_0\in[0,1)$ is an absolute constant.
\item $\lim_{N\rightarrow\infty}\log\log n_N-|2k_Nt_N'/n_N|=+\infty$.
\end{enumerate}
Then, we have
$$\limsup_{N\rightarrow\infty}\log_{n_N}d_{TV}(P_{n_N,k_N}^{*t_N},\nu_{n_N,k_N}^{t_N})\le c_0-1.$$

\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T09:36:31.233540+00:00","domain":"probability theory","id":"claim_05455424e5ee00864df6e5fb6a9969e8f0c38475347d81f78961ebf331a6429c","kind":"definition","schema_version":1,"statement":"[Definition 7 of arXiv:2609.00567, 'Hodge--Tate splitting and Akizuki--Nakano vanishing in positive characteristic'] Consider a pullback square of stacks
  \begin{equation*}
    \begin{tikzcd}
