{"assumptions":[],"created_at":"2026-10-26T19:41:33.838079+00:00","domain":"probability theory","id":"claim_07206301cef2404b1f9fd9b7bc2aad6e2c7b2d73d9c3ff91838cba745cc83d69","kind":"concept","schema_version":1,"statement":"[Lem 12 of arXiv:2604.11489, '2604.11489'] \cite{C-M}
