{"assumptions":[],"created_at":"2026-10-26T19:17:42.305474+00:00","domain":"probability theory","id":"claim_0ec97b5456a320c111c8ad56dad08270e01a501a2683b61f30e4199a2280f670","kind":"concept","schema_version":1,"statement":"[Prop 64 (Bounds for Uniform integrability) of arXiv:2510.22155, 'Random walks in space-time random media in all spatial dimensions: the full subcritical fl'] Fix $f:I\to \mathbb R$ of exponential decay at infinity.  
\begin{enumerate}


\item 
We have a bound uniform over all $N\ge 1$, all initial conditions $   a_1,   a_2\in I$ and all $  {\boldsymbol{v}}$ in some neighborhood of the origin of $\mathbb R^d$:
\begin{multline}
    \left| N^{\frac{d-2}{2}}\sum_{s=0}^{Nt}\frac1{m!} \mathbf E^{(  {\boldsymbol{v}},2)}_{(   a_1,   a_2)} \bigg[ \bigg(\sum_{r=0}^{s-1}\boldsymbol u_{  {\boldsymbol{v}}}(   R^1_{r}-   R^2_{r})\bigg)^m  \phi \big(N^{-1/2} (   R^1_{s} - N^{-1}   d_Ns)\big)\cdot f(    R^1_{s}-   R^2_{s})\bigg]\right| \\\leq 
    \begin{cases}
      C^m \|\phi\|_{L^\infty} |  {\boldsymbol{v}}|^{2pm}\frac{(Nt)^{\frac{m}{2}}}{(m/2)!} & d=1  \\
      C^m \|\phi\|_{L^\infty}|  {\boldsymbol{v}}|^{2pm}  (\log Nt)^{2pm} \left[ 1+\big|\log \left(\frac{Nt}{  1+|a_1-a_2|^2}\right)\big|\right]  & d=2\\
      C^m \|\phi\|_{L^\infty}  |  {\boldsymbol{v}}|^{2pm}  \big(N^{-1/2} (1+|a_1-a_2|)\big)^{2-d} & d\ge 3\\
    \end{cases}
\end{multline}
Here $C$ is an absolute constant not depending on $v,t,m,\phi, a_1,a_2$.

\item Summing \eqref{geombound} over $m\in\mathbb Z_{\ge 0}$, we have a bound uniform over all $N\ge 1$, all initial conditions $   a_1,   a_2\in I$ and all $  {\boldsymbol{v}}$ in some neighborhood of the origin of $\mathbb R^d$:
\begin{multline}
\left| N^{\frac{d-2}{2}}\sum_{s=0}^{Nt} \mathbf E^{(  {\boldsymbol{v}},2)}_{(   a_1,   a_2)} \bigg[ e^{\sum_{r=0}^{s-1}\boldsymbol u_{  {\boldsymbol{v}}}(   R^1_{r}-   R^2_{r})}  \phi \big(N^{-1/2} (   R^1_{s} - N^{-1}   d_Ns)\big)\cdot f(    R^1_{s}-   R^2_{s})\bigg]\right| \\\leq 
    \begin{cases}
      C\|\phi\|_{L^\infty} e^{N |  {\boldsymbol{v}}|^{4p} t} & d=1  \\
      \frac{C\|\phi\|_{L^\infty}}{1-C|  {\boldsymbol{v}}|^{2p}\log Nt}   \left[ 1+\big|\log \left(\frac{Nt}{  1+|a_1-a_2|^2}\right)\big|\right] & d=2\\
     \frac{C\|\phi\|_{L^\infty}}{1-C|  {\boldsymbol{v}}|^{2p}}  \left(N^{-1/2} (1+|a_1-a_2|)\right)^{2-d}  & d\ge 3\\
      \end{cases}
\end{multline}
The right side should be understood to be infinite if the denominator is non-positive. Here $C$ is an absolute constant not depending on $v,t,m,\phi, a_1,a_2$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T17:18:19.443695+00:00","domain":"probability theory","id":"claim_0ec9cc1babb4a7234e3c322d0312e14c687967b08661baacd83078b77bb7cfe7","kind":"definition","schema_version":1,"statement":"[Definition def:wishart of arXiv:2508.17838, '\bf Edge Universality for Inhomogeneous Random Matrices'] Let \(M\le N\) and  $\alpha = {M}/{N}$ where $M$ may depend on $N$, define   
\begin{equation} 
H_N \;=\; \Sigma_N \circ W_N,
\end{equation} as an inhomogeneous Wishart  matrix  and the corresponding additive perturbation (namely, signal-plus-noise matrices)   \begin{equation}
X_N \;=\; (H_N + A_N)\,(H_N + A_N)^*.
\end{equation}
where \(W_N=(W_{ij})\) is an \(M\times N\) random matrix with real or complex   entries  and \(\Sigma_N=(\sigma_{ij})\) is a deterministic  \(M\times N\)  matrix  with nonnegative entries. 
Precisely, the following assumptions hold:

\begin{enumerate}[leftmargin=*,label=(C\arabic*)]
  \item \textbf{(Entry moment)}  
 The entries $\{W_{ij}\}_{i,j=1}^N$ are independent, symmetric, and satisfy
 \begin{equation}
      \begin{cases}
       \mathbb{E}[W_{ij}^2]=1, & \text{real 
        case},\\
        \mathbb{E}[|W_{ij}|^2]=1,\;\mathbb{E}[W_{ij}^2]=0, & \text{complex 
        case}.
      \end{cases}
    \end{equation} 
    and for some \(\theta\ge1\) and all integers \(k\ge2\),
    \begin{equation}
      \mathbb{E}[|W_{ij}|^{2k}]
      \;\le\;
      \theta^{\,k-1}(2k-1)!!,
    \end{equation}
  where   \(\theta=\theta_N\to\infty\)  may be allowed  if needed.

  \item \textbf{(Variance profile)}  
    The profile matrix \(\Sigma_N=(\sigma_{ij})\) satisfies
    \begin{equation}
      \sum_{j=1}^N \sigma_{ij}^2 = 1
      \quad(\forall\,i\in[M]),
      \qquad
      \sum_{i=1}^M \sigma_{ij}^2 = \alpha
      \quad(\forall\,j\in[N]).
    \end{equation}
    Equivalently, the bipartite transition matrix on \(S=[M]\sqcup[N]\) is
    \begin{equation}
      P_{S}
      = \begin{pmatrix}
          0 & (\sigma_{ij}^2)_{M\times N} \\
          \alpha^{-1}(\sigma_{ij}^2)_{N\times M}^T & 0
        \end{pmatrix}.
    \end{equation}

  \item \textbf{(Rank-\(r\) perturbation)}  
    The deterministic matrix \(A_N\) admits a decomposition
\begin{equation}
    A_N = Q_1\,\Lambda\,Q_2^*, 
    \quad 
    \Lambda = \big( \mathrm{diag}(a_1,\dots,a_r, \underbrace{0,\dots,0}_{M-r}), \; 0_{M \times (N-M)} \big),
\end{equation}
where \(Q_1\) and \(Q_2\) are orthogonal (or unitary) matrices of size \(M\) and \(N\), respectively, and \(\underbrace{0,\dots,0}_{M-r}\) denotes the \(M-r\) zeros in the diagonal block.
     Moreover, for some fixed $\tau>0$, 
    \begin{equation}
      \|A_N\|_{\mathrm{op}}
      \;\le\;
      \sqrt{\alpha} \;+\;\tau\,N^{-1/3}.
    \end{equation}
\end{enumerate}
When  \(W_N\) has i.i.d.\ Gaussian entries,   the resulting model is denoted  by \(\widetilde X_N\) with \(\beta=1,2\).","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:39:41.443071+00:00","domain":"probability theory","id":"claim_0ed06a6285cb5cff5a9500a0cfb586f6de160a844d4d3b105e4333283eab7e4c","kind":"concept","schema_version":1,"statement":"[Lemma 22 of arXiv:2604.07478, 'Mixing Times and Cutoff for the Rook's Walk'] Let $n,d$ be any parameters for the Rook's Walk. Then for $\epsilon\in(0,1)$,
   \[t_\text{mix}(\epsilon) \geq \frac{d(n-1)}{2n} \log d + c_l(\epsilon) \frac{d(n-1)}{n}\]
   where $c_l(\epsilon)$ is a constant dependent only on $\epsilon$.
   \begin{proof}
     Firstly, consider the lower bound from Theorem \ref{main1},
      \[t_\text{mix}(\epsilon) \geq \underbrace{\left(\log \left(\frac{d(n-1)}{2n}\right) + \log\left(\frac{1-\epsilon}{\epsilon}\right)\right)}_\mathbf{A} \underbrace{\left(2\log\left(\frac{d(n-1)}{d(n-1)-n}\right)\right)^{-1}}_\mathbf{B}\]
      We proceed by bounding $\mathbf{A}$ and $\mathbf{B}$ separately.
      \begin{align*}
         \mathbf{A} &:=  \log \left(\frac{d(n-1)}{2n}\right) + \log\left(\frac{1-\epsilon}{\epsilon}\right)\\
         &=  \log(d/2) + \log\left(\frac{n-1}{n}\right)+\log\left(\frac{1-\epsilon}{\epsilon}\right)\\
         &\geq  \log(d/2) + \log\left(\frac{1-\epsilon}{\epsilon}\right)+1
      \end{align*}
      \begin{align*}
         \mathbf{B} &:= \left(2\log\left(\frac{d(n-1)}{d(n-1)-n}\right)\right)^{-1}\\
         \frac{1}{2\mathbf{B}} &= \log\left(\frac{d(n-1)}{d(n-1)-n}\right)\\
         \frac{1}{2\mathbf{B}} &= -\log\left(\frac{d(n-1)-n}{d(n-1)}\right)\\
         \frac{1}{2\mathbf{B}} &= -\log\left(1 - \xi\right)\tag{Using $\xi:=\frac{n}{d(n-1)}$}
      \end{align*}
      Now, recall the Taylor expansions of $-\log(1-\xi)$ and $\frac{\xi}{1-\xi}$ around zero for $\xi\in (0,1)$,
      \[-\log(1-\xi) = \sum_{k=1}^\infty \frac{\xi^k}{k} \quad \text{and} \quad \frac{\xi}{1-\xi} = \sum_{k=1}^\infty \xi^k \]
      Therefore, $-\log(1-\xi) \leq \frac{\xi}{1-\xi}$. Thus,
      \begin{align*}
         \frac{1}{2\mathbf{B}} &\leq \frac{\xi}{1-\xi}\\
         \mathbf{B} &\geq \frac{1-\xi}{2\xi}\\
         \mathbf{B} &\geq \frac{1}{2\xi} - \frac{1}{2}\\
         \mathbf{B} &\geq \frac{d(n-1)}{2n} - \frac{1}{2}
      \end{align*}
      Combining our bounds for $\mathbf{A}$ and $\mathbf{B}$ and absorbing lower order terms we have,
      \begin{align*}
         t_\text{mix}(\epsilon) &\geq \left(\log(d/2) + \log\left(\frac{1-\epsilon}{\epsilon}\right)+1\right)\left(\frac{d(n-1)}{2n} - \frac{1}{2}\right)\\
         &\geq \frac{d(n-1)}{2n}\log(d/2) + \log\left(\frac{1-\epsilon}{\epsilon}\right)\frac{d(n-1)}{2n}- \frac{1}{2}\log(d/2) -\frac{1}{2}\log\left(\frac{1-\epsilon}{\epsilon}\right)\\
         &\geq \frac{d(n-1)}{2n}\log(d/2) + \left(\log\left(\frac{1-\epsilon}{\epsilon}\right)-2\right)\frac{d(n-1)}{2n} -\frac{1}{2}\log\left(\frac{1-\epsilon}{\epsilon}\right)\\
         &\geq \frac{d(n-1)}{2n}\log(d/2) + \left(\log\left(\frac{1-\epsilon}{\epsilon}\right)-6\right)\frac{d(n-1)}{2n}\\
         &\geq \frac{d(n-1)}{2n}\log(d/2) + c_l(\epsilon)\frac{d(n-1)}{n}
      \end{align*}
      as required.
   \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

