{"assumptions":[],"created_at":"2026-10-27T10:52:57.737584+00:00","domain":"probability theory","id":"claim_0ef9267e2c8e636997b986e05d1eb167f87e6a1f5f671b70dae05793375a047e","kind":"definition","schema_version":1,"statement":"[Definition 35 of arXiv:2609.02755, 'The Sharp Rate of Probabilistically Strong Convergence to the KPZ Equation'] For $\zeta \in [0, \zeta_0)$ we write
	\begin{align*}
		E^\zeta_\vartheta = \{(Z, \boldsymbol{\psi}, \mcV) \in \cM_{\mathrm{adm}}(\tilde{\mfT}^\zeta) \times (C^{\vartheta - N\zeta})^3 \times \mathcal{D}^{3/2 + 2 \kappa - N\zeta, - \kappa - N\zeta} ({\tilde \mfT^\zeta_{\ge - 2\kappa}}) \},
	\end{align*}
	which we equip with the metric
	\begin{align*}
		d_{E^\zeta_\vartheta}&((Z, \boldsymbol{\psi}, \mcV), (\bar{Z}, \bar{\boldsymbol{\psi}}, \bar{\mcV})) \\
		&= \| Z; \bar{Z} \|^{(\zeta)}_{2+2\kappa; \mathcal{O}_T} + \| \boldsymbol{\psi} - \bar{\boldsymbol{\psi}} \|_{(C^{\vartheta - N\zeta})^3} + \| \mcV; \bar{\mcV} \|^{(\zeta)}_{3/2+2\kappa - N\zeta, -\kappa - N\zeta; \mathcal{O}_T}\;,
