{"assumptions":[],"created_at":"2026-10-27T07:31:20.587462+00:00","domain":"probability theory","id":"claim_1011db3252fb3a25576226e52e162bba088fe1888059a5151bb466731f482245","kind":"concept","schema_version":1,"statement":"[Theorem 10 (The general linear Gaussian Kalman filter) of arXiv:2608.25164, 'A time-fractional Kalman filter'] \begin{myenumerate}
\item
The best estimate $\widehat{X}(t)=\E[X(t)\mid\Y_t]$ of $X(t)$, given the
observations $Y(s)$ for $s\leq t$, satisfies the stochastic integral equation

\begin{align}
\widehat{X}(t)=\E[X(t)]
-\int_0^t\frac{G^2(s)}{D^2(s)}H(t,s)\widehat{X}(s)ds
+\int_0^t\frac{G(s)}{D^2(s)}H(t,s)dY(s),

\end{align}
where
\begin{align*}
H(t,s)=\E[X(t)\widetilde X(s)],\qquad
\widetilde X(s)=X(s)-\widehat X(s),\qquad 0\leq s\leq t.
\end{align*}
\item
The error function $H(t,s)=\E[X(t)\widetilde X(s)]$ satisfies the following Riccati  intehral equation
\begin{align}
H(t,s)
&=\operatorname{Cov}(X(t),X(s))\nonumber\\
&\quad-\int_0^s\frac{G^2(r)}{D^2(r)}H(t,r)H(s,r)dr,
\qquad 0\leq s\leq t,                                      
\end{align} 
\end{myenumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T18:32:23.588038+00:00","domain":"probability theory","id":"claim_101bdf77f11b321b0afc119653ec9a6539a10ea33009a0580321018b118bbeda","kind":"concept","schema_version":1,"statement":"[Thm 6.1 of arXiv:2603.13873, '{Solvability of BSDEs with possibly unbounded stochastic coefficients \\ on a general weig'] Assume that $\xi\in L_\tau^p(\rho_\cdot;{\mathbb R})$, $\int_0^\tau e^{\int_{0}^{s}\rho_r{\rm d}r}h_s{\rm d}s\in L_\tau^p(0;{\mathbb R}_+)$ and the random core function $f$ satisfies assumption (A:A3 of the paper). Then, the process $\{U_t(\xi),t\in[0,\tau]\}$ defined by
\begin{align}
U_{t\wedge \tau}(\xi):=e^{-\int_0^{t\wedge \tau}\mu_r{\rm d} r }\mathop{\operatorname{ess\,inf}}\limits_{q\in\mathcal{H}(\xi,f,\mu_\cdot,\nu_\cdot)}\mathbb{E}_{{\mathbb Q}^q}\Big[e^{\int_0^\tau \mu_r{\rm d} r}\xi+\int_{t\wedge \tau}^{\tau}e^{\int_0^s \mu_r{\rm d} r}f(s,q_s){\rm d} s\big|\mathcal{F}_{t\wedge \tau}\Big], \ \ t\geq 0
\end{align}
can be represented as the value process $y_\cdot$ of the unique weighted $L^p$ solution $(y_t,z_t)_{t\in[0,\tau]}$ in the space of $H_\tau^p(\rho_\cdot;{\mathbb R}\times {\mathbb R}^{1\times d})$ of the following BSDE
\begin{align}
 y_t=\xi+\int_t^\tau [\mu_s y_s-g(s,-z_s)] {\rm d}s-\int_t^\tau z_s{\rm d}B_s, \ \ t\in[0,\tau],
\end{align}
where the random function $g$ is the Legendre-Fenchel transform of $f$, i.e.,
\begin{align}
g(\omega,t,z):=\sup_{q\in{\mathbb R}^{1\times d}}\big(q\cdot z-f(\omega,t,q)\big),\ \ (\omega,t,z)\in\Omega\times[0,\tau]\times{\mathbb R}^{1\times d}.
\end{align}
Consequently, the operator $\{U_t(\cdot),t\in[0,\tau]\}$ constitutes a dynamic concave utility function defined on the space of $L_\tau^p(\rho_\cdot;{\mathbb R})$, i.e., it satisfies the following properties: for each $t\geq 0$,
\begin{itemize}
\item [\textbullet]\text{Monotonicity:} $U_{t\wedge \tau}(\xi)\geq U_{t\wedge \tau}(\eta)$ for each $\xi, \eta\in L_\tau^p(\rho_\cdot;{\mathbb R})$ such that $\xi\geq\eta$;
\item [\textbullet]\text{Concavity:} $U_{t\wedge \tau}(\lambda\xi+(1-\lambda)\eta)\geq \lambda U_{t\wedge \tau}(\xi)+(1-\lambda) U_{t\wedge \tau}(\eta)$ for all $\xi, \eta\in L_\tau^p(\rho_\cdot;{\mathbb R})$ and $\lambda\in(0,1)$;
\item [\textbullet]\text{Time consistency:} $U_{s\wedge \tau}(\xi)=U_{s\wedge \tau}(U_{t\wedge \tau}(\xi))$ for each $\xi\in L_\tau^p(\rho_\cdot;{\mathbb R})$ and each $s\in [0,t]$.
\end{itemize}
Moreover, let $\tilde q_s\in\partial g(s,-z_s), \ s\in[0,\tau]$. By this notation we mean that $(\tilde q_t)_{t\in [0,\tau]}$ is an $(\mathcal{F}_t)$-progressively measurable ${\mathbb R}^{1\times d}$-valued process such that for each $s\in[0,\tau]$ and $u\in {\mathbb R}^{1\times d}$,
\begin{align*}
g(s,u)-g(s,-z_s)\geq \tilde q_s\cdot (u+z_s)\ \ \ {\rm or \ equivalently}\ \ \ \tilde q_s\cdot u-g(s,u)\leq -\tilde q_s\cdot z_s-g(s,-z_s).
\end{align*}
Then, the infimum in (equation Ut of the paper) is attained for $\tilde q_\cdot$ provided that anyone of the following three conditions holds:
\begin{itemize}
\item [(i)] $\mathbb{E}[\exp\left(\frac{\bar p}{2}\int_0^\tau \nu_t^2 {\rm d} t\right)]<+\infty$ for any $\bar p>1$;

\item [(ii)] $\mathbb{E}[\exp\left(\frac{1}{2}\int_0^\tau \nu_t^2 {\rm d} t\right)]<+\infty$ and $\int_0^\tau e^{\int_{0}^{s}\mu_r{\rm d}r}h_s{\rm d}s\leq K$ for some constant $K>0$;

\item [(iii)] the process $L_t^{\tilde q}:=\exp(\int_{0}^{t}\tilde q_s{\rm d} B_s-\frac{1}{2}\int_{0}^{t}|\tilde q_s|^2{\rm d} s), \ t\in[0,\tau]$
is a uniformly integrable martingale and $\int_0^\tau e^{\int_{0}^{s}\mu_r{\rm d}r}h_s{\rm d}s\leq K$ for some constant $K>0$.\vspace{0.2cm}
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:30:14.227141+00:00","domain":"probability theory","id":"claim_102db046a521dd285333fdaeede729c9df48d558525666fb7c0b1829c98221fc","kind":"concept","schema_version":1,"statement":"[Theorem main-thm-2 of arXiv:2608.23202, 'Locally finite Fixed points of Branching Brownian Motion'] Let $\Pi$ be a fixed point of BBM with drift $\lambda \geq \sqrt{2}$ and $\theta$ be a point process. Then,   
\begin{enumerate}
    \item For $\lambda > \sqrt{2}$, $\theta \in Dom_{\lambda}(\Pi)$ if and only if $\theta$ satisfies (H1), (H2), (H3). In that case, $\Pi \overset{d}{=}\widetilde{\mathcal E}_\infty^\lambda(\cdot - S)$ with $S = \log(Z)/\mu$, where $\widetilde{\mathcal E}_\infty^\lambda$ and $Z$ are sampled independently of each other \footnote{Note that the random variable $Z$ appearing here can be $0$ with positive probability. As such, comparing with Remark (infinite-S of the paper), $S$ is a $[-\infty, \infty)$-valued random variable and $\Pi = \widetilde{\mathcal E}_\infty^\lambda(\cdot - S)$ is an empty point process on the event $S= -\infty$.}. \\

\item For $\lambda = \sqrt{2}$, $\theta \in Dom_{\lambda}(\Pi)$ if and only if $\theta$ satisfies (A1), (A2), (A3). In that case, $\Pi \overset{d}{=}\widetilde{\mathcal E}_\infty(\cdot - S)$ with $S = \log(Z)/\sqrt{2}$, where $\widetilde{\mathcal E}_\infty$ and $Z$ are sampled independently of each other\footnote{The critical case $\lambda = \sqrt{2}$ in this result was also addressed in [Shekhar_Domain] although with an additional assumption of $\theta$ having a finite top particle and with a slightly stronger notion of convergence as compared to Definition (Def_DOA of the paper).}. 
