     \item $G(x) \geq 0$;
     \item $G(x)$ is compactly supported in $B(0,1)$, the unit ball in $\mathbb{R}^{d}$;
     \item $\int_{\mathbb{R}^{d}} G(x) d x=1$;
     \item $\displaystyle\lim_{\eta \rightarrow 0} G_{\eta}(x)=\displaystyle\lim_{\eta \rightarrow 0} \eta^{-d} G(x / \eta)=\delta_{0}(x)$, where $\delta_{0}(x)$ is the Dirac delta function and the limit is taken in the space of Schwartz distributions.
 \end{enumerate}","status":"unverified"}

