{"assumptions":[],"created_at":"2026-10-26T19:35:10.792985+00:00","domain":"probability theory","id":"claim_11b05b9761cb9efa24b7c06860b49a16f04a85b8c69a013c6d6ccdeb365079b1","kind":"lemma","schema_version":1,"statement":"[Lemme 21 of arXiv:2604.00635, 'Large deviations of the periodic Toda chain'] Let  $\kappa>0$ and $\Ups\in \mathcal G_{\kappa}$. Then, for $N \geq 2$,

\begin{enumerate}

\item For all $\delta > 0$

$$\Ups^{\otimes N} \Big[ \big\{\bs{x}_N \in \R^N \, : \,  |x_k - x_j| \leq N^{-1 - \delta} \quad \text{ for some } \quad k \neq j \big\} \Big] \, \leq \,  \norm{\varrho}_{ L^{\infty}(\R) } N^{1-\delta} \, .$$

\item There is a constant $C^\prime > 0$ such that

$$\Ups^{\otimes N}\Big[ \Big\{ \bs{x}_N \in \R^N \, : \, 1+ \frac{2}{\ell N} \sum_{\substack{j=1 \\ j \neq k} }^N \ln|x_k - x_j| \, \leq \frac{\kappa}{2}

            \quad \text{ for some } \quad  k \in \intn{1}{ N } \Big\} \Big] \,  \leq \, C^\prime N^{-1}  \, .$$

\item Let  $\delta \geq 2$ and set $\mc{F} = \mc{F}_1 \cap \mc{F}_2 $ where

\begin{align*}

\mc{F}_1 &= \big\{  \bs{x}_N \in \mathbb{R}^N \, : \, |x_k - x_j | \geq N^{-1-\delta} \quad  \forall k \neq j \in  \intn{1}{N} \big\}  \vspace{4mm} \\

\mc{F}_2 &= \Big\{ \bs{x}_N \in \mathbb{R}^N \, : \, 1 \, - \,  \sul{\substack{j=1 \\ j \neq k}}{N} \frac{ \ln|x_k - x_j|  }{ \ln(2\veps_N) }  \, \geq  \, \frac{\kappa}{2} \quad \forall k \in \intn{1}{N} \Big\} \, .

\end{align*}

Then

\begin{align*}

&\Int{\mathbb{R}^N}{} \mathbbm{1}_{ \mc{F} }(\bs{x}_N) \, \ln\bigg( 1 - \sul{\substack{j=1 \\ k \neq j}}{N}  \frac{  \ln|x_k - x_j| }{ \ln(2\veps_N) } \bigg) \,\dd^{N}\Ups(\bs{x}_N) \\

&= \Int{\mathbb{R}}{} \ln\left( 1 - \frac{N-1}{\ln(2\veps_N)} \Int{\mathbb{R}}{} \ln|x - y| \, \dd \Ups(y) \right) \, \dd \Ups(x) + \mathrm{O}(N^{-\frac{1}{2}}) \, .

\end{align*}

\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:13:49.975917+00:00","domain":"probability theory","id":"claim_11b150b28deba049d28640221064d002dd5892fa4aaf8ce8513a90638e39c925","kind":"lemma","schema_version":1,"statement":"[Lemma lem:Kolmo of arXiv:2411.07157, 'Rough differential equations in the flow approach'] Pick $\tau\in\mathcal{T}$, and suppose that for some $\eta>0$ and $c>0$ small enough we have
