{"assumptions":[],"created_at":"2026-10-27T14:18:13.240688+00:00","domain":"probability theory","id":"claim_125330172b55412fa02dc22c84896ba91d89328e3535725bea954e4b49fa44c2","kind":"concept","schema_version":1,"statement":"[Thm cty of arXiv:2507.02518, '{\bf Exponential Ergodicity in Relative Entropy and $L^2$-Wasserstein Distance for non-equ'] Assume {\bf (C)}. There exist  $K_*,c,\tilde c,\lambda>0$, depending on $d$ and on the constants in {\bf (C)} except on $K_I$, such that, provided $K_I\leqslant K_*$, then  (equation Degth of the paper) has a unique stationary solution $\bar{\mu}\in\mathscr P_2(\mathbb R^{2d})$,
\begin{align}\mathbb W_2(P_t^\ast\mu_0,\bar{\mu})\leq c\text{\rm{e}}^{-\lambda t}\mathbb W_2(\mu_0,\bar{\mu}),\ \ t\geq 0, \mu_0\in\mathscr P_2(\mathbb R^{2d}),
\end{align}
and

\begin{align} \mathrm{Ent}(P_t^\ast\mu_0|\bar{\mu})\leq \tilde{c}\text{\rm{e}}^{-2\lambda t}\mathrm{Ent}(\mu_0|\bar{\mu}),~ t\geq 1, \mu_0\in\mathscr P_2(\mathbb R^{2d}).
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T15:12:20.543451+00:00","domain":"probability theory","id":"claim_1276ee87dfaf4616ea4ecd7c89e0513f527c0df152293ea819418d256413c8b5","kind":"lemma","schema_version":1,"statement":"[Lemma lem:gcan of arXiv:2603.27906, 'Marked GUE-corners process in doubly periodic dimer models'] Let $R_2>R_1>0$, then
 \begin{multline}
\mathcal{J}_d=
\frac{1}{(2\pi\mathrm{i})^2}\int_{\tilde \Gamma_s'}\int_{\tilde \Gamma_l'}
\boldsymbol{\mathcal{M}}_{i_1,j_1,i_2,j_2}(z_1,w_1;z_2,w_2) 
\exp\left({N(G(z_2,w_2)-G(z_1,w_1))}\right)
\frac{w_1^{r_1}}{w_2^{r_2}}
 \frac{z_1^{\mu_1\sqrt{N}}}{z_2^{\mu_2\sqrt{N}}}
