\begin{equation}
\rho_{\al c}(x) \sim \sqrt{\lambda_+-x}, \quad  \text{ for } \ \ x \in \left[\lambda_+ - 2\wt c,\lambda_+ \right],\ \al\in\{1,2\}.
\end{equation}
\item[(2)] For $z =E+\ii \eta\in S(\wt c,C_0,-\infty)$ and $\al\in\{1,2\}$, 
\begin{equation}
\vert m_{\al c}(z) \vert \sim 1,  \quad  \im m_{\al c}(z) \sim \begin{cases}
