\item $X^{(n)}$ is a \emph{near}-log-concave random variable of degree \emph{1} with $\mathcal{I}_{|\mathbf{D}^{(n)}|}^{(1)} = \mathcal{I}_{|\mathbf{D}^{(n)}|}\setminus\{4\}$ for every $n\geq 5$
\end{enumerate}
given that $\mathcal{I}_{|\mathbf{D}^{(n)}|} = \{2,\ldots,|\mathbf{D}^{(n)}|-1\}$ for every finite $n\geq 2$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T01:10:08.714837+00:00","domain":"probability theory","id":"claim_12d780fd976447a00cd08e99cf761b69e2d56a6662c2cf96d80d4011062f59a8","kind":"concept","schema_version":1,"statement":"[Lemma repl_lemma_2 of arXiv:2411.17653, 'Exclusion processes with non-reversible boundary: hydrodynamics and large deviations'] For any function $H \in C^{1,2}( {\Omega_T})$ and any $t \in [0,T]$, it holds, for any $N \in \mathbb{N}$ and any $\epsilon > 0$,
 {
\begin{align*}
\mathbb{E}_{\nu_N} &\left[\Big | \int_0^t [\langle h_{-}(\eta_s), H_s\rangle - F_-(\overrightarrow{\eta}_{sN^2}^{\lfloor \epsilon N \rfloor}(\epsilon_N)) H_s(0)] ds \Big | \right] \\
&\hspace{4.5cm} \lesssim  {\frac{l}{\epsilon N}} +\epsilon ( l B + 1 + l) + \sum_{j = 2}^{l} \sum_{p=1}^{j-1} \binom{j-1}{p} \frac{2 l}{\epsilon^{p-1} N ^p} {+ \frac{1}{B}},
\end{align*}} for all $B > 0$ independent of $N$ and $\epsilon$. The result also holds by replacing $h_-, F_-$ and $\overrightarrow{\eta}$ by $h_+$, $F^+$ and $\overleftarrow{\eta}$, respectively.
Above $\overrightarrow{\eta}^{\lfloor \epsilon N\rfloor}_{sN^2}$ and $\overleftarrow{\eta}^{\lfloor \epsilon N\rfloor}_{sN^2}$ are the same as in (equation right_average of the paper) and (equation left_average of the paper) {, respectively, and $F_{\pm}(\cdot)$, $\langle h_-(\eta_s), H_s\rangle$ and $\langle h_+(\eta_s), H_s\rangle$ are as in (equation def_F_pm of the paper), (equation def_langle_h_minus of the paper) and (equation def_langle_h_plus of the paper), respectively.} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T10:42:55.318536+00:00","domain":"probability theory","id":"claim_12e01c399076cc0518d72d01c4907a09330e0b0409965d7185a13eb90b16b6b9","kind":"theorem","schema_version":1,"statement":"[Prop 26 (Variational identity for the sub-Gamma class) of arXiv:2609.02398, '\textbf{Convex Order Comparisons for Sub-Gamma Random Variables}'] Fix $a > 0$. For every $p \in (0,1)$ the feasible spreads $\{\nu > 0 : Y_{p,\nu} \in \SG(1,a)\}$ form the interval $(0, \nu^{\SG}_{\max}(p,a)]$: the supremum in \eqref{eqn:sgnumax} is finite and attained; moreover $\nu^{\SG}_{\max}(p,a) = \nu^{\SG}_{\max}(1-p,a)$. For $c > 0$, every $X \in \SG(1,a)$ satisfies $X \lecx c\Lap$ if and only if
\begin{align}
    (1-p)\,\nu^{\SG}_{\max}(p,a) \le c\left(1 + \log\frac{1}{2p}\right)
    \qquad \text{for every } p \in (0, 1/2].

\end{align}
Consequently
\begin{align}
    c^{\SG}(1,a) = \sup_{p \in (0,1/2]} R^{\SG}(p,a),
    \qquad
    R^{\SG}(p,a) \coloneqq \frac{(1-p)\,\nu^{\SG}_{\max}(p,a)}{1 + \log\frac{1}{2p}},

\end{align}
and the infimum in \eqref{eqn:defcSG} is a minimum: $c^{\SG}(1,a)$ is itself admissible.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:18:27.572290+00:00","domain":"probability theory","id":"claim_12f7d0d538a9e8d359c102ea487f4b8ed312d8aaf925880ae42268605bc2815c","kind":"concept","schema_version":1,"statement":"[Lem 15 of arXiv:2510.23423, 'One-arm exponents of the high-dimensional Ising model'] Let $d\geq 2$ and $G=(V,E)$ be a subgraph of $\mathbb Z^d$. Let $J\in (\mathbb R^+)^E$, $\mathsf{h}\in \mathbb R^V$, and $A\subset V$. Then, for every $x\in V$,
\begin{equation}
	\partial_{\mathsf{h}_x}\langle \sigma_A\rangle_{G,J,\mathsf{h}}=\langle \sigma_A;\sigma_x\rangle_{G,J,\mathsf{h}},
\end{equation}
and for every $uv\in E$,
\begin{equation}
	\partial_{J_{uv}}\langle \sigma_A\rangle_{G,J,\mathsf{h}}=\langle \sigma_A;\sigma_u\sigma_v\rangle_{G,J,\mathsf{h}}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:39:41.440725+00:00","domain":"probability theory","id":"claim_13012fd9b4883a9453b508bf24922f2a903000dc5dd6aadd63057294a36a8a45","kind":"theorem","schema_version":1,"statement":"[Prop 34 of arXiv:2604.07370, 'Probabilistic Weyl law for twisted Toeplitz matrices with rough symbols'] Let $\mc{K}\subset\subset \C$. Let $\phi_{\mu_N}$ be as in \eqref{Expression simplifiée du potentiel logarithmique en fonction du déterminant} and $\phi_{\widetilde{\mu}_N}$ be as in \eqref{Expression simplifiée du potentiel logarithmique en fonction du déterminant - 2}. Let $\beta>0$ be as in Proposition \ref{Différence des potentiels loga entre mu_N tilde et mu}. Then, there exists $C_0>0$ such that for all $z\in \mc{K}$, 
    \begin{equation}
        \begin{split}
            \phi_{\mu_N}(z) &\leq \phi_{\widetilde{\mu}_N}(z)+\mc{O}(N^{-\vartheta}\log(\delta N^{-\beta}))+\mc{O}(N^{-\vartheta})\\
            &+\mc{O}\pr{N^{-\vartheta}\log\pr{1+C_0N^{\beta-\varrho\eta/2}\delta^{-1}}}+\log\pr{1+2C_0N^{-\varrho\eta/2}\alpha^{-1/2}}\\
            &+\mc{O}\pr{\alpha^{{\kappa_2}}\log\pr{1+C_0N^{\beta-\varrho\eta/2}\delta^{-1}}}
        \end{split}

    \end{equation}
    with probability $1-o(1)$, and
    \begin{equation}
        \begin{split}
            \phi_{\mu_N}(z)&\geq \phi_{\widetilde{\mu}_N}(z)+\mc{O}(N^{-\vartheta})+\mc{O}(\alpha^{{\kappa_2}})+\mc{O}(\alpha^{-1/2}N^{-\varrho\eta/2})\\
            &+\mc{O}(N^{-\vartheta}\log(\delta N^{-\beta}))+\mc{O}(\alpha^{{\kappa_2}}\log(\delta N^{-\beta}))
        \end{split}

    \end{equation}
    with probability $\geq 1-o(1)$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T17:42:08.413009+00:00","domain":"probability theory","id":"claim_1302124cbe5dadd4fdf3931a182bdc97f322aa94f70c695fd1b3a4ac49ca8580","kind":"concept","schema_version":1,"statement":"[Lemma beta-i of arXiv:2511.15893, 'On a Class of Dynamical Poisson-Voronoi Tessellations'] For all non-negative measurable functions $f$ on $(\Omega,{\mathcal F })$, we have:
