{"assumptions":[],"created_at":"2026-10-27T17:18:19.447098+00:00","domain":"probability theory","id":"claim_14983aaf5b73307cab1bc0670261fb0cf9efdbfdf789207ed2c23b3e8d7fb101","kind":"definition","schema_version":1,"statement":"[Definition def:NBP-Wishart of arXiv:2508.17838, '\bf Edge Universality for Inhomogeneous Random Matrices'] Let $H\in\mathbb{C}^{N\times M}$ be a $N\times M$ matrix, and let $x,y$  respectively denote  elements in $[N], [M]$.  For each integer $n\ge0$, define the nonbacktracking power matrix $V_n$ (viewed as an operator) as follows:

\paragraph{Even case ($n=2m$):}
\begin{itemize}
  \item $V_{2m}:\,\mathbb{C}^{[N]}\to\mathbb{C}^{[N]}$, with
  \begin{equation}
  (V_{2m})_{x_0x_{2m}} = \sum_{y_1,x_2,\dots,y_{2m-1}}
  \Bigl[\prod_{i=0}^{2m-2}\mathbf{1}(\zeta_i\neq\zeta_{i+2})\Bigr]\,
  H_{x_0y_1}H^*_{y_1x_2}\cdots H^*_{y_{2m-1}x_{2m}},
  \end{equation}
  summing over $y_{2k+1}\in[M],\,x_{2k}\in[N]$. Here $\zeta_i$ denotes $x_i$ or $y_i$.
  \item $V_{2m}:\,\mathbb{C}^{[M]}\to\mathbb{C}^{[M]}$, with
  \begin{equation}
  (V_{2m})_{y_0y_{2m}} = \sum_{x_1,y_2,\dots,x_{2m-1}}
  \Bigl[\prod_{i=0}^{2m-2}\mathbf{1}(\zeta_i\neq\zeta_{i+2})\Bigr]\,
  H^*_{y_0x_1}H_{x_1y_2}\cdots H_{x_{2m-1}y_{2m}},
  \end{equation}
  summing over $x_{2k+1}\in[N],\,y_{2k}\in[M]$.
\end{itemize}

\paragraph{Odd case ($n=2m+1$):}
\begin{itemize}
  \item $V_{2m+1}:\,\mathbb{C}^{[N]}\to\mathbb{C}^{[M]}$, with
  \begin{equation}
  (V_{2m+1})_{x_0y_{2m+1}} = \sum_{y_1,x_2,\dots,x_{2m}}
  \Bigl[\prod_{i=0}^{2m-1}\mathbf{1}(\zeta_i\neq\zeta_{i+2})\Bigr]\,
  H_{x_0y_1}H^*_{y_1x_2}\cdots H_{x_{2m}y_{2m+1}},
  \end{equation}
  summing over $y_{2k+1}\in[M],\,x_{2k}\in[N]$.
  \item $V_{2m+1}:\,\mathbb{C}^{[M]}\to\mathbb{C}^{[N]}$, with
  \begin{equation}
  (V_{2m+1})_{y_0x_{2m+1}} = \sum_{x_1,y_2,\dots,y_{2m}}
  \Bigl[\prod_{i=0}^{2m-1}\mathbf{1}(\zeta_i\neq\zeta_{i+2})\Bigr]\,
  H^*_{y_0x_1}H_{x_1y_2}\cdots H^*_{y_{2m}x_{2m+1}},
  \end{equation}
  summing over $x_{2k+1}\in[N],\,y_{2k}\in[M]$.
\end{itemize}
We also set 
\begin{equation}
V_0 = \begin{cases}I_N:\mathbb{C}^{[N]}\to\mathbb{C}^{[N]},\\
I_M:\mathbb{C}^{[M]}\to\mathbb{C}^{[M]},\end{cases}
\quad
V_1 = \begin{cases}H:\mathbb{C}^{[N]}\to\mathbb{C}^{[M]},\\
H^*:\mathbb{C}^{[M]}\to\mathbb{C}^{[N]},\end{cases}
\quad
V_n = 0~(n<0).
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T21:02:06.325498+00:00","domain":"probability theory","id":"claim_149d24c9ac186aa861473938c03198041af5797bcda9acae8de62af9393383c5","kind":"concept","schema_version":1,"statement":"[Thm 4 of arXiv:2607.06242, 'Exponential mixing and Freidlin--Wentzell large deviation principle for Markov cocycles'] Assume that there is a lower semicontinuous function $U: E\to[0,\infty)$ and a measurable function $S:E\to[0,\infty]$ such that for any given $x,y\in E$ there exist progressively measurable processes $X_t^{\s,x}$ and $Y_t^{\s,x,y}$
      (denoted $X_t^{\s}$ and $Y_t^{\s}$ for simplicity)
      such that the following conditions hold:
      \begin{enumerate}[label=(H\arabic*)]
        \item There is a lower semicontinuous function $V: E\to \mathbb R_+$ and constant $\gamma>0$ such that
        \begin{align*}
          P_t^{\sigma}V(x) + \gamma \int_0^tP_s^{\sigma}V(x)ds\leq V(x) + \int_0^tK(\beta_s\s)ds
        \end{align*}
        where $K\in L^1(\Sigma,m)$ is nonnegative, and for any $M>0$, $U, p$ are bounded on $\{V\leq M\}$ and $\{V\leq M\}\times \{V\leq M\}$. 
        \item There exist $\zeta,\kappa>0$ such that for all $t\geq 0$,
        \begin{align*}
          p(X_t^{\s},Y_t^{\s})\leq p(x,y)\exp\left(-\zeta t + \kappa\int_0^tS(X_s^{\s})ds\right).
        \end{align*}
        \item There exist $\varpi>0$ and $b\in L^1(\Sigma,m)$ such that 
        \begin{align*}
          U(X_t^{\s}) + \varpi\int_0^tS(X_s^{\s})ds \leq U(x)+ \int_0^tb(\beta_s\s)ds + M_t^{\s},
        \end{align*}
        where $M_t^{\s}$ is a continuous local martingale with $M_0^\sigma=0$ and
        \[d\langle M^{\s}\rangle_t\leq b_1S(X_t^{\s})dt+b_2(\b_t\s)dt \quad \text{ for }t\geq 0,\]
        where  $b_1>0$ is a constant and  $b_2\in L^1(\Sigma,m)$ is nonnegative. Furthermore, 
        \begin{align*}
          \zeta>\frac{\kappa}{\varpi} \int_{\Sigma}b d m.
        \end{align*}
        \item The law of $\left(X_t^{\s}\right)_{t\in\mathbb R_+}$ coincides with $\mathbf P_{\s,x}$ and for any $\d\in(0,1]$, there exist a constant $C_{\d}>0$ and  a measurable function $\bar{\varepsilon}_{\d}:\mathbb{R}_+\to (0,1)$ which is non-increasing, such that for any $t\geq 0$, 
        \begin{align*}
          d_{TV}\left(\mathcal{L}(Y_t^{\s}), P_{t}^{\s}(y,\cdot)\right)\leq C_{\d}\left(M_{\d}(t,\s)\right)^{1/2}, \,\quad d_{TV}\left(\mathcal{L}(Y_t^{\s}), P_{t}^{\s}(y,\cdot)\right)\leq 1-\bar{\varepsilon}_{\d}(M_{\d}(t,\s)),
        \end{align*}
        where 
        \[ M_{\d}(t,\s): =\mathbf E\left(\int_0^tb_3(\beta_s\s)p(X_s^{\s},Y_s^{\s})ds\right)^{\d},\]
        and $b_3\in L^1(\Sigma,m)$ is nonnegative. 
      \end{enumerate}
      Then there is a unique $\beta_t$-invariant stationary measure 
      $(\G_\sigma)_{\s\in \Sigma}$
      of $P_t^{\s}$  such that $\G_\sigma P_t^\sigma=\G_{\beta_t \sigma}$ $m$-a.s. for all $t\geq 0$. Furthermore, there exist $\Sigma_0\subset\Sigma$ with $m(\Sigma_0)=1$, $T>0$ and $\l>0$ such that the following properties hold.
      \begin{itemize}
        \item Pullback exponential stability: for every $\sigma\in \Sigma_0$ and $x\in E$, there is $C_{\lambda}(\sigma,x)>0$ such that, for all $t\geq 0$,
        \begin{align*}
          \W_{\rho\wedge 1}\left(\delta_x P_t^{\beta_{-t} \sigma}, \G_\sigma\right) \leq C_\lambda(\sigma,x)e^{-\lambda t}.
        \end{align*}
        \item Forward exponential stability: for each fixed $r\in[0,T)$, there is a full measure set $\Sigma_r\subset\Sigma_0$ such that, for every $\sigma\in \Sigma_r$ and $x\in E$, there is $C_{\lambda,r}(\sigma,x)>0$ such that, for all $n\geq0$,
        \begin{align*}
          \W_{\rho\wedge 1}\left(\delta_x P_t^\sigma, \G_{\beta_t \sigma}\right) \leq C_{\lambda,r}(\sigma,x)e^{-\lambda t},\qquad t=nT+r.
        \end{align*}
      \end{itemize}
      Here $\W_{\rho\wedge 1}$ is the Wasserstein distance induced by the metric $\rho\wedge 1$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T02:47:21.729325+00:00","domain":"probability theory","id":"claim_14ae83e6858ab63886306683b015ccd90bd87df1caa5ad850523938abcc03bfb","kind":"theorem","schema_version":1,"statement":"[Theorem Einaiiagapi of arXiv:2412.09290, 'Asymptotics of Harish-Chandra transform and infinitesimal freeness'] Let $A$ be a random Hermitian matrix of size $N$. Assume that for every finite $r$ one has
  \begin{equation}
    \lim_{N \rightarrow \infty} N \left( \frac{1}{N} \log \mathbb{E}[H \text{}
    C (x_1, \ldots, x_r, 0^{N - r} ; \lambda_1 (A), \ldots, \lambda_N (A))] -
    \sum_{i = 1}^r \Psi (x_i) \right) = \sum_{i = 1}^r \Phi (x_i), 
  \end{equation}
  where $\Psi, \Phi$ are smooth functions in a (complex) neighborhood of $0$ and the
  above convergence is uniform in a (complex) neighborhood of $0^r$. Then one has the following     limit:
  \begin{equation}
    \lim_{N \rightarrow \infty} N \left( \frac{1}{N^{k + 1}} \mathbb{E} \left[
    \sum_{i = 1}^N \lambda_i^k (A) \right] -\ensuremath{\boldsymbol{\mu}}_k \right)
    =\ensuremath{\boldsymbol{\mu}}'_k, 
  \end{equation}
  where $(\ensuremath{\boldsymbol{\mu}}_k)_{k \in \mathbb{N}}$ are given by ((topg of the paper)) and
  \begin{equation}
    \ensuremath{\boldsymbol{\mu}}'_k := \sum_{m = 0}^{k - 1} \frac{k!}{m! (m + 1) !
    (k - m - 1) !}  \left. \frac{\mathrm{d}^m}{\mathrm{d} x^m} ((\Psi' (x))^{k - m
    - 1} \Phi' (x)) \right|_{x = 0} . 
  \end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:09:59.303766+00:00","domain":"probability theory","id":"claim_14ba961d4050e5e43c1139b7ed627d88498ac49617dfe0dab3916a2fe85e01e2","kind":"lemma","schema_version":1,"statement":"[Lemma pitdef of arXiv:2608.07236, 'Negative association of Busemann functions \\in exponential last-passage percolation'] Suppose $\textup{\texttt{slope}}_m (h)> \textup{\texttt{slope}}_{m+1} (h)$ and recall $\sigma^m$  defined in (equation qmap of the paper).
We then have the following identities:
\begin{align}
(\sigma^{m} h)^{m+1} (x) &= h^{m+1}(x) + \sup_{z\leq x} \{h^{m}(z) - h^{m+1}(z-1)\} - \sup_{z\leq 0} \{h^{m}(z) - h^{m+1}(z-1)\},  \\
(\sigma^{m} h)^{m} (x) &= h^{m}(x) - \sup_{z\leq x} \{h^{m}(z) - h^{m+1}(z-1)\} +  \sup_{z\leq 0} \{h^{m}(z) - h^{m+1}(z-1)\}.
\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:25:44.587359+00:00","domain":"probability theory","id":"claim_14c433038effe846ce9dbea18ee62ea4e63c149b7357b5aa6b19e1bef402b916","kind":"theorem","schema_version":1,"statement":"[Thm interaction_gain of arXiv:2509.08659, 'Gap metrics for stationary point processes and quantitative convexity of the free energy'] Let $\mathsf{P}_i\in  \mathcal P_{s,1}(\Gamma)$, $i=0,1$ with  finite distance $\mathscr W_p(\mathsf{P}_0,\mathsf{P}_1)<\infty$ and finite free energy $\mathcal F_{\beta}(\mathsf{P}_i)<\infty$, $i=0,1$. Let $ \mathsf{Q}$ be the $\mathscr W_p-$optimal coupling from Theorem (thm:convnex_entropy of the paper). Then for $0\leq t\leq 1$\begin{align}
    \mathcal F_{\beta}(\mathsf{P}_{t})\leq (1-t)\mathcal F_{\beta}(\mathsf{P}_{0})+t\mathcal F_{\beta}(\mathsf{P}_{1}) -
        \frac{\beta(1-t)t}{2}\int \sum_{(0,0)\neq (x,y)\in \bar\xi} (x-y)^2\inf_{z\in [x,y]}f(\left\lvertz\right\rvert) \mathsf{Q}^0(d\bar\xi),
    \end{align}
    where $\mathsf U:=\iota( \mathsf{Q})$,  $\mathsf{P}_t:= \mathsf{gap}^{-1}\left((T_t)_{\#}\mathsf U\right)$ and $f$ is chosen as in (equation eq:function_f of the paper).","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:11:11.692961+00:00","domain":"probability theory","id":"claim_14c9082435ca6608899d6bb3bf531c5ca584113dd7d5fe0fce719ecbaa13eca5","kind":"concept","schema_version":1,"statement":"[Theorem thm:intro-one of arXiv:2609.00645, 'Global persistence of nearly radial concentrated vortices in a bounded domain'] Let $\mathbf a_*\in D$ be a strict local minimum point of $H$.  Fix
$\kappa,M,R>0$.  For each $\varepsilon>0$, let
$\mathbf a_\varepsilon\in D$ and let
$\omega_{\varepsilon,0}\in L^\infty(D)$ be nonnegative and satisfy
\begin{equation}
  \int_D\omega_{\varepsilon,0}\,\mathrm d\mathbf x=\kappa,
  \qquad
  \|\omega_{\varepsilon,0}\|_\infty\leq M\varepsilon^{-2},
  \qquad
  \operatorname{supp}\omega_{\varepsilon,0}
  \subset B_{R\varepsilon}(\mathbf a_\varepsilon).
\end{equation}
Suppose that
\begin{equation*}
  \mathbf a_\varepsilon\longrightarrow\mathbf a_*,
  \qquad
  \mathcal A(\omega_{\varepsilon,0})\longrightarrow0
  \qquad\text{as }\varepsilon\longrightarrow0.
\end{equation*}
Let $\omega_{\varepsilon,t}$, $t\in\mathbb R$, denote the corresponding
Yudovich solution of (equation eq:euler-intro of the paper).
Then, as $\varepsilon\to0$,
\begin{equation}
  \sup_{t\in\mathbb R}\mathcal A(\omega_{\varepsilon,t})\longrightarrow0,
\end{equation}
and
\begin{equation}
  \sup_{t\in\mathbb R}\ \sup_{\mathbf b\in
  \mathsf C(\omega_{\varepsilon,t})}
  |\mathbf b-\mathbf a_*|\longrightarrow0.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:53:31.977325+00:00","domain":"probability theory","id":"claim_14ca7b672106df753d6804d1a0a7b5e10618721186dfbf11501f5540acbd822a","kind":"theorem","schema_version":1,"statement":"[Prop 26 of arXiv:2606.11271, '\LARGE The $K$-th nearest neighbor random walk on a Poisson point process gets trapped'] Let $(Y^L_n)_{n\ge 0}$ be the Markov chain on $\{0,1,\ldots,3L\}$ with $Y^L_0=0$ and transition probabilities:
\[
\P(Y^L_{n+1}=j \mid Y^L_n=i) = \begin{cases} 
(1-p)\mathbf{1}_{j=1}+p\mathbf{1}_{j=2} & \text{if } i=0 \\
(1-p)\mathbf{1}_{j=i+1}+p\mathbf{1}_{j=i-1} & \text{if } i\equiv 0 \pmod 3 \text{ and } 0<i<3L \\
(1-p)\mathbf{1}_{j=i-1}+p\mathbf{1}_{j=i+1}  & \text{if } i\not\equiv 0 \pmod 3 \text{ and } 0<i<3L \\
(1-p)\mathbf{1}_{j=3L-1}+p\mathbf{1}_{j=3L-2}  & \text{if } i=3L.
\end{cases}
\]
If $\mu = \mu_0$, then on the event $\cH_L$, the walk $(X_n)_{n\ge 0}$ has the law of $(x_{Y^L_n})_{n\ge 0}$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T16:26:02.394852+00:00","domain":"probability theory","id":"claim_14cb86a14229fc4c61c0db8a40780ad0fc6b24d4e2cb2f9cc460d07a52ab4379","kind":"definition","schema_version":1,"statement":"[Defn $\sharp$ and $\flat$ modifications of arXiv:2608.30031, 'Ziggurats, taut foliations, and contact structures'] Let $\mathcal{G}$ be a cooriented $C^0$-foliation on the $2$-torus $\mathbb{T}^2$, and $p \in \mathbb{T}^2$. We choose a smooth closed arc $c$ transverse to $\mathcal{G}$ and containing $p$ in its interior. After some arbitrarily small $C^0$ isotopy, we may assume that $\mathcal{G}$ is smooth in a neighborhood of $c$, and we choose coordinates $N(c) \cong (-\varepsilon, \varepsilon)_x \times (-2,2)_y$ near $c$, in which $c$ is identified with $\{0\} \times [-1,1]$, $p=(0,0)$, and $\mathcal{G}$ is tangent to $\partial_x$. 

    Let $h : [-1,1] \rightarrow [-1,1]$ be a smooth diffeomorphism satisfying 
    \begin{itemize}
        \item $h \geq \mathrm{id}$ (resp.~$h \leq \mathrm{id}$),
        \item $h = \mathrm{id}$ near $\partial [-1,1]$,
        \item $h > \mathrm{id}$ (resp.~$h < \mathrm{id}$) on $[-1/2, 1/2]$.
    \end{itemize}

    We modify $\mathcal{G}$ in $(-\varepsilon/2, \varepsilon/2) \times (-2,2) \subset N(c)$ so that the parallel transport along the leaves of $\mathcal{G}$ from left to right is $h$, and moreover the new $C^0$-foliation $\widetilde{\mathcal{G}}$ is everywhere either tangent or positively (resp.~negatively) transverse to $\partial_x$ in $N(c)$. Choosing $h$ sufficiently $C^0$-close to $\mathrm{id}$, we can further arrange that $T\widetilde{\mathcal{G}}$ is $C^0$-close to $T\mathcal{G}$. 

    We call the resulting $C^0$-foliation a $\sharp$ (resp.~$\flat$) modification of $\mathcal{G}$ near the point $p$. This modification can be made arbitrarily $C^0$-small and close to $p$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:52:45.029049+00:00","domain":"probability theory","id":"claim_14cd33d7f77a56366a2e1b793b18412b8615b6d85dbc640bc980daacc1e88658","kind":"theorem","schema_version":1,"statement":"[Corollary 5 (Fluctuation-Dissipation Relation) of arXiv:2606.07096, 'Non-Selection of Lagrangian Trajectories in the Zero-Noise Limit for a Class of Stochastic'] Let $W^\beta$, $u$ be as in Theorem~\ref{thm:SWP_stable} and additionally assume that $u$ is divergence-free. Then for any $\rho_0\in L^2$ and any $\kappa>0$, the associated solution $\rho^\kappa$ to the PDE~\eqref{eq:FP_PDE_stable_v2} satisfies
    \begin{equation}
        \| \rho_0\|_{L^2}^2-\|\rho^\kappa_t\|_{L^2}^2 = 2\kappa ^\beta\int_0^t \big\| |\nabla|^\beta \rho^\kappa_s\big\|_{L^2}^2 \dd s = \int_{\T^d} Var\big[ \rho_0((X^\kappa_{0,t})^{-1}(x))\big] \dd x
    \end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:48:25.142609+00:00","domain":"probability theory","id":"claim_14d0b25b9d4424f7bd7d50769e5df70379099048a1f46f3c1ff8760cd441c8ab","kind":"concept","schema_version":1,"statement":"[Theorem thm:wobbling of arXiv:2607.04620, 'The Exact Ville Identity\\ \large From the Absorbing Case to the General Law\\ with an App'] Let $\{M_n,\mathcal{F}_n\}$ be a mean-zero martingale and fix a level $r\ge0$. Let $T_r$ be the first $n\ge1$ with $M_n>r$, and $\infty$ if no such $n$ exists. Suppose
\begin{enumerate}[label=(\roman*)]
\item (sufficient wobbling)
\[
  \lim_{\varepsilon\downarrow0}\limsup_{k\to\infty}
  \mathbb{P}\left(\sup_{n\ge k}|M_n-M_k|>\varepsilon\right)=1,
\]
\item (bounded expected overshoot) there is $B<\infty$ with $\mathbb{E}[M_n\mid T_r=n]\le r+B$ a.s. for every $n\ge1$.
\end{enumerate}
Then $\mathbb{P}(T_r<\infty)=1$ and $\mathbb{E}[M_{T_r}]\le r+B$; moreover $\limsup_{n\to\infty}M_n=+\infty$ almost surely. Condition (i) ensures the martingale wobbles arbitrarily far out; condition (ii) bounds the overshoot of $M_{T_r}$ beyond $r$. Dropping either condition can make $\mathbb{P}(T_r=\infty)>0$, as the counterexamples of [klass2026beyond] demonstrate. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-09-07T12:18:08.279175+00:00","domain":"probability theory","id":"claim_14d1e116895a1bfd47abc7d97d6aef47a8958ea2281a9673f00dcef937013ef1","kind":"concept","schema_version":1,"statement":"[Lemma 8 (Theorem 1.1 in \cite{Hitczenko_studiamath}) of arXiv:2505.20799, 'A note on the improved sparse Hanson-Wright inequalities'] Let $\xi_{1}, \cdots, \xi_{n}$ be independent symmetric random variables with log-convex tails, i.e., $\log \mathbb{P}\{\vert\xi_{i}\vert\ge t \}$ is a convex function for $t\ge 0$. Then for $r\ge 2$
	\begin{align}
		\Big\Vert \sum_{i}\xi_{i}\Big\Vert_{L_{r}}\asymp  \Big(\sum_{i}\mathbb{E}\vert \xi_{i}\vert^{r}   \Big)^{1/r}+\sqrt{r}\Big( \sum_{i}\mathbb{E}\xi_{i}^{2}  \Big)^{1/2}.\nonumber
	\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:23:27.759010+00:00","domain":"probability theory","id":"claim_14d440a00c6def333aac10fc19ccaf92e9659effec7c559b2847d1c12971fdc1","kind":"lemma","schema_version":1,"statement":"[Lemma lem:grid-annular-estimate-paper of arXiv:2606.08683, 'Exact Fourier dimensions of dyadic Mandelbrot cascades under minimal integrability'] There exist constants \(C,c,\eta>0\) such that, for every \(n\ge1\),
