{"assumptions":[],"created_at":"2026-10-28T01:54:57.568846+00:00","domain":"probability theory","id":"claim_14d5a8ae5f2428b6bfefdbf5eff985ac441bd9b50af46e3a7d9c3ac5e3d6e3a2","kind":"concept","schema_version":1,"statement":"[Theorem Thm:BesovLog of arXiv:2412.03366, 'Regularity of Weighted Tensorized Fractional Brownian Fields and associated function space'] Let $s, \beta \in \mathbb{R}$ and $0 < p,q\leq \infty$ and $p'$ the conjugate exponent of $p$. We have the following embeddings
\begin{itemize}
\item if $q<+\infty$
\begin{equation}
\widetilde{B}^s_{p,q,\vert \log \vert^{\beta - r_1/q}}(\mathbb{R}^2) \hookrightarrow B^s_{p,q,\vert \log \vert^{\beta}}(\mathbb{R}^2) \hookrightarrow \widetilde{B}^s_{p,q,\vert \log \vert^{\beta +r_2/q}}(\mathbb{R}^2)
\end{equation}
where $$r_1 = \begin{cases}q(\frac{1}{p}-1)+ \max(q-1,0) & \text{ if } p \le 1 \\ 
\max( \frac{q}{\min(p,p')}-1,0) & \text{ if }p>1 \end{cases}$$
and
$$
r_2 = \begin{cases}1  & \text{ if } p < 1 \\ 
\max(1- \frac{q}{\max(p,p')}-1,0) & \text{ if }p\ge 1 .\end{cases}$$

\item if $q=+\infty$
\begin{equation}
\widetilde{B}^s_{p,\infty,\vert \log \vert^{\beta - \max(1/p-1,0) -1}}(\mathbb{R}^2) \hookrightarrow B^s_{p,\infty,\vert \log \vert^{\beta}}(\mathbb{R}^2) \hookrightarrow \widetilde{B}^s_{p,\infty,\vert \log \vert^{\beta }}(\mathbb{R}^2)
\end{equation}

\item if $q=2$, the Sobolev spaces $H^{s}_{2,\vert \log \vert^{\beta}}(\mathbb{R}^2)$ coincide with the classical Besov spaces $B^{s}_{2,2,\vert \log \vert^{\beta}}(\mathbb{R}^2)$ and with the hyperbolic Besov spaces $\widetilde{B}^{s}_{2,2,\vert \log \vert^{\beta}}(\mathbb{R}^2) $.
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T10:51:11.511306+00:00","domain":"probability theory","id":"claim_14e2942a36c66b1758662026df235e57e6edaa2d6688e6fea0bca7b605704158","kind":"theorem","schema_version":1,"statement":"[Proposition 3 (Cumulants and endpoint behavior) of arXiv:2609.02590, 'Directional Optimal Sub-Gamma Scales for Infinitely Divisible Laws'] For every integer $n\geq1$ such that
$\int |x|^{n+2}\nu(\dd x)<\infty$,
\begin{equation}
 \E R_X^n=\frac{2\kappa_{n+2}(X)}{(n+1)(n+2)V}.

\end{equation}
In particular, when the third cumulant is finite,
\begin{equation}
 \cplus(X)\geq\pos{\frac{\kappa_3}{3V}},
 \qquad
 \cminus(X)\geq\pos{-\frac{\kappa_3}{3V}}.

\end{equation}
The MGF boundaries give
\begin{equation}
 \cplus(X)\geq\frac{1}{\tplus(X)},
 \qquad
 \cminus(X)\geq\frac{1}{\tminus(X)}.

\end{equation}
If $\kappa_4$ is finite, then both directional objectives have the same
one-sided derivative at the origin:
\begin{equation}
 \Psi_+'(0+)=\Psi_-'(0+)
 =\frac{\kappa_4}{12V}-\frac{\kappa_3^2}{9V^2}.

\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T10:34:20.756210+00:00","domain":"probability theory","id":"claim_14f19d75dd289d33c25379b4da51f142804f9e7cd5c3ba6de577d7c203513e7e","kind":"theorem","schema_version":1,"statement":"[Proposition 4 of arXiv:2609.02218, 'Neumaier graphs of coherent rank five'] Let $n\geqslant8$ and $m\geqslant3$. 
Suppose $H$ is a Hadamard matrix of order $n$ with first row $h_1=\one^\transpose$, and let $\bL$ be a family of $m$ MALS of order $n-1$. 
Let $A$ be the adjacency matrix of $\Gamma(H;\bL)$.
Then
\[
 A^2
 =
 \left ((m-1)\frac{n(n-1)}2+n(n-2)\right )A_0+\mu_{A_1}A_1+\lambda_{A_2}A_2
 +\mu_{A_3}A_3+\lambda_{A_4}A_4,
\]
where
\begin{equation}
\begin{aligned}
 \lambda_{A_2}
 &=(m-2)\frac{n^2}{4}+n(n-2),
 &\lambda_{A_4}
 &=(m-1)\frac{n(n-1)}4+n(n-3),\\
 \mu_{A_1}
 &=(m-1)\frac{n(n-2)}4+n(n-2),
 &\mu_{A_3}
 &=(m-2)\frac{n(n-2)}4+n(n-2).
\end{aligned}
\end{equation}
Furthermore,
$\Gamma(H;\bL)$ is edge regular if and only if $m=n-3$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:55:18.055326+00:00","domain":"probability theory","id":"claim_14ffd5226a5a17d7be078304e768f5b8cb836d6dd013e68302f3cdd91c4d11dc","kind":"concept","schema_version":1,"statement":"[Theorem 10 (\cite{panchenko2005question}) of arXiv:2606.16636, 'Free energy of non-convex multi-species spin glasses with centered Ising spins'] Let
\begin{equation*}
    0=m_0\le m_1\le\cdots\le m_K=1\qquad\text{and}\qquad 0=\widehat q_0\le \widehat q_1\le\cdots\le \widehat q_K\le \widehat q_{K+1}=1.
\end{equation*}
Let $\Phi$ and $\xi$ be smooth, convex, even functions, with $\Phi$ of moderate growth. Let $z_0,\ldots,z_K$ be independent centered Gaussian random variables with
\begin{equation}
    \E z_r^2=\xi'(\widehat q_{r+1})-\xi'(\widehat q_r).
\end{equation}
Define $\Phi_{K+1}=\Phi$ and, recursively,
\begin{equation}
    \Phi_r(x)
    =
    \begin{cases}
    \displaystyle
    \frac1{m_r}
    \log \E_{z_r}e^{m_r\Phi_{r+1}(x+z_r)}, & m_r>0,\\[2mm]
    \displaystyle
    \E_{z_r}\Phi_{r+1}(x+z_r), & m_r=0.
    \end{cases}
\end{equation}
Here $\E_{z_r}$ denotes expectation over $z_r$ only. Put
\begin{equation}
    V_r(x,z_r)
    = e^{m_r(\Phi_{r+1}(x+z_r)-\Phi_r(x))}.
\end{equation}
For an external field $h\in\R$, define
\begin{equation}
    Z=h+z_0+\cdots+z_K,
    \qquad
    Z_r=h+z_0+\cdots+z_{r-1}, \qquad\text{and}\quad W_r=V_r(Z_r,z_r).
\end{equation}
For $1\le l\le K$, set
\begin{equation}

    U_l^{\mathrm P}
    =
    \E\left[
        W_1\cdots W_{l-1}
        \left(
            \E\left[W_l\cdots W_K\Phi'(Z)
            \mid z_0,\ldots,z_{l-1}\right]
        \right)^2
    \right].
\end{equation}
Then $U_l^{\mathrm P}$ is nondecreasing in each mass coordinate $m_j$, for each $j\in\{1,\dots,K\}$.

Moreover, each $\Phi_r$ is convex and even, $\Phi_r'\in\mcCp$, and the map
\begin{equation}

    g\mapsto \E_{z_r}V_r(x,z_r)g(x+z_r)
\end{equation}
sends $\mcC$ into $\mcC$ and sends $\mcCp$ into $\mcCp$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T08:33:12.350226+00:00","domain":"probability theory","id":"claim_1506408e481aa5a9f7fa8ba9237ebd06ada4d4addc857b728d0c201dc91fc493","kind":"concept","schema_version":1,"statement":"[Ppn 177 (estimates for $\barvD$ and $\barvD^\frozen$) of arXiv:2608.29416, 'Algorithmic threshold for high-dimensional projection pursuit I: general theory'] Let $\barvD$ and $\barvD^\frozen$ be as specified by Definition~\ref{d:barD}.
 For $N$ large enough, it holds for all
