{"assumptions":[],"created_at":"2026-10-27T06:48:43.520518+00:00","domain":"probability theory","id":"claim_164852958164bd99aa854759ae78d5b29a28c0d3e2ac313c5bbe00857e06c77b","kind":"theorem","schema_version":1,"statement":"[Proposition 4 of arXiv:2608.06646, 'Three-dimensional stochastic wave equation with non-Lipschitz coefficients'] Suppose the initial values $u_0$, $v_0$ and the spatial covariance function $f$ satisfy the assumptions of Theorem~\ref{T:MainTheorem}. Let $u$ be the solution to~\eqref{E:SWE}. Then, there exist constants $c,C>0$ such that for all $T>0$, $p\ge 2$, $x,y\in \R^3$, and $|x-y|\le 1$, $t\in [0,T]$, 
    \begin{equation}        
     \Norm{u(t,x)-u(t,y)}_p^2\le CM{e^{c\beta t}}|x-y|^{2{\bar{\gamma}}}\,,   
    \end{equation}
    where $\beta={\sqrt{L_{b}}+p^{\frac{1}{\overline{\nu}+1}}L_{\sigma}^{\frac{2}{\overline{\nu}+1}}}$. Here $\bar\gamma = \min\{{\alpha_1},\alpha_2,\alpha_3, \gamma_1, \gamma_2\}$, $\bar{\nu}= \min\{\nu, \nu_1, \nu_2\}$, and $L_b, L_\sigma$ are the Lipschitz constants of $b$ and $\sigma$, respectively.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T18:35:57.130256+00:00","domain":"probability theory","id":"claim_165a31fa0950348a9578fa6c88adcc250774c0c1a1cd569b6873450827f24117","kind":"concept","schema_version":1,"statement":"[Corollary twopointcor of arXiv:2604.07227, 'Transition probabilities of step-reinforced random walks'] Let $S$ be as above. Then, for any $n\geq 1$, one has $\mathbb{P}(S_{2n-1}=0)=1/2$ and 
  \begin{equation}

      e^{-C(1-\alpha)n}\alpha^n \leq 2\mathbb{P}(S_{2n}=0)-1 \leq \alpha^n,
  \end{equation}
  where $C$ is a positive constant that does not depend on $\alpha$ and $n$. In particular, for any $n\geq 1$,
  $$
  \lim_{\alpha\to 0+}\frac{\log (2\mathbb{P}(S_{2n}=0)-1) }{\log \alpha} =n, \quad  \lim_{\alpha\to 1-}\frac{\log (1-\mathbb{P}(S_{2n}=0)) }{\log (1-\alpha)} =1.
  $$ (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:31:02.826051+00:00","domain":"probability theory","id":"claim_16663172ff24a732087d0372bdc66317c695022fda5b08a1f0a3400d678e4001","kind":"theorem","schema_version":1,"statement":"[Corollary cor:defecttwolattice of arXiv:2609.01690, 'Iterated-sumset spectra: The complete exponent law and its rank geometry'] For every $h\geq2$ and $n\geq1$, the least $D$ for which some
$A\subset[0,D]^n\cap\mathbb Z^n$ with $|A|=4$ satisfies $|hA|=M_h-2$ is
\begin{equation}
 D_h=1+\binom{h+1}{2}.
\end{equation}
Consequently
\begin{equation}
 1+\binom{h+1}{2}
 \leq\nu_n(h,4)\leq\nu_1(h,4)
 \leq\max\{h^2,D_h^{\max}\}.
\end{equation}
In particular, $\nu_n(h,4)=\Theta(h^2)$ with constants uniform in $n$.
Moreover, for every $n\geq2$,
\begin{equation}
 \nu_n(h,4)>\nu_1(h,4)^{1/n}.
\end{equation}
Thus the inequality proposed in [NathansonLattice2026]
fails already for $k=4$, for every $h\geq2$ and every $n\geq2$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:49:17.501183+00:00","domain":"probability theory","id":"claim_166d050e6ef29dc42cdc6969c74c03859217973bdf55bda068c3b3e4a33b6666","kind":"lemma","schema_version":1,"statement":"[Lemma 11 of arXiv:2605.30030, 'Critical exponents for planar random-cluster model with cluster-weight~$q=4$'] Let~$\upsilon:[0,\infty)^2\rightarrow (0,\infty)$ be a function that is increasing in the first variable, decreasing in the second and that 
 satisfies the quasi-multiplicativity relation
\begin{equation*}
    \upsilon(r,\rho)\upsilon(\rho,R) \asymp \upsilon(r,R),\quad\text{for every }0< r\leq \rho\leq R.
\end{equation*}
If there is some constant~$\varsigma>0$ such that
\begin{align}
    \lim_{\eps\to0}\liminf_{N\to\infty} \frac{\log\upsilon(\eps N,N)}{\log \eps} = \lim_{\eps\to0}\limsup_{N\to\infty} \frac{\log\upsilon(\eps N,N)}{\log \eps} = \varsigma,
\end{align}   
then for any positive sequences~$(r_n)_{n\in\N}$ and~$(R_n)_{n\in\N}$ with~$\frac{R_n}{r_n} \to \infty$ as~$n \to \infty$, 
\begin{align}
    \lim_{n\to\infty}\frac{\log\upsilon(r_n,R_n)}{\log(R_n/r_n)} =-\varsigma.
\end{align}
In particular,
\begin{equation}
\lim_{N\to\infty}\frac{\log\upsilon(1,N)}{\log N}=-\varsigma.
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T08:52:08.650072+00:00","domain":"probability theory","id":"claim_166f9c7eea5dc6040ebc4713ed1879bc210d28b3f8efdf7ee3d1fdec431c6915","kind":"concept","schema_version":1,"statement":"[Theorem 1 of arXiv:2608.29940, 'Counterexamples to the site-percolation analogues\\ of the Easo--Severo--Tassion cutset th'] There exists an infinite, connected, locally finite graph $G$ with a distinguished vertex $\rho$ such that
\begin{enumerate}
  \item[(i)] $\displaystyle\inf_{z\in V(G)}\mathbb{P}_{p}(z\leftrightarrow\infty)>0$ for every $p>2^{-1/2}$, and in particular $p_c^*(G)<1$;
  \item[(ii)] $\displaystyle\mathcal{C}_G(z\leftrightarrow\infty)\ge \tfrac14$ for every $z\in V(G)$, so $G$ is uniformly transient;
  \item[(iii)] $\displaystyle\sup_{n\ge1}\bigl|\mathcal{Q}^{\mathrm{site}}_n(\rho)\bigr|^{1/n}=\infty$, and hence $\kappa^{\mathrm{site}}(G)=\infty$.
\end{enumerate}
Consequently Claims~\ref{conj:A} and~\ref{conj:B} are both false. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:29:14.939574+00:00","domain":"probability theory","id":"claim_16737192e4c6ed8714ee8e7c5c47ac2e3349d0d440c0b77ca259d55b239a9ce1","kind":"concept","schema_version":1,"statement":"[Theorem Thm2ndResult of arXiv:2606.13615, 'Data-Driven Subsampling Rates for Diffusion Parameter Estimation of SDEs'] Suppose that Assumption~(Assumptions of the paper) holds and that (equation eqGenSDEIntro of the paper) admits an invariant measure $\mu$. Let $\mathbf{X}_0 \sim \mu$ be independent of $\mathbf{W}$, let $\mathbf{X} = (\mathbf{X}_t)_{t \geq 0}$ be the corresponding solution process to (equation eqGenSDEIntro of the paper) with $d$-th component $X = (X_t)_{t \geq 0}$, and assume that the ergodicity condition (equation eqErgoCond of the paper) is fulfilled. Then it holds that
\begin{equation}

\lim_{\delta \rightarrow 0} \lim_{J \rightarrow \infty} \frac{1}{J} \sum_{j=1}^J T_{j,\delta}(X) = 2 \quad P\text{-almost surely}.
\end{equation}
Furthermore, for $\mu$-almost all $\mathbf{x} \in \mathbb{R}^d$, (equation eqStatementMainResult2 of the paper) also holds for the $d$-th component $X^{\mathbf{x}} = (X_t^{\mathbf{x}})_{t \geq 0}$ of the solution process $\mathbf{X}^{\mathbf{x}} = (\mathbf{X}_t^{\mathbf{x}})_{t \geq 0}$ with initial condition $\mathbf{X}_0^{\mathbf{x}} = \mathbf{x}$ $P$-a.s., in place of $X$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:05:37.777553+00:00","domain":"probability theory","id":"claim_167d4e18e60ff189a0dbfab2462d8e7affbcb928fc6fa20951911043b20e6da1","kind":"theorem","schema_version":1,"statement":"[Pro 2.2 of arXiv:2608.00420, '{Weighted $L^p$ solutions of scalar BSDEs with general unbounded stochastic coefficients}\'] Let $\bar\rho_t(\omega)$, $\bar\mu_t(\omega)$: $\Omega \times [0,\tau]\mapsto {\mathbb R}$ and $\bar f_t(\omega)$, $\bar\nu_t(\omega)$: $\Omega \times [0,\tau]\mapsto {\mathbb R}_+$ be four $(\mathcal{F}_t)$-progressively measurable processes satisfying $\int_{0}^{\tau}\left(|\bar\rho_t|+|\bar\mu_t|+\bar\nu_t^2\right){\rm d}t<+\infty$,
\begin{align*}
\bar\rho_t\geq \bar\mu_t+\frac{\theta}{2(p-1)}\bar\nu_t^2, \ \ t\in[0,\tau]
\end{align*}
for some constant $\theta>1$, and
$$
\mathbb{E}\left[\left(\int_0^\tau e^{\int_{0}^{t}\bar\rho_r{\rm d}r}\bar f_t{\rm d}t\right)^{p}\right]<+\infty.
$$
Assume that the generator $g$ satisfies the following assumption:
\begin{enumerate}
\renewcommand{(A)}{(A)}
\renewcommand{(A)}{(A)}
\item $\forall (t,y,z)\in[0,\tau]\times{\mathbb R}\times{\mathbb R}^d$,~ $\sgn(y)g(\omega,t,y,z) \leq \bar f_t(\omega) + \bar\mu_t(\omega)|y| + \bar\nu_t(\omega)|z|$,
\end{enumerate}
and $(y_t,z_t)_{t\in [0,\tau]}$ is an adapted solution of BSDE (equation BSDE1.1 of the paper) such that $y_\cdot\in S_\tau^{p}(\bar\rho_\cdot;{\mathbb R})$. Then there exists a constant $C_{p,\theta}>0$ depending only on $p$ and $\theta$ such that for each $0\leq r\leq t< +\infty$,
\begin{align*}
\mathbb{E}\left[\sup_{s\in[t\wedge\tau,\tau]}\left(e^{p
\int_{0}^{s}\bar{\rho}_{r}{\rm d}r}|y_s|^{p}\right)\bigg|\mathcal{F}_{r\wedge\tau}\right]\leq
C_{p,\theta}\mathbb{E}\left[e^{p\int_{0}^{\tau}\bar{\rho}_{r}{\rm d}r}|\xi|^{p}+\left(
\int_{t\wedge\tau}^{\tau}e^{ \int_{0}^{s}\bar{\rho}_r{\rm d}r}\bar{f}_s{\rm d}s\right)^{p}\bigg|\mathcal{F}_{r\wedge\tau}\right].
\end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:53:31.975035+00:00","domain":"probability theory","id":"claim_167dd7ec8e500837f1e49992b3a32cd296aa6a36b3d18ed9a5eb139e2ac58cff","kind":"concept","schema_version":1,"statement":"[Theorem 10 of arXiv:2606.11142, 'Strong invariance principles for diffusions, Markov chains and their perturbations.'] (Simplified Theorem 1.1 from \cite{Bitter}). Under the Boundedness Assumption, for every $n$ and pairs $(t_i, x), (t_j, y)$, there exists a constant $C > 0$ such that the error between the transition densities is bounded by:
\begin{equation*}
|p - p_\epsilon|(t_i, t_j, x, y) \le C \ln(e(j - i)) \cdot \Delta^{(n)} \cdot \mathcal{Q}_{S-d-6} \left( \frac{x - y}{\sqrt{t_j - t_i}} \right),
\end{equation*}
where $\Delta^{(n)} = \frac{1}{n^{\min(\gamma_2/2,\alpha_2,\beta)}} + \Delta_a + \Delta_b$, and $S$ is some number greater than $2d + 6$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

