{"assumptions":[],"created_at":"2026-10-27T06:29:21.915433+00:00","domain":"probability theory","id":"claim_1bcb9240e57332ec3dfebf31114f5bc6595433bdfc4b078e9b096723048c2b45","kind":"concept","schema_version":1,"statement":"[Theorem 4 of arXiv:2608.01419, 'A model of opinion dynamics evolving via a preferential attachment mechanism involving mul'] Consider the model described in \S\ref{subsec:model_fixed_sample_size}, and let us define $Z_{n}=(n^{-1}A_{n},n^{-1}B_{n},n^{-1}C_{n})$ for all $n\in\mathbb{N}$ with $n\geqslant N$. Fix \emph{any} $T>0$. Writing $t_{N}=0$ and $t_{n}=\sum_{N+1\leqslant i\leqslant n}i^{-1}$ for $n\geqslant N+1$, we set $m_{n}=\min\{m\geqslant n: t_{m}\geqslant t_{n}+T\}$ for each $n\in\mathbb{N}$. Recall the function $h$ as defined in \eqref{h_defn_fixed_size}. For each fixed $n\in\mathbb{N}$ with $n\geqslant N+1$, let $\{Z^{n}(t): t\geqslant t_{n}\}$, with $Z^{n}(t)=(a^{n}(t),b^{n}(t),c^{n}(t))$ for each $t\geqslant t_{n}$, indicate the solution to
\begin{equation}
\left(\dot{a}(t),\dot{b}(t),\dot{c}(t)\right)=h(a(t),b(t),c(t)) \text{ for all }t\geqslant t_{n}, \text{ with } \left(a(t_{n}),b(t_{n}),c(t_{n})\right)=\left(n^{-1}A_{n},n^{-1}B_{n},n^{-1}C_{n}\right),\nonumber
\end{equation}
and let 
\begin{equation}
W_{j}=(j+1)^{-1/2}\left\{\left(j^{-1}A_{j},j^{-1}B_{j},j^{-1}C_{j}\right)-\left(a^{n}(t_{j}),b^{n}(t_{j}),c^{n}(t_{j})\right)\right\} \text{ for each }j\geqslant n.\nonumber
\end{equation}
We now define the process $\{W^{n}(t):t\in [t_{n},t_{n}+T]\}$ by linear interpolation, as follows: 
\begin{equation}
W^{n}(t)=W_{j}+\frac{t-t_{j}}{t_{j+1}-t_{j}}(W_{j+1}-W_{j}) \text{ for }t\in[t_{j},t_{j+1}], \text{ for each }j\in\{n,n+1,\ldots,m_{n}-1\}.\nonumber  
\end{equation}  
Finally, we set $\tilde{W}^{n}(t)=W^{n}(t_{n}+t)$ for all $t\in[0,T]$. Likewise, we define $\tilde{Z}^{n}(t)=Z^{n}(t_{n}+t)$ for all $t\in[0,T]$. Then the laws of the processes $\{(\tilde{Z}^{n}(\cdot),\tilde{W}^{n}(\cdot))\}_{n\in\mathbb{N}}$ are relatively compact in the space $\mathcal{P}(C([0,T];\mathbb{R}^{3}))^{2}$, where $C([0,T];\mathbb{R}^{3})$ is the set of all continuous functions from $[0,T]$ to $\mathbb{R}^{3}$ and $\mathcal{P}(C([0,T];\mathbb{R}^{3}))^{2}$ is the space of all probability measures on $C([0,T];\mathbb{R}^{3})\times C([0,T];\mathbb{R}^{3})$.

If a subsequence of $\{(\tilde{Z}^{n}(\cdot),\tilde{W}^{n}(\cdot))\}_{n\in\mathbb{N}}$ converges in law to a limiting process $\{z^{*}(\cdot),w^{*}(\cdot)\}$, then $z^{*}(\cdot)$ belongs to a compact, connected, internally chain transitive invariant set corresponding to the ODE described by \eqref{ODE_fixed_sample_size}, and, letting $J_{h}$ denote the Jacobian of $h$, each of
\begin{multline}
w^{*}(t)-\int_{0}^{t}\left\{J_{h}\left(z^{*}(s)\right)+\frac{1}{2}I_{3}\right\}w^{*}(s)ds \quad \text{and}\quad \left[w^{*}(t)-\int_{0}^{t}\left\{J_{h}\left(z^{*}(s)\right)+\frac{1}{2}I_{3}\right\}w^{*}(s)ds\right]\\\left[w^{*}(t)-\int_{0}^{t}\left\{J_{h}\left(z^{*}(s)\right)+\frac{1}{2}I_{3}\right\}w^{*}(s)ds\right]^{T}-\int_{0}^{t}Q\left(z^{*}(s)\right)ds,\nonumber
\end{multline}
is a martingale for all $t\in[0,T]$, where $Q:\mathcal{S}\rightarrow\mathbb{R}^{3\times 3}$ is a matrix-valued function with entries given by
\begin{equation}
\begin{cases}
&Q_{1,1}(a,b,c)=H_{1}(a,b,c)\{1-H_{1}(a,b,c)\},\\
&Q_{1,2}(a,b,c)=Q_{2,1}(a,b,c)=H_{2}(a,b,c)\{1-H_{1}(a,b,c)\},\\
&Q_{2,2}(a,b,c)=H_{4}(a,b,c)-H_{2}^{2}(a,b,c),\\
&Q_{1,3}(a,b,c)=Q_{3,1}(a,b,c)=H_{2}(a,b,c)-H_{1}(a,b,c)H_{3}(a,b,c),\\
&Q_{2,3}(a,b,c)=Q_{3,2}(a,b,c)=H_{4}(a,b,c)-H_{2}(a,b,c)H_{3}(a,b,c),\\
&Q_{3,3}(a,b,c)=kq_{\beta}(a,b,c)\{1-q_{\beta}(a,b,c)\}+k^{2}\{1-q_{\beta}(a,b,c)\}^{2}-k^{2}H_{1}(a,b,c)\\&+2k H_{2}(a,b,c)-H_{3}^{2}(a,b,c),
\end{cases}
\end{equation}
with $H_{1}$, $H_{2}$ and $H_{3}$ as defined in \eqref{H_{1}_defn}, \eqref{H_{2}_defn} and \eqref{H_{3}_defn}, and $H_{4}:\mathcal{S}\rightarrow[0,k^{2}]$ defined as
\begin{equation}
H_{4}(a,b,c)=\sum_{i\in[k]}i^{2}g\left(\frac{i}{k}\right){k\choose i}q_{\beta}(a,b,c)^{i}\{1-q_{\beta}(a,b,c)\}^{k-i} \text{ for } (a,b,c)\in\mathcal{S},_defn}
\end{equation}
where $\mathcal{S}$ is as defined in \eqref{domain_defn} and $q_{\beta}(\cdot,\cdot,\cdot)$ is as defined in \eqref{q_defn}. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

