{"assumptions":[],"created_at":"2026-10-27T20:36:16.061464+00:00","domain":"probability theory","id":"claim_1be3974650e11639a08dd8760b35e05f91ef2c6ad75afdcd34c3305e63845030","kind":"theorem","schema_version":1,"statement":"[Thm exact ruin  for the collective model of arXiv:2606.28031, 'Insurance risk models in a heterogeneous time-dependent population: scaling limits and rui'] Assume:
\begin{enumerate}
\item[{\em (1)}] {the Cram\'er condition (equation cram of the paper) applies};
\item[{\em (2)}] there exists a deterministic $\ell_\alpha$ such that 
\[
\ell_\alpha = \lim_{t \to \infty} \frac{k_\alpha(t)}{t} \quad \text{almost surely, for all } \alpha \in [0, \overline{\alpha}];
\]
\item[{\em (3)}] $\alpha_*:=\sup\BRA{\alpha>0 :\ell_{\alpha}=0}\in (0, \overline{\alpha})$.
\end{enumerate}

Then, the ruin probability $p(u)$ is positive and satisfies, for any $\alpha \in (\alpha_*, \overline{\alpha}]$,
\begin{equation*}
p(u) = \frac{1}{\mathbb{E}\big[{\mathrm e}^{-\alpha V(\tau(u)) - k_{\alpha}(\tau(u))} \,\big|\, \tau(u) < \infty\big]}.
\end{equation*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:47:22.251437+00:00","domain":"probability theory","id":"claim_1be427dd1d3ea6c2f6d2eefacb7503561e190448be5ecec0cf54823d2481ee67","kind":"definition","schema_version":1,"statement":"[Definition 63 of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] Define  the cell $\mathfrak Y \subset \bar{\mathfrak{X}}$ centered at $z_0$ by
  \begin{flalign}

    \begin{aligned}
  \mathfrak{Y} = \bigg\{ z \in \overline{\mathfrak{X}} : & \dist_{\bm{u}_{z_0;q}} (z, z_0) \le q^{-1/2} N^{(\frac34 A-\frac12)\delta -1/2} (\md_{z_0}\me_{z_0;q})^{-1/4},\\
  &  \dist_{\bm{w}_{z_0;q}} (z, z_0) \le q^{-1/2} N^{(\frac34A-\frac12)\delta -1/2} (\md_{z_0}\me_{z_0;q})^{1/4} \bigg\}.
  \end{aligned}
	\end{flalign} 

\noindent Further define $\mathfrak{Y}^- \subset \mathfrak{X}$ by  $\mathfrak{Y}^-=(1/L)\cdot(\mathfrak{Y}-z_0)+z_0$ (namely, to be its shrinking by a factor $L$), where $L$ is a sufficiently large constant that depends only on the constant $C$ in \Cref{prop:last}.","status":"unverified"}

