{"assumptions":[],"created_at":"2026-10-27T08:02:08.139023+00:00","domain":"probability theory","id":"claim_1c26924263c227b19d324d61112d372a6a8a195ecd35ccc39722481b7c66ddc9","kind":"concept","schema_version":1,"statement":"[Lemma 18 of arXiv:2608.27569, 'Laplace and Dolbeault operators on Sasakian manifolds'] On the $\left( 2n+1\right) $-dimensional
Sasakian manifold with Lefschetz operator $L$ and adjoint $\Lambda $ and operator $H$, we have for all positive integers $b$, 
\begin{align*}
[L^{b},H] &= 2bL^{b}, \\
[L^{b},\Lambda] &= (-bH-b(b-1))L^{b-1}.
\end{align*}
As a consequence, the map $L^b:\Omega^m\to \Omega^{m+2}$ is injective for $m\leq n-b$ and $\Lambda^b:\Omega^m\to \Omega^{m-2}$, for $m\geq n+2b$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:54:34.576472+00:00","domain":"probability theory","id":"claim_1c2af14b72b81a95b8f47b0098c9dcb49989fe55d74fb18f69597d4426f3aa3d","kind":"concept","schema_version":1,"statement":"[Lemma 5 of arXiv:2606.14812, 'Joint convergence in Wiener chaos via transport hierarchy and Malliavin covariances'] Let $ (X_{N}= I_{p} (f_{N}), N\geq 1)$ with $p\geq 2$ satisfying (\ref{c1}). 

		\begin{enumerate}
			\item Let $ (Y_{N}=I_{p}(g_{N}), N\geq 1) $ be a sequence of random variables which converges in $ L ^{2}(\Omega)$.  Assume that there exists $\rho \in \mathbb{R}$ such that
			\begin{equation}
				\mathbf{E}[ X_{N} Y_{N} ]\to _{N \to \infty} \rho. 
			\end{equation}
			Then 
			\begin{equation*}
				\langle  DX_{N}, DY_{N} \rangle _{ H ^{\otimes p}} \to _{N \to \infty} p\rho \mbox{ in } L ^{2}(\Omega). 
			\end{equation*}
			\item Let $ (Y_{N}=I_{q}(g_{N}), N\geq 1) $ be a sequence of random variables in the $q$ th Wiener chaos such that $q<p$. Assume that $(Y_{N}, N\geq 1)$ is bounded in $ L ^ {2}(\Omega)$. Then 
			\begin{equation*}
				\langle  DX_{N}, DY_{N} \rangle _{ H ^{\otimes p}} \to _{N \to \infty} 0 \mbox{ in } L ^{2} (\Omega). 
			\end{equation*}

		\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T15:27:25.781941+00:00","domain":"probability theory","id":"claim_1c2e81ef7af9f64e0a5e934add92e2933b1926745e0a4bbf00787c1a2f3bf040","kind":"concept","schema_version":1,"statement":"[Thm main of arXiv:2605.08052, 'Rapid phase ordering of Ising dynamics on $\mathbb Z^2$'] There exists $p_0<1$ such that for all $p>p_0$ and all $\beta>\beta_c(2)$ the following holds. 

\smallskip
\noindent \textbf{Finite volume.}  Suppose $X_t$  is the continuous-time Ising Glauber dynamics on $\mathbb{T}_n^2$ initialized from $x_0 \sim \bigotimes_{\mathbb{T}^2_n} Rad(p)$. With probability $1-o(1)$, $x_0$ is such that 
\begin{align*}
    \|\mathbb P_{x_0}( X_t\in \cdot ) - \pi_{\mathbb{T}_n^2}^+ \|_{{\textsc{tv}}} \le n^{-10} \qquad \text{for all }t\in [n^{o(1)} ,  e^{\Omega(n)}]\,.
\end{align*}
\textbf{Infinite volume.} If $X_t$ is the continuous-time Glauber dynamics on all of $\mathbb Z^2$ initialized from $x_0 \sim \bigotimes_{\mathbb Z^2} \text{Rad}(p)$, then with probability going to $1$ as $R\to\infty$, $x_0$ is such that for $\Lambda_R = \{-\frac{R}{2},...,\frac{R}{2}\}^2$, for all $t \ge R$, we have 
\begin{align*}
        \|\mathbb P_{x_0}(X_t(\Lambda_R)\in \cdot) - \pi^+_{\mathbb Z^2}(\sigma(\Lambda_R)\in \cdot)\|_{{\textsc{tv}}} \le \exp( - \Omega((\log t)^{10}))\,.
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T09:36:31.236761+00:00","domain":"probability theory","id":"claim_1c36138eb74a7506b05e274c05d73785137d9631d01c68153620af5f12a596e0","kind":"theorem","schema_version":1,"statement":"[Proposition 33 of arXiv:2609.00567, 'Hodge--Tate splitting and Akizuki--Nakano vanishing in positive characteristic'] Let $f \colon Y \to X$ be a qcqs morphism of qcqs $\F_p$-schemes.
