				&\times  \left(\lambda^{2k} t^{2k\nu} E_{\nu, 2k\nu+1}^{k+1, k+1}(p_1 t^\nu, p_2 t^\nu) + \lambda^{2k+1} t^{(2k+1)\nu} E_{\nu, (2k+1)\nu+1}^{k+1, k+1}(p_1 t^\nu, p_2 t^\nu)\right),
	\end{align}		
