{"assumptions":[],"created_at":"2026-10-27T17:18:19.437536+00:00","domain":"probability theory","id":"claim_1e689087fb5669c17523a148063c77b83f51a5664904cd183e948a43f8965218","kind":"definition","schema_version":1,"statement":"[Definition def:inhomo of arXiv:2508.17838, '\bf Edge Universality for Inhomogeneous Random Matrices'] Let $W_N$ be an $N\times N$ real symmetric (or complex Hermitian) Wigner matrix, let $\Sigma_N$ be a deterministic variance-profile matrix and $A_N$ be a finite-rank perturbation.  Define
\begin{equation} 
H_N=\Sigma_N \circ W_N,  
\end{equation}
where “\(\circ\)” is the Hadamard (entrywise) product, and the corresponding deformed inhomogeneous random  matrix
\begin{equation}
    X_N=H_N+A_N.
\end{equation}
Here,  the following conditions are assumed: 

\begin{enumerate}[leftmargin=*,label=(A\arabic*)]
  \item  \textbf{(Wigner matrix)}  
    The entries $\{W_{ij}\}_{i\le j}$ are independent, symmetric, and satisfy
    \begin{equation}
      \begin{cases}
        \mathbb{E}[W_{ii}^2]=2,\;\mathbb{E}[W_{ij}^2]=1, & \text{real 
        case},\\
        \mathbb{E}[W_{ii}^2]=1,\;\mathbb{E}[|W_{ij}|^2]=1,\;\mathbb{E}[W_{ij}^2]=0, & \text{complex 
        case}.
      \end{cases}
    \end{equation}
    Moreover, there exists $\theta\ge 1$ such that for all $k\ge2$,
    \begin{equation}
      \mathbb{E}\bigl[|W_{ij}\bigr|^{2k}]
      \;\le\;
      \theta^{\,k-1}(2k-1)!!,
     \end{equation}
    where  $\theta:=\theta_N\rightarrow\infty$ may be  allowed   if needed. 
  \item  \textbf{(Variance profile)}  
    The profile matrix $\Sigma_N=(\sigma_{ij})$ has nonnegative entries such that 
    \(\sum_{j=1}^N\sigma_{ij}^2=1\) for each~$i$.  Equivalently, 
    $P_N:=(\sigma_{ij}^2)_{i,j=1}^N
    $ is a Markov transition matrix.

  \item  \textbf{(Finite-rank deformation)}  
    The perturbation $A_N$ is symmetric (resp.\ Hermitian) of rank $r$, with spectral decomposition
    \begin{equation}
        A_N = Q\,\Lambda\,Q^*, 
      \qquad
      \Lambda = \mathrm{diag}(a_1,\dots,a_r,0,\dots,0),
    \end{equation}

    where $Q$ is an orthogonal (resp.\  unitary) matrix.  
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:09:43.679254+00:00","domain":"probability theory","id":"claim_1e7310c214d8c8cf041dcd2baa6f441d51fe335244e555fbf30fd446a90a1f83","kind":"definition","schema_version":1,"statement":"[Defn d.moment-function of arXiv:2605.28430, 'Limit theory for Lipschitz-localized statistics in random geometric models'] \ 
We say that $\xi : \mathbb{R}^d \times \mathbb{K} \times \hat{\mathcal{N}}_{\mathbb{R}^d \times \mathbb{K}} \to \mathbb{R}$ satisfies a $p$-moment condition with respect to $\tilde{\mathcal{P}}$ 
 on {\em  finite windows}
 if $\xi( \tilde{x}_i, \tilde{\mathcal{P}}_n )$
satisfy  the $p$-moment condition~(equation e:xinpmom of the paper), that is to say

\begin{equation}

\sup_{1 \leq n< \infty} \sup_{1 \leq q \leq p} \sup_{x_1,\ldots,
  x_{q} \in W_n} \mathbb {E} _{\bk x1{q}}[ \max(1,|\xi(\tilde{x}_1, \tilde{\mathcal{P}}_n )|^p)]
\leq M_p^{\xi} < \infty.
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:50:48.852760+00:00","domain":"probability theory","id":"claim_1e758f10d6cd483c238c172121d991eecd09f7a174d4a056ce130280ac0ca3f6","kind":"theorem","schema_version":1,"statement":"[Theorem thm:stat.dist.alpha>0.beta>lambda0 of arXiv:2607.10708, 'A class of Markov processes with resetting and applications to cybersecurity'] Let $X=(N,\Lambda,C)$  be a self-exciting PDMP with resetting and $Y=(N,\Lambda)$. Under Assumption (a:finitereset of the paper) holds and with $\alpha>0\ \&\  \beta>{\lambda^o}$, $Y$ has invariant measure $\Pi$ on $\mathbb N_0\times[{\lambda^o}, A)$, given by the following:

\begin{equation} 
    \Pi(n, d\lambda)=\pi(n,\lambda)d\lambda 

\end{equation}
    whose density is defined as

\begin{equation} 
  \begin{split}
    \pi(0,\lambda)=&\mathds{1}_{\{\lambda <\beta\}}\frac{K_0}{\alpha  (\beta -{\lambda^o})} \left(\frac{\beta -\lambda }{\beta -{\lambda^o}}\right)^{\frac{\beta -\alpha }{\alpha }} e^{\frac{\lambda - {\lambda^o}}{\alpha}},\\
    \pi(n,\lambda)=&\mathds{1}_{\{\lambda<\beta\}}\frac{1}{F(\lambda)}\int_{{\lambda^o}}^{\lambda} \frac{F(y)p(n-1,y)}{\alpha(\beta-y)}dy\\
    &+\mathds{1}_{\{\lambda\geq \beta\}}\frac{1}{F(\lambda)}\int_{\lambda}^{A} \frac{F(y)p(n-1,y)}{\alpha(y-\beta)}dy, \quad n\geq 1.
  \end{split}

\end{equation}
  For $n\ge 0$, 

\begin{equation} 
    p(n,\lambda) = \int \mathds{1}_{\{u+{\lambda^o}<\lambda\}} (\lambda-u) \pi(n,\lambda-u)\,dG_{\ell}(n+1, u),

\end{equation}

\begin{equation} 
    F(\lambda)=\exp(-\frac{\lambda}{\alpha})|\lambda-\beta|^{\frac{\alpha-\beta}{\alpha}},

\end{equation}
  and $K_0=\sum_{n=1}^\infty \int_{[{\lambda^o},A)} \lambda \bar{G}_{\ell}(n, (A-\lambda) \textrm{-}) \Pi(n-1, d \lambda)$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:09:43.678254+00:00","domain":"probability theory","id":"claim_1e7ef5174aea066a6e4d3b505bd1a2983e79e259c8da1e976995c044dbfd96af","kind":"definition","schema_version":1,"statement":"[Defn d.omegatmixing of arXiv:2605.28430, 'Limit theory for Lipschitz-localized statistics in random geometric models'] \ 
 \begin{enumerate}[wide,label=(\roman*),labelindent=0pt]
\item  The  marks $U$ of the point process $\tilde \mathcal{P}=\sum_{x \in \mathcal{P}}
  \delta_{\tilde{x}}$, $\tilde{x}=(x,U)$, $x\in\mathbb{R}^d$,  $U\in\mathbb{K}$,
satisfy  {\em $\textnormal{BL}$-mixing correlations} if
there exists an increasing-decreasing family of  functions $\omega_k :  [0, \infty) \to [0,2]$, $k \in \mathbb{N}$, called correlation decay functions,  such that for all $p,q \in \mathbb{N}, x_1,\ldots,x_{p+q} \in \mathbb{R}^d$, and all $f \in \textnormal{BL}(\mathbb{K}^p)$, and
  $g \in \textnormal{BL}(\mathbb{K}^q)$ we have

\begin{align} 
\left|\mathbb {E} _{\bk x1{p+q}}[f(\bk U1{p})g(\bk U{p+1}{p+q})] - \mathbb {E} _{\bk x1p}[f(\bk U1p)]\mathbb {E} _{\bk x{p+1}{p+q}}[g(\bk U{p+1}{p+q})]\right|\le \omega_{p+q}(s),
\end{align}

where $s := d(\bk x1p,\bk x{p+1}{p+q})$ is at (equation defs of the paper).

\item  The marks $U$ have  {\em fast $\textnormal{BL}$-mixing correlations} if $(\omega_k)_{k \in \mathbb{N}}$ are fast decreasing.

\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:21:52.429260+00:00","domain":"probability theory","id":"claim_1e83419c8a89d3202890070c042121eb79b78262a444488eea3650408c6f6897","kind":"theorem","schema_version":1,"statement":"[Proposition 194 of arXiv:2601.16377, '2601.16377'] For each $q\in[m]$, $k \geq 1$ and $x\in [-\hat{W}_q,0]$, the random variables
 \begin{equation}

 \int_{\amsmathbb{R}} \left(\mathsf{Ht}^{(q)}_\N(\N^{-1}\lfloor x \N \rfloor, y)-\E\big[\mathsf{Ht}^{(q)}_\N(\N^{-1}\lfloor x \N \rfloor, y)\big]\right) y^k\dd y
 \end{equation}
 are asymptotically Gaussian (in the sense that the joint moments of these random variables converge towards expressions satisfying the Wick formula) with asymptotic covariance for the triplets $(k_1,q_1,x_1)$ and $(k_2,q_2,x_2)$ given by
 \begin{equation}

 \frac{1}{\pi} \int_{\{y_1 \mid (x_1,y_1)\in\pounds_{q_1}\}}\int_{\{y_2 \mid (x_2,y_2)\in\pounds_{q_2}\}} \mathrm{Gr}\big(z^{(q_1)}(x_1,y_1),z^{(q_2)}(x_2,y_2)\big)\,y_1^{k_1}y_2^{k_2}\dd y_1\dd y_2,
 \end{equation}
 where the maps $z^{(q)}$ are as in Section~\ref{Section_complex_structure}.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:19:06.721730+00:00","domain":"probability theory","id":"claim_1ea0ae358e37584eb81de78ce62dfa2e6243463f9aabcd3275b9fb382501dc00","kind":"concept","schema_version":1,"statement":"[Theorem thm2.2 of arXiv:2606.01944, 'Propagation of Chaos for Mean-field Mean Reflected Backward Stochastic Differential Equati'] Under Assumptions (H1)-(H4), the mean-field mean reflected BSDE associated with $(\xi,f,h)$ admits a unique solution $(Y,Z,K)\in \mathcal{S}^2\times\mathcal{H}^2\times I[0,T]$. Moreover, for each $t\in[0,T]$, we have 
 \begin{align*}
     K_T-K_t=\sup_{s\in[t,T]}L_s(\bar{Y}_s), 
 \end{align*}
 where
 \begin{align*}
