{"assumptions":[],"created_at":"2026-10-26T19:36:04.989600+00:00","domain":"probability theory","id":"claim_26c4265b248877e53409cb8d8080ae16e437bd1df9e2b6dd73a51d6520ccb548","kind":"concept","schema_version":1,"statement":"[Theorem 4 (\cite{DovOrsToaldo}) of arXiv:2604.00882, 'On some extensions of generalized counting processes'] {The density $\ell_\nu(x,t)$ of the process $\mathcal{L}^\nu(t)$, $t > 0$, solves the time-fractional boundary-initial problem}
	\begin{equation}
		\begin{cases}
			\left( \mathbb{D}_t^{2\nu} + 2\lambda \mathbb{D}_t^{\nu}\right) \ell_\nu(x,t) = -\frac{\partial}{\partial x} \ell_\nu(x,t), \quad x > 0,\,\, t > 0,\,\, 0 < \nu < \frac{1}{2}, \\
			\ell_\nu(x,0) = \delta(x), \\
			\ell_\nu(0,t) = \frac{t^{-2\nu}}{\Gamma(1-2\nu)} + 2\lambda \frac{t^{-\nu}}{\Gamma(1-\nu)},
		\end{cases}
	\end{equation}

	{and has $x$-Laplace transform, for $0 < \gamma < \lambda^2$,}
	\begin{equation}
		\widetilde{\ell}_\nu(\gamma, t) = \frac{1}{2} \left[ \left( 1 + \frac{\lambda}{\sqrt{\lambda^2 - \gamma}} \right) E_{\nu,1} (r_1 t^\nu) + \left( 1 - \frac{\lambda}{\sqrt{\lambda^2 - \gamma}} \right) E_{\nu,1} (r_2 t^\nu) \right],
	\end{equation}

	{where}
	\begin{equation}
		r_1 = -\lambda + \sqrt{\lambda^2 - \gamma}, \quad r_2 = -\lambda - \sqrt{\lambda^2 - \gamma}.
	\end{equation}

	{The fractional derivatives appearing in \eqref{2.20} are  in the Riemann-Liouville sense.} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:45:07.257460+00:00","domain":"probability theory","id":"claim_26e97123184dfd5b70a0f7bc3a92a03de4da326677a84b2cdf021b0b9980575d","kind":"definition","schema_version":1,"statement":"[Definition 5 of arXiv:2604.19308, '\textbf{On McKean--Vlasov SDEs with polynomial drifts for SIS epidemic models}'] Let $I$ be a solution to~\eqref{eq:SIS epidemic model} with positive paths and $\rho,x_{0} > 0$.
\begin{enumerate}[(i)]
\item We say that $I$ becomes \emph{extinct with exponential rate $\rho$} if 
\begin{equation}
\limsup_{t\uparrow\infty} \frac{1}{t^{\rho}}\log(I_{t}) < 0\quad\text{a.s.}
\end{equation}
In the case $\rho = 1$ we will simply say that $I$ becomes \emph{exponentially extinct}.

\item The solution $I$ is said to \emph{persist above $x_{0}$} if $\limsup_{t\uparrow\infty}I_{t}\geq x_{0}$ a.s. Furthermore, \emph{persistence around $x_{0}$} holds for $I$ if
\begin{equation}
\liminf_{n\uparrow\infty} I_{t} \leq x_{0} \leq \limsup_{t\uparrow\infty}I_{t} \quad\text{a.s}
\end{equation}
\end{enumerate}","status":"unverified"}

