{"assumptions":[],"created_at":"2026-10-27T10:42:55.313517+00:00","domain":"probability theory","id":"claim_29268581be61e0e19fe4f6ab2f0fc5b2e691120b9aed9f6933311366591c895a","kind":"lemma","schema_version":1,"statement":"[Lem 8 of arXiv:2609.02398, '\textbf{Convex Order Comparisons for Sub-Gamma Random Variables}'] For all $p \in (0, 1/2]$,
