{"assumptions":[],"created_at":"2026-10-27T19:48:47.286861+00:00","domain":"probability theory","id":"claim_2b7a2ca88c3af46489d18456ae808b15eefe3fa465bbbaf6de495531beca8f29","kind":"lemma","schema_version":1,"statement":"[Lemma optnprefix of arXiv:2604.20660, 'The Legendre structure of the TAP complexity\\ for the Ising spin glass'] Let $n\geq 2$ and let $(u_i)_{1\leq i\leq n}$ and $(q_i)_{1\leq i\leq n}$ be strictly increasing sequences of numbers in $(0,1)$. Let $\zeta\in \mathrm{Prefix}_{n+1}((u_i)_{1\leq i\leq n},(q_i)_{1\leq i\leq n})$ where $\mathrm{Prefix}_{n+1}$ is as in Definition (def:nprefix of the paper). Suppose that $\zeta$ satisfies the assumptions of Proposition (prop:annealed cond of the paper). Let $(X_t)_{t\in [0,1]}$ be the Auffinger--Chen process
		\begin{equation*}
			\begin{cases}
				\mathrm{d} X_t=\xi''(t)\zeta([0,t])\partial_x \Phi_\zeta(t,X_t)\mathrm{d} t+\sqrt{\xi''(t)} \mathrm{d} B_t\\
				X_0=0.
			\end{cases}
		\end{equation*}
		For every $s\in [0,1]$, set
		\begin{equation*}
			H_\zeta(s):=\frac{1}{2}\int_s^1 \xi''(r)\Bigl(\mathbb{E}[(\partial_x\Phi_\zeta(r,X_r))^2]-r\Bigr)\mathrm{d} r.
		\end{equation*}
		Then, the following hold:
		\begin{enumerate}
			\item For every $k\in [n-1]$,
			\begin{equation}
				-\mathbb{E}[\Phi_\zeta(q_k,X_{q_k})]+\frac{1}{2}\int_0^1 t\xi''(t)\zeta([0,t])\mathrm{d} t +\frac{1}{2}\int_0^{q_k}t\xi''(t) \zeta([0,t])\mathrm{d} t=-\mathcal{P}\mathrm{arisi}(\zeta),
			\end{equation}
			\item   \begin{equation}
				-\mathbb{E}[\Phi_\zeta(q_n,X_{q_n})]+\frac{1}{2}\int_0^1 t\xi''(t)\zeta([0,t])\mathrm{d} t +\frac{1}{2}\int_0^{q_n}t\xi''(t) \zeta([0,t])\mathrm{d} t=-f,
			\end{equation}
			\item For every $k\in [n]$,
			\begin{equation}
				\mathbb{E}[(\partial_x\Phi_\zeta(q_k,X_{q_k}))^2]=q_k,
			\end{equation}
			\item  \begin{equation}
				\mathrm{supp}(\zeta)\cap [q_n,1]\subset \underset{[q_n,1]}{\mathrm{arg\,min}}(H_\zeta).
			\end{equation}
		\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:59:25.042252+00:00","domain":"probability theory","id":"claim_2b7b189856f4b2612b0c039d28a40c1280d95977254bd7344a3a9194bf3f0691","kind":"theorem","schema_version":1,"statement":"[Proposition 22 of arXiv:2606.31596, 'The Invariant Measure of Multiscale Markov Chains via Fast Arborescence Factorization'] Let $U:X\times\T^{n}\to\R$ be a potential of regularity class $C^2$ with respect to $y\in\T^{n}$. $X$ finite set. $\beta_1,\beta_2>0$.

Let $\frac{1}{h}\in\N$ and $Y_h:=\{0,h,2h,\dots,1-h\}^{n}$ a discrete set of points in $\T^{n}$ with uniform spacing. Define the edge set $E_h:=\{(y,y')\in Y_h\times Y_h\,|\,\exists\,i:\, y_i'=y_i\pm h,\ y_j'=y_j\,\forall\,j\neq i \}$ with rates
\begin{equation} 
	r_x(y,y') \,:=\, e^{-\frac{1}{2}\beta_2\,(U(x,y')-U(x,y))} 

	\,,\quad  (y,y')\in E_h \,.
\end{equation}

Then:
\begin{itemize}

\item[i)] the rates $r_x(y,y')$ are reversible with respect to the measure $\widetilde\nu_x(y)$ defined by \eqref{eq:nuXYsimple};\\

\item[ii)] the effective rates $\bar r(y,y')$ defined by \eqref{eq:weff2},\eqref{eq:Gibbs} are approximately reversible with respect to the effective Gibbs measure $\bar\mu(y)$ defined by \eqref{eq:effGibbs}, precisely:

\begin{equation}
 \bar\mu(y)\; \bar r(y,y') - \bar\mu(y')\; \bar r(y',y) \,=\, O(h^2)\;\bar\mu(y)\,\bar r(y',y) \,.
\end{equation}
\end{itemize}

\begin{comment}
As a consequence the two-scale dynamics $r_N$ defined by \eqref{diffr} has limiting invariant measure
\begin{equation}
\lim_{N\to\infty}\pi_N(x,y) \,=\, \bar\pi(M_y)\, \mu_y(x)\,,\quad (x,y)\in X\times Y_h
\end{equation}
with
\begin{equation}
\bar\pi(M_y) \,=\, \bar\mu(y) \,+ O(h^2)\,\bar\mu(y)\,,\quad y\in Y_h \,.
\end{equation}
\end{comment}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:41:19.335182+00:00","domain":"probability theory","id":"claim_2b849658cb704b18489db0ae676caad4452cce056f6044e5438ebfc29ac27909","kind":"lemma","schema_version":1,"statement":"[Lemma lem:good_convergence of arXiv:2609.04138, 'The conformally invariant metric on $\CLE_4$ I:\\ subsequential limits of the non-simple C'] Jointly with~(equation eq cv subsequence of the paper),~(equation eq cv Hausdorff balls of the paper) and~(equation eq cv subsequence boundary of the paper), for all $t \in \BQ_{\ge 0}$, $x \in \BD_\BQ$, $\alpha \in \SCS'$, along a subsequence again denoted by $(\kappa_n)_{n \ge 0}$, we have
