{"assumptions":[],"created_at":"2026-10-27T07:27:14.875412+00:00","domain":"probability theory","id":"claim_2ba6c71d75e35d66f94333b79d1fb09e362f62e55e6cf2a6babca6e622d6bf02","kind":"lemma","schema_version":1,"statement":"[Lemma 15 of arXiv:2608.23462, '2608.23462'] Suppose that Assumption~\ref{assu:frozenLipschitz} holds, that $g$ and $\sigma_k$, $k=1,\dots,d_2$, are continuously differentiable in $x \in \R^{d_1}$ as well as in $y\in \R^{d_2}$, and that the mixed second-order derivatives $D^2_{y,x} g$ and $D^2_{y,x} \sigma_k$ exist. Assume moreover that $D_x g$, $D_x \sigma_k$, $D_y g$, $D_y \sigma_k$, $D^2_{y,x} g$, and $D^2_{y,x} \sigma_k$ are jointly continuous and uniformly bounded on $\R^{d_1+d_2}$.
    Then the mapping $(x,y) \mapsto \hat{Y}^{x,y}$ is differentiable in $x$ in the sense that there is a family of processes $D_x \hat Y^{x,y} v$ indexed with $x,v\in \R^{d_1}$, $y\in \R^{d_2}$ satisfying
    \begin{align} 
        \lim\limits_{h \to 0} &\hat{\E} \bigg[ \sup_{t \in [0,T]} \bigg| \frac{\hat{Y}^{x + hv,y}_t - \hat{Y}^{x,y}_t }{h} -D_x \hat{Y}^{x,y}_t v\bigg|^2 \bigg] = 0
    \end{align}
    for any finite $T >0$ where the first-order derivative flow $D_x \hat{Y}^{x,y} v$ is an instance of the general dynamics
    \begin{align} 
        \begin{cases}
        d \zeta^{x,y,z,v}_t = D_x g(x,\hat{Y}^{x,y}_t) v dt + D_y g(x,\hat{Y}^{x,y}_t) \zeta^{x,y,z,v}_t dt \\ \qquad \qquad \qquad + \sum_{k=1}^{d_2} \Big( D_x \sigma_k(x,\hat{Y}^{x,y}_t) v + D_y \sigma_k(x,\hat{Y}^{x,y}_t) \zeta^{x,y,z,v}_t \Big) d \hat{W}^k_t, \\
        \zeta^{x,y,z,v}_0 = z \in \R^{d_2}
        \end{cases}
    \end{align}
    for $z=0$, i.e. $D_x \hat{Y}^{x,y} v = \zeta^{x,y,0,v}$. Moreover for each $p \geq 2$ and finite time horizon $T > 0$, the process is uniformly bounded in $x,y$, i.e. there exists $C_{p,T}> 0$ with
    \begin{align*}
        \hat\E \Big[ \sup_{0\leq t \leq T}|\zeta^{x,y,z,v}_t|^p \Big] &\leq C_{p,T}( |v|^p + |z|^p )
    \end{align*}
    for $x,v \in \R^{d_1}$, $y,z \in \R^{d_2}$ and continuous in $x,y$ with respect to convergence in $L^p$, i.e.
    \begin{align*}
        \lim\limits_{(x',y') \to (x,y)} &\hat{\E} \Big[ \sup_{t \in [0,T]} | \zeta^{x',y',z,v}_t - \zeta^{x,y,z,v}_t|^p \Big] = 0.
    \end{align*}
    for $x,v \in \R^{d_1}$, $y,z \in \R^{d_2}$. Additionally, if $\hat Y^{x}$ is $p$-dissipative for $p \geq 2$ with constant $\beta > 0$, then there exists $ C_{\beta,p}^{(1)},C_{\beta,p}^{(2)} > 0$ with
    \begin{align*}
        \|\zeta^{x,y,z,v}_t\|_{L^p} \leq \{ e^{-(p\beta /2)t}|z|^p + C_{\beta,p}^{(1)}|v|^p \}^{1/p} \leq e^{-(\beta  /2)t} |z| + C_{\beta,p}^{(2)}|v|
    \end{align*}
    for all $x,v \in \R^{d_1}$, $y,z \in \R^{d_2}$, and $t \geq 0$.","status":"unverified"}

