{"assumptions":[],"created_at":"2026-10-26T19:33:46.770474+00:00","domain":"probability theory","id":"claim_34e1357c679bb002fccdacd70d666810708e3491be2e7f3ab0d2924df935aa88","kind":"definition","schema_version":1,"statement":"[Definition 38 of arXiv:2603.24616, 'Pinning in non-critical half-space geometric last passage percolation'] Fix $M, N \in \mathbb{N}$, $q \in (0, 1)$, and $c \in [0, q^{-1})$. We define the {\em Pfaffian Schur process} to be the probability distribution on sequences of partitions $\lambda^0,\dots,\lambda^M$, given by
\begin{equation}
\begin{split}
&\mathbb{P}\left(\lambda^{0},\dots,\lambda^{M}\right)=\frac{1}{Z}\cdot \tau_{\lambda^{0}}(c) \cdot s_{\lambda^{1}/\lambda^{0}}(q)\cdots s_{\lambda^M/\lambda^{M-1}}(q) \cdot s_{\lambda^{M}}(\underbrace{q,q, \dots, q}_{\text{$N$ times}}),
\end{split}
\end{equation}
where the normalization constant was computed explicitly in \cite[Proposition 3.2]{BR05}:
$$ Z =\frac{1}{(1-cq)^N(1-q^2)^{N(N-1)/2 + NM}}.$$","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:06:21.712355+00:00","domain":"probability theory","id":"claim_34e84e12b21e5eed8b0902ab98f631a1c6e2a57ffab90d14ec008b584d8b267f","kind":"concept","schema_version":1,"statement":"[Maintheorem 2 of arXiv:2607.21374, 'Local structure at the maximum and sharp persistence asymptotics of rough fractional Brown'] Assume \(0<H<1/2\).  The following assertions hold.
\begin{enumerate}[
  label=\textup{(\themaintheorem.\arabic*)},
  ref=\themaintheorem.\arabic*,
  font=\normalfont\bfseries,
  leftmargin=*
]
\item
\emph{Tangent limit.}
If \(\tau\) is the unique maximiser of \(B\) on \([0,1]\), then there is a
probability law \(Q\) on \(\mathcal X\) such that the zooms \(\Xi_a\)
defined in \eqref{eq:tangent-zoom} satisfy
\begin{equation}
  \mathcal L(\Xi_a)\Longrightarrow Q
  \qquad\text{on }\mathcal X
  \quad\text{as }a\to\infty.

\end{equation}
The limiting law is \(H\)-self-similar: if \(X\) has law \(Q\), then, for
every \(c>0\),
\begin{equation}
  \bigl(c^H X(t/c)\bigr)_{t\in\mathbb R}
  \stackrel d= X.

\end{equation}

\item
\emph{Two-sided hard-wall limit.}
The tangent law \(Q\) in \ref{thm:main-tangent-limit} is also the path-space
limit of the finite-grid hard-wall laws from \eqref{eq:pure-wall-law}:
\begin{equation}
  Q_{h,L^-,L^+}\Longrightarrow Q

\end{equation}
whenever \(h\downarrow0\) through dyadic values and
\(L^-\to\infty\), \(L^+\to\infty\), without any restriction on the ratio of
the two horizons. Moreover,
\begin{equation}
  Q\bigl(
    f(0)=0,
    f(t)<0\text{ for every }t\in\mathbb R\setminus\{0\}
  \bigr)=1.

\end{equation}

\item
\emph{Rerooting-rescaling invariance.}
For each fixed nondegenerate compact interval
\(I\subset\mathbb R\) with \(0\notin I\), the tangent law \(Q\) is
rerooting-rescaling invariant at its maximum in \(I\) with exponent \(H\).
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

