			\end{equation*}
		\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T09:13:18.536908+00:00","domain":"probability theory","id":"claim_35f97f16e5953b415409ca171d3b501043bf5bad87b6f4958bc9eaf31d148e28","kind":"concept","schema_version":1,"statement":"[Lemma 21 (Overshoot Lemma) of arXiv:2608.30668, 'Recurrence and capacity of stable branching random walks'] There is a constant \(C\) such that for all $a \in \Z^d$ and all radius \(r> \lVert a \rVert, r'>0\), 
\begin{equation*}{
\sum_{y:\lVert y \rVert > r+r' } \sum_{\gamma:y \to a \subset B(0,r)} s(\gamma) \leq  Cr^{2}\P_{0}(\lVert S_{1} \rVert > r').
}\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:41:19.333005+00:00","domain":"probability theory","id":"claim_35f982a084d5d974a2f4238b03c5b342715a5cddc4646cf82e90fd3698d7ce1d","kind":"definition","schema_version":1,"statement":"[Definition def TVS of arXiv:2609.04138, 'The conformally invariant metric on $\CLE_4$ I:\\ subsequential limits of the non-simple C'] Fix $a,b>0$ and let $h$ be a zero-boundary GFF in a simply connected domain $G \subsetneq \BC$. We say that $\mathbb{A}_{-a,b}$ is a two-valued local set of $h$ of levels $-a$ and $b$ if it is a local set of $h$ and satisfies the following properties.
\begin{enumerate}
\item 
If $h_{\mathbb{A}_{-a,b}}$ denotes the harmonic part of $h$ on $G \setminus \mathbb{A}_{-a,b}$ (as in~(subsec:gff of the paper)), then we have that $h_{\mathbb{A}_{-a,b}} \in \{-a,b\}$ a.s.
\item 
The set $\mathbb{A}_{-a,b}$ is a \emph{thin} local set, i.e., for any smooth test function $f \in C_0^{\infty}(G )$, we have that
\begin{align*}
(h,f) = (h-h_{\mathbb{A}_{-a,b}}, f) + \int_{G \setminus \mathbb{A}_{-a,b}} h_{\mathbb{A}_{-a,b}}(x) f(x) \mathrm{d}x
\end{align*}
a.s.
\item  The set $\mathbb{A}_{-a,b} \cup \partial G$ has a finite number of connected components.
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:30:24.615185+00:00","domain":"probability theory","id":"claim_35f9f5200c283a6d2debd894cd8513bf88cc79aeb0315c692f9af80238f640f2","kind":"concept","schema_version":1,"statement":"[Theorem 1 of arXiv:2506.09592, 'Extremal process of the local time of simple\\random walk on a regular tree'] There exists a random Borel measure~$\ZZ$ on~$[0,1]$ and a (deterministic) law~$\DD$ on infinite, locally finite point processes on~$(-\infty,0]$ such that, for~$\ell_{\tau_\varrho}$  sampled under~$P^\zero$,
\begin{equation}

\sum_{x\in\BbbL_n}\delta_{\theta_n(x)}\otimes\delta_{\sqrt{\ell_{\tau_\varrho}(x)}-m_n}\,\,\,\underset{n\to\infty}\lawarrow\,\,\,\sum_{i\ge1}\sum_{j\ge1}\delta_{x_i}\otimes\delta_{h_i+d_j^{(i)}},
\end{equation}
where~$\{(x_i,h_i)\}_{i\ge1}$ enumerates points in a sample from the Poisson point process
\begin{equation}

\PPP\bigl(\,\ZZ(\textd x)\otimes\texte^{-2h\slb}\textd h\bigr)
\end{equation}
and~$\{d_j^{(i)}\colon j\ge1\}_{i\ge1}$ are i.i.d.\ samples from~$\DD$ independent of ~$\{(x_i,h_i)\}_{i\ge1}$ and~$\ZZ$. 

Moreover, a.e.\ sample of $\ZZ$ is such that $\ZZ([0,1]) <\infty$, $\ZZ([0,\epsilon))>0$ for each~$\epsilon>0$ yet $\ZZ(\{0\})=0$ and there exists a constant $\wt C_\star\in(0,\infty)$ such that, for~$\ell_{\tau_\varrho}$ sampled from~$P^\zero$,
\begin{equation}

\wt C_\star\, b^{-2n} \sum_{x \in \BbbL_n} \Bigl(n\slb - 
\sqrt{\ell_{\tau_\varrho}(x)}\,\Bigr)^+ \ell_{\tau_\varrho}(x)^{1/4}\,
	\texte^{2\slb\,\sqrt{\ell_{\tau_\varrho}(x)}}\delta_{\theta_n(x)}\,\,\,\underset{n\to\infty}\lawarrow\,\,\,\ZZ.
\end{equation}
A.e.~sample of $\{d_j\colon j\ge1\}$ from~$\DD$ has a point at the origin. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T05:37:14.890348+00:00","domain":"probability theory","id":"claim_3602a93a5f92f4680b6cb15895f47fc48bc0678da967bd9e98dbbed007428d2d","kind":"theorem","schema_version":1,"statement":"[Corollary 7 of arXiv:2607.11608, '2607.11608'] Let $\beta>\beta^{*}$ where $\beta^*$ is defined in \eqref{beta} and $N\in \N$. Assume that  $M=M(N)\in \N$ is such that  $M^{\beta}\sim N$ for $N\gg 1$. Let  $f_M$ be as in \eqref{fM}.  Then, 
