{"assumptions":[],"created_at":"2026-10-27T17:18:19.416571+00:00","domain":"probability theory","id":"claim_379128c8717584de9b20a0e5991d0d3e83af3a05ab230a62742d1f4cee57c24f","kind":"concept","schema_version":1,"statement":"[Proposition prop:2d_kernel_BGR of arXiv:2507.22011, 'Random Lozenge Waterfall:\\Dimensional Collapse of Gibbs Measures'] {borodin-gr2009q}}]

