{"assumptions":[],"created_at":"2026-10-27T08:33:12.355575+00:00","domain":"probability theory","id":"claim_3848f84eb297c57bdca552db5d49bbff6cdbce8130a7803ff7538777124c537f","kind":"definition","schema_version":1,"statement":"[Dfn 224 of arXiv:2608.29416, 'Algorithmic threshold for high-dimensional projection pursuit I: general theory'] In the spherical (resp.\ Ising) projection pursuit problem, we say that an algorithm $\cA$ (as in \eqref{eq:algorithms-as-maps}) \textbf{$(\ioeps,\gamma)$-attains} a target measure $\mu\in \cP_2(\bbR)$ if the output $\bx = \cA(\bG,\bg^{\aux})$ satisfies, with probability at least $\gamma$, \emph{both} of the following properties:
    \begin{enumerate}[(i)]
         \item  
         $\bx \in S_N(\iota)$ (resp.\ $\Sigma_N(\iota)$);
         \item 
         $\bbW_2(\mu,\mu_{\bG}(\bx)) \le \ioeps$.
    \end{enumerate}
For $\fq \in [1,2)$, we say that $\cA$ is \textbf{$(\fq,\iotamsr,\iotasol,\gamma)$-confined} to a subset $\cM\subseteq \cP_2(\bbR)$ if the output $\bx$ satisfies, with probability at least $\gamma$, \emph{either} of the following properties:
    \begin{enumerate}[(i)]
        \item  $\bx \notin S_N(\iotasol)$ (resp.\ $\Sigma_N(\iotasol)$);
        \item  $\bbW_\fq(\mu_{\bG}(\bx),\cM) \le \iotamsr$.
    \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T02:47:21.634143+00:00","domain":"probability theory","id":"claim_384a666a9875907553c2e8501703f93e09f6f0f38c72f81d7be97c58c1564e2b","kind":"lemma","schema_version":1,"statement":"[Lemma lem:secondhalfsumgeneral of arXiv:2412.09145, 'Asymptotic expansions for normal deviations of random walks conditioned to stay positive'] For all $a, b>0$, $a\notin \mathbb{Z}$ and $t \in (0,1)$ there exist numbers $c_{i,\nu}$ such that, uniformly in $z$,
\begin{multline*}
    \sum_{k=2}^{\lfloor n/2\rfloor} 
        \frac{z^m}{(n-k+t)^{b}(k-t)^a}
        e^{-\frac{z^2}{2 (n-k+t)}}
\\
=
    \frac{z^m}{n^b}
    e^{-\frac{z^2}{2 n}}
    \sum_{\nu=0}^{\lfloor a \rfloor-1}
        \frac{z^{2\nu}}{n^{\nu}}
        \sum_{i=\nu}^{\lfloor a \rfloor-1}
            \frac{c_{i,\nu}g_{a-i}(t)}{n^{i}}
+
    O\left(\frac{1}{n^{a+b-m/2-1}}\right),
\end{multline*}
where
\begin{align*}
    g_{\lambda}(t) 
=
    \sum_{k=2}^{\infty}
        \frac{1}{(k-t)^{\lambda}}.
\end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:52:05.661647+00:00","domain":"probability theory","id":"claim_3857399016184160bbd619ef7ccf260bd3b47972a68354e86c93b2dd1bbcfba3","kind":"concept","schema_version":1,"statement":"[Thm master of arXiv:2602.06011, 'Excursion decomposition of the XOR-Ising model'] {DRC-1}}]
    There exists a coupling $\mathbb P_{\delta}$ of the following objects
    \begin{enumerate}[label=(\roman*)]
        \item A double random current $\mathbf{n}_\delta$ with wired boundary conditions on $D_\delta$ and a double random current $\mathbf{n}_\delta^\dagger$ with free boundary conditions on $D_\delta^\dagger$
        \item A height function $h_\delta$ taking integer values on $D_\delta$ and half-integer values on $D_\delta^\dagger$
        \item A XOR-Ising model $\tau_\delta$ with $+$ boundary conditions on $D_\delta$ and a XOR-Ising model $\tau_\delta^\dagger$ with free boundary conditions on $D_\delta^\dagger$
    \end{enumerate}
    in such a way that
    \begin{enumerate}[label=(\arabic*)]
        \item There exists no pair $(e, e^\dagger)$ of dual edges such that $\mathbf{n}_\delta(e)>0$ and $\mathbf{n}_\delta^\dagger(e^\dagger)>0$.
        \item The set
        \begin{equation}
            \mathbf{n}_\delta^\mathrm{odd} :=\{e\in E_\delta: \mathbf{n}_\delta(e)\ \text{is odd}\}
        \end{equation}
        is equal to the collection of interfaces of $\tau_\delta^\dagger$. In particular, the spin $\tau_\delta^\dagger(u)$ is given by a product of  $-c_\delta$ over the inner boundaries surrounding $u$.
        The same holds for the dual models.
        \item The spins are given by
        \begin{align}
            &\tau_\delta(v) = \cos(\pi h_\delta(v)), \\ 
            &\tau_\delta^\dagger(u) = \sin(\pi h_\delta(u)).
        \end{align}
        In particular, 
        \begin{equation}
            h_\delta(u)-h_\delta(v) = \frac{1}{2}\ \tau_\delta(v)\tau_\delta^\dagger(u).
        \end{equation}
        \item The conditional law of $\tau_\delta$ given $\mathbf{n}_\delta$ is that of i.i.d. symmetric sign assignments $(\xi_k^\delta)_{k\geq1}$ to the clusters of $\mathbf{n}_\delta$. The same holds for the dual models.
        \item [ dimer-boson, nesting-field] The bosonisation identity holds, i.e.
        \begin{equation}
            \mathbb E_\delta\Big[\prod_{i=1}^n\cos(\pi h_\delta(v_i))\prod_{j=1}^k\sin(\pi h_\delta(u_j))\Big] = \mathbb E_{\delta, \beta}^+\Big[ \prod_{i=1}^n\sigma_\delta(v_i)\prod_{j=1}^k\mu_\delta(u_j)\Big]^2
        \end{equation}
        for any primal vertices $v_1, \ldots, v_n\in D_\delta$ and any dual vertices $u_1, \ldots, u_k\in D_\delta^\dagger$. Here, the so-called disorder operators are such that
        \begin{align}
            \mathbb E_{\delta, \beta}^+\Big[\prod_{j=1}^k \mu_\delta(u_j)\Big] := \mathbb E_{\delta, \beta}^+\Big[\exp\big\{-2\beta\sum_{xx'\in E_\delta^\gamma}\sigma_\delta(x)\sigma_\delta(x')\big\}\Big] = \mathbb E_{\delta, \beta^\dagger}^\varnothing\Big[\prod_{j=1}^k\sigma_\delta^\dagger(u_j)\Big],
        \end{align}
        where $\gamma$ is any\footnote{The second equality is the well-known Kramers--Wannier duality of the Ising model. In particular, the expression on the left-hand side of (equation eq:disorder of the paper) does not depend on the choice of the disorder line $\gamma$, but only on the choice of dual vertices $u_1, \ldots, u_k$. The expectation on the right-hand side of (equation eq:bosonisation of the paper) does depend on the homology class of $\gamma$ in $D_\delta\setminus\{v_1, \ldots, v_n\}$, but only up to a sign that is cancelled by the square.} collection of dual edges such that $\{u_1, \ldots, u_k\}$ is the set of dual vertices incident to an odd number of edges in $\gamma$,  and $E_\delta^\gamma$ is the subset of edges of $E_\delta$ crossed by $\gamma$.
        \item When exploring a cluster of $\mathbf{n}_\delta$ from the outside, the law of $\mathbf{n}_\delta$ inside each inner boundary is that of a DRC with free boundary conditions. The same holds for $\mathbf{n}_\delta^\dagger$.
        \item When exploring a cluster of $\mathbf{n}_\delta$ from the outside, the law of $\mathbf{n}_\delta^\dagger$ inside each inner boundary is that of a DRC with wired boundary conditions (and thus the inner boundary itself is identified into (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:33:23.331454+00:00","domain":"probability theory","id":"claim_385a416d5810b0d1990025269aae0b3629bf28d2f9e4785eb0c59bf41c0fed9d","kind":"concept","schema_version":1,"statement":"[Theorem 1 of arXiv:2506.22040, '\vspace{-3em} Khinchin inequalities for uniforms on spheres with a deficit'] Let $d \geq 2$ be a fixed dimension, let $\xi_1, \xi_2, \dots$ be independent random vectors uniform on the unit Euclidean sphere $S^{d-1}$ in $\R^d$ and let $Z$ be a Gaussian random vector in $\R^d$ with mean $0$ and covariance $\frac{1}{d}I_d$. Let $p \geq 2$. For every $n \geq 1$, every real scalars $a_1, \dots, a_n$ with $\sum_{j=1}^n a_j^2 = 1$, we have
\begin{equation}
\E\left|\sum_{j=1}^n a_j\xi_j\right|^p \leq \E|Z|^p - c_{p,d}\sum_{j=1}^n a_j^4,
\end{equation}
where
\[ 
c_{p,d} = \frac{(p+d-2)(p+d-4)}{24d^2(d+2)}\cdot \begin{cases} 3p(p-2), & 2 \leq p \leq 4, \\ 1, & p > 4. \end{cases}
 \] (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

