{"assumptions":[],"created_at":"2026-10-28T01:10:08.747549+00:00","domain":"probability theory","id":"claim_3a414efee7aeb72dc8ce7664ac564f132aaac9a08a5552f1e93dbb76de614562","kind":"definition","schema_version":1,"statement":"[Definition def_weak_sol_eq_linear_prob of arXiv:2411.17653, 'Exclusion processes with non-reversible boundary: hydrodynamics and large deviations'] We say that $v$ is a weak solution of (equation PDE_problem_linear of the paper) if the following two conditions are satisfied:
\begin{enumerate}
    \item $v \in L^2([0,T], H^1([0,1]))$;
    \item For every $G \in C^{1,2}( {\Omega_T})$ and every $t \in [0,T]$, 
    \begin{equation} 
    F(v,G,t) = 0,
    \end{equation} where
    \begin{align*}
        F(v,G,t) &:= \int_0^1 v_t(x) G_t(x)dx - \int_0^t \int_0^1 v_s(x) \partial_s G_s(x) dx ds + \int_0^t \int_0^1 \nabla v_s(x) \nabla G_s(x) dx ds \\
        &- \int_0^t \int_0^1 v_s(x) f_s(x) \nabla G_s(x) dx ds - \sum_{y \in \{0,1\}} \int_0^t v_s(y)[h_s(y)-f_s(y)] G_s(y) ds.
    \end{align*} 
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:06:06.299025+00:00","domain":"probability theory","id":"claim_3a5ca2f28753725a448288af71ec2362cb4bdc2e077511f6699d5d06751d1ce8","kind":"concept","schema_version":1,"statement":"[Cor criteria of arXiv:2605.24671, 'Immigration Processes with Binomial Catastrophes and Random Survival Parameters'] Consider the process $C_{\mathrm{ind}}(\lambda,\nu)$ and let $X\sim \nu$. 
\begin{enumerate}
    \item \textit{General criteria.}
    \begin{itemize}
        \item If $\displaystyle\liminf_{n\to\infty} n\lambda\,\mathbb E(X^{n+1})>1$, then $\mathbb P(\mathcal A_{C_{\mathrm{ind}}})>0$.
        \item If $\displaystyle\limsup_{n\to\infty} n\lambda\,\mathbb E(X^{n+1})<1$, then $\mathbb P(\mathcal A_{C_{\mathrm{ind}}})=0$.
    \end{itemize}
    Furthermore, the expected number of catastrophes is infinite if and only if the sum of the moments diverges; that is,
    \begin{equation*}
        \mathbb E(M_{C_{\mathrm{ind}}})=\infty \quad \text{if and only if} \quad \sum_{n\ge0}\mathbb E(X^{n+1})=\infty.
    \end{equation*}
    \item \textit{Density criteria.} Suppose that $\nu$ admits a bounded density $f$ on $[0,1]$ and that the left limit $f(1^-):=\lim_{x\uparrow 1} f(x)$ exists. Then:
    \begin{itemize}
        \item If $f(1^-)>\frac{1}{\lambda}$, then $\mathbb P(\mathcal A_{C_{\mathrm{ind}}})>0$.
        \item If $f(1^-)<\frac{1}{\lambda}$, then $\mathbb P(\mathcal A_{C_{\mathrm{ind}}})=0$.
    \end{itemize}
    If, in addition, $f$ is left-differentiable at $1$ and $f(1^-)=\frac{1}{\lambda}$, then $\mathbb P(\mathcal A_{C_{\mathrm{ind}}})=0$.    
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T15:27:25.789526+00:00","domain":"probability theory","id":"claim_3a6e0635d97eebc1938135d1cb429d4581227351dcf350bb0d7d2319fa554661","kind":"concept","schema_version":1,"statement":"[Lem plus-start-final-step of arXiv:2605.08052, 'Rapid phase ordering of Ising dynamics on $\mathbb Z^2$'] The following holds for $0\le i\le k-1$ and for a $\beta$-independent constant $C$. If $\tau\sim \mathbf P$ for $\mathbf{P}\in \mathcal D(\Lambda_L^i)$, 
        \begin{align*}
            \mathbf{E}[\|\mu_{(i+1) t_L/k}^{+,i} - \pi_{\Lambda_L^i}^\tau \|] \le C(1+i) L^{-8}\,,
        \end{align*}
        where $\mu^{+,i}_t$ is the law of Ising dynamics in $\Lambda_L^i$ started from all plus. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:52:05.651212+00:00","domain":"probability theory","id":"claim_3a8079e8d61ebb4cf36a4daf6fb2fec14229afc54b8295ceae9cb24e1469afa2","kind":"theorem","schema_version":1,"statement":"[Prop bdy-expect of arXiv:2602.06011, 'Excursion decomposition of the XOR-Ising model'] Let $\alpha\in(0,1]$. Let $D$ be a bounded, simply connected domain. Fix any $A\subseteq \partial D$ to be a (deterministic) closed subset of the boundary such that $\dim_M(A)<2-\alpha^2/2$. 
    For any continuous, bounded  function $f:\mathbb C\to\mathbb R$,
    \begin{equation}
        \lim_{n\to\infty}\mathbb E[(\field{e^{i\alpha\phi}}, f\1_{[A]_n})]=0.
    \end{equation}
    As a consequence,
    \begin{equation}
        \lim_{n\to\infty}(\field{e^{i\alpha\phi}}, f\1_{[A]_n})=0,
    \end{equation}
    where the limit is almost sure and in $L^2(\mathbb P)$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:25:41.601521+00:00","domain":"probability theory","id":"claim_3a824386e4464574fbab3411c4534431a13fe690c61d431b918710ccbf434e83","kind":"concept","schema_version":1,"statement":"[Proposition 61 of arXiv:2608.12947, 'Branch-stationary max-stable fields on rooted trees'] The field
\begin{equation}
  U_v^\psi
  =
  \psi\left(
    \frac{\eta_v^{-\alpha}}{S_\psi}
  \right),
  \qquad v\in\mathcal T,

\end{equation}
has standard uniform margins and finite-dimensional copulas
\((C_K^\psi)\). In particular, these copulas extend continuously to
\([0,1]^K\) and form a projectively consistent family of Archimax
copulas.

The following statements are equivalent:
\begin{enumerate}[(i)]
\item \(\eta\) is branch-stationary;
\item for every non-empty finite \(K\subset\mathcal T\),
\begin{equation}
  \ell_{aK}(x^a)=\ell_K(x),
  \qquad
  a\in\mathcal T,\quad x\in[0,\infty)^K;

\end{equation}
\item for every non-empty finite \(K\subset\mathcal T\),
\[
  C_{aK}(u^a)=C_K(u),
  \qquad
  a\in\mathcal T,\quad u\in(0,1]^K;
\]
\item for every non-empty finite \(K\subset\mathcal T\),
\[
  C_{aK}^\psi(u^a)=C_K^\psi(u),
  \qquad
  a\in\mathcal T,\quad u\in(0,1]^K;
\]
\item \(U^\psi\) is branch-stationary.
\end{enumerate}

If \(Z\) satisfies (equation 17 of the paper) and
\(\Theta=\Theta^{[\varnothing]}\), then
\begin{equation}
  \ell_K(x)
  =
  \E*{
    \max_{v\in K}x_v\Theta_v^\alpha
  },
  \qquad x\in[0,\infty)^K.

\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:55:18.056572+00:00","domain":"probability theory","id":"claim_3a8d5540fe31573a6dc6768c739b26c45cdaf2a614557d99510f24d4b5f17d26","kind":"concept","schema_version":1,"statement":"[Proposition 25 of arXiv:2606.16636, 'Free energy of non-convex multi-species spin glasses with centered Ising spins'] We fix $(t,q)\in(0,\infty)\times \mcl Q_\infty^\D$ and suppose that there is a sequence $(N_k,x_k,q_k)_{k\in\N}$ such that $\lim_{k\to\infty} N_k=+\infty$, $\lim_{k\to\infty}\Delta_{N_k}(x_k,q_k)=0$, $\sup_k|q_k|_{L^\infty}<\infty$, and $q_k$ converges pointwise a.e.\ to some $q\in\mcl Q_\infty^\D$. Then, there are a subsequence $(N'_k,x'_k,q'_k)_{k\in\N}$ and ${p}\in \mcl Q^\D_{\infty,\leq 1}$ such that
\begin{enumerate}
    \item  $R_{N'_k}$ under $\E\la\cdot\ra^\circ_{N'_k,x'_k,q'_k}$ converges in law to
    \begin{align*}
        \Ll(Q^{\ell,\ell'}_{p}\1_{\ell\neq \ell'}+ (\vecone,1) \1_{\ell =\ell'}\Rr)_{\ell,\ell'\in\N}
\end{align*}
    under $\E \la\cdot\ra_\fR$ as $k$ tends to infinity;
    \item  we have $\lim_{k\to\infty}A_{N'_k}\Ll(x'_k,q'_k\Rr) =-  \mathscr{P}_{t,{q}}({p})$;
    \item 
    for every bounded continuous $g:\R^{\D}\times \R\to\R$,
    \begin{equation*}  \lim_{k\to\infty} \E \la g\Ll(\diag\Ll(\tau\tau'^\intercal\Rr), \alpha\wedge\alpha'\Rr)\ra_{N'_k+1,x'_k,q'_k} =\E \la g\Ll(\diag\Ll(\tau\tau'^\intercal\Rr), \alpha\wedge\alpha'\Rr)\ra_{\fR,{q}+t\nabla\xi({p})}.
    \end{equation*}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:55:18.052020+00:00","domain":"probability theory","id":"claim_3aa109705e69e0e4ddf5a2e7286518315f316ccf126f2e3aaef63a0c93ac30a9","kind":"theorem","schema_version":1,"statement":"[Theorem 24 of arXiv:2606.16164, 'A Low-Regularity Semigroup Sewing Lemma via Quotient Structures'] Let $\gamma\in(0,1)$ and $\alpha\in\mathbb R$. The assignment
\begin{equation}

