\end{equation} 
where $\mathcal{X}_i$ are i.i.d. random variable with the same  Tracy-Widom distribution $F_1$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:17:42.312730+00:00","domain":"probability theory","id":"claim_3d2283a44dfc80394459e7cfacbb6aba330cff933cfc5084e987d4c83e8eb235","kind":"concept","schema_version":1,"statement":"[Theorem 26 of arXiv:2608.05931, 'Effective Lagrangian regularity and the uniqueness threshold for random H\"older velocity '] Suppose $U = \sum_{j=0}^\infty u^j$ satisfies Assumption~\ref{asmp:main for refreshing} for some $\beta >0$ and let $\alpha \in (0,1)$ such that $\alpha + \beta/2 > 1$. Suppose that for some $K \geq 1$ and 
    \begin{equation}

    0 \leq \lambda < \frac{\beta}{2-\alpha} \land \Big( 1- \frac{1-\alpha}{\beta}\Big), 
    \end{equation}
    we have that for all $j \in \N, n \in \{0,1,2\}$, and $1 \leq p<\infty$,
     \begin{equation*}
         \|\nabla^n u^j\|_{L^p_\omega \continuous^0_{t,x}} \leq K p^\lambda 2^{(n-\alpha)j}.
     \end{equation*}
     Then there exist $\delta(\alpha,\beta,\lambda)>0$ and a random field $M : \T^d \to [1,\infty)$ such that 
     \begin{enumerate}
         \item almost surely $\sup_{y \in \T^d} |M(y)| < \infty$; in fact for all $p \geq 1$, $\E \big[\big(\log\big(\sup_{y \in \T^d} |M(y)| + 1\big)\big)^p\big]<\infty$.
         \item for all $p \geq 1$, $M \in L^p_\omega L^p_y$,
         \item and for any $y,z \in \T^d$ and $w \in C^{1/2 + \delta}([0,1])$ with $w_0=0$, if we have any solution $X$ to~\eqref{eq:main refreshing ODE 0}, and any solution $\tilde X$ to 
          \begin{equation}

         \tilde X_t=z+\int_0^t U(s,\tilde X_s)\,ds+w_t,\qquad t\in[0,1],
         \end{equation}
        then we have the stability estimates on the time interval $[0,1]$
        \begin{equation}

        \|X - \tilde X\|_{C^{1/2 +\delta}_t} \leq M(y)\big(|y-z| + \|w\|_{C^{1/2+\delta}_t}\big),\end{equation}
         and, in the case that $w=0$, the expansion/compression estimate for all $t \in [0,1],$
         \[\frac{1}{M(y)} |y-z| \leq |X_t - \tilde X_t| \leq M(y) |y-z|.\]
     \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:54:18.299263+00:00","domain":"probability theory","id":"claim_3d477f731d56232e90d90c53bf5d6ada032d12aabd12da4b483535c7d268c44f","kind":"theorem","schema_version":1,"statement":"[Prop prop_iii of arXiv:2608.30382, 'Convergence rates for the RMSprop optimizer with full control of the hyperparameters'] Let $\beta\in[ \nicefrac{1}{2}, 1 ) $,
$ \varepsilon \in [0,\infty) $,
$ i \in \{ 1, 2, \dots, d \} $,
$ n \in {\mathbb N} \backslash \{ 1 \} $,
let $ A_n \in \mathcal F_{ n - 1 } $,
and let $ C_X^{ (3) } , C_v^{ (-3) } \in (0,\infty) $.
Assume that
\bas{
  {\mathbb E}\bigl[
    | X^{(i)}(\theta_{n-1},U_n) |^3
    |
    \mathcal F_{ n - 1 }
  \bigr]
  \le C_X^{ (3) }
\qquad\text{on }A_n
}
and
\bas{

  {\mathbb E}[ \1_{ A_n }( v_{ n - 1 }^{ (i) } )^{ - 3 } ]
  \le C_v^{ ( - 3 ) }
  .
}
The negative-moment assumption implies that $v_{n-1}^{(i)}>0$ almost surely
on $A_n$. If $\varepsilon=0$, the conditional covariances in the conclusion are
therefore evaluated on $A_n$ and extended by zero to $ \Omega \backslash A_n $.
Then one has
\bas{

  {\mathbb E}\Bigl[
    \1_{A_n}\mathrm{cov}((\sqrt{v_n^{(i)}}+\varepsilon)^{-1},
    X^{(i)}(\theta_{n-1},U_n)|\mathcal F_{n-1})^2
  \Bigr]^{1/2}
  \le
  4 C_X^{(3)} (C_v^{(-3)})^{1/2}\,\frac{1-\beta}{1-\beta^{n-1}}.
}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T15:12:20.541503+00:00","domain":"probability theory","id":"claim_3d4fe0936222f0d81d6727fe51f8b2390123beb8c8822ae688f2b023afacf0ab","kind":"concept","schema_version":1,"statement":"[Proposition prop:turning_point of arXiv:2603.27906, 'Marked GUE-corners process in doubly periodic dimer models'] For~$k=1,\dots,\ell$, set~$a_k=\alpha_k\beta_{k-1}^{-1}$ and~$b_k=\alpha_k^{-1}\beta_k$. Then
