{"assumptions":[],"created_at":"2026-10-27T10:55:57.005564+00:00","domain":"probability theory","id":"claim_3de6af301151c361353695a52a67f220925fd66bc0d725e836bdb2ebcc2fb8a1","kind":"theorem","schema_version":1,"statement":"[Theorem 20 (Deterministic error bound \cite{halko2011finding}) of arXiv:2609.02790, 'Full-Model Optimality for Tunable Linear Generative Priors in Compressed Sensing'] Let $A$ be an $m \times n$ matrix with SVD $A=U\Sigma V$, and fix $k \geq 0$. Choose a test matrix $\Omega$, and construct the sample matrix $Y=A \Omega$. Partition $\Sigma$ as 

\[
A = U
\begin{bmatrix}
\Sigma_1 & \\
& \Sigma_2
\end{bmatrix}
\begin{bmatrix}
V_1^{*} \\
V_2^{*}
\end{bmatrix},
\qquad
\Sigma_1 \in \mathbb{R}^{k \times k},\;
\Sigma_2 \in \mathbb{R}^{(n-k)\times(n-k)}.
\]
and define $\Omega_1$ and $\Omega_2$ via $\Omega_1=V_1^\star  \Omega$ and $ \Omega_2=V_2^\star  \Omega$. Assuming that $\Omega_1$ has full row rank, the approximation error satisfies
\begin{equation}
    \left\|\left(\mathbf{I}-P_{Y}\right) A\right\|_F^2 \leq\left\|\Sigma_2\right\|_F^2+ \| \Sigma_2 \Omega_2 \Omega_1^{\dagger} \|_F^2,
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:31:20.883220+00:00","domain":"probability theory","id":"claim_3deb464d00ba380ba0cf2f424aa3e8df62c3a33de80095e8a0bb568b4babe167","kind":"definition","schema_version":1,"statement":"[Definition 1 of arXiv:2506.11918, 'Central limit theorems for the Euler characteristic in the Random Connection Model for hig'] [Simplex functions and integral representations] 
Let $K$ be a simplicial complex with $\dim(K)\leq\alpha$ on the vertex set $\{1,\dots,r\}$ for some $r\in\N$.
\begin{enumerate}
\item Define the simplex function of $K$ by
\begin{align*}
f_K: \X^r \rightarrow [0,1], \qquad f_K(x_1,\dots,x_r):= \prod_{\sigma\in K} \; \varphi_{|\sigma|-1} (x_\sigma),
\end{align*}
where $\varphi_{|\sigma|-1} (x_\sigma)$ denotes the value of $\varphi_{|\sigma|-1}$ evaluated at the points $\{ x_i\,|\, i\in \sigma\}$.
\item The integral representation $I_K$ of $K$ (over an observation window $W$) is defined by
\begin{align*}
I_K(W) \,:=\, \int_{W^r} f_K(x_1,\dots,x_r) \;\; \lambda^r \, (\d {(x_1,\dots,x_r)}).
\end{align*}
We call $K$ the simplicial complex associated to $I_K$.
\item For $m,l\in\{1,\dots,\alpha+1\}$ and $\max\{m,l\}\leq r\leq m+l$, we consider the simplicial complex
\begin{align} 
K_{m,l}^r \,:=\, \Big\langle [1,\dots,m], [1,\dots,m+l-r,m+1,\dots,r] \Big\rangle
\end{align}
on the vertex set $\{1,\dots,r\}$, which is generated by a $(m-1)$-simplex and a $(l-1)$-simplex sharing $m+l-r$ vertices.
Moreover, we denote by $\kappa_{m,l}^r$ the simplex function and by $\z m l r$ the integral representation of $K_{m,l}^r$, which means
\begin{align*}
\z m l r (W) \,:=\, \int_{W^r} \kappa_{m,l}^r(x_1,\dots,x_r) \;\; \lambda^r \, (\d {(x_1,\dots,x_r)}).
\end{align*}
Finally, let $\kappa_m:=\kappa_{m+1,m+1}^{m+1}$ be the simplex function of a simplicial complex generated by an $m$-simplex.
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T08:26:47.189293+00:00","domain":"probability theory","id":"claim_3df65350c3a7dfe3d6f91e29f25f73f26a379b82e241346e5c3bc73699946bb9","kind":"definition","schema_version":1,"statement":"[Dfn 104 (discrete-time occupation measures) of arXiv:2608.29416, 'Algorithmic threshold for high-dimensional projection pursuit I: general theory'] Partition time into intervals $I_d \equiv [q_d,q_{d+1})$, and partition space into rectangles 
	$R_{\vl,j}
	\equiv J_{\vl}
	\times K_j$, as above.
Let $\rho_{\vY,N}$ be the occupation density for $\vY^{\frozen,\bullet,N}$: that is, we let $\rho_{\vY,N}$ be uniform on each $I_d\times R_{\vl,j}$, with
	\[
	\frac{\rho_{\vY,N}(I_d\times R_{\vl,j})}{|I_d|}
	= \mu_{\bullet,\bG^N}
	\Big( \vY^{\frozen,\bullet,N}(q_d) \in R_{\vl,j}\Big)
	\,,\]
where $\mu_{\bullet,\bG^N}$ is as defined in Theorem~\ref{t:tightness}.  Recall from Definition~\ref{d:rerand.Ising} that in the spatial rerandomization, the $a(q_d)\in[M]$ indices and the $i(q_d)\in[N]$ indices evolve completely independently, so the processes $\vY^{\frozen,\bullet,N,\RomI:\RomIII}$ and $Y^{\frozen,\bullet,N,\Ising}$ are independent under $\mu_{\bullet,\bG^N}$. This implies the above is equal to
	\beq
	\mu_{\bullet,\bG^N}
	\bigg( 
	\vY^{\frozen,\bullet,
	N,\RomI:\RomIII}(q_d)
	 \in J_{\vl}
	 \bigg)
	\cdot
	\mu_{\bullet,\bG^N}
	\Big( Y^{\frozen,\bullet,N,\Ising}(q_d) 
	\in K_j \Big)\,.
	\eeq
We similarly let $\rho_{D,N}$ be the signed measure which is uniform on each $I_d\times R_{\vl,j}$, with
	\begin{align}\nonumber
	&\frac{\rho_{D,N}
	(I_d\times R_{\vl,j})}{|I_d|}
	= 
	\bE_{\bG^N} \bigg[
	\frac{\Delta \bar{D}^{\frozen,\RomI,N}(q_d)}
	{\delta_d}
	\ind\Big\{
	\vY^{\frozen,\bullet,N}(q_d) \in R_{\vl,j}
	\Big\}\bigg] \\
	&\qquad\stackrel{\eqref{e:review.b}}{=}
	(p^N)'(q_d)^{1/2}
	\bigg\{ \sum_{B^\frozen \in 
		B^{\frozen,\coarse}}
		\frac{|B^\frozen|}
			{|B^{\frozen,\coarse}|}
	\bbb^{\frozen,N}\Big(q_d, 
		B^\frozen \Big)
	\bigg\}
	\mu_{\bullet,\bG^N}
		\Big( 
		\vY^{\frozen,\bullet,N}(q_d) \in R_{\vl,j}\Big) \nonumber\\
	&\qquad\stackrel{\eqref{e:review.b}}{=}
	(p^N)'(q_d)^{1/2}
	\bbb^{\frozen,\coarse,N}(q_d, B^{\frozen,\coarse}) 
	\mu_{\bullet,\bG^N}
		\Big( 
		\vY^{\frozen,\bullet,N}(q_d) \in R_{\vl,j}\Big)

	\end{align}
with $B^{\frozen,\coarse}=B^{\frozen,\coarse}(q_d,J_{\vl})$ as defined by \eqref{e:coarsened.bucket}, and recalling that the last term above factorizes as in \eqref{e:a.i.factorization}. We similarly define measures $\rho_{V,N}$, $\rho_{U,N}$, 
$\rho_{\www,N}$,
and $\rho_{\rrr,N}$
 using increments of 
$\tilde{Q}^{\frozen,\RomII,N}$, $\tilde{Q}^{\frozen,\RomII,\RomIII,N}$, $\tilde{Q}^{\frozen,\Ising,N}$, and 
$C^{\frozen,\RomIII,N}$ respectively.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:58:01.570460+00:00","domain":"probability theory","id":"claim_3dfede189b2ec949bad716e3d539d34b55edb878f67a691a44f4104e227b4401","kind":"concept","schema_version":1,"statement":"[Proposition 9 of arXiv:2608.27307, '2608.27307'] Under Assumption~\ref{ass:basic}, the following statements hold.
        \begin{enumerate}[label=(\roman*)]
                \item There exists a unique holomorphic function $\Pi:\C^+\to\C^{L\times L}$ such that, for every $z\in\C^+$, $\Om(\Pi(z),z)=0$, $\Im\Pi(z)>0$, and $\Im(z^{-1}\Pi_{11}(z))>0$.
                \item Define $\wt T(z):=z^{-1}\Pi_{11}(z)$ and $T(z):=\Pi_{22}(z)$. There exist unique positive semidefinite matrix-valued measures $V_1$ and $V_2$ on $[0,\infty)$, with values in $\C^{M\times M}$ and $\C^{N\times N}$, respectively, such that $V_1([0,\infty))=I_M$, $V_2([0,\infty))=I_N$, and
