\end{align}
for $1\leq i, j \leq d;$
\item $\chi$ vanishes along random walks under the diffusive scaling, i.e., 
for $\mathbb{P}$-a.e. $\omega$, and all $i=1, \dots, d$, $T>0$, 
\begin{align}

    \lim_{n\to \infty}\sup_{t\in [0, T]} \frac{1}{n}\abs{\chi^i(\omega, X_{n^2t})}=0 \qquad \text{in } \Prob_0^\omega.
\end{align}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T10:55:57.000998+00:00","domain":"probability theory","id":"claim_3fd3076e80d38c6290e61835a0769acc39a4bd40267b4b4ce2289f8b1a864aeb","kind":"lemma","schema_version":1,"statement":"[Lemma 9 (Parity-weighted inner comparison) of arXiv:2609.02788, '\textbf{Quantized Einstein Metrics on \(S^7\) with \(SU(3)\)-Symmetry}'] At the overlap $t=\delta_b=b^{1/2}$,
