{"assumptions":[],"created_at":"2026-10-26T19:21:52.489263+00:00","domain":"probability theory","id":"claim_429a623d1065c03e637bc2aaa43f66f4a121cde6bb9a180f08ed2c16fdc29901","kind":"lemma","schema_version":1,"statement":"[Lemma 208 of arXiv:2601.16377, '2601.16377'] Let $p_1(z),\ldots,p_H(z)$ be polynomials of degree (at most) $H-1$, such that
 \begin{equation}

  \oint_{\gamma_h} \frac{p_g(\zeta)}{\sigma(\zeta)} \frac{\dd \zeta}{2\ii\pi}= \delta_{g,h}.
 \end{equation}
 Consider the integral operator $\mathcal{P}^H:\mathscr{L}^2(\gamma^+) \longrightarrow \mathscr{L}^2(\gamma^+)$ given by $\displaystyle f \longmapsto \oint_{\gamma^+} f(w)\, \dfrac{ P^H(z,w)}{2\ii\pi}\dd w$, where
 \begin{equation}

 P^H(z,w)= \frac{p_h(z)}{\sigma(z)},\quad \textnormal{ for } w\in \gamma_h^+, \quad h\in [H].
 \end{equation}
 Then for any polynomial $f(z)$ of degree at most $H-1$, we have
 \begin{equation}

 \mathcal P^H \left[\frac{f}{\sigma}\right](z)=\frac{f(z)}{\sigma(z)}.
 \end{equation}
 Further, for any $f\in \mathscr{L}^2(\gamma^+)$ with vanishing integrals around each $\gamma_h$, $h\in[H]$, we have $\mathcal P^H f=0$.","status":"unverified"}

