{"assumptions":[],"created_at":"2026-10-27T10:52:57.738657+00:00","domain":"probability theory","id":"claim_4377fd4991aef3742e6f9bec7f6e948918144cea286752445eb880b7705ef86d","kind":"lemma","schema_version":1,"statement":"[Lemma 40 of arXiv:2609.02755, 'The Sharp Rate of Probabilistically Strong Convergence to the KPZ Equation'] Let $\tilde{E}, E, F$ be metric spaces. Let $\iota : \tilde{E} \to E$ be a compact embedding. Let $E_{\mathrm{sol}} \subset E$ be open and let $f : E_{\mathrm{sol}} \to F$ be continuous. Suppose that $(X_\lambda)_{\lambda \in \Lambda}$ is a collection of $\tilde{E}$-valued random variables such that:
	\begin{enumerate}
		\item there exist $e \in \tilde{E}$ and $p > 0$ such that $\sup_{\lambda \in \Lambda} \mathbb{E}[ d_{\tilde{E}}(X_\lambda, e)^p ] < \infty$;
		\item for every $\lambda \in \Lambda$, $\iota(X_\lambda) \in E_{\mathrm{sol}}$ almost surely;
		\item every subsequential limit $\mu$ of the laws $(\iota(X_{\lambda}))_{\lambda \in \Lambda}$ satisfies $\mu(E_{\mathrm{sol}}) = 1$.
	\end{enumerate}
	Then for all $y_0 \in F$,
	\begin{equ}
		\limsup_{M \to \infty} \sup_{\lambda \in \Lambda} \mathbb{P}( d_F( f(\iota(X_\lambda)), y_0) > M) = 0\;.
	\end{equ}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:28:49.122478+00:00","domain":"probability theory","id":"claim_43792a9cae275fc46893ed42650a6eb2ee3dc5857d7788f6bb80ae0ca30d25d0","kind":"theorem","schema_version":1,"statement":"[Proposition prop:approx-fixed-point of arXiv:2608.18293, 'Critical tensor covariance at the Marchenko--Pastur threshold'] For each fixed $z\in\mathbb{C}_+$,
