		&=\frac{1}{\mathbb{E}(e^{\gamma X})}\int_p^q \sum_{j=0}^\infty \frac{\beta^{j+1}}{1-\beta} \widetilde{\mathbb{P}}\left(z> -\min_{0\leq k\leq j} S_k \right)\mathrm{d} z. 
	\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:51:12.739305+00:00","domain":"probability theory","id":"claim_4463cad6a5ebf55c83664a75f33454d173357a0d1fed081c26ff68497c485b07","kind":"concept","schema_version":1,"statement":"[Lem 8 of arXiv:2605.02420, '\textbf{Large time behavior of critical marked Hawkes processes with heavy tailed marks an'] a) Suppose that Assumption \ref{ass:beta_general} is satisfied and that $f$ is of the form \eqref{e:f_sum} with all $\theta_k$ nonnegative, $f_T$ is given by \eqref{e:fT} with $F_T=T^{1+\beta}$ and $g_T$ is as in Proposition \ref{prop:Laplace}. Then 
 \begin{equation}
 H(g_T(t))\le f_T(t), \qquad \textrm{ for any}\ t\ge 0.

\end{equation}
Moreover, there exists $T_0\ge 1$ (which may depend on $f$)  and $C>0$ such that for any $T\ge T_0$ we have
\begin{equation}
Tg_T(tT)\le C f^{1/(1+\beta)}(t), \qquad t\ge 0.

