    \begin{align*}
   \frac{C^{-1}}{\sqrt{1+ne^{-2\beta}+n\tan \varphi}} e^{ - \tau_\beta(\varphi) \|v\|} \le \langle \sigma_{0^*} \sigma_{v^*} \rangle_{\beta^*, S_n^*}\le \frac{C}{\sqrt {1+ne^{-2\beta}+n\tan \varphi}} e^{-\tau_\beta (\varphi ) \|v\|}\,.
