,
\end{equation}

where $\gamma^{\bbH,x}_{T/N}$ is the Gaussian measure on $\bbH$ with variance $T/N$ (as in (equation eq: Gaussian H of the paper)) and mean 
$\big( \frac{1}{N}\sum_i n_k(x_i) \big)_{k \geq -d}$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:29:14.934956+00:00","domain":"probability theory","id":"claim_44ee517ef53a81ad13565731138647305969cd3c887556651fca98f15f30c888","kind":"theorem","schema_version":1,"statement":"[Proposition prop.L2FluxDeg2 of arXiv:2606.13442, 'Scaling limit of additive functionals for reversible non-gradient exclusion process: criti'] The following $L^2$ and flux estimates hold for the two-scale expansion $\widetilde{G}_\lambda$:
		\begin{enumerate}
			\item There exists a finite positive constant $C(c_{-},c_{+},\rho)$ such that the  two-scale expansion satisfies
			\begin{equation*}
				\norm{\widetilde{G}_\lambda-\overline{G}_\lambda}^2_{L^2}\leqslant C3^{3m}\expec{\overline{G}_\lambda,-{\overbracket[1pt][-1pt]{\mathcal{L}}} \overline{G}_\lambda}.
			\end{equation*}
			\item There exists an exponent $\alpha(c_{-},c_{+}, \mathbf{r}) > 0$ and a finite positive constant $C(c_{-},c_{+}, \mathbf{r},\rho)$ such that the following estimate holds for any $V\in L^2$ satisfying $\left\langle V,-{\overbracket[1pt][-1pt]{\mathcal{L}}} V \right\rangle<\infty$:
			\begin{equation*}
				\left|\expec{V,-\mathcal{L}\widetilde{G}_\lambda+{\overbracket[1pt][-1pt]{\mathcal{L}}} \overline{G}_\lambda}\right|\leqslant C\left\langle V,-{\overbracket[1pt][-1pt]{\mathcal{L}}} V \right\rangle^{\frac{1}{2}}\left(3^{-\alpha m}\expec{\overline{G}_\lambda,-{\overbracket[1pt][-1pt]{\mathcal{L}}} \overline{G}_\lambda}^{\frac{1}{2}}+3^{7m} \expec{-{\overbracket[1pt][-1pt]{\mathcal{L}}} \overline{G}_\lambda,-{\overbracket[1pt][-1pt]{\mathcal{L}}} \overline{G}_\lambda}^{\frac{1}{2}}\right).
			\end{equation*}
		\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T09:57:28.718090+00:00","domain":"probability theory","id":"claim_44ef547e8575f6e0fbd19a2067aabc37e418de62894cb0b50d6ccd625907676e","kind":"concept","schema_version":1,"statement":"[Lemma 5 of arXiv:2609.01166, 'Nonparametric inference for density-dependent McKean--Vlasov diffusions'] For every candidate $\xi$, and \(M>v_\star\),
\begin{eqnarray}
 \KL(\pi_0\Vert\pi_\xi)
 &=& (1-\tau_0(M))\KL(\pi_0^M\Vert\pi_\xi^M) + (1-\tau_0(M))\log\frac{1-\tau_0(M)}{1-\tau_\xi(M)} + R_\xi(M)\\
 &\leq& \KL(\pi_0^M\Vert\pi_\xi^M)+d_m(M)+\bar R_m(M),
\end{eqnarray}
where $R_\xi(M):=\int_{A_M^c}\pi_0(x) \log(\pi_0(x)/\pi_\xi(x))\,\dd x$. Moreover, 
\begin{equation}
\KL(\pi_0^M\Vert\pi_\xi^M)
\leq \frac{1}{c_M}\left(
\KL(\pi_0\Vert\pi_\xi)+d_m(M)+\bar R_m(M)
\right)
\end{equation}
with \(c_M:=\int_{A_M} e^{-K(V(x)-v_\star)}\,dx\left(\int_{\R^d} e^{-\kappa(V(x)-v_\star)}\,dx\right)^{-1}\in(0,1)\). (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:39:41.438669+00:00","domain":"probability theory","id":"claim_44f3d9d986893d24bad642213ae3c7febf6aba1d4a16bca7e941372be84fec3c","kind":"lemma","schema_version":1,"statement":"[Lem 11 of arXiv:2604.07370, 'Probabilistic Weyl law for twisted Toeplitz matrices with rough symbols'] Let $p\in BS_\xi$. Then, there exists a constant $C$ such that for all $N\in \N^*$, 
