{"assumptions":[],"created_at":"2026-10-27T20:51:52.052467+00:00","domain":"probability theory","id":"claim_4aa0507ec5e98f658d77615f85cd54b677de0b2480e6a3b45fe36aa9f4b45e24","kind":"theorem","schema_version":1,"statement":"[Proposition prop:kernel of arXiv:2607.12564, 'Power-law and log-periodic degree tails for a family of probability generating function eq'] Let $\varphi(t)=\mathbb{E} e^{-tW}$ and $y(t)=1-\varphi(t)$, so the Laplace fixed point reads
\begin{equation}
  y(\lambda t)=\lambda\,y(t)-p\,y(t)^2=y(t)\bigl(\lambda-p\,y(t)\bigr).
\end{equation}
Then, for every $m\in\mathbb{Z}$, with $z_m:=\rho+i\chi m$ and $C(z):=1/\Gamma(-z)$,
\begin{equation}
  \mathbb{E}[W^{z_m}]=C(z_m)\int_0^\infty y(t)^2\,t^{-z_m-1}\,dt .
\end{equation}
Writing $t=\lambda^{v}$ and $H_p(v):=\lambda^{-\rho v}\,y(\lambda^{v})^{2}\ge0$, (equation eq:ysquare of the paper)
reads $\mathbb{E}[W^{z_m}]=C(z_m)\log\lambda\,\widehat H_p(m)$, $\widehat H_p(m)=\int_\mathbb{R} H_p(v)e^{-2\pi imv}dv$;
since $C(z_m)\ne0$, (cor:const of the paper) and (prop:reduce of the paper) show that, for $j\in\{1,2\}$, $\Psi_j$
is constant iff the periodization
$\mathcal P_p(u):=\sum_{n\in\mathbb{Z}}H_p(u+n)$ is constant. Moreover the unit-shift ratio of $H_p$,
\begin{equation}
  \frac{H_p(v+1)}{H_p(v)}=\lambda^{2-\rho}\Bigl(1-\tfrac{p}{\lambda}\,y(\lambda^{v})\Bigr)^{2}
\end{equation}
is strictly decreasing in $v$, from $\lambda^{2-\rho}>1$ (as $v\to-\infty$) to $\lambda^{-\rho}<1$
(as $v\to+\infty$).","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T15:12:20.540965+00:00","domain":"probability theory","id":"claim_4aa13c93cde221c225d6f695697b6cd2d3c81ea6e83145ffb88bcae107e4cfa0","kind":"theorem","schema_version":1,"statement":"[Theorem thm:correlation_kernel of arXiv:2603.27906, 'Marked GUE-corners process in doubly periodic dimer models'] Let~$\rho_k^{\operatorname{Int}}=\rho_{k,N}^{\operatorname{Int}}$ be the~$k$th correlation function associated to the point process~$\{u_s^t\}_{1\leq s\leq t\leq 2\ell N}$. For~$k$ black points~$(\ell x_p+i_p,2y_p+j_p)$,~$p=1,\dots,k$, where~$x_p=0\dots,2N-1$,~$i_p=0,\dots,\ell-1$,~$y_p=0,\dots,\ell N-1$, and~$j_p=0,1$, we have
\begin{multline}
\rho_k^{\operatorname{Int}}\left(\ell x_1+i_1,2y_1+j_1;\dots;\ell x_k+i_k,2y_k+j_k\right) \\
=\det\left(K_{\operatorname{Int}}\left(\ell x_p+i_p,2y_p+j_p;\ell x_{p'}+i_{p'},2y_{p'}+j_{p'}\right)\right)_{p,p'=1}^k,
\end{multline}
where
\begin{multline}
\left[K_{\operatorname{Int}}(\ell x+i,2y+j;\ell x'+i',2y'+j')\right]_{j',j=0}^1 \\
= -\frac{\one_{\ell x+i>\ell x'+i'}}{2\pi\mathrm{i}}\int_{\tilde \Gamma_l}\left(\prod_{m=1}^{2i'}\phi_m(z)\right)^{-1}Q(z,w)\prod_{m=1}^{2i}\phi_m(z)w^{x-x'}z^{y'-y}\frac{\,\mathrm{d} z}{z} \\
+\frac{1}{(2\pi\mathrm{i})^2}\int_{\tilde \Gamma_s}\int_{\tilde \Gamma_l}\left(\prod_{m=1}^{2i'}\phi_m(z_1)\right)^{-1}Q(z_1,w_1)Q(z_2,w_2)\prod_{m=1}^{2i}\phi_m(z_2) \\
\times \frac{(z_2-1)^{\ell N}}{(z_1-1)^{\ell N}}\frac{w_2^{x-N}}{w_1^{x'-N}}\frac{z_1^{y'}}{z_2^y}\frac{\,\mathrm{d} z_2\,\mathrm{d} z_1}{z_2(z_2-z_1)}.
\end{multline}
The contours~$\tilde \Gamma_l$ and~$\tilde \Gamma_s$ are simple closed positively oriented curves in~$\mathcal R$ containing~$p_0$ and~$q_\infty$ in their interior, and~$p_\infty$ and~$q_0$ in their exterior. Moreover,~$\tilde \Gamma_s$ is contained in the interior of~$\tilde \Gamma_l$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T00:55:42.215548+00:00","domain":"probability theory","id":"claim_4aab70c93c3286a319bcca780380b683a917854affac61556b43303b18b89bc6","kind":"concept","schema_version":1,"statement":"[Lemma lem:unbiasedness of arXiv:2411.16366, 'Connections between sequential Bayesian inference and evolutionary dynamics'] \textbf{Unbiasedness of the non-local replicator-mutator with perfect system.} Consider the signal-observation pair (equation eq:sig of the paper)-(equation eq:obs of the paper) with $g(x) = Gx, \enskip h(x) = Hx$ and Gaussian initial conditions. If $m_0= \mathbb{E}[X_0]$ then the generalised Kalman-Bucy filter with $s < r, r > 0$ is unbiased, i.e. $\mathbb{E}[m_t] = \mathbb{E}[X_t], \enskip t > 0$. 
\begin{proof}
Begin with the mean equation from the generalised Kalman-Bucy filter
\begin{align*}


	m_t &= m_0 + \int_0^t Gm_u du + (r-s)\int_0^t K_u dZ_u -  (r-s)\int_0^t K_u H m_u du \\
	& = m_0 + \int_0^t Gm_u du + (r-s)\int_0^t K_u H (X_u^{\ast} - m_u)du + (r-s)\int_0^t K_u\Xi^{1/2} dB_u
\end{align*}
where $K_t:= C_t H^\top \Xi^{-1}$ corresponds to the Kalman gain at time $t$ and we have substituted in the form of the observations in the second equality.  Then 
\begin{align*}

	\mathbb{E}[m_t] &= m_0 + \int_0^t G \mathbb{E}[m_u]du + (r-s)\int_0^t K_u H (\mathbb{E}[X_u^{\ast}] - \mathbb{E}[m_u])du 


\end{align*}
Also recall that 
\begin{align*}
	\mathbb{E}[X_t^\ast] = \mathbb{E}[X_0^\ast] + \int_0^t G \mathbb{E}[X_u^\ast]du
\end{align*}
then 
\begin{align*}
	\mathbb{E}[m_t] - \mathbb{E}[X_t^\ast] = m_0 - \mathbb{E}[X_0^\ast] + \int_0^t (G - (r-s)K_sH)(\mathbb{E}[m_s] - \mathbb{E}[X_s^\ast])ds
\end{align*}
which corresponds to an ODE of the form $\dot{y}_t =A_ty_t$ with $y_t := \mathbb{E}[m_t] - \mathbb{E}[X_t^\ast]$, which has solutions $y_t = 0, \enskip t > 0$ whenever $y_0 = 0$. 
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

