{"assumptions":[],"created_at":"2026-10-27T21:04:07.032428+00:00","domain":"probability theory","id":"claim_4afb4a92502b742f797a65c34bbe519eb15298068d8c59811aef9e83cca81945","kind":"concept","schema_version":1,"statement":"[Theorem thm:NonMon of arXiv:2607.29409, 'The Zombie Infection Model'] $ $
		\begin{enumerate}[label=\alph*)]
