{"assumptions":[],"created_at":"2026-10-26T20:59:25.039778+00:00","domain":"probability theory","id":"claim_4bde5c29af2345dae6ade77f7e5e4a200fce8c273c5188a54c792fdceb5fcc31","kind":"definition","schema_version":1,"statement":"[Definition 5 of arXiv:2606.31596, 'The Invariant Measure of Multiscale Markov Chains via Fast Arborescence Factorization'] For every $x,y \in \hat V$ with $x\neq y$ the \emph{reduced rates} is
\begin{equation}
\begin{split}
    \hat{r}_N(x,y)\,:&=\, \sum_{z \in V }\,r_N(x,z)\; P_{N}^{\hat V}(y\,|\,z) \\
    &=\,
    r_N(x,y) \,+\sum_{z\in V\setminus\hat V} r_N(x,z)\; P_{N}^{\hat V}(y\,|\,z)\,.
\end{split}
\end{equation}
The \textit{reduced edge set} is $\hat E:=\{(x,y)\in \hat V\times\hat V \,:\, \hat r_N(x,y)>0 \,\}\,$ and we call $(\hat V,\hat E,\hat r_N)$ the \textit{reduced weighted graph}.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:01:22.580413+00:00","domain":"probability theory","id":"claim_4bebb5bc5429cd8cb46096336b1ec585b7207db2c2f9b53a7de1afe416bafedc","kind":"concept","schema_version":1,"statement":"[Theorem Thm-cancel of arXiv:2605.16963, 'Stochastic Euler Equations with Pseudo-differential Noise: Continuous and Discontinuous Pe'] Let $d\ge1$ and $\mu\in[0,\infty)$. 
		\begin{enumerate}[label=\textup{\textbf {(\arabic{enumi})}},leftmargin=0.79cm]\setlength\itemsep{0.2em}
			\item   Let $\alpha\in[0,1]$. If $\mathscr{N}_1\subset\mathbb{A}^{\alpha}$  is bounded $($cf. Definition (Ak class define of the paper)$)$ and $\mathscr{O}_1\subset{\rm OP}\mathcal{S}^\mu$ is bounded,  then  we have
			\begin{equation}
				\sup _{\mathcal A\in\mathscr{N}_1,\, \mathcal P\in\mathscr{O}_1}\big \langle
				\mathcal P\mathcal A f, \mathcal Pf\big \rangle _{L^{2}}
				\lesssim   \left \|f\right \|^{2}_{H^{\mu}},\quad f\in H_d^{\mu+\alpha},
			\end{equation}
			and 
			\begin{align}
				\sup_{\mathcal A\in\mathscr{N}_1,\, \mathcal P\in\mathscr{O}_1}\Big|\left
				\langle \mathcal P\mathcal A^{2}f, \mathcal Pf \right \rangle _{L^{2}}
				+ \left \langle \mathcal P\mathcal A f, \mathcal P\mathcal A
				f \right \rangle _{L^{2}} \Big| \lesssim \left \|f\right \|_{H^{\mu}}^{2},
				\quad f\in H_d^{\mu+2\alpha}.
			\end{align}

			\item  Let $\beta\ge0$. If $\mathscr{N}_2\subset\mathbb{B}^{\beta}$  is bounded $($cf. Definition (Bk class define of the paper)$)$ and $\mathscr{O}_2\subset{\rm OP}\mathcal{S}_0^\mu$ is bounded,  then  we have
			\begin{equation}
				\sup _{\mathcal B\in\mathscr{N}_2,\, \mathcal P\in\mathscr{O}_2}\big \langle
				\mathcal P \mathcal B f, \mathcal Pf\big \rangle_{L^{2}}
				\lesssim \left \|f\right \|^{2}_{H^{\mu}},\quad f\in H_d^{\mu+\beta},
			\end{equation}
			and
			\begin{equation}
				\sup _{\mathcal B\in\mathscr{N}_2,\, \mathcal P\in\mathscr{O}_2}\Big|
				\big \langle \mathcal P\mathcal B^{2}f, \mathcal Pf \big \rangle _{L^{2}}
				+\big \langle \mathcal P\mathcal B f, \mathcal P\mathcal B f
				\big \rangle _{L^{2}} \Big| \lesssim  \left \|f\right \|_{H^{\mu}}^{2},
				\quad f\in H_d^{\mu+2\beta}.
			\end{equation}
		\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:20:15.585491+00:00","domain":"probability theory","id":"claim_4c086f8bd93fe86d3734768061676e4b1fe26476f594a24130766fd8b41e8d0e","kind":"theorem","schema_version":1,"statement":"[Corollary cor:hyperbolic-interior of arXiv:2609.00777, 'Universal murmuration and Hecke augmentation'] Let
