{"assumptions":[],"created_at":"2026-10-27T12:52:05.661811+00:00","domain":"probability theory","id":"claim_4cf8e4a9da692750ccab7f88b3aeedbf685b56874a8c603de618061cb81d8290","kind":"concept","schema_version":1,"statement":"[Thm DRC of arXiv:2602.06011, 'Excursion decomposition of the XOR-Ising model'] Let $D$ be a Jordan domain and $D_\delta$ be as above. For the (critical) coupling $\mathbb P_\delta$, 
    \begin{equation}
        (h_\delta, \hat\mathbf{n}_\delta, \hat\mathbf{n}_\delta^\dagger, c_\delta, c_\delta^\dagger, \xi_\delta, \xi^\dagger_\delta) \overset{(d)}{\longrightarrow} (\frac{1}{2\sqrt{2}\lambda}\ h, \hat\mathbf{n}, \hat\mathbf{n}^\dagger, c, c^\dagger, \xi, \xi^\dagger),
    \end{equation}
    where
    \begin{enumerate}[label=(\roman*)]
        \item h is a GFF with zero boundary conditions in $D$, 
        \item The inner boundaries of the boundary cluster of $\hat\mathbf{n}_\delta$ converge to $\mathcal L_{-\sqrt{2}\lambda, \sqrt{2}\lambda}$. The label $c(\ell)$ of an inner boundary $\ell$ is such that the boundary values of $h$ in $\mathcal O(\ell)$ are $c(\ell)\sqrt{2}\lambda$.
        \item The outer boundaries of the outermost clusters of $\hat\mathbf{n}^\dagger_\delta$ converge to $\mathcal L_{-2\lambda, 2\lambda}$. The sign $\xi^\dagger(\gamma)$ of an outer boundary $\gamma$ is such that the boundary values of $h$ in $\mathcal O(\gamma)$ are $\xi^\dagger(\gamma)2\lambda$. Moreover, the inner boundaries of the cluster corresponding to $\gamma$ converge to
        \begin{enumerate}
            \item [(iii.a)] $\mathcal L_{-2\lambda, (2\sqrt{2}-2)\lambda}$ if $\xi^\dagger(\gamma)=+1$,
            \item [(iii.b)] $\mathcal L_{-(2\sqrt{2}-2)\lambda, 2\lambda}$ if $\xi^\dagger(\gamma)=-1$,
            \item [(iii.c)] where the label $c^\dagger(\ell)$ of an inner boundary $\ell$ is such that the boundary values of $h$ in $\mathcal O(\ell)$ are $\xi(\gamma)(c(\ell)+1)\sqrt{2}\lambda$. 
        \end{enumerate}
        \item The structure repeats iteratively by applying the Markov property (MP-free of the paper) of Theorem (thm:master of the paper), which gives the nesting of two-valued sets described in Section (sec:decomp of the paper).
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:13:49.973431+00:00","domain":"probability theory","id":"claim_4d1508317c501439fe5d244e8b1dea12bfc1fe2753fd7ad40eeaa2a822428de0","kind":"theorem","schema_version":1,"statement":"[Proposition eq:prop1 of arXiv:2411.07157, 'Rough differential equations in the flow approach'] Fix a universal constant $C_R>0$, and define 
\begin{equ}
\Xi \equiv \Xi(\xi, V,{\tt u} ,C_R)
\eqdef
\max \Big(
{\talloblong \omega\xi \talloblong}_{4}, C_R,
\|V\|_{C^9(B_0(C_R+|{\tt u}|))} \Big)\;.
\end{equ}
If there exists constants $C,p\geqslant1$ such that $T=C\Xi^{-p}$, we just write $T = T_{\Xi}$.

There exists $\tilde{T} = \tilde{T}_{\Xi} \in(0,1]$ such that, for any $T \in (0,\tilde{T}]$ and $\eps \in (0,1]$, the map
\begin{equs}
    \Phi:\binom{\theta_{\eps,}}{\tilde{R}_{\eps,}}\mapsto\binom{\Phi^\theta_{\eps,}}{\Phi^{\tilde{R}}_{\eps,}}(\theta_{\eps,},\tilde{R}_{\eps,})\eqdef\binom{-\int_{}^{T}\tilde K_{\nu,}\mathcal{R}^2_{\nu} \dot G_{\nu}  \big(\tilde{F}_{\eps,\nu}[K_{\nu}\theta_{\eps,\nu}]+\tilde{R}_{\eps,\nu}\big)\mathrm{d}\nu}{-\int_0^{}\tilde K_{,\nu}\big(
      \mathrm{D} \tilde{F}_{\eps,\nu}[K_{\nu}\theta_{\eps,\nu},\mathcal{R}_\nu\dot G_\nu \tilde{R}_{\eps,\nu}]+\Tilde{I}_{\eps,\nu}[K_\nu\theta_{\eps,\nu}]\big)
      \mathrm{d}\nu}    
 \end{equs}
is a contraction for the norm 
\begin{equs}    \nnorm{\theta_{\eps,},\tilde{R}_{\eps,}}_T\eqdef 
    \sup_{\mu\in(0,T]}{\| \theta_{\eps,\mu} 
    \|}_{L_{0;T}^\infty}\vee\sup_{\mu\in(0,T]}\mu^{-\delta/2}{\|  \tilde{R}_{\eps,\mu} 
    \|}_{L_{0;T}^\infty}\,.
\end{equs}
In particular, the system (equation eq:sys2 of the paper) has a unique solution, denoted $(\theta_{\eps,},\tilde{R}_{\eps,})$, satisfying the estimate
  \begin{equs}
        \sup_{\mu\in(0,T]}\mu^{-\delta/2}{\| \tilde{R}_{\eps,\mu} 
    \|}_{L^\infty_{0;T}}\leqslant C_R\,.
    \end{equs}
Finally, the solution $(\theta_{\eps,},\tilde{R}_{\eps,})$ is continuous in the data $(\tilde{F}_{\eps,},\Tilde{I}_{\eps,})$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T10:07:48.568829+00:00","domain":"probability theory","id":"claim_4d1bd4a2097094a25c29092fbac53411e363c9fe90df7db5b633cd3e0f653b86","kind":"concept","schema_version":1,"statement":"[Proposition 46 of arXiv:2609.01460, 'On cost-induced Santal\'o-type inequalities \\ in Polish measure spaces'] Let $A\subset \mathbb{S}^n$ be a measurable set with positive measure. Then,
\begin{equation}
\sigma_{n}(A^s) \leq \sigma_{n}(C_A^s).

\end{equation}
If $0<\sigma_n(A) < \frac{1}{2}$, there is equality in \eqref{eq:sph_BS} if and only if $A$ is a spherical cap up to removal of null sets. If $\sigma_n(A)\geq \frac{1}{2}$, there is always equality, namely, both sides of \eqref{eq:sph_BS} are zero. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:24:10.196763+00:00","domain":"probability theory","id":"claim_4d228cc885d60bafc855028a80f16d6525a529fb7bfa3a89082afb6e068c2755","kind":"definition","schema_version":1,"statement":"[Definition 27 of arXiv:2605.03851, 'The Relay Random Tree:\\A stochastic geometry approach of multihop relay in an urban visib'] \textbf{General Range.}

