where $B=\left(\prod_{m=1}^\ell(1+\alpha_m^{-1}\beta_m)(1+\alpha_{m+1}\beta_m^{-1})\right)$ and the implicit constant in the remainder term is uniform for compact subsets of $\Lambda_{\{0,1\}}^2$. 
 For $|Z_1|, |Z_2| \leq N^{\frac{1}{12}}$, the remainder term
 is uniformly $\mathcal{O}(N^{-\frac{1}{4}})$, as $N\rightarrow\infty$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T18:32:23.810647+00:00","domain":"probability theory","id":"claim_4f6828fa8c284eaa23894e28b1bbe10b562fc977499a0c80265dd882bfbabb39","kind":"definition","schema_version":1,"statement":"[Definition defi_solution of arXiv:2603.26307, '\LARGE The incompressible Navier--Stokes--Fourier system with thermal noise'] Let Assumption (Ass:noise of the paper) be satisfied, $u_0 \in L^2(\mathbb{T}^3; \mathbb{R}^3)$ be divergence-free and  $\psi_0\in L^2(\mathbb{T}^3)$ be non-negative.
	A  \emph{weak martingale solution 
		to (equation Eq_new_var of the paper)} 
	consists of a probability space $(\Omega,\mathfrak{A},\mathbb{P})$, a filtration $\mathscr{F}$ satisfying the usual conditions, independent $3$-dimensional standard $\mathscr{F}$-Brownian motions $(W_n)_{n\in \mathbb{Z}^3}$ and $3\times 3$-matrix valued $\mathscr{F}$-Brownian motions $(B_n)_{n\in \mathbb{Z}^3}$ with covariance structure (equation Eq_noise_matrix_covariation of the paper), a weakly continuous and adapted  $L^2(\mathbb{T}^3;\mathbb{R}^3)$-valued process
	$u$, and  progressively measurable   $\psi \in L^\infty(0,T;L^2( \mathbb{T}^3))$ and  $q\in \mathcal{M}_+([0,T]\times \mathbb{T}^3)$, $\mathbb{P}$-a.s., such that the following holds:
	\begin{enumerate}[(i)]
		\item  We have the additional regularity {$\nabla u\in L^{7/5}([ 0,T]\times \mathbb{T}^3 ;\mathbb{R}^{3\times 3})$ and $\nabla \psi \in  L^{7/5}([0,T]\times \mathbb{T}^3;\mathbb{R}^3)$}, $\mathbb{P}$-almost surely.
		\item   It holds  $\psi \ge 0$, $\mathbb{P}\otimes \mathrm{d} t \otimes \mathrm{d} x$-a.e., and  $q \ge \frac{1}{\psi}(|\nabla \psi|^2 + |\nabla_\mathrm{sym} u|^2)$,  as measures  on $[0,T]\times \mathbb{T}^3$, $\mathbb{P}$-almost surely. 
		\item   For every divergence-free $\varphi\in C^{{\infty}}(\mathbb{T}^3;\mathbb{R}^3)$ it holds
		\begin{align}\begin{split}
				& \int_{\mathbb{T}^3}  u_t\cdot \varphi\,\mathrm{d} x \,-\, 
				\int_{\mathbb{T}^3} u_0 \cdot \varphi\,\mathrm{d} x
				\\&\quad=\,  \int_0^t \int_{\mathbb{T}^3} -  \Bigl(\frac{1}{2}+ \frac{F_1}{4}\Bigr) \nabla u: \nabla  \varphi \,+\, u\otimes u:\nabla \varphi \,\mathrm{d} x\, \mathrm{d} s \,+\, \frac{1}{\sqrt{2}}\sum_{n \in \mathbb{Z}^3}\int_0^t \int_{\mathbb{T}^3}\psi f_n \nabla \varphi\,\mathrm{d} x :\mathrm{d} B_{n,s},
			\end{split}
		\end{align}
		and $\nabla \cdot u_t = 0$ for all $t\in [0,T]$, $\mathbb{P}$-almost surely.
		\item  
		For every $\zeta\in C_c^{{\infty}}([0,T) \times \mathbb{T}^3)$ it holds
		\begin{align}\begin{split}
				&-\,
				\int_0^T \int_{\mathbb{T}^3} \psi  \partial_t \zeta  \, \mathrm{d} x\, \mathrm{d} t \,-\, \int_{\mathbb{T}^3}
				\psi_0 \zeta
				\,\mathrm{d} x 
				\\&\quad=\,  \int_0^T \int_{\mathbb{T}^3} - \bigl(1+ {F_1}/2 +G_1/2\bigr) \nabla \psi\cdot \nabla  \zeta \,+\,\psi u\cdot \nabla \zeta   \,-\, (F_2/2+G_2/8) \psi \zeta \,\mathrm{d} x\,\mathrm{d} t \,+\, \int_{[0,T]\times\mathbb{T}^3} \zeta \,\mathrm{d} q
				\\&\qquad + \sum_{i=1}^3
				\sum_{n \in \mathbb{Z}^3}\int_0^T \int_{\mathbb{T}^3} \psi g_n \partial_i \zeta  + \frac{1}{2} \psi  \zeta \partial_ig_n \,\mathrm{d} x \, \mathrm{d} W_{n,t}^i
				\, +\, \frac{1}{\sqrt{2}}\sum_{i,j =1}^3\sum_{n \in \mathbb{Z}^3}\int_0^T \int_{\mathbb{T}^3}u_j\partial_i (\zeta f_n) \,\mathrm{d} x \,\mathrm{d} B_{n,t}^{ji},
			\end{split}
		\end{align}  $\mathbb{P}$-almost surely.
	\end{enumerate}
	A weak martingale solution to (equation Eq_new_var of the paper) is moreover called \emph{globally admissible}, whenever 
	\begin{equation}\mathrm{ess \, sup}_{t\in [0,T]}
		\frac{1}{2}\int_{\mathbb{T}^3}
		|u_t|^2 +\psi_t^2 \,\mathrm{d} x \,\le\, 
		\frac{1}{2}\int_{\mathbb{T}^3}
		|u_0|^2 +\psi_0^2 \,\mathrm{d} x,
	\end{equation}
	$\mathbb{P}$-almost surely.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T08:44:39.746926+00:00","domain":"probability theory","id":"claim_4f6d3cdc1153fa208d2a1ed8316c7e48ba2e3b82f13d1fa324734a8de083a837","kind":"lemma","schema_version":1,"statement":"[Lemma 18 of arXiv:2608.29872, 'Local Laws and Outlier Eigenvalues for Spiked Separable Covariance Matrices'] Under the assumptions of Theorem \ref{maintheorem}, for any deterministic matrices $\Gamma_1,\Gamma_2\in\C^{(p+n)\times(p+n)}$ satisfying $\norm{\Gamma_1},\norm{\Gamma_2}=\OO(1)$ and any deterministic unit vector $\uu \in \mathbf{S}$, we have
