where we recall that $\Theta$ is defined in (\ref{defn_Phi}).","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T01:41:54.341913+00:00","domain":"probability theory","id":"claim_4f7ba4912304c4c641f22557773fc96ba595bc452ac3bb8f1b1f208c14127a25","kind":"lemma","schema_version":1,"statement":"[Lemma lem:KPS of arXiv:2412.01381, 'Ergodicity and mixing for locally monotone stochastic evolution equations'] Assume that $(P_t)_{t\ge 0}$ has the $e$-property and that there exists $z\in H$ such that for every bounded set $J$ and every $\delta>0$, we have
\begin{equation}
\inf_{x\in J}\liminf_{T\to\infty} Q_T(x,B(z,\delta))>0.
\end{equation}
Suppose further that for every $\varepsilon>0$ and every $x\in H$, there exists a bounded Borel set $K\subset H$ such that
\begin{equation}
\liminf_{T\to\infty} Q_T(x,K)>1-\varepsilon.
\end{equation}
Then there exists a unique invariant probability measure $\mu_\ast$ for $(P_t)_{t\ge 0}$ such that the semigroup $(P_t)_{t\ge 0}$ is weak$^\ast$-mean ergodic and the weak law of large numbers holds.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T17:18:19.441169+00:00","domain":"probability theory","id":"claim_4f7e3266d4fda356a03466086fbff5a38dfec8a527c6a4041e7bd67a89b46cdf","kind":"theorem","schema_version":1,"statement":"[Theorem prop:U_asy of arXiv:2508.17838, '\bf Edge Universality for Inhomogeneous Random Matrices'] For the deformed Gaussian matrix $X$ in Definition (def:inhomo of the paper) and  under the assumptions (itm:B1 of the paper)-(itm:B2 of the paper) of Definition (mixingdef of the paper), with $n = \sum_{j=1}^s n_j$, $a=\|A_N\|_{\mathrm{op}}$, the following hold.
\begin{enumerate}[label=(\roman*)]
  \item  For all  $n_j\ge 1$, there exists a constant $C > 0$ such that
\begin{equation} 
\mathbb{E}\left[\prod_{j=1}^s \operatorname{Tr} \left(U_{n_j}\left(\frac{X}{2}\right)\right)\right]
\le (1 + a^n)(C n)^s \left\{e^{C \frac{n^{\frac{3}{2}}}{\sqrt{N}}} + (1\lor \frac{t_N}{n})^s e^{C \frac{n^2 t_N}{N}} + \Big((\frac{C n^2 t_N}{N})^{[\frac{n}{t_N}]}\land 1\Big) e^{C \frac{n^3}{N}}\right\}.
\end{equation}
  \item  If   $a \le 1 + O( N^{-\frac{1}{3}})$ and $t_N \ll n_j = O(N^{\frac{1}{3}})$, then
  \begin{equation}
   \mathbb{E}\Big[\prod_{j=1}^s \mathrm{Tr} \big(U_{n_j}\big(\frac{X}{2}\big)\big)\Big]
    = \mathbb{E}\Big[\prod_{j=1}^s \mathrm{Tr} \big( U_{n_j}\big(\frac{\widetilde{X}}{2}\big)\big)\Big]
    + o(n^s),
  \end{equation}
  where $\widetilde{X} =  \frac{1}{\sqrt{N}} W_{N}^{(\mathrm{G}\beta \mathrm{E})}+A_N$.
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T08:44:39.746731+00:00","domain":"probability theory","id":"claim_4f7f419a460f89915cc59fe8a1b8e4a13cfa8c24c3ba4b2cc5efd30244b79515","kind":"concept","schema_version":1,"statement":"[Lemma 17 of arXiv:2608.29872, 'Local Laws and Outlier Eigenvalues for Spiked Separable Covariance Matrices'] (Cumulant expansion formula, Lemma C.11 of \cite{bao2020statisticalinferenceprincipalcomponents}) For a fixed $\ell\in \mathbb{N}$, let $f\in C^{\ell+1}(\mathbb{R})$. Suppose that $\xi$ is a centered random variable with finite moments up to order $\ell+2$. Then we have  
\begin{equation}
\expect\qb{\xi f(\xi)}=\sum_{k=1}^{\ell}\frac{\kappa_{k+1}(\xi)}{k!}\expect\qb{f^{(k)}(\xi)}+\cal R_{\ell+1},
\end{equation}
where the error term $\cal R_{\ell+1}$ satisfies
\begin{equation}
\abs{\cal R_{\ell+1}}\leq C_\ell\expect\qb{|\xi|^{\ell+2}}\sup_{|t|\leq s}|f^{(\ell+1)}(t)|+C_\ell\expect\qb{|\xi|^{\ell+2}\mathds{1}(|\xi|>s)}\sup_{t\in \mathbb{R}}|f^{(\ell+1)}(t)|
\end{equation}
for any $s>0$ and $C_\ell:=(C\ell)^{\ell}/\ell!$ for some constant $C>0$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T16:38:11.736853+00:00","domain":"probability theory","id":"claim_4f82251db9a5df2164714b50a254f7962a7d177251b4d2c679bb517bbee0c5d7","kind":"lemma","schema_version":1,"statement":"[Lemma lem_prop_flow of arXiv:2504.00512, 'Localization-delocalization transition for a random block matrix model at the edge'] [Basic properties for the flow]

Under (flow of the paper), the following properties hold for $t\in \left[{t_0,t_c}\right]$.

\begin{itemize}
    \item If $t_c-t=\mathrm{o}(1)$, we have that (recall $m_t$ defined in (equation eq:Zt of the paper))
    \begin{equation}
t_c-t=\frac{\im z_t}{\im m_t}(1+\mathrm{o}(1)).

 \end{equation}

 \item $M_t$ satisfies the following equation:
 \begin{equation}
  \frac{\mathrm{d} }{\mathrm{d} t} M( z_t, \Lambda_t)=\frac{1}{2}M( z_t, \Lambda_t).  

\end{equation}
From this equation, we easily see that \begin{equation}
    \begin{aligned}
        \im m_t\sim \im m_{t_0} \quad \text{whenever}\quad t-t_0=\mathrm{O}\left({1}\right) \, .
    \end{aligned}
\end{equation}

 \item {\bf Conjugate flow}: We have $Z_t^*=Z(\overline z_t, \Lambda_t)$, $M_t^*=M(\overline z_t, \Lambda_t)$, and $\overline m_t=m_t(\overline z_t,\Lambda_t)$. Moreover, they satisfy the following equations under the conjugate flows $(\overline z_t, \Lambda_t)$:
\begin{equation}
 \frac{\mathrm{d}}{\mathrm{d} t}Z(\overline z_t, \Lambda_t )=-\frac12 Z(\overline z_t, \Lambda_t )- m_t(\overline z_t, \Lambda_t ) ,\quad \frac{\mathrm{d}}{\mathrm{d} t} M( \overline z_t, \Lambda_t)=\frac{1}{2}M( \overline z_t, \Lambda_t).
\end{equation}




   \item  For any $   (z_{i})_{t}\in \{z_t, \overline z_t\}$, $i\in\{1,2,3\}$, $\widehat M_{(1,2),t}$ and $K_{(1,2),t}$ satisfy the equations
   \begin{equation}
    \frac{\mathrm{d}}{\mathrm{d} t}\widehat M_{(1,2),t} =\widehat M_{(1,2),t},\quad \frac{\mathrm{d}}{\mathrm{d} t} K_{(1,2),t}= \left(K_{(1,2),t}\right)^2+K_{(1,2),t},
    \end{equation}
     and $K_{(1,2,3),t}$ satisfies the following equation for any $a_1,a_2,a_3\in [\![{D}]\!]$: 
    \begin{align}
        \frac{\mathrm{d}}{\mathrm{d} t} (K_{(1,2,3),t})_{a_1 a_2 a_3}= \frac{3}{2}K_{(1,2,3),t} + \sum_{a=1}^D &\left[(K_{(1,2),t})_{a_1 a}(K_{(1,2,3),t})_{a a_2 a_3}  +(K_{(2,3),t})_{a_2 a}(K_{(1,2,3),t})_{a_1 a a_3} \right. \nonumber\\
    &\left.+ (K_{(3,1),t})_{a_3 a}(K_{(1,2,3),t})_{a_1 a_2 a}\right] .    
    \end{align} 






\end{itemize}","status":"unverified"}

