and analogously, the \textbf{$BA$-transition entrance distribution} on \(\bar{A} \cap (A + 1)\):  
\begin{equation}
    \eta^+_A(\d x) = \frac{1}{v_A^+}\rho(x)\overleftarrow{\mathcal{L}}\overleftarrow{q}(x)\d x,
\end{equation}
where \(v_A^+\) and \(v_B^+\) are normalizing constants such that these define probability measures.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:34:33.544898+00:00","domain":"probability theory","id":"claim_595e5bd53e53e26457693626c69bb2ece92155d4ff86dc7cb9bacc13abf83fc6","kind":"definition","schema_version":1,"statement":"[Definition 43 (Glauber dynamic) of arXiv:2603.28734, 'Free energy analyticity of the disordered XY model and Debye screening in the 2D Coulomb g'] Consider the square lattice graph $\Z^d$ (also denoted $G=(V,E)$).
    Let $\mu$ denote a stationary measure on $\Pi_G$.
    For any $u\in V$, let $G_u$ denote the subgraph of $G$ induced by the vertices $V\setminus\{u\}$.
    A \emph{Glauber dynamic} for $\mu$ is a function
    \[
        R:\Pi_G\times V\times\Sigma \to \Pi_G,
    \]
    with the following properties.
    \begin{itemize}
        \item\textbf{Local update.}
        For any $\tau\in \Pi_G$, $u\in V$ and $\iota\in\Sigma$, we have $R(\tau,u,\iota)|_{G_u}=\tau|_{G_u}$.
        \item\textbf{Consistency.}
        For any $\tau\in \Pi_G$ and $u\in V$, the distribution of $R(\tau,u,\iota)$ in $\diff\iota$ is $\mu[\blank|\tau|_{G_u}]$.
        \item\textbf{Equivariance.}
        For any $\tau\in \Pi_G$, $u\in V$, $\iota\in\Sigma$ and $\theta\in\Theta$, we have $R(\tau,u,\iota)\circ\theta=R(\tau\circ\theta,u\circ\theta,\iota)$.
    \end{itemize}
    We shall also write $R_{u,\iota}:\Pi_G\to\Pi_G,\,\tau\mapsto R(\tau,u,\iota)$ for any $u\in V$ and $\iota\in\Sigma$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:55:18.058686+00:00","domain":"probability theory","id":"claim_596330833ff5bc770538caed541e4ca76da628a0e358d319d9e14eeea9206b8d","kind":"theorem","schema_version":1,"statement":"[Corollary 45 (One-species formula for balanced models) of arXiv:2606.16636, 'Free energy of non-convex multi-species spin glasses with centered Ising spins'] Assume that $\xi$ is balanced with respect to $\lambda$. Then, for every $t\geq0$,
\begin{equation}

    \lim_{N\to\infty}\bar F_N(t,0)=\sup_{a\in\mcl Q_\infty}\inf_{r\in\mcl Q_\infty}\left\{\psi_\circ(r)-\la r,a\ra_{L^2}+t\int_0^1\xi_\star(a(v))\,\d v\right\}.
\end{equation}
In particular, for the explicit balanced models in Lemma~\ref{l.power_series_balanced_models}, the effective one-species covariance function is
\begin{equation}

    \xi_\star(x)=\sum_{p\geq1}\beta_p^2x^p,\qquad \beta_p^2=\sum_{s_1,\ldots,s_p\in\sS}\Delta^2_{s_1,\ldots,s_p}\lambda_{s_1}\cdots\lambda_{s_p}.
\end{equation}","status":"unverified"}

