{"assumptions":[],"created_at":"2026-10-26T19:37:51.460291+00:00","domain":"probability theory","id":"claim_5a69b38e94caf4de4ff036bcc2a63349a34c560190bd82e55c190cea329d0290","kind":"theorem","schema_version":1,"statement":"[Prop 49 of arXiv:2604.03777, 'Equilibrium fluctuations for a multi-species particle system with long jumps'] Let $(k_j)_{j \in \mathbb{Z} } \subset \mathbb{Z}$ be such $k_j - k_{j-1} >0$, for any $j \in \mathbb{Z}$. Moreover, for any $j \in \mathbb{Z}$ let $F_j: [0, T] \times \Omega \mapsto \mathbb{R}$ be such that, for every $s \in [0, \; T]$, $\supp \big( F_j(s, \cdot) \; \big) \subset \{k_{j-1}+1, \ldots ,  k_j\}$, and $\mathbb{E}_{\nu_{\rho}} \big[ F_j(s, \eta) \big]=0$. Therefore, there exists some universal constant $\kappa$ such that
	\begin{align*}
		\forall t \in [0, T], \quad \mathbb{E}_{\nu_{\rho}} \Bigg[ \sup_{s \in [0,t] } \Bigg(  \int_{0}^s \sum_{j} F_j(r, \; \eta_r^n) \; \dd r \Bigg)^2  \Bigg] \leq  \kappa \int_0^{t}  \sum_{j}   \frac{(k_j - k_{j-1})^{\gamma}}{\Theta(n)} \mathbb{E}_{\nu_{\rho}} \big[ \big\{ F_j(s, \eta) \}^{2} \big] \dd s.
	\end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:28:53.744299+00:00","domain":"probability theory","id":"claim_5a6bc9dd629b1385cf26ba6b767ef65f8ed0dde2af70869561073388ff3b8856","kind":"lemma","schema_version":1,"statement":"[Lemma 12 of arXiv:2605.13727, 'Stochastic evolution equations\\ driven by arbitrary cylindrical Lévy processes'] Let $L$ be a cylindrical L\'evy process in $U$, and let $\Psi$ be a predictable, $L_2(U,H)$-valued process that is integrable with respect to $L$. Then the integral process $(Y(t):\, t\in [0,T])$, defined by $Y(t):=\int_{(0,t]} \Psi\,{\rm d}L$, satisfies the following properties: 
	\begin{enumerate}
        \item [{\rm (a)}] Let $V$  be a separable Hilbert space  and $B \in L(H,V)$. Then, for all $0\leq p<q\leq T$ and $S \in \mathcal{F}_{p}$, we have that $\mathbb{1}_S B\Psi$ is $L$-integrable and
        	\begin{equation}
        		\mathbb{1}_{S}B \left(\int_{(p,q]} \Psi(s)\,{\rm d}L(s)\right)=\int_{(p,q]} \mathbb{1}_S B\Psi(s)\,{\rm d}L(s).
        \end{equation}
		\item [{\rm (b)}] Let $\Phi:\Omega\times[0,T]\rightarrow H$ be a uniformly bounded, adapted, càglàd process. Then, for each fixed $t>0$,  it follows that $\langle \Psi^\dagger \Phi, \cdot \rangle$ is $L$-integrable and
		\[\int_{(0,t]} \langle\Phi(s),\cdot\rangle \, {\rm d}Y(s)=\int_{(0,t]} \big\langle \Psi^\dagger(s)\Phi(s),\cdot\big\rangle \, {\rm d}L(s).\]
		\item [{\rm (c)}] For every stopping time $\tau$, we have that $\1_{(0,\tau]}\Psi$ is $L$-integrable and
		\[Y(\tau \wedge T)=\int_{(0,T]} \1_{(0,\tau]}(s)\Psi(s)\,{\rm d}L(s).\]
	\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:25:40.221838+00:00","domain":"probability theory","id":"claim_5a792abc2edb739db7ac721dc9187a5c86ecbeb7f72d2d9aa64dc0c727afe40f","kind":"theorem","schema_version":1,"statement":"[Proposition prop:master-generating of arXiv:2609.02544, 'A finiteness theorem for geodesic Leech wheels'] A geodesic Leech labeling satisfies the following identity.
\begin{equation}
  \sum_{r=1}^{N}z^r
  =P_A(z)+P_B(z)+C_B(z)
  +\frac{P_A(z)^2-P_A(z^2)}2-C_A(z).
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:49:17.502657+00:00","domain":"probability theory","id":"claim_5a7c30fa88e1bfa70a9c948769ec446e1ab7979f90ce0cb7de995ae06433a481","kind":"concept","schema_version":1,"statement":"[Lemma 24 of arXiv:2605.30030, 'Critical exponents for planar random-cluster model with cluster-weight~$q=4$'] There exists~$c >0$ such that the following holds. 
	For any~$R > r > \delta$ and
	any events~$A$ and~$B$ depending on the edges in~$\Lambda^\delta_{r}$ and outside~$\Lambda^\delta_{R}$, respectively, 
	\begin{align}
	\big|\tfrac{\rcP[A \cap B]}{\rcP[A]\rcP[B]}-1\big| \le c \Delta^\delta(r,R).
	\end{align}
	For any~$r_1,r_2 > \delta$ with~$r_1 + r_2 \leq |x|/2$, 
	and any events~$A$ and~$B$ depending on the edges in~$\Lambda^\delta_{r_1}$ and~$\Lambda^\delta_{r_2}(x)$, respectively, 
	\begin{align}
	\big|\tfrac{\rcP[A \cap B]}{\rcP[A]\rcP[B]}-1\big|\le c \Delta^\delta(r_1,|x|) \Delta^\delta(r_2,|x|).
	\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:00:22.781557+00:00","domain":"probability theory","id":"claim_5a7e8dd5236465c706f63ead40879bf7d8f008836c12b8c6347a0b0daf9cd2d7","kind":"theorem","schema_version":1,"statement":"[Prop vartheta = theta + epsilon of arXiv:2411.01633, 'On the Limit of the Tridiagonal Model \\for $\beta$-Dyson Brownian Motion'] On the event $A_k$ defined in Lemma (Concentration for specific functionals of theta of the paper), for $n$ sufficiently large, we have,
\begin{equation}
        \vartheta_k(t) = (c_k(t)+\mu_k(t))\theta_k(t)+\epsilon_k(t),
    \end{equation}
    with $c_k(t):=\frac{1}{\|\theta_{k-1}(t)\|}$, $\epsilon_k(t) \in \Theta_{k-1}(t)+ \mathcal{E}_k(t)$, $\sup_{t \in [0,T]}\|\epsilon_k(t)\| \leq C_{k,T} \frac{\log(n)}{\sqrt{n}}$, and $\sup_{t \in [0,T]} |\mu_k(t)| \leq C_{k,T}\frac{\log(n)^{2(k-1)}}{n}$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:27:08.848778+00:00","domain":"probability theory","id":"claim_5a89742d3893fe13ef8cba6301e133a9cc1476c55c1ba14534a08f110b556af2","kind":"definition","schema_version":1,"statement":"[Defination 6 (Stochastic Process of Order $\eps^\kappa$) of arXiv:2511.10814, '\Large \bf \boldmath\ \\ Convergence of the extended Kalman filter with small and state-de'] A family of stochastic processes $ \x(t)=(\x^\eps(t))_{t\ge 0}$, $\eps>0$ is said to be \textbf{ of order $\eps^\kappa$} 
			for some $\kappa>0$  if for any $q\in [1,\infty)$ there exist   constants $\eps_q>0, ~ C_q>0$, 
			such that 			
			$$\eps^{-\kappa} \left\vert\x^\eps(t) \right\vert_{q} \le C_q   ~~\text{for all}~~ (t,\eps)\in[0,\infty)\times (0,\eps_q).	$$			
		Similarly, a family of random variables  $ X=(X^\eps)$, $\eps>0$ is said to be of order $\eps^\kappa$ 
			for some $\kappa>0$  if for any $q\in [1,\infty)$ there exist   constants $\eps_q>0,~ C_q>0$, 
			such that			
			$$\eps^{-\kappa} \left\vert{X^\eps} \right\vert_{q} \le C_q   ~~\text{for all}~~ \eps\in (0,\eps_q).	$$","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:35:04.213987+00:00","domain":"probability theory","id":"claim_5a8acb8413e6984be1649daf315c18936b6d3975bf34b5c687e5cc160e05e96a","kind":"theorem","schema_version":1,"statement":"[Coro 12 of arXiv:2608.03956, 'From Triangular Array Progression\\ to Near-Log-Concave State Transitions'] Let $p^{(n)}_{\T}$ be the polynomial as given in (\ref{triangularpolynomial}) for every $n\geq 0$. Define 
\begin{align}
q^{(n)}(x) = p^{(n)}_{\T}(x) - (x+1)^n \hspace{0.1in} \forall x \in \R, \notag
\end{align}
as the deviation polynomial $q^{(n)}$ for every $n\geq 0$. Then, 
\begin{enumerate}
\item $q^{(n)} = 0$ for $n\in\{0,1,2,3\}$
\item $q^{(n)}$ has degree $n-1$ for $n\geq4$ and its coefficients sum to zero
\end{enumerate}
Accordingly, $q^{(n)}$ has a root at $x=1$ for every $n\geq 0$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:01:22.600089+00:00","domain":"probability theory","id":"claim_5aa0506ec645849f7a6737b8ad807aa9d7329c520996a7334725f23c8a7c3a84","kind":"lemma","schema_version":1,"statement":"[Lemma lem:x=v+eta(ej-ei) of arXiv:2606.10257, 'Downward conditional monotonicity gives survival and extinction for contact processes in r'] Let $x=v^*+\eta(e_j-e_i)$ for some fixed $\eta>0$ and fixed pair $i<j$. Assume that $T$ is strictly monotone, that $\alpha$ is increasing, and that, for every $\ell<i$,
	\begin{equation}
