    	\end{equation*} 
    	is uniformly integrable. Then, we have in probability and in \(L^1\),
		\begin{equation}
			\frac{1}{\sharp \mathscr{V}(\mathscr{D}_t)}\sum_{\boldsymbol{x}\in \mathscr{D}_t}H(\boldsymbol{x},\mathscr{D}_t) \longrightarrow \mathbb{E}_o[H(\0,\mathscr{D}_o)],
		\end{equation}
		as \(t\to\infty\). (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:07:15.764491+00:00","domain":"probability theory","id":"claim_5c01b506f84d5ff10eeb0880528366b8a705180f43cc82946e405ae1007acb86","kind":"theorem","schema_version":1,"statement":"[Proposition prop:lbm-full-cm-response of arXiv:2608.02459, 'Response Calculus for Spectral Simplicity\\ and Joint Eigenvalue Densities'] Let $x\in\Omega_{\rm LBM}$ and let $\Lambda>0$ have multiplicity
$r$ for $A_x$, with real $L^2(M_x)$-orthonormal eigenbasis
$(\phi_i)_{i=1}^r$.  Set
\begin{equation}
 \sigma_{ij}^x
 :=\Theta_{M_x}(\phi_i,\phi_j)=\phi_i\phi_jM_x
 \in\mathcal M_{\rm fe}(D),
 \qquad 1\le i,j\le r.

\end{equation}
The response in (equation eq:lbm-cluster-response-matrix of the paper), initially defined
for $f\in C_c^\infty(D)$, extends uniquely to a continuous linear map
$f\mapstoB_f^\Lambda(M_x)$ on $H$, given by
\begin{equation}
 \begin{aligned}
 \left(\inner{B_f^\Lambda(M_x)\phi_j}{\phi_i}
              _{L^2(M_x)}\right)_{i,j=1}^r
 &=-\gamma\Lambda
 \left(\inner{U_D\sigma_{ij}^x}{f}_{H}\right)_{i,j=1}^r\\
 &=-\gamma\Lambda
 \left(\int_D\widetilde f\,\phi_i\phi_j\,dM_x\right)_{i,j=1}^r.
 \end{aligned}

\end{equation}
For $f\in H_0^1(D)\setminus C_c^\infty(D)$, this notation denotes only the
continuous extension; no tilted operator or analytic eigenvalue branch is
asserted.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:32:19.938337+00:00","domain":"probability theory","id":"claim_5c077fee50acfa6be3a6f8685df0e3c9176fb32714225b11e05707289c15a2ea","kind":"theorem","schema_version":1,"statement":"[Corollary 26 of arXiv:2608.02927, 'Thinning Operation via the Poisson-F\"ollmer Process'] Let $T=\E X$ and $X$ be a random variable with density $f$ with respect to $\pi_{T}.$ Assume that $f$ is bounded away from zero and infinity and $H(X|\pi_{T}) < \infty.$ Then, for every $a$ in $[0,1],$ we have
    \begin{displaymath}
        \frac{d}{da} \big(  H  ( T_{a}(X) | \pi_{aT} ) \big) = T H \big( T_{a} (S(X)) | T_{a}(X) \big) .
    \end{displaymath}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:55:18.935349+00:00","domain":"probability theory","id":"claim_5c1330eafc9c89014dfbf1d84976a56a9c2e6d7315226a9b261851520ebbb5ad","kind":"theorem","schema_version":1,"statement":"[Theorem lem:explicit-left-M of arXiv:2602.07920, 'On the position matrix of single-shelf shuffle and card guessing'] Let $n\ge 2$ and let $i\in \mathcal E_n$. For each
$1\le a\le n$, the $a$th coordinate of the left eigenvector
$\widetilde\zeta^{(i)}=(\widetilde{w}^{(i)})^\top B^{-1}$ is given by
\begin{equation}
\widetilde\zeta^{(i)}(a)
= \frac{1}{i!(n-i)}\Bigl[
   (-1)^{\,i-a}\binom{i-1}{a-1}
 + (-1)^{\,n-1-a}\binom{i-1}{a-1-(n-i)}
 \Bigr],
\end{equation}
where, as usual, $\binom{m}{r}=0$ if $r<0$ or $r>m$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:34:33.540422+00:00","domain":"probability theory","id":"claim_5c1972440eb7f809847b20dc212ff473b2ca98249e72c2c7c6d7b9294a0f0ee8","kind":"definition","schema_version":1,"statement":"[Definition 10 (Two-dimensional Coulomb gas) of arXiv:2603.28734, 'Free energy analyticity of the disordered XY model and Debye screening in the 2D Coulomb g'] Fix $d=2$ and $\beta\in\R_{\geq 0}$.
    The \emph{two-dimensional lattice Coulomb gas} on $\Lambda_n$ with free boundary conditions at inverse temperature $\beta$
    is the probability measure on $q\in\Z^{F(\Lambda_n)}$
    given by
    \begin{equation}

        \mu_{\Coulomb,\Lambda_n,\beta}^\free[\{q=Q\}] = \frac{1}{Z_{\Coulomb,\Lambda_n,\beta}^\free} \mathbf{1}\Big[\sum\nolimits_{f\in F(\Lambda_n)}Q(f)=0\Big]\cdot e^{-\frac{\beta(2\pi)^2}{2} \langle Q , -\Delta^{-1} Q \rangle}.
    \end{equation}
    Notice that, contrary to the XY model,
    the Hamiltonian of the Coulomb gas is non-local due to the presence of the inverse Laplacian.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:47:40.724283+00:00","domain":"probability theory","id":"claim_5c1d66faf9cabc6d9abd83558af64af97fed4b467fccc19434bc2b92da24b937","kind":"concept","schema_version":1,"statement":"[Proposition prop:unif_bound_ratio_probas of arXiv:2604.18558, 'Uniform analyticity of local observables in FK-percolation and analyticity of the Ising sp'] There exist $\delta > 0$ and a sequence $c_\epsilon$ going to 0 when $\epsilon$ goes to 0 such that for any $|z|\leq \epsilon < \delta$, any $N \geq 0$, and any non-negative local function $F$ which is not identically 0, 
