{"assumptions":[],"created_at":"2026-10-27T08:18:19.216421+00:00","domain":"probability theory","id":"claim_5d3e3ee136a61fb8d16f50ebcc8a8d300a23ff67601f7ebeef34bbec68db0ecd","kind":"definition","schema_version":1,"statement":"[Definition 8 (\cite{Aguiar2010}) of arXiv:2608.29075, 'The 2-Monoidal Structure of Symmetric Sequences'] A \textit{2-monoidal category} is a 5-tuple $(\C,\square,I,\circ,J)$ where $(\C,\square,I)$ and $(\C,\circ,J)$ are monoidal categories with units $I$ and $J$ respectively, along with a transformation (called the interchange law) $$\zeta_{A,B,C,D}: (A \circ B) \square (C \circ D) \rightarrow (A \square C) \circ (B \square D)$$ that is natural in $A,B,C$, and $D$, and three morphisms $$\Delta_I: I \rightarrow I \circ I, \quad \mu_J: J \square J \rightarrow J, \quad \iota_J = \epsilon_I: I \rightarrow J,$$ such that the axioms below are satisfied.

    \textbf{Associativity.} The following diagrams commute.
\begin{equation}
\begin{tikzcd}
	{\Big((A \circ B)\square (C \circ D)\Big) \square (E \circ F)} & {(A \circ B)\square \Big((C \circ D) \square (E \circ F)\Big)} \\
	{\Big((A \square C)\circ (B \square D)\Big) \square (E \circ F)} & {(A \circ B) \square \Big((C \square E) \circ (D \square F)\Big)} \\
	{\Big((A \square C) \square E\Big) \circ \Big((B \square D) \square F\Big)} & {\Big(A \square (C \square E)\Big) \circ \Big(B \square (D \square F)\Big)}
	\arrow["{\scriptscriptstyle a^\square}", from=1-1, to=1-2]
	\arrow["{\scriptscriptstyle \zeta \square (\id \circ \id)}"', from=1-1, to=2-1]
	\arrow["{\scriptscriptstyle (\id \circ \id) \square \zeta}", from=1-2, to=2-2]
	\arrow["{\scriptscriptstyle \zeta}"', from=2-1, to=3-1]
	\arrow["{\scriptscriptstyle \zeta}", from=2-2, to=3-2]
	\arrow["{\scriptscriptstyle a^\square \circ a^\square}"', from=3-1, to=3-2]
\end{tikzcd}\end{equation}

\begin{equation}
\begin{tikzcd}
	{\Big((A \circ B)\circ C\Big) \square \Big((D \circ E) \circ F\Big)} & {\Big(A \circ (B\circ C)\Big) \square \Big(D \circ (E \circ F)\Big)} \\
	{\Big((A \circ B) \square (D \circ E)\Big) \circ (C \square F)} & {(A \square D) \circ \Big((B \circ C) \square (E \circ F)\Big)} \\
	{\Big((A \square D) \circ (B \square E)\Big) \circ (C \square F)} & {(A \square D) \circ \Big((B \square E) \circ (C \square F)\Big)}
	\arrow["{\scriptscriptstyle a^\circ \square a^\circ}", from=1-1, to=1-2]
	\arrow["{\scriptscriptstyle \zeta}"', from=1-1, to=2-1]
	\arrow["{\scriptscriptstyle \zeta}", from=1-2, to=2-2]
	\arrow["{\scriptscriptstyle \zeta \circ (\id \square \id)}"', from=2-1, to=3-1]
	\arrow["{\scriptscriptstyle (\id \square \id) \circ \zeta}", from=2-2, to=3-2]
	\arrow["{\scriptscriptstyle a^\circ}"', from=3-1, to=3-2]
\end{tikzcd}\end{equation}

\textbf{Unitality.} The following diagrams commute.
\begin{equation}
\begin{tikzcd}
	{I \square (A \circ B)} & {(I \circ I)\square(A \circ B)} && {(A \circ B) \square I} & {(A \circ B)\square (I \circ I)} \\
	{A \circ B} & {(I \square A) \circ (I \square B)} && {A \circ B} & {(A \square I) \circ (B \square I)}
	\arrow["{\scriptscriptstyle \Delta_I \square (\id \circ \id)}", from=1-1, to=1-2]
	\arrow["{\scriptscriptstyle \zeta}", from=1-2, to=2-2]
	\arrow["{\scriptscriptstyle (\id \circ \id) \square \Delta_I}", from=1-4, to=1-5]
	\arrow["{\scriptscriptstyle \zeta}", from=1-5, to=2-5]
	\arrow["{\scriptscriptstyle l^\square_{A \circ B}}", from=2-1, to=1-1]
	\arrow["{\scriptscriptstyle l^\square_A \circ l^\square_B}"', from=2-1, to=2-2]
	\arrow["{\scriptscriptstyle r^\square_{A \circ B}}", from=2-4, to=1-4]
	\arrow["{\scriptscriptstyle r^\square_A \circ r^\square_B}"', from=2-4, to=2-5]
\end{tikzcd}\end{equation}

\begin{equation}
\begin{tikzcd}
	{J \circ (A \square B)} & {(J \square J) \circ (A \square B)} && {(A \square B)\circ J} & {(A \square B) \circ (J \square J)} \\
	{A \square B} & {(J \circ A) \square (J \circ B)} && {A \square B} & { (A \circ J) \square (B \circ J)}
	\arrow["{\scriptscriptstyle \mu_J \circ (\id \square \id)}"', from=1-2, to=1-1]
	\arrow["{\scriptscriptstyle (\id \square \id) \circ \mu_J}"', from=1-5, to=1-4]
	\arrow["{\scriptscriptstyle l^\circ_{A \square B}}", from=2-1, to=1-1]
	\arrow["{\scriptscriptstyle l^\circ_A \square l^\circ_B}"', from=2-1, to=2-2]
	\arrow["{\scriptscriptstyle \zeta}"', from=2-2, to=1-2]
	\arrow["{\scriptscriptstyle r^\circ_{A \square B}}"","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:49:49.204699+00:00","domain":"probability theory","id":"claim_5d48c3e28de1df9d165b3b48752eb7b1549c475dd00141ad6ac81cafd9847a44","kind":"concept","schema_version":1,"statement":"[Theorem 9 (Cholesky decomposition with stochastic rounding) of arXiv:2604.27119, '\Large Applied Random Matrix Theory\relatedversion'] Let $\mtx{A} \in \Sym_d^{++}(\R)$ be a $d \times d$ positive-definite matrix with $\diag(\mtx{A}) = \Id$. 
