\begin{equation}  A(\omega,x,y) =  \lim_{n\to\infty}  [L_{x,\pi_n}(\omega) - L_{y, \pi_n}(\omega) ] \quad \forall x,y\in\mathbb{Z}^2    \end{equation}
that recovers the weights $\omega$: 
\[  \omega_x = A(\omega,x,x+e_1) \wedge A(\omega,x,x+e_2).\qedhere \]","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:21:52.422045+00:00","domain":"probability theory","id":"claim_62511eb01143c2002ac1e6d96d4f0d9b54f85e60f3b0ea80579d461760675d9a","kind":"concept","schema_version":1,"statement":"[Proposition 140 of arXiv:2601.16377, '2601.16377'] Consider a discrete ensemble satisfying Assumptions~\ref{Assumptions_Theta}, \ref{Assumptions_basic}, \ref{Assumptions_offcrit}, \ref{Assumptions_analyticity} and the additional Assumption~\ref{Assumptions_extra}. For any $h,h_2\in[H]$, any $z\in \amsmathbb M_h\setminus \amsmathbb{A}_h^{\mathfrak{m}}$ and $z_2\in\amsmathbb C\setminus \amsmathbb{A}_{h_2}^{\mathfrak{m}}$, we have
\begin{equation}

\begin{split}
& \quad Q_{h}^{-}(z)\big\langle \bth_{h}\cdot \boldsymbol{W}_{2;\bullet,h_2}(z,z_2)\big\rangle + \frac{\delta_{h,h_2}\,Q_{h}^{-}(z)}{2(z_2 - z)^2} \\
& = \widetilde R_{h;h_2}(z;z_2)+ \mathbbm{Err}_{h;h_2}^{(1)}(z;z_2)+ \mathbbm{Err}_{h;h_2}^{(2)}(z;z_2).
\end{split}
\end{equation}
Here, $\widetilde R_{h;h_2}(z;z_2)$ is a meromorphic function of $z\in \amsmathbb M_h$, with only possible singularities being simple poles at $z=z_2 \pm \frac{1}{2\N}$. It is also holomorphic in $z_2\in\amsmathbb C\setminus \amsmathbb{A}_{h_2}^{\mathfrak{m}}$ except for the singularity we just mentioned. If $\hat a'_h \in \amsmathbb{S}_h$, then $\widetilde R_{h;h_2}(\hat a'_h;z_2)=0$; if $\hat b'_h\in \amsmathbb{S}_h$, then $\widetilde R_{h;h_2}(\hat b'_h;z_2)=0$.

Besides, for any $\N$-independent $\eps>0$ and disjoint pair of $\N$-independent compacts $\amsmathbb{K}_h \subset \amsmathbb{M}_h \setminus \amsmathbb{A}_h^{\mathfrak{m}}$ and $\amsmathbb{K}^{(2)}_{h_2} \subset \amsmathbb{C} \setminus \amsmathbb{A}_{h_2}^{\mathfrak{m}}$, there exists a constant $C>0$ depending only on $\eps$, these compacts and the constants in the assumptions, such that
   \begin{equation}
    \sup_{\substack{(z,z_2) \in \amsmathbb{K}_h \times \amsmathbb{K}_{h_2}^{(2)}}} \big|\mathbbm{Err}_{h;h_2}^{(1)}(z;z_2)\big|\leq C \N^{-\frac{1}{2}+\eps}.
   \end{equation}
The function $\mathbbm{Err}_{h;h_2}^{(2)}(z;z_2)$ is a finite sum --- with a number of terms which does not depend on anything --- of expressions of the form
  \begin{equation}

  \frac{F(z)}{\N^{q}} \cdot \prod_{i=1}^k \E \left[ \big(\Delta G_{h_2}(z_2)\big)^{\tilde{l}_{i}} \cdot \prod_{j=1}^{l_i} \partial_z^{d_{i,j}} \Delta G_{g_{i,j}}(z) \right],
  \end{equation}
  for some $q,k,l_1,\ldots,l_k \in \amsmathbb{Z}_{> 0}$ and $\tilde{l}_1,\ldots,\tilde{l}_k \in \{0,1\}$ satisfying\footnote{In fact, there is exactly one $\tilde{l}_{i}$ equal to $1$ and the other are equal to $0$. So, \eqref{eq_Err2_bound_two_2} is the same constraint as \eqref{eq_Err2_bound2}.}
  \begin{equation}

  q+1\leq \sum_{i=1}^k (l_i+\tilde{l}_i)\leq q+2,
  \end{equation}
  some function $F(z)$ holomorphic for $z \in \amsmathbb{K}_h$ and bounded from above in absolute value by $C$, and some $d_{i,j} \in \{0,1\}$ and $g_{i,j} \in [H]$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:48:35.820991+00:00","domain":"probability theory","id":"claim_626aa5c9afacc2bec340202467a61d7a396622d4cb92df471f97253e65cb0082","kind":"theorem","schema_version":1,"statement":"[Theorem analogue of theorem 3.10 of arXiv:2411.09614, 'Moment estimates for the stochastic heat equation on Cartan-Hadamard manifolds'] Let $M$ be a Cartan-Hadamard Manifold satisfying $\sec_M\leq -K_1<0$. A mild solution to the Cauchy problem of PAM driven by noise $W_\alpha$ exists and is unique if the initial condition $u_0\in L^\infty(M)\cap L^r(M)$, $1\leq r\leq +\infty$ and $\alpha>\frac{n-2}{4}$. Moreover, with the convention $\frac{1}{+\infty}=0$, its second moment satisfies 
    \begin{equation}
        \limsup_{t\to+\infty}\frac{\ln\mathbb{E}[u(t,x)^2]}{t}\leq \Theta_{\alpha}(\beta)-\frac{(n-1)^2}{\max(2,r)}K_1,
    \end{equation}

where $\Theta_{\alpha}(\beta)$ is a non-negative and (not strictly) increasing function satisfying the following properties.
\begin{enumerate}
    \item Define $$i=i(\alpha):=\begin{cases}
        1& \frac{n-2}{4}<\alpha<\frac{n}{4},\\
        2& \alpha=\frac{n}{4},\\
        3& \alpha>\frac{n}{4}.
    \end{cases}$$ Let $F_i:\mathbb{R}_+\to \mathbb{R}_+$ for $i\in\set{1,2,3}$ be the functions defined in Lemma (Analogue of lemma 3.9 of the paper). Then, for $\beta<\frac{1}{\sqrt{CF_i(0)}}$,  $\Theta_{\alpha}\equiv0$. Here $C>0$ is the constant taken from Lemma (Analogue of lemma 3.9 of the paper).
    \item The following asymptotic relations hold: \begin{enumerate}[label=(\roman*)]
        \item if $\alpha\in \left(\frac{n-2}{4},\frac{n}{4}\right)$, $\Theta_{\alpha}(\beta)\sim_{\beta\to\infty}(C\beta^2)^{1-2\alpha+\frac{n}{2}}$,
        \item if $\alpha=\frac{n}{4}$, then $\Theta_{\alpha}(\beta)\sim_{\beta\to+\infty}\frac{C\beta^2}{\ln([C\beta]^2)^2}$,\\
        \item if $\alpha>\frac{n}{4}$, then $\Theta_{\alpha}(\beta)\sim_{\beta\to+\infty}C\beta^2$.
    \end{enumerate}
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:16:18.694095+00:00","domain":"probability theory","id":"claim_627c6e0933c7f4da9dfd111cd73f0478af3aebcabc45cd42bcf3ebf016131b9d","kind":"lemma","schema_version":1,"statement":"[Lemma 36 (Mixed-word formula) of arXiv:2607.26377, '\textbf{Entire Logarithmic Signatures\\ of Bounded-Variation Paths in Finite Dimensions}'] Let $\beta:[0,T_{\beta}]\to V$ be a continuous bounded-variation path with $\beta_0=0$ and $\beta_{T_{\beta}}=v\neq0$. Fix $\ell\in V^*$ with $\ell(v)=1$, put $W=\ker\ell$, and write
\[
\beta_t=x_tv+X_t,
\qquad x_t=\ell(\beta_t),
\qquad X_t\in W.
\]
Let $r\geq1$, let $n_0,\ldots,n_r\geq 0$, and let $\eta_1,\ldots,\eta_r\in W^*$, extended to $V^*$ by $\eta_j(v)=0$. Set $N=r+\sum_{j=0}^r n_j$. The canonical pairing of the covector word with the degree-$N$ signature level is
\begin{equation}
\begin{aligned}
&\left\langle
\ell^{\otimes n_0}\otimes\eta_1\otimes
\ell^{\otimes n_1}\otimes\cdots\otimes
\eta_r\otimes\ell^{\otimes n_r},
S_N(\beta)
\right\rangle\\
&\quad=\int_{\Delta_r(T_{\beta})}
\frac{x_{t_1}^{n_0}}{n_0!}
\prod_{j=1}^{r-1}
\frac{(x_{t_{j+1}}-x_{t_j})^{n_j}}{n_j!}
\frac{(1-x_{t_r})^{n_r}}{n_r!}
\prod_{j=1}^r\eta_j(\dd X_{t_j}).
\end{aligned}
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:36:44.552404+00:00","domain":"probability theory","id":"claim_628e2048c6d0a84660c68d0e03bb4fe2f32a61eda572cde4fe7b86fd64332004","kind":"definition","schema_version":1,"statement":"[Definition 28 of arXiv:2604.01978, 'Homogenized Transformers'] Let $B\in C^{1}((\S^{d-1})^{n};\mathsf{T}(\S^{d-1})^{n})$ and
$G:(\S^{d-1})^n\times\Uptheta\to \mathsf{T}(\S^{d-1})^n$ be such that for ${\uprho_*}$-a.e.\ $\theta$,
the map $X\mapsto G(X,\theta)$ is $C^2$.
A continuous $(\S^{d-1})^{n}$-valued adapted process $(X(t))_{t\ge 0}$ with $X(0)=x$ is called a solution to the Itô SDE 
    \begin{equation} 
        \de X(t)=B(X(t))\de t+\int_{\Uptheta}G(X(t),\bm{\theta})\mathsf{W}(\de \bm{\theta},\de t),
    \end{equation}
if for all $g\in C^{\infty}((\S^{d-1})^{n})$, we have
\begin{align*}
g(X(t))
= g(x)
&+ \int_{0}^{t} (Bg)(X(s))\,\de s \\
&+ \frac{1}{2}\int_{0}^{t}\int_{\Uptheta} \Hess g(X(s))[G(X(s),\theta), G(X(s),\theta)]\,{\uprho_*}(\de \theta)\,\de s \\
&+ \int_{0}^{t}\int_{\Uptheta} (G(\cdot,\theta)g)(X(s))\,\mathsf{W}(\de \theta,\de s),
\end{align*}
where $Bg=\langle \grad g,B\rangle$, $G(\cdot,\theta)g=\langle \grad g, G(\cdot,\theta)\rangle$.","status":"unverified"}

