{"assumptions":[],"created_at":"2026-10-27T23:00:22.780939+00:00","domain":"probability theory","id":"claim_65702ee7b9b2b35a07a9d53e3c23be1bfefd1f6929da67fe3cf2c7c8d83f93e8","kind":"concept","schema_version":1,"statement":"[Thm Weak Convergence of Approximate Tridiagonal Entries of arXiv:2411.01633, 'On the Limit of the Tridiagonal Model \\for $\beta$-Dyson Brownian Motion'] Fix a $k \in \mathbb{N}$ and $T>0$ and define a vector of approximated tridiagonal entry processes,
\begin{equation*}
    \Tilde{E}_n(t):=\left(\Tilde{a}_1(t),\dots ,\Tilde{a}_k(t), \frac{1}{\sqrt{n}}(\Tilde{b}_1(t)^2-n),\dots ,\frac{1}{\sqrt{n}}(\Tilde{b}_k(t)^2-n)\right).
\end{equation*} Then, $\Tilde{E}_n(t)$ converges weakly in $C[0,T]$ to a vector process $E(t)=(A_1(t),\dots ,A_k(t),B_1(t),\dots,B_k(t))$, distributed as $\frac{1}{\sqrt{2}}E(t) \sim \mathbf{OU}_{2k}(1,3,\dots ,2k-1,2,4,\dots ,2k)$. More explicitly, the components $A_j(t) \in C[0,T]$ and $B_j(t) \in C[0,T]$ are jointly-independent centered Ornstein--Uhlenbeck processes with covariances $\mathrm{Cov}(A_j(t),A_j(s))=2e^{-(2j-1)|t-s|}$ and $\mathrm{Cov}(B_j(t),B_j(s))=2e^{-2j|t-s|}$, for $j=1,\dots ,k$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:47:12.029003+00:00","domain":"probability theory","id":"claim_657546f0e27210698a7fb135a986dad01955c3d3679c98f792e61a38a5f62003","kind":"lemma","schema_version":1,"statement":"[Lemma lem:11 of arXiv:2512.09219, 'Strong confluence of geodesics in Liouville quantum gravity'] Fix $z\in \mathbb{C}, r>0$. On the event $F_r(z)$, the following hold.
  \begin{enumerate}
  \item  Any path $\xi\subseteq B_{\delta_2 r}(V_r(z))$ from $B_{\delta_2 r}(I_u)$ to $B_{\delta_2 r}( (\mathcal{M}\setminus S_u)\cup S_v\cup \mathcal{A}_{v_+}\cup \mathcal{A}_{v_-})$ must necessarily intersect $B_{\delta_2 r}(\mathcal{A}_{u_-}\cup \mathcal{A}_{u_+})$.
  \item Any path $\xi\subseteq B_{\delta_2 r}(V_r(z))$ from $B_{\delta_2 r}(I_v)$ to $B_{\delta_2 r}( (\mathcal{M}\setminus S_v)\cup S_u\cup \mathcal{A}_{u_+}\cup \mathcal{A}_{u_-})$ must necessarily intersect $B_{\delta_2 r}(\mathcal{A}_{v_-}\cup \mathcal{A}_{v_+})$.
  \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:07:56.710284+00:00","domain":"probability theory","id":"claim_657829d278b8f570f7fb8ef72798c471b9cdb8cf4cdac1e470bfad5e25256db1","kind":"concept","schema_version":1,"statement":"[Proposition p:difference of arXiv:2411.04773, 'Meeting of squared Bessel flow lines and application to the skew Brownian motion'] In the setting of Definition (def:vary of the paper), let $\overline{\delta_0}, \overline{\delta_1}$, $\overline{\delta_2}$ be deterministic drift functions such that $\overline{\delta_0}(x)>0$ on ${\mathbb R}$.  Let $r_0\in {\mathbb R}$ be a constant and $r_1\ge r_0$ be an $\mathcal F$-stopping time. We write $Y=(Y_x,\, x\ge r_0)$ for the ${\rm BESQ}(\overline{\delta_0}\,|_{r_1}\, \overline{\delta_1})$ flow line  starting at $(0,r_0)$ and we let $\mathcal S$ be the ${\rm BESQ}(\overline{\delta_2})$ flow, both driven by $\mathcal W$. Let $\mathcal W^-_Y$ and $\mathcal W^+_Y$ defined as in (equation eq:W- of the paper) and (equation eq:W+ of the paper) from $(\mathcal W,Y)$ in place of $(\mathcal W,S)$. We extend $Y$ to ${\mathbb R}$ by setting $Y_x=0$ when $x<r_0$.  Consider the collection of processes 
 \begin{align*}
\mathcal S^+_{r,x}(a) &:=\mathcal S_{r,x}(a+ Y_r)- Y_x, &&  a\ge 0,\,  t(Y)>x\ge r, \\
\mathcal S^-_{r,x}(a) &:=  \mathcal S_{r,x}(a), && a\le Y_r,\, t(Y)>x\ge r\ge r_0
\end{align*}

\noindent where $t(Y):=\inf\{x\ge r_1\,:\, Y_x=0 \hbox{ and } \overline{\delta_1}(x)< 0\}$. We impose that 
\begin{equation}
    \mathcal S^+_{r,x}(a)=0  \mbox{ \rm if } x\ge \varphi_+(a,r), \qquad \mathcal S^-_{r,x}(a)=Y_x \mbox{ \rm if } x\ge \varphi_-(a,r),
\end{equation}

\noindent where, for any $a$ and $r$, 
\begin{align}
 \varphi_+(a,r) & :=\inf\{y> r\,:\, \mathcal S_{r,y}(a+ Y_r)\le Y_y  
\hbox{ and }  \overline{\delta_2}(y)\le  (\overline{\delta_0}\,|_{r_1}\, \overline{\delta_1})(y)\},\\
\varphi_-(a,r) & :=\inf\{y> r\,:\, \mathcal S_{r,y}(a)\ge Y_y\hbox{ and } \overline{\delta_2}(y) \ge (\overline{\delta_0}\,|_{r_1}\, \overline{\delta_1})(y)\}. \nonumber 
\end{align}

\noindent See Figure (fig:decomp of the paper). Then
\begin{enumerate}[(i)]
\item  $\mathcal S^+$ is a ${\rm BESQ}(\overline{\delta_2}\,|_{r_0}\,\overline{\delta_2} - \overline{\delta_0}\,|_{r_1}\, \overline{\delta_2} -\overline{\delta_1})$ flow driven by the white noise $\mathcal W^+_Y$ killed on $\{\overline{\delta_2} \le (\overline{\delta_0}\,|_{r_1}\, \overline{\delta_1})\}$ and restricted to $(-\infty,t(Y))$.
\item  The noise  $\mathcal W$ driving the SDEs of $Y$ and $\mathcal S^-$ can be replaced with $\mathcal W^-_Y$. In particular, $Y$ and $\mathcal S^-$ are measurable with respect to $\mathcal W^-_Y$ and $r_1$.
\item If $Y$ is a $\ominus$-flow line, then $\mathcal W^+_Y$ is a white noise on ${\mathbb R}_+ \times {\mathbb R}$  independent of $\mathcal W^-_Y$. 
\item Let $b\in {\mathbb R}$ and $\overline{\delta'}:= (\overline{\delta_0} \,|_b\, \overline{\delta_1})$. If $Y$ is a $\oplus$-flow line, then conditionally on 
$r_1=b$, $\mathcal W^-_Y$ is independent of $\mathcal W^+_Y$ and has the law of $\mathcal W^-$ associated by (equation eq:W- of the paper) to  the ${\rm BESQ}(\overline{\delta'})$ flow line starting at $(0,r_0)$. 
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:33:21.480003+00:00","domain":"probability theory","id":"claim_657da6e8e2b2315c6dc6b9fa015636b3b4274fb2294211bb6cf4251015744a90","kind":"theorem","schema_version":1,"statement":"[Cor Cor_strong_alpha_convex of arXiv:2606.22183, 'Expected loss of quasi-arithmetic means of exchangeable random variables'] Let $I\subseteq \mathbb{R}$ be a nonempty open interval, $\alpha:(I-I)\to\mathbb{R}_+$ be an even function,
 and $L:I\to \mathbb{R}$ be a strongly $\alpha$-convex function.
Then
 \begin{align*}
