{"assumptions":[],"created_at":"2026-10-26T19:49:02.099942+00:00","domain":"probability theory","id":"claim_6675af0c2c92695ff2eee6f6d6dab67f0687adcd804805ad34f702ef24b3b680","kind":"theorem","schema_version":1,"statement":"[Thm 5 (Convergence of normalized trace) of arXiv:2604.26499, 'Spectrum of Random Matrices with Exploding Moments'] Let $M$ be the matrix same as in Condition \ref{cond:matrixcond_1_NonHer}.
For any partition $\pi\in\mathcal P(k)$, let
$$
\tau_N^{nh}[T_\pi]
=
\frac{1}{N}
\sum_{\phi:V\to[N]\atop\mathrm{injective}}
\prod_{(u,v)\in E}
m_{\phi(u)\phi(v)},
$$
be defined for $M$ same as in \eqref{eq:tauN_def}.
Then, as $N\to\infty$, the following hold.
\begin{enumerate}
      \item For $\alpha>1$ and for every $T_\pi$ we have
    $$
    \mathbb{E}[\tau_N^{nh}[T_\pi]] \longrightarrow 0 .
    $$
    \item For $\alpha=1$ we have
    $$
    \mathbb{E}\big[\tau_N^{nh}[T_\pi]\big]
   \longrightarrow
    \tau^{nh}[T_\pi]
   :=
    \begin{cases}
   \displaystyle\prod_{k\ge2} C_{k}^{\,q_{k}}, & \text{if $T_\pi$ is a fat tree},\\[0.8em]
    0, & \text{otherwise,}
   \end{cases}
   $$
  where $q_{k}$ denote the number of unordered vertex pairs $\{i,j\}$ such that there are exactly $k$ edges between these vertices.

\item For $\alpha<1$ we have 
    \begin{align*}
\mathbb{E}\big[\tau_N^{nh}[T_\pi]\big] \sim
\begin{cases}
0, & \parbox[t]{0.6\textwidth}{\setstretch{0.9}\raggedright
$T_\pi$ contains any edge of multiplicity one (in any direction) or any vertex with a single loop (or both),}\\[0.6em]
O(N^{|V|-1-\alpha \mathfrak{p}}), & \text{otherwise,}
\end{cases}
\end{align*}
where $|V|$ is the number of vertices of $T_\pi$, and $\mathfrak{p}$ is the number of edges of the graph obtained by forgetting the multiplicity and orientation of the edges of the graph $T_\pi$.
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:35:10.791719+00:00","domain":"probability theory","id":"claim_66845d2600f3840afebfdb78cd963c4d843c2c85346dde3748c91e790ed28ce6","kind":"concept","schema_version":1,"statement":"[Prop 10 (Upper bound on balls) of arXiv:2604.00635, 'Large deviations of the periodic Toda chain'] For any $\mu \in \mathcal{M}_1(\mathbb{R})$, we have

