    \item [{\rm (3)}] the sequence $(\diff_n)_{n \in \mathbb{N}}$ consists of  {$L_2(U,V)$-valued},  $L$-integrable, predictable processes satisfying, for all $n \in \mathbb{N}$ and $t\geq 0$,  that $\diff_n^*(t)\leq K_2 Y_n^*(t-)$;    \item  [{\rm (4)}] the sequence   $(C_n)_{n \in \mathbb{N}}$ consists of   $H$-valued, càdlàg, adapted processes converging to $0$ uniformly on compacts in probability.
\end{enumerate}
Then  $(Y_n)_{n \in \mathbb{N}}$ converges to $0$ uniformly on compacts in probability.","status":"unverified"}

