\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:36:16.061225+00:00","domain":"probability theory","id":"claim_6c387b50cb562b102f9122ada3dfec2a41b192640355cd420a73955d4e3aa18f","kind":"concept","schema_version":1,"statement":"[Lemma lem: Martingale of arXiv:2606.28031, 'Insurance risk models in a heterogeneous time-dependent population: scaling limits and rui'] Assume there exists $\overline{\alpha}>0$ such that both $\mathbb{E}[{\mathrm e}^{-\overline{\alpha} X(1)}]$ and $\mathbb{E}[{\mathrm e}^{-\overline{\alpha} Y(1)}]$ are finite. Then, for any $\alpha \in [0,\overline{\alpha}]$, the process $M_\alpha$ defined by
\[
M_\alpha(t) := \exp{{\left(- \alpha V(t) - k_\alpha(t)\right)}}
\] 
is a càdlàg $\PAR{\mathcal{F}_t}_{t\geqslant 0}$-martingale, with $M_\alpha(0)=1$. It is also an $\PAR{\mathcal{F}_t \vee \mathcal{F}^F}_{t\geqslant 0}$-martingale.

Moreover, if $\tau$ is a bounded $\PAR{\mathcal{F}_t \vee \mathcal{F}^F}_{t\geqslant 0}$-stopping time, then
\begin{equation}
\mathbb{E}\big[M_\alpha(\tau)\,\vert\, \mathcal{F}^F\big] = 1, \quad \text{almost surely.}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:41:29.055796+00:00","domain":"probability theory","id":"claim_6c46a92bb89522e13eb4c3cea4bdaf95818cc282fd51de204513a95805a22e66","kind":"lemma","schema_version":1,"statement":"[Lemma 26 of arXiv:2608.26619, 'Uniqueness of Positively Curved Ancient Ricci Flows on Surfaces with Boundary'] If $v:\old\times(-\infty,0)\rightarrow\bR$ satisfies \eqref{eq_symmetry_v}  with $v(\cdot,t)\xrightarrow{C^\infty(\mathbb{D})} 0$ as $t\rightarrow -\infty$, and we define $\phi(x,t)=\frac{v(x,t)-v_R(x,t)}{x_1}$ as in Lemma \ref{lem_neumann}, then there exists some $T<0$ and $\gamma>0$ such that for any $-\infty<s<t\leq T$ we have
\begin{equation}
\|\phi(\cdot,t)\|_{L^\infty(\old)}\leq \gamma\left(\int_s^t \|v(\cdot,\tau)\|_{C^2(\old)}~d\tau\right)\|\phi(\cdot,s)\|_{L^\infty(\old)}.
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:42:16.244697+00:00","domain":"probability theory","id":"claim_6c47cb430cc17028643aa57f940314d52d3debaca2e755ee19ff89576ada31c9","kind":"concept","schema_version":1,"statement":"[Theorem thm:gumbel of arXiv:2607.01463, 'Two Multi--Draw Coupon Collector models with different retention rules'] A collector receives at each run $d$ distinct coupons ($d$ is a positive integer) and keeps \textbf{all the new} observed coupons (\textit{Problem I}), while he chooses \textbf{the least--collected coupon} at each run (\textit{Problem II}). Let $T_{N,d}$ and $T_{N,1}$ be the random variables denoting, respectively, the number of trials for a complete set of $N$ different types of coupons, which are uniformly distributed. Then, as $N\to\infty$,
\begin{equation}
    \frac{
        T_{N,d}
        -
        \frac{N}{d}\log N
    }{
        \frac{N}{d}
    }
  \Longrightarrow
    G, 
\end{equation}
and
\begin{equation}
    \frac{
        T_{N,1}
        -
        \frac{N}{d}\log N
        -
        N C_d
    }{
        \frac{N}{d}
    }
    \Longrightarrow
    G,

\end{equation}
where
\[
    C_d
    =
    \int_0^1
    \left[
        \frac{1}{1-(1-x)^d}
        -
        \frac{1}{dx}
    \right]\,dx,
\]
and $G$ is the standard Gumbel random variable, with distribution function
\[
    \mathbb{P}(G\le x)=\exp\{-e^{-x}\},
    \qquad x\in\mathbb{R}.
\] (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:01:22.599406+00:00","domain":"probability theory","id":"claim_6c4a49ae8148db35138fe04543fd392427f1d2f6b27e072546ff38e1b33876e9","kind":"lemma","schema_version":1,"statement":"[Lemma lem:v<L(B_t|H) of arXiv:2606.10257, 'Downward conditional monotonicity gives survival and extinction for contact processes in r'] Assume that $T$ is irreducible, monotone, that $\alpha$ is increasing, and that the MMPP is DCM. Given any $t>0$ and any history of arrivals $\mathcal{H}_{t}$, $v^*\preceq\mathcal L(B_0)$ implies that 
	\begin{equation*}
		v^*\preceq\mathcal L(B_t\mid\mathcal{H}_{t} ).
	\end{equation*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:09:15.344849+00:00","domain":"probability theory","id":"claim_6c4da811997c5c16e08eecaa93bf90bdec8f83675516934a0f4f6ff61ec5288b","kind":"concept","schema_version":1,"statement":"[Theorem of arXiv:2411.05534, 'Inverse problems for stochastic partial differential equations'] A strongly measurable function $ f(\cdot) : \Omega \rightarrow \mathcal{X} $ is Bochner integrable if and only if the scalar function $ |f(\cdot)|_{\mathcal{X}}: \Omega \rightarrow \mathbb{R} $ is integrable.
    In this case, for any $ E \in \mathcal{F} $,
    \begin{align*}
        \left|\int_E f(s) d \mu\right|_{\mathcal{X}} \leq \int_E|f(s)|_{ \mathcal{X}} d \mu
        .
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:55:18.052746+00:00","domain":"probability theory","id":"claim_6c58194b966eaad4eafd06e48583eb4ea6c7adb016a11855e86a0fd2ee42b63d","kind":"definition","schema_version":1,"statement":"[Definition 32 of arXiv:2606.16164, 'A Low-Regularity Semigroup Sewing Lemma via Quotient Structures'] Let $0<\gamma\le1$ and  $H\in Z\hat C^{\gamma}(\Delta_T^3;B_\alpha)$.  A defect-dependent scale splitting for $H$ at level $B_\alpha$ is a recursive rule $\mathsf s$ which acts on the residuals generated by the dyadic construction as follows.  If a dyadic interval $[a,c]$ has midpoint $b=(a+c)/2$ and carries a residual $Q_{ca}\in B_\alpha$, then $\mathsf s$ assigns two child residuals $Q^{\mathsf s}_{cb}, Q^{\mathsf s}_{ba} \in B_\alpha$, satisfying
\begin{equation}

Q_{ca}=Q^{\mathsf s}_{cb}+S_{c-b}Q^{\mathsf s}_{ba}+H_{cba}.
\end{equation}
If \(0<\gamma<1\), the rule $\mathsf s$ is called {\bf subcritical admissible} if there exist constants $0\le\theta<2^{-\gamma}$ and $C_H\ge0$ such that, for every residual
$Q_{ca}$ generated on a dyadic interval $[a,c]$ of length $L=c-a$,
\begin{equation}

\max\bigl\{\norm{Q^{\mathsf s}_{cb}}_{B_\alpha}, \norm{Q^{\mathsf s}_{ba}}_{B_\alpha}\bigr\}\le \theta\norm{Q_{ca}}_{B_\alpha}+C_H L^\gamma .
\end{equation}
If $\gamma=1$, the rule $\mathsf s$ is called {\bf critical admissible} if there exist constants $C_H,C_\ast,\eta>0$ such that, for every residual $Q_{ca}$ generated on a dyadic interval $[a,c]$ of length $L=c-a$,
\begin{equation}

\max\bigl\{\norm{Q^{\mathsf s}_{cb}}_{B_\alpha}, \norm{Q^{\mathsf s}_{ba}}_{B_\alpha}\bigr\}\le\left(\frac12+C_\ast L^\eta\right) \norm{Q_{ca}}_{B_\alpha}+C_H L .
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T09:52:47.243665+00:00","domain":"probability theory","id":"claim_6c5abf784bf13b27c6f453e35f1c58fe870f63c7f61384371cf8bc408ec9b11c","kind":"concept","schema_version":1,"statement":"[Theorem 12 (fractional null-form estimate) of arXiv:2609.01093, 'Ideal MHD below the classical well-posedness threshold'] Let $n\ge2$, $\breg\in(\frac12,1]$, $s>\frac{n+1}2$ and
$\rpar\in[0,1]$. Then
\begin{equation}
 \|Q_0(f,g)\|_{L^2_tY^{s-1,\rpar}}
 \le C\Big(
   \|f\|_{H^{s-1,1+\rpar}_{\breg}}
   \|g\|_{H^{s-1,1}_{\breg}}
  +\|f\|_{H^{s-1,1}_{\breg}}
   \|g\|_{H^{s-1,1+\rpar}_{\breg}}
 \Big),
\end{equation}
where $C=C(n,s,\breg,v_{\rm A})$ is uniform for
$\rpar\in[0,1]$. In particular,
\begin{equation}
     \|Q_0(f,f)\|_{L^2_tY^{s-1,\rpar}}
 \le 2C\|f\|_{H^{s-1,1}_{\breg}}
