{"assumptions":[],"created_at":"2026-10-27T19:48:47.284466+00:00","domain":"probability theory","id":"claim_7277fabbafdab4b9c52eed9546e2bb09f4588432016f83e8cc0a4e16f5f14425","kind":"theorem","schema_version":1,"statement":"[Prop tv-general of arXiv:2604.20629, 'Rates of forgetting for the sequentially Markov coalescent'] Let $K$ be a Markov kernel on $(0,\infty)$
with transition density $q( \cdot |s)$ with respect to Lebesgue
measure, and let $\pi$ be an invariant probability measure for $K$.
Suppose that:
\begin{enumerate}
\item There exists $L<\infty$ such that 
\begin{equation}
\int^{\infty}_{0}\bigl|q(t|a)-q(t|b)\bigr| dt\le L |a-b|,\qquad a,b>0;
\end{equation}
\item There exists a coupling $(X_{n},Y_{n})_{n\ge0}$ of two copies of
the chain, with 
\[
X_{0}=x,\qquad Y_{0}\sim\pi,
\]
such that for some $r\in(0,1)$, 
\begin{equation}
\mathbb{E}\!\left[ |X_{n+1}-Y_{n+1}| \, \mid  \, X_{n},Y_{n}\right]\le r |X_{n}-Y_{n}|\qquad\text{a.s. for all }n\ge0.
\end{equation}
Then for every $n\ge1$, 
\begin{equation}
d_{\mathrm{TV}}\!\bigl(K^{n}(x,\cdot),\pi\bigr)\le\frac{L}{2} r^{ n-1} \mathbb{E}|x-Y_{0}|.
\end{equation}
In particular, the chain is geometrically ergodic in total variation.
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:36:49.851936+00:00","domain":"probability theory","id":"claim_72798109dbf46ee04ed1ddb94c94b193ac3776ed16c3c4aea23cb4786a8ce13d","kind":"lemma","schema_version":1,"statement":"[Lemma lem:dgt4-origin-frozen of arXiv:2609.02829, 'Quantitative explosion and percolation of the divisible sandpile'] Assume that $d\geq5$ and that the scenery is i.i.d., atomless, centered,
	and of finite positive variance. For every $n\geq0$:
	\begin{equation}
	\begin{aligned}
		\{u_{n+1}(0)=0\}
		&=\{-\zeta(0)>Pw_n(0)\},\\
		(-\zeta(0)-Pu_n(0))_+
		&=(-\zeta(0)-Pw_n(0))_+,\\
		\mathbb{E} u_{n+1}(0)-\mathbb{E} u_n(0)
		&=\mathbb{E}(-\zeta(0)-Pw_n(0))_+\, .
	\end{aligned}
	\end{equation}
	If $\mathbb{E}|\zeta(0)|^p<\infty$ for some $p\geq2$, then
	\begin{equation}
	\begin{aligned}
		\frac{G(0,0)\mathbb{E} Pw_n(0)}{\mathbb{E} u_n(0)}
		&\longrightarrow1,\\
		\sup_{n\geq0}\mathbb{E}|Pw_n(0)-\mathbb{E} Pw_n(0)|^p
		&<\infty\, .
	\end{aligned}
	\end{equation}
	If, in addition, $\mathbb{E} e^{\theta_0|\zeta(0)|}<\infty$ for some
	$\theta_0>0$, then, for every
	\[
		0<\lambda<
		\frac{\theta_0}{
		\displaystyle\sup_{z\ne0}G(0,z)/G(0,0)},
	\]
	there is $C(\lambda)<\infty$ such that for every $n,r\geq0$,
	\begin{equation}
		\mathbb{P}\left(
		Pw_n(0)-\mathbb{E} Pw_n(0)\leq-r
		\right)
		\leq C(\lambda)e^{-\lambda r}\, .
	\end{equation}","status":"unverified"}

