    \end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T02:39:12.338611+00:00","domain":"probability theory","id":"claim_74bc2f81d0fc1b33d9d78846f5785c6b3856bd7c8a294e9a2983c0bd7449878b","kind":"lemma","schema_version":1,"statement":"[Lemma lem:wp:marginalSDE of arXiv:2412.07710, 'An H-theorem for a conditional McKean-Vlasov process related to interacting diffusions on '] Suppose $(U, W)$ satisfy Assumption (as:results:lyapunov of the paper) and $(\mu, \gamma, \mathbf{X})$ is a linear growth solution to $\kappa$-MLFE{} on $[0, T]$ with potentials $(U, W)$  and initial condition $\lambda \in \mathcal{Q}_{\kappa, d}$. Then for all $t \in [0, T]$, the edge time marginal $\bar{\mu}_t$ satisfies $\bar{\mu}_t = \mathcal{L}(\bar{X}_0(t), \bar{X}_1(t))$, where $(\bar{X}_0, \bar{X}_1)$ solve the following SDE with initial condition $\bar{\lambda}$:
        \begin{equation}
        \begin{aligned}
            d{\bar{X}}_0(t) &= \gamma(t, \bar{X}_0(t), \bar{X}_1(t)) dt + \sqrt{2}d\tilde{B}_0(t), \\
            d{\bar{X}}_1(t) &= \gamma(t, \bar{X}_1(t), \bar{X}_0(t)) dt + \sqrt{2}d\tilde{B}_1(t), 
                    \end{aligned}

    \end{equation}
    where $\tilde{B}_0, \tilde{B}_1$ are independent $d$-dimensional Brownian motions. Moreover, we have
    \begin{equation*}
    \int_0^T \int_{\ensuremath{\mathbb{R}}^d \times \ensuremath{\mathbb{R}}^d} \frac{|\nabla_{(x_0, x_1)} \bar{\mu}_t(x_0, x_1)|^2}{\bar{\mu}_t(x_0, x_1)} dx_0 dx_1 dt < \infty.
\end{equation*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T08:02:08.131901+00:00","domain":"probability theory","id":"claim_74c3d5323fb581f61fe5ad684ed2bf663ba01402241cd3c6dabdc2d31ab86d01","kind":"definition","schema_version":1,"statement":"[Definition 1 (Wasserstein Distance, \cite{peyre2019computational}) of arXiv:2608.27500, 'Optimal Transport for Network Comparison: \\ A Review with Machine Learning Applications'] Let $\mu=\sum_{i=1}^n a_i\delta_{x_i}$ and $\nu=\sum_{j=1}^m b_j\delta_{y_j}$ be probability measures in $(\mathbb{R}^d,\|\cdot\|)$. For $1\leq p<\infty$, the $p$-Wasserstein distance between $\mu$ and $\nu$ is defined as
\begin{align}
    W_p(\mu,\nu)=\bigg(\min_{\pi\in \Pi(\mu,\nu)}\sum_{i=1}^n\sum_{j=1}^m \|x_i-y_j\|^p\pi_{ij}\bigg)^\frac{1}{p}.
\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T17:42:08.462138+00:00","domain":"probability theory","id":"claim_74c42c21617b12150c465bfd73030f3723924f2fb8fe0fe7384ab99fc1d9be70","kind":"concept","schema_version":1,"statement":"[Lemma definition:twop-headc of arXiv:2511.15893, 'On a Class of Dynamical Poisson-Voronoi Tessellations'] The two point Palm probability distribution of ${\mathcal H }_c$ is

