        \|V\|_{\mathfrak{X}^{k}((\S^{d-1})^n)}\coloneqq \max_{X\in (\S^{d-1})^n}\left(\|V(X)\|+\max_{j\in[k]}\|\nabla^{j}V(X)\|\right)
    \end{equation*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T02:28:34.963881+00:00","domain":"probability theory","id":"claim_756b03f47f0048d960515178980ab925a0972b58a92e32d818643291c65098d1","kind":"concept","schema_version":1,"statement":"[Thm first main of arXiv:2412.05950, 'Quantitative particle approximation of nonlinear stochastic Fokker-Planck equations with s'] Assume $(\mathbf{A}^V)$, $(\mathbf{A}^c)$, $(\mathbf{A}^F)$,  and $(\mathbf{A}^K)$, let $T_{max}$ be the maximal existence time for ((SPDE_Ito of the paper)) and fix $T \in \left(0,T_{max}\right)$. In addition, let the dynamics of the particle system be given by ((particles of the paper)) with $\nu=Id$, $\sigma$ independent of the space  and  for any $m \ge 1$,
				\begin{align*}
					\sup_{N \in \mathbb{N}} \Big \| \left\| \rho^N_0 \right\|_{q} \Big \|_{{L^m(\Omega)}} < \infty
				\end{align*}
				with $ d \geq 1$, $q>d$ given by $(\mathbf{A}^K)$ and  $\beta \in \left(0,\frac{1}{2\big[1 + \frac{1}{d} - \frac{1}{q}\big]}\right) $.
				Then

				\begin{align*}
					\Big \| \left\|\rho - \rho^N \right\|_{T,q} \Big \|_{L^m(\Omega)}  &\le C \Big \| \left\|\rho_0 - \rho^N_0 \right\|_{q} \Big \|_{L^m(\Omega)} + C N^{-\varkappa} \, \nonumber 
				\end{align*}
				where
				\begin{align*}
					\varkappa = \min \left(\frac{\beta}{d}\gamma,\frac{1}{2}-\beta\Big(1 + \frac{1 }{d}-\frac{1}{q}\Big) \right)
				\end{align*}
				\noindent and $\rho$ is a  solution of SPDE (equation SPDE_Ito of the paper) with initial condition $\rho_0$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T00:55:42.224113+00:00","domain":"probability theory","id":"claim_75791150c9fa12b807e5eedf60631a2b61f203aaa157aa3e97c4c972e163b315","kind":"concept","schema_version":1,"statement":"[Thm potential-zero of arXiv:2411.16376, 'Higher order approximations in arcsine laws for subordinators'] Let $X=(X_t)_{t\geq0}$ be a killed subordinator which is not identically zero. Assume that the Laplace exponent $\Phi(z)$ satisfies the following condition:
\begin{enumerate}[label={\upshape (\Alph*')}]
\item There exist constants $n\in\ensuremath{\mathbb{N}}\cup\{0\}$, $c_0\in(0,+\infty)$, $c_1,\dots,c_n\in\ensuremath{\mathbb{R}}\setminus\{0\}$ and $\beta_0<\beta_1<\dots<\beta_n<+\infty$ with $\beta_0\in(0,1]$, and a locally integrable function $R:(0,+\infty)\to(0,+\infty)$ such that $R(t)$ is non-increasing on $(r,+\infty)$ for some $r>0$, $R(t)=o(t^{-1-\beta_n})$, as $t\to+\infty$, and
\begin{align}
    \frac{d}{dz}
    \bigg(
    \frac{1}{\Phi(z)}
    -
    \sum_{k=0}^n
    \frac{1}{c_k z^{\beta_k}}
    \bigg)
    =
    O(R(|z|)),
    \quad
    \text{as $z\to\infty$ in $\{z\in\ensuremath{\mathbb{C}}\mid {\rm Re}\,z>0\}$}.	
\end{align}
\end{enumerate}
Then the potential measure $U|_{(0,+\infty)}$ restricted over $(0,+\infty)$ admits a continuous density $u(x)$ $(0<x<+\infty)$ which can be estimated as
\begin{align}
   u(x)
   =
   \sum_{k=0}^n
   \frac{x^{-1+\beta_k}}{c_k\Gamma(\beta_k)}+O(\varepsilon_1(x)),
   \quad\text{as $x\to0+$,}
\end{align}
where
\begin{align}
    \varepsilon_1(x)
    =
    x^{-2}R(x^{-1})+x^{-1}\int_{x^{-1}}^{+\infty} R(t)\,dt.	
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T16:26:02.365030+00:00","domain":"probability theory","id":"claim_757beaea70f083609fc4957f1126e5b95fa55396171bf5ef6c80823da0a786e5","kind":"definition","schema_version":1,"statement":"[Defn of arXiv:2608.30031, 'Ziggurats, taut foliations, and contact structures'] Let $\mathcal{G}$ denote the standard horizontal foliation on the neighborhood $N(\mathcal{W}) = [-1,2]^2_{x,z}$ of the square window $\mathcal{W} = [0,1]^2$, i.e., $\mathcal{G}$ is tangent to $\partial_x$. Let $\star \in \{ \sharp, \flat\}$. A \textbf{$\star$~modification of $\mathcal{G}$ in $N(\mathcal{W})$} is a smooth foliation $\mathcal{G}^\star$ on $N(\mathcal{W})$ satisfying
     \begin{itemize}
        \item $T\mathcal{G}^\star$ is either tangent or transverse to $T \mathcal{G}$; it is positively transverse if $\star = \sharp$ and negatively transverse if $\star = \flat$,
         \item $\mathcal{G}^\star$ coincides with $\mathcal{G}$ near $\partial N(\mathcal{W})$,
         \item $\mathcal{G}^\star$ is transverse to $\mathcal{G}$ in a neighborhood of $\mathcal{W}$.
     \end{itemize}","status":"unverified"}

