{"assumptions":[],"created_at":"2026-10-27T11:40:59.357134+00:00","domain":"probability theory","id":"claim_7ad5eea8e92a6360888e498f37ddbc5aadac69342c24ae71c6b8b0fe10f5db4e","kind":"lemma","schema_version":1,"statement":"[Lemma 3 (Large-trace spectral structure) of arXiv:2609.03958, '2609.03958'] Let $n\geq 2$ and $K\geq 0$. Suppose that $\lambda\in \Gamma_2$ satisfies $\lambda_1\ge\cdots\ge\lambda_n\geq -K$ and $\sigma_2(\lambda)=f$ with $f_0\leq f\leq f_1$ for two constants $f_1\geq f_0>0$.  Then there exists  $S_0 >0$ depending only on
$n$, $K$, $f_0$ and $f_1$ such that whenever $\sigma_1(\lambda)\geq S_0$, we have 
$$\frac{\sigma_1(\lambda)}{n}\leq  \lambda_1\leq \sigma_{1}(\lambda),$$
$$-K\leq\lambda_i  \leq n \frac{2(f_1+(n-1)^2K^2)}{S_0}+(n-2)K,\qquad i\geq2,$$
\begin{equation}
  \frac{f_0}{2\sigma_1(\lambda)}\leq  \sigma_{1;1}(\lambda)\leq  \frac{2n(f_1+(n-1)^2K^2)}{\sigma_1(\lambda)},
\end{equation}
$$\frac{1}{2}\sigma_1(\lambda)\leq \sigma_{1;i}(\lambda)\leq 2\sigma_1(\lambda),\qquad i\geq2.$$
In fact, we can take 
\begin{equation*}
  \begin{split}
    S_0&=\max \Big \{2n(n-1)K, \sqrt{\frac{n-2}{n-1} } \frac{2n(f_1+(n-1)^2K^2)}{\sqrt{f_0}},  \\
      & (n-2)K+\sqrt{4nf_1+(4n(n-1)^2+(n-2)^2)K^2}\Big \}.
  \end{split}
\end{equation*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T18:51:26.590107+00:00","domain":"probability theory","id":"claim_7ad8e91af9eab17f5c892a1fce1e42be3e1e219519916bf16c895b4ea04a4e11","kind":"lemma","schema_version":1,"statement":"[Lemma lem:kernel-asymp of arXiv:2606.02003, 'Higher-Order Multifractional Stable Motion:\\ Definition and Fundamental Properties'] Under Assumption~(ass:params of the paper), with $\gamma(t) = H(t)-1/\alpha$:

\begin{enumerate}[label=(\roman*)]

\item \textbf{Vanishing for $u > t$.}
  For all $u > \max\{0,t\}$: $f_n(t,u;H,\alpha) = 0$.

\item \textbf{Near-diagonal behaviour.}
  For $u \in (t-\delta, t)$ with $\delta \in (0,t)$ sufficiently
  small (so that $u > 0$):
  \begin{equation}

  f_n(t,u;H,\alpha)
  = \frac{(t-u)^{\gamma(t)}}{\Gamma(\gamma(t)+1)} + R_1(t,u),
  \end{equation}
  where $|R_1(t,u)| \leq C_1\,(t-u)^{\gamma(t)+1}$ for a constant
  $C_1 > 0$ uniform in $t$ on compact intervals.

\item \textbf{Tail behaviour.}
  For $u < \min\{0, t-1\}$ (so that $|u|$ is large and $|t/u| < 1$):
  \begin{equation}

  f_n(t,u;H,\alpha)
  = C_n(t)\,|u|^{\gamma(t)-n} + R_2(t,u),
  \end{equation}
  where $|R_2(t,u)| \leq C_2\,|u|^{\gamma(t)-n-1}$, and the leading
  coefficient is
  \begin{equation}

  C_n(t)
  = \frac{(-t)^n}{\Gamma(\gamma(t)+1)}\binom{\gamma(t)}{n},
  \quad
  \binom{\gamma}{n} := \frac{\gamma(\gamma-1)\cdots(\gamma-n+1)}{n!}.
  \end{equation}
  The constant $C_2 > 0$ is uniform in $t$ on compact intervals.

\end{enumerate}","status":"unverified"}

