    =&\Biggl(\tilde{E}_t^\epsilon[U_{t}^{n-1,\epsilon} |\mathcal{Y}_t^\epsilon]+\sum_{i=1}^{n-1}\tilde{E}_t^\epsilon[U_{t}^{n-i-1,\epsilon} J_t^i|\mathcal{Y}_t^\epsilon]\Biggr)
    \Biggl\{1+\sum_{j=1}^{n-1}(-1)^{j}\Biggl(\sum_{i=1}^{n-1}\tilde{E}_t^\epsilon[J_t^i |\mathcal{Y}_t^\epsilon]\Biggr)^{j}\Biggr\}\\
    &+O_P^T(\epsilon^n),
  \end{align*}
  for every $n \in \mathbb{N}$.
  Here, $H_{t,i}^\epsilon$ and $U_{t,i}^\epsilon$ is given in (\ref{eq4-24}), and
  \begin{align}
    \begin{split}
      J_t^i=&\int_0^t\int_0^{t_{i}}\cdots \int_{0}^{t_2} (H_{t_1}^{n-1,\epsilon})^\top (\sigma(t_1)\sigma(t_1)^\top)^{-1} (dY_{t_1}^\epsilon-c(t_1)X_{t_1}dt_1)\\
    &\times \cdots \times (H_{t_i}^{n-1,\epsilon})^\top (\sigma(t_i)\sigma(t_i)^\top)^{-1} (dY_{t_i}^\epsilon-c(t_i)X_{t_i}dt_i).
    \end{split}    
  \end{align}
  Also, $x/0$ is interpreted as $0$ for any $x \in \mathbb{R}$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:17:42.311144+00:00","domain":"probability theory","id":"claim_7cdd75b8f74d83f87617d4f500405f4bbb7cf34ad304ce47e068ad8833c556c7","kind":"concept","schema_version":1,"statement":"[Proposition 5 of arXiv:2608.05931, 'Effective Lagrangian regularity and the uniqueness threshold for random H\"older velocity '] Let $u : \T^d \to \R^d$ be such that $u \in C^0(\T^d)$ and $y \in \T^d$. Let $X$ be \textit{any} solution to
