{"assumptions":[],"created_at":"2026-10-27T16:38:11.735884+00:00","domain":"probability theory","id":"claim_7d42b122bd0c175273f2ab99b23b389e5e7a5e9b5481a3eeb0e7043391c25d70","kind":"definition","schema_version":1,"statement":"[Definition def:underline of arXiv:2504.00512, 'Localization-delocalization transition for a random block matrix model at the edge'] Suppose that $f$ and $g$ are matrix-valued functions. Define
\begin{equation}
\underline{g(H)Hf(H)} := g(H)Hf(H)-\widetilde{\mathbb{E}}g(H)\widetilde{H}(\partial_{\widetilde{H}}f)(H) - \widetilde{\mathbb{E}}(\partial_{\widetilde{H}}g)(H)\widetilde{H}f(H),
\end{equation}
where $\widetilde{H}$ is an indepdent copy of $H$, $\widetilde{\mathbb{E}}$ denotes the partial expectation with respect to $\widetilde H$, and $(\partial_{\widetilde{H}}f)(H)$ denotes the directional derivative of the function $f$ in the direction $\widetilde H$ at the point $H$, i.e.,
\begin{equation}
[(\partial_{\widetilde{H}}f)(H)]_{xy} = (\widetilde{H}\cdot \nabla f(H))_{xy} := \sum_{\alpha,\beta\in \mathcal{I}}\widetilde{H}_{\alpha\beta}\frac{\partial f(H)_{xy}}{\partial H_{\alpha\beta}}.
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:48:47.286779+00:00","domain":"probability theory","id":"claim_7d44d18a6f2791a158033e328b31f0be07246b04cc364ececdb24dccb8f1eca3","kind":"lemma","schema_version":1,"statement":"[Lemma compression2 of arXiv:2604.20660, 'The Legendre structure of the TAP complexity\\ for the Ising spin glass'] Let $\zeta$ be a probability measure on $[0,1]$ with an $(n+1)$-atom prefix $\{0,q_1,\ldots,q_n\}$, where $0<q_1<\cdots<q_n<1$.
		Define $q_{ij}:=q_{\min(i,j)}$ for $i,j\in[n]$, and set
		\begin{equation*}
			\Delta_k :=
			\begin{cases}
				- \zeta(\{q_k\}) & \text{if } k \in [n-1],\\
				\zeta([0,q_n)) & \text{if } k = n.
			\end{cases}
		\end{equation*}
		Let $(\mathbf{m}^{(1)},\ldots,\mathbf{m}^{(n)})\in \mathrm{SUSY}_n(\zeta,\varepsilon)$, where $\mathrm{SUSY}_n(\zeta,\varepsilon)$ is as in Definition (def:susyreplicas of the paper), and define
		\begin{equation*}
			z^{(i)} :=- \sum_{k=1}^n \xi'(q_{ik})\, \Delta_k\, \mathbf{m}^{(k)},
			\qquad i \in [n].
		\end{equation*}
		Then for every $i,j\in [n]$,
		\begin{equation*}
			\langle z^{(i)}+\partial_m h_\zeta(q_i,\mathbf{m}^{(i)}),\,\mathbf{m}^{(j)}\rangle
			= N\,\xi'(q_{ij})\int_{q_j}^1 \zeta([0,t])\,\mathrm{d} t+O(N\varepsilon).
		\end{equation*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:01:54.287398+00:00","domain":"probability theory","id":"claim_7d47badee369df7e5aa743c95da6782f2082b9d95c630f1dd71fc00179ec8d49","kind":"definition","schema_version":1,"statement":"[Defn def local solution' of arXiv:2411.01847, 'Well-Posedness of Stochastic Chemotaxis System'] We say that $(u,v,\tau)$ is a local mild solution to the system ((main2 of the paper)) if
	\begin{enumerate}
