{"assumptions":[],"created_at":"2026-10-27T07:23:05.295461+00:00","domain":"probability theory","id":"claim_836bee615022f030621a5747df7571724748e91e425d4ca7d9d5fa850e8f1cbc","kind":"lemma","schema_version":1,"statement":"[Lemma 8 of arXiv:2608.21701, 'Superdiffusivity of random walks on the three-dimensional randomly oriented Manhattan latt'] The following properties hold for the functions $L$, ${\rm LB}_m$ and ${\rm UB}_m$:
\begin{itemize}
    \item[i.] the functions $L$, ${\rm LB}_m$, and ${\rm UB}_m$ are non-increasing in the first variable, and
\begin{equation}

1\le {\rm LB}_m(x,z)\le \sqrt{L(x,z)}\le {\rm UB}_m(x,z)\le L(x,z)\quad\text{for } x>0,\ z>1;
\end{equation}
\item[ii.] for every $0<\alpha<1$,
\begin{align}

\int_\alpha^1 \frac{\rmd r}{r{\rm LB}_m(r,z)} &\le 2{\rm UB}_m(\alpha,z) + \frac{{\rm UB}_m(\alpha,z)}{z}\quad\text{and}\\

\int_\alpha^\beta \frac{\rmd r}{r{\rm UB}_m(r,z)} &\ge 2\left( {\rm LB}_{m+1}(\alpha,z) - {\rm LB}_{m+1}(\beta,z) \right)\quad \text{for every $0<\alpha<\beta\le1$};
\end{align}
\item[iii.] for every fixed $c_0>0$, there exists $C<\infty$ such that, for all $\gamma\in[c_0z^{-1},1]$, $r\in(0,1)$, $m\ge0$, and $z>1$,
\begin{align} 
{\rm LB}_m(\gamma r,z) &\le {\rm LB}_m(r,z) \left[ 1+ C\frac{(m+1)(1+\log z)}{z} \right],
\\

{\rm UB}_m(\gamma r,z) &\le {\rm UB}_m(r,z) \left[ 1+ C\frac{(m+1)(1+\log z)}{z} \right];
\end{align}
\item[iv.] for each fixed $B>1$ there exists $C_{B}<\infty$ such that,
whenever $s,t\in(0,1)$, $m\ge0$, $z>1$, and $B^{-1}s\le t\le Bs$,
\begin{equation}

C_{B}^{-1}{\rm LB}_m(s,z) \le {\rm LB}_m(t,z) \le C_{B}{\rm LB}_m(s,z);
\end{equation}
\item[v.] for every fixed $B\in(0,\infty)$, there exists $C_B<\infty$ such that, for all $r\in(0,1)$, $m\ge0$, and $z>1$,
\begin{equation}

{\rm LB}_{m+1}(Br,z) \ge {\rm LB}_{m+1}(r,z) \left[ 1- C_B\frac{m+1}{z} \right] - C_B{\rm LB}_{m+1}(1,z).
\end{equation}
\end{itemize}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:21:10.888916+00:00","domain":"probability theory","id":"claim_8370223785be6f3897e7de9f8a434392c3851145e9774c08d226e87526d3a627","kind":"theorem","schema_version":1,"statement":"[Proposition 35 (Bernoulli percolation on extremal URGs) of arXiv:2504.02435, 'Poisson-Voronoi percolation in higher rank'] Let $(G,\rho)$ be an extremal unimodular random graph and let $G[p]$ denote the configuration of $p$-Bernoulli percolation on $(G,\rho)$. Then the following hold:
\begin{itemize}
\item[{\rm(1)}] The number of infinite clusters in $G[p]$ is almost surely constant and $0$, $1$ or $\infty$.
\item[{\rm(2)}] There exists a constant $p_c$ such that for any $p>p_c$, $G[p]$ has an infinite cluster almost surely, while for any $p<p_c$, there is almost surely no infinite cluster.
\item[{\rm(3)}] There exists a constant $p_u$ such that for any $p>p_u$, $G[p]$ has a unique infinite cluster almost surely, while for any $p<p_u$, there is almost surely not a unique infinite cluster.
\end{itemize}","status":"unverified"}

