{"assumptions":[],"created_at":"2026-10-26T20:58:09.069423+00:00","domain":"probability theory","id":"claim_84da774e3beb3016c91b8a46422c0b706a09c2b1969b022a5796a4c6805da009","kind":"lemma","schema_version":1,"statement":"[Lemma 18 of arXiv:2606.27774, 'Variational Formulas for the Spectrum of\\ Block Wishart Matrices'] Fix $\bS \in \bbH_+^k$, $\bT \in \sa{k}{\C}$ and $\bZ \in \bbH_+^k$, and let 
$\bB := \Im(\bS)$, $\bfeta := \bfeta(\bS,\bT)$. 
Then  the following hold:
\begin{enumerate}
\item $\bfeta$ satisfies
\begin{equation}

\Im(\bfeta) = -\bfeta\, \bB\, \bfeta^{*},\qquad \|\bfeta\|_\op \le \|\bB^{-1}\|_\op\, .
\end{equation}
\item
If $\bS$ satisfies $\bK_{\up{\alpha,\nu}}(\bS) = \bZ$, then
\begin{align}

&\int \bfeta\,\bB\,\bfeta^*\, \nu(\de\bT) 
= \frac{1}{\alpha}\bS^{-1}\bB\bS^{*-1} - \Im(\bZ),\\

&\bI = \alpha^2\, \bS\int \bfeta\,\bB\,\bfeta^*\, \nu(\de\bT)\, \bS^*\bB^{-1} 
+ \alpha\, \bS\,\Im(\bZ)\,\bS^* \bB^{-1}.
\end{align}
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:44:17.188462+00:00","domain":"probability theory","id":"claim_84e382b37a39e3f8550e90db607ec0c69264c4ac8e9969841e8cfbb9630f34d9","kind":"lemma","schema_version":1,"statement":"[Lemma 20 of arXiv:2604.18871, 'Quantitative approximation of the Vlasov(--Fokker--Planck)--Navier--Stokes system by stoch'] Let Assumptions~\ref{assump-PDE} and \ref{assump-particles} hold, with $\sigma\in [0,+\infty)$.
Then there exists a constant $C=C(T,k,A,\gamma,d,p)>0$ such that for any $N\in \N^*$ and any $t\in [0,T]$,

\begin{align*}
\big\| \langle v \rangle^{k} &(F^{(N)}_{t} - F_{t}) \big\|_{L^{2}_{x,v}}^2 + \frac{\sigma_{N}^2}{2} \int_{0}^t \big\| \langle v \rangle^{k} \nabla_{v}(F^{(N)}_{s} - F_{s}) \big\|_{L^2_{x,v}}^2 \dd s\\
