{"assumptions":[],"created_at":"2026-10-27T05:37:14.891216+00:00","domain":"probability theory","id":"claim_85527f077dc83867340ff50caca4dac1af642cf261168d225413a669e46f717d","kind":"concept","schema_version":1,"statement":"[Lemma 14 of arXiv:2607.11608, '2607.11608'] Given $N\ge M\gg 1$, define $Z_M$ by its coefficients in the eigenfunction expansion of $\L$ as follows. For $0\le n\le M$, $\widetilde{Z}_M(n,t)$ is a solution of the following differential equation:
\begin{align*}
\begin{cases} d\widetilde{Z}_M(n,t)=\nu^{-1}_n\sqrt{M}(\widetilde{Y}_N(n,t)-\widetilde{Z}_M(n,t))dt \\ {\widetilde{Z}}_{M}|_{t=0}=0,
\end{cases}
\end{align*}
where 
\begin{align*}
\widetilde{Y}_N(n,t)=\int_{\R^d}Y_N(t,x)h_n(x)dx, 
\end{align*}
and we set ${\widetilde{Z}}_{M}\equiv 0$ for $n>M$. Then, 
\begin{align}
Z_M(t,x):=\sum_{n=0}^{M}{\widetilde{Z}}_{M}(n,t)h_n(x)

\end{align}
is a centered Gaussian process in $L^{2}(\R^d)$, which satisfies $\P_{M}Z_M=Z_M$. Moreover, we have 
\begin{align}
&\E\big[\|Z_M\|^2_{L^{2}(\R^d)}\big]\sim \log M, \notag\\
&\E\bigg[2\textup{Re}\int_{\R^d}Y_N \overline{Z_M}dx-\int_{\R^d}|Z_M|^2dx\bigg]\sim \log M, \\
&\E\bigg[\Big|\!\!:\!\!\|Y_N-Z_M\|^2_{L^{2}(\R^d)}\!\!:\!\!\Big|^2 \bigg]\les M^{-1}\log M, \notag\\
&\E\bigg[\Big|\!\int_{\R^d}Y_N f_Mdx\Big|^2 \bigg]+\E\bigg[\Big|\!\int_{\R^d}Z_Mf_M dx\Big|^2 \bigg]\les M^{-\frac{3}{2}},\notag\\
& \E\bigg[\int_{0}^{1}\left\|\frac{d}{ds} Z_M(s)\right\|^2_{\mathcal{H}^1(\R^d)}ds\bigg]\les M, \notag
\end{align}
for any $N\ge M\gg 1$, where $Z_M=Z_M(1)$ and 
\begin{align*}
\!\!:\!\!\|Y_N-Z_M\|^2_{L^{2}(\R^d)}\!\!:=\|Y_N-Z_M\|^2_{L^{2}(\R^d)}-\E\big[\|Y_N-Z_M\|^2_{L^{2}(\R^d)}\big].
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:12:09.045560+00:00","domain":"probability theory","id":"claim_855e91acb3083d1bd04fdefae1629aa8d5593074583904bc98aa88ee2dceaaa8","kind":"theorem","schema_version":1,"statement":"[Corollary cor:optimalGaussian of arXiv:2608.25279, 'Provable Non-Acceleration of Standard Strang\\ Splittings of Kinetic Langevin Dynamics'] Let $\kappa>1$ and set
\begin{equation*}
 h_*=\frac{2}{\sqrt{\kappa+1}},
 \qquad
 \gamma_*=\sqrt{\kappa+1}\,\log\frac{\sqrt\kappa+1}{\sqrt\kappa-1},
\end{equation*}
so that
\begin{equation*}
 \beta_*=e^{-\gamma_*h_*}=\left(\frac{\sqrt\kappa-1}{\sqrt\kappa+1}\right)^2,
 \qquad
 s_*=\frac{h_*^2}{2}(1+\beta_*)=\frac{4}{(\sqrt\kappa+1)^2}.
\end{equation*}
Let $U_H(x)=\frac12x^\top Hx$ on $\mathbb R^d$ with $\mathrm{Id}_d\preceq H\preceq\kappa\mathrm{Id}_d$, and write $Q=Q_{h_*,\gamma_*}^{U_H}$. Then $Q$ has a unique invariant law $\pi_H$, and $\pi_H$ is a centered Gaussian. For every initial state $z\in\mathbb R^d\times\mathbb R^d$,
\begin{equation*}
 \limsup_{n\to\infty}\lVert \delta_zQ^n-\pi_H\rVert_{\mathrm{TV}}^{1/n}
 \le\sqrt{\beta_*}=\frac{\sqrt\kappa-1}{\sqrt\kappa+1},
\end{equation*}
and for suitable $z$ the limit exists and equals $\sqrt{\beta_*}$. Moreover, there are initial states $z,\widetilde z$ with
\begin{equation*}
 \lim_{n\to\infty}\norm{\delta_zQ^n-\delta_{\widetilde z}Q^n}_{\mathrm{TV}}^{1/n}
 =\sqrt{\beta_*}.
\end{equation*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T11:07:35.029492+00:00","domain":"probability theory","id":"claim_855eda305ec2ddef756ccc917f6f864c43bbf1e7e4b9ee625e28789086cb0524","kind":"definition","schema_version":1,"statement":"[Defn 18 of arXiv:2609.02879, 'On the cut locus of Hamilton--Jacobi equations I: structure and propagation via the touchi'] Let $\phi\in\text{\rm SCL}\,(\T^n)$. We define the function of \emph{degree of regularity} of $\phi$ as
	\begin{align*}
		R_\phi(x)=
		\begin{cases}
			\inf\{\lambda\geqslant0: |p-D\phi(x)|\leqslant\lambda\cdot d(y,x),\forall y\in\T^n, p\in D^+\phi(y)\},&x\in \reg(\phi),\\
			+\infty,&x\in\cut(\phi),
		\end{cases}
	\end{align*}
	and the sub-level set of $R_\phi$ as
	\begin{align*}
		F(\phi,\lambda)=\{x\in\T^n: R_\phi(x)\leqslant\lambda\},\qquad\lambda\geqslant0.
	\end{align*}","status":"unverified"}

