        -\sum_{{\color{NavyBlue}{\mathbf{i}}}\in \{{\color{NavyBlue}{\mathbf{0}}}, {\color{NavyBlue}{\mathbf{1}}}\}}\int_s^t\bracket{~_{{\color{NavyBlue}{\mathbf{i}}}}|\bm{\ell}_u}{\sigX[u]^{-1}}dX_u^i + 
        \dfrac12\sum_{{\color{NavyBlue}{\mathbf{i}}}, {\color{NavyBlue}{\mathbf{j}}}\in \{{\color{NavyBlue}{\mathbf{0}}}, {\color{NavyBlue}{\mathbf{1}}}\}}\int_s^t\bracket{~_{{\color{NavyBlue}{\mathbf{ij}}}}|\bm{\ell}_u}{\sigX[u]^{-1}}d\bracket{X^i}{X^j}_u.
