{"assumptions":[],"created_at":"2026-10-26T19:37:51.454498+00:00","domain":"probability theory","id":"claim_8a2b45672d2f4c6c2c999e8c8526756539dcad9f596682e43b2fe754d1ad193f","kind":"definition","schema_version":1,"statement":"[Definition 2 of arXiv:2604.03777, 'Equilibrium fluctuations for a multi-species particle system with long jumps'] Let $\gamma > 0$, $\lambda \in \mathbb{R}$. We say that a $\mathcal{S}'(\mathbb{R})$-valued 
stochastic process $(\mathcal{Z}_t)_{ 0 \leq t \leq T}$ is a stationary solution of the 
fractional Ornstein-Uhlenbeck equation with diffusivity $D>0$ (in short, 
$OU(\gamma,\lambda, D)$), 
\begin{equation} 
\dd \mathcal{Z}_t = ( \mathbb{L}^{ \gamma  } + \widehat{\mathbb{L}}_{\lambda}^{ \gamma}) \; \mathcal{Z}_t \; \dd t + \sqrt{2D \; \mathcal{P}^{\gamma} } \; \dd  \mathcal{W}_t
\end{equation}
if $(\mathcal{Z}_t)_{ 0 \leq t \leq T}$ is such that  
\begin{enumerate}
\item for all $t\in[0,T]$, 
$\mathcal{Z}_t$ is a mean zero Gaussian field whose covariance 
satisfies 
\begin{equation} 
\mathbb{E}_{P} [ \mathcal{Z}_t(H_1) \mathcal{Z}_t(H_2) ] = D \int_{\mathbb{R}}  H_1(u) \; H_2(u) \, \dd u
\end{equation}
for every $H_1, \; H_2 \in \mathcal{S}(\mathbb{R})$; 
\item
 for all $H \in \mathcal{S}(\mathbb{R})$, the processes $\mathcal{M}_t(H)$ and $\mathcal{N}_t(H)$ given by
\begin{equation}  
\mathcal{M}_t(H) := \mathcal{Z}_t(H) - \mathcal{Z}_0(H) - \mathcal{I}_t(H), \quad \mathcal{N}_t(H) := \mathcal{M}_t(H)^2  -2  D t \;    \mathcal{P}^{\gamma} H,
\end{equation}
are martingales with respect to the canonical filtration 
generated by $(\mathcal{Z}_t)_{ 0 \leq t \leq T}$, where, for $H\in\cS(\R)$, $\mathcal{I}_t(H)$ is given by
\begin{equation} 
\forall t \in [0, \; T], \quad \mathcal{I}_t(H):= \int_0^t\mathcal{Z}_s (( \mathbb{L}^{ \gamma  
} + \widehat{\mathbb{L}}_{\lambda}^{ \gamma}) H) \; \dd s.
\end{equation}




\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T15:07:17.279003+00:00","domain":"probability theory","id":"claim_8a35e0f80c40e0e07138468146fd86ed43a7641b87a4893cca58e6cec13c4473","kind":"lemma","schema_version":1,"statement":"[Lemme eq:conditionomega of arXiv:2603.21634, 'Individual-based stochastic model with unbounded growth, birth and death rates: a tightnes'] Assumption~(hyp:poidsomega of the paper) is equivalent to the combination of the following properties. First, $\omega \in \mathcal{C}^{1}(\mathbb{R}^{*}_{+})$, is positive and non-decreasing, and then
\begin{multline}
 \exists \omega_{1}>0, \forall x>0, \\
 \overline{g}(x)(1+\omega'(x)) + b(x)\left(1+\left|\omega(x_{0})+\omega(x-x_{0}) -\omega(x)\right|\right) + d(x)\omega(x) \leq \omega_{1}(1+x+\omega(x)), 
\end{multline}
and
\begin{align}
 \exists \omega_{2}>0, \forall x>0, \quad b(x)(\omega(x_{0})+\omega(x-x_{0}) -\omega(x))^{2}+ d(x)\omega^{2}(x) \leq \omega_{2} (1+x+\omega(x)).

\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T01:10:08.714593+00:00","domain":"probability theory","id":"claim_8a3c098a428086fa4fba6d89abf551830cfb75fab221a8b9a0a57e23b84062fa","kind":"concept","schema_version":1,"statement":"[Lemma repl_lemma_ave of arXiv:2411.17653, 'Exclusion processes with non-reversible boundary: hydrodynamics and large deviations'] For every $H \in C([0,T])$, for any $t \in [0,T]$ and $z=\epsilon_N$, it holds
\begin{equation} 
\lim_{\epsilon\to 0}\lim_{N\to+\infty}\mathbb{E}_{\nu_N} \left[\Big | \int_0^t [\eta_{sN^2}(z) - \overrightarrow{\eta}^{\lfloor \epsilon N\rfloor}_{sN^2}(z)] H(s)ds\Big| \right] =0,
\end{equation}
where, for every $L\in\mathbb N$ and $\eta \in \Omega_N$,
\begin{equation} 
\overrightarrow{\eta}^L(z) :=\frac{1}{L\epsilon_N}\sum_{y= z+\epsilon_N}^{z+L\epsilon_N}\eta(y).
\end{equation}
The same result holds for $z = \tau_N$ by replacing the average to the right, i.e. $\overrightarrow{\eta}^{\lfloor \epsilon N\rfloor}_{sN^2}$, by an average to the left, i.e. $\overleftarrow{\eta}^{\lfloor \epsilon N\rfloor}_{sN^2}$, which is defined, for every $L\in\mathbb N$ and $\eta \in \Omega_N$, as
\begin{equation}
 \overleftarrow{\eta}^L(z) :=\frac{1}{L\epsilon_N}\sum_{y=z-L\epsilon_N}^{z-\epsilon_N}\eta(y).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:13:31.915825+00:00","domain":"probability theory","id":"claim_8a564b49394a04c30b96d809cb6452206e105ea553306029c4872bf9964ce23e","kind":"concept","schema_version":1,"statement":"[Lemma eq:reweight_by_two of arXiv:2506.10765, 'A General Coupling for Ising Models and Beyond'] Let $G=(V,E)$ be a finite  graph. Let $A\subset V$ with $|A|$ even (could be $0$). Then, $\forall \omega\in\{0,1\}^E$,
\begin{align}
