{"assumptions":[],"created_at":"2026-10-27T19:35:19.874049+00:00","domain":"probability theory","id":"claim_8c2b36f10da49c6878eea32f2405b23359faee61e3dfbacc5594f36fb84e58c2","kind":"definition","schema_version":1,"statement":"[Defn ent of arXiv:2608.27939, 'Entropy and domination for quasi-Hitchin representations'] Given a discrete representation $\rho:\pi_1(S) \to \mathrm{PSL}_n(\mathbb{C})$, we define its Hilbert entropy to be:
\begin{equation}
H(\rho) =  \limsup\limits_{L\to \infty} \displaystyle\frac{\log \#\{[\gamma] \text{ a conjugacy class in } \pi_1(S)\ \vert\ l^H_\rho(\gamma) \leq L\}}{L}
\end{equation}
where $l^H_\rho(\gamma)$ is the Hilbert length of $\gamma$ with respect to $\rho$.  The \textit{translation length entropy} $E(\rho)$ is defined by the same expression, replacing $l^H_\rho(\gamma)$  by   the \textit{translation length} $\ell_\rho(\gamma)$ of $\rho(\gamma)$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:28:49.121641+00:00","domain":"probability theory","id":"claim_8c39523acc92a9b5a62eeb12689239778eb6b67151f9b7ce8f42c2f919fccb81","kind":"lemma","schema_version":1,"statement":"[Lemma lem:elementary-expansion of arXiv:2608.18293, 'Critical tensor covariance at the Marchenko--Pastur threshold'] For $a_n=d/n$,
\begin{equation}
  R_n=\sum_{k=0}^{d}
  \frac{(d)_k}{(n)_k}e_k(\delta),

\end{equation}
where $(q)_k=q(q-1)\cdots(q-k+1)$. If
\begin{equation}
  P_n=\prod_{i=1}^n(1+a_n\delta_i)
  =\sum_{k=0}^n a_n^k e_k(\delta),

\end{equation}
then
\begin{equation}
  \mathbb{E}|R_n-P_n|^2\longrightarrow0.

\end{equation}
Moreover,
\begin{equation}
  \sup_n\mathbb{E} R_n^2<\infty.

\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:42:16.235719+00:00","domain":"probability theory","id":"claim_8c398c2724d148d1e6829e761f9fe5a95d403243b2ed9f7dbddee0c0c4bc9cd8","kind":"theorem","schema_version":1,"statement":"[Theorem prop:uniform-time-avg-poc of arXiv:2607.00149, '\bf Uniform-in-time Propagation-of-Chaos for\\ Stein Variational Gradient Descent'] Let Assumption~(ass:poc of the paper) hold. Recall the constant $c_0$ from Lemma~(lem:finite-time-poc of the paper). Then, there exists a finite constant $C>0$ such that, for any $\delta>0$ and all sufficiently large $N$,
\begin{equation}
\sup_{T>0}
\mathbb E\,\left[\mathsf{KSD}_\pi\bigl(\overline\mu_T^N,\overline\mu_T\bigr)\, \mathbf{1}_{\{\int \|x\|^2 \mu^N_0(dx) \le R\}}\right]
\le C N^{-\beta/2}\exp\{c_0(1+R)(\log N)^{c_0\delta}\} + C(\delta\log\log N)^{-1/2}.
\end{equation}
Consequently,
\begin{equation}
    \lim_{M \to \infty} \, \limsup_{N \to \infty}\,\sup_{T>0}\mathbb{P}\left[\mathsf{KSD}_\pi\bigl(\overline\mu_T^N,\overline\mu_T\bigr) \ge M (\log \log N)^{-1/2}\right] = 0.
\end{equation}
Moreover, suppose that the empirical initial second moments satisfy the uniform sub-Gaussian bound
\[
R_N:=\int_{\mathbb R^d}|x|^2\,\mu_0^N(dx),
\qquad
\sup_{N\ge1}\mathbb E\exp\{\lambda R_N^2\}<\infty
\]
for some \(\lambda>0\). Then there exists \(C<\infty\) such that, for all sufficiently large \(N\),
\begin{equation}
\sup_{T>0}
\mathbb E\,\mathsf{KSD}_\pi(\overline\mu_T^N,\overline\mu_T)
\le
C(\log\log N)^{-1/2}.
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:38:23.574506+00:00","domain":"probability theory","id":"claim_8c3b378b62e995fef0628a3bff5b96dd12c596f47924d701e481767d7e77c103","kind":"concept","schema_version":1,"statement":"[Proposition prop:equiv of arXiv:2511.01851, 'Percolation on graphs of polynomial growth is local:\\analyticity, supercritical sharpness'] The following statements are equivalent:
