{"assumptions":[],"created_at":"2026-10-27T11:17:33.993315+00:00","domain":"probability theory","id":"claim_9364f049db059b83f6988a06eb668c864c376ffbd80193d644651813781bf957","kind":"concept","schema_version":1,"statement":"[Proposition 32 of arXiv:2609.03386, 'Twisted Gradient Flow Approach to Vegetation-Rainfall-Bushfire Interactions Model'] For every $\delta \in (1,\infty)$ the approximate initial-boundary value problem $\mbox{(AP)}{}_{\text{{\tiny $\delta$}}}$ admits at least 
one strong solution $(u_{\text{{\tiny $\delta$}}},v_{\text{{\tiny $\delta$}}},w_{\text{{\tiny $\delta$}}})$ on $[0,T]$ satisfying 

\begin{equation}
u_{\text{{\tiny $\delta$}}}(x,t) \ge 0, \quad v_{\text{{\tiny $\delta$}}}(x,t) \ge 0, \quad w_{\text{{\tiny $\delta$}}}(x,t) \ge 0, \quad \text{a.e.}~(x,t) \in Q_T.
\end{equation}

\indent
Moreover, the following estimates hold:
\begin{enumerate}\leftskip6pt
\item[(1)] There exists a constant $C_{21}>0$, which depends on $\delta$, $T$, $\|u_0\|_{H^1(\Omega)}$, $\|v_0\|_{H^1(\Omega)}$ and $\|w_0\|_{H^1(\Omega)}$,
such that

\begin{equation*}
\int_0^T \|u_{\text{{\tiny $\delta$}}}'(t)\|_{L^2(\Omega)}^2dt+\left( \sup_{0 \le t \le T} \|u_{\text{{\tiny $\delta$}}}(t)\|_{H^1(\Omega)} \right)^2
+\int_0^T \|u_{\text{{\tiny $\delta$}}}(t)\|_{H^2(\Omega)}^2 dt \le C_{21}.
\end{equation*}

\item[(2)] There exists a constant $C_{22}>0$, which depends on $\delta$, $T$ and $\|v_0\|_{H^1(\Omega)}$, such that

\begin{equation*}
\int_0^T \|v_{\text{{\tiny $\delta$}}}'(t)\|_{L^2(\Omega)}^2dt+\left( \max_{0 \le t \le T} \|v_{\text{{\tiny $\delta$}}}(t)\|_{L^2(\Omega)} \right)^2 \le C_{22}.
\end{equation*}

\item[(3)] There exists a constant $C_{23}>0$, which depends on $\delta$, $T$, $\|v_0\|_{H^1(\Omega)}$ and $\|w_0\|_{H^1(\Omega)}$, such that

\begin{equation*}
\int_0^T \|w_{\text{{\tiny $\delta$}}}'(t)\|_{L^2(\Omega)}^2dt+\left( \sup_{0 \le t \le T} \|w_{\text{{\tiny $\delta$}}}(t)\|_{H^1(\Omega)} \right)^2
+\int_0^T \|w_{\text{{\tiny $\delta$}}}(t)\|_{H^2(\Omega)}^2 dt \le C_{23}.
\end{equation*}

\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:38:25.224670+00:00","domain":"probability theory","id":"claim_936a5796dc9ba38e672dc255a1a44c144bc94403fd984c90e9cb70a50b3fed61","kind":"theorem","schema_version":1,"statement":"[Proposition Propositio:Stabilitytrace of arXiv:2609.00324, 'Quantitative Stability for Fractional Yamabe minimizers'] Let $\gamma \in (0,1)$ and $a= 1-2\gamma$. Then, there exists a constant $C>0$ such that for any $U\in \dot{W}^{1,2}(\mathbb{R}_{+}^{n+1}, y^a )$ with trace $TU =w$
\begin{align*}
    \int_{\mathbb{R}_{+}^{n+1}} y^a |\nabla U|^2 dxdy - \frac{1}{\bar{S}(n,\gamma)} \|w \|_{L^{2^{*}}(\mathbb{R}^n )}^2  \geq C \text{dist} (U,\mathcal{M}_{\mathbb{R}_+^{n+1}})^2 \, ,
\end{align*}
where
