    \text{dist} (U,\mathcal{M}_{\mathbb{R}_+^{n+1}}) = \inf \{\|U - V\|_{\dot{W}^{1,2}(\mathbb{R}^{n+1}_+,y^a)} : V \in \mathcal{M}_{\mathbb{R}^{n+1}_+ } \} .
