{"assumptions":[],"created_at":"2026-10-27T14:25:44.589381+00:00","domain":"probability theory","id":"claim_962338d7b747565605da704a9203ff5d061517e2a73708f8093d331eb992d5b3","kind":"definition","schema_version":1,"statement":"[Defi def:elec_energy of arXiv:2509.08659, 'Gap metrics for stationary point processes and quantitative convexity of the free energy'] [Electric energy]
Let $I\subset \IR$ be an interval.
\begin{enumerate}
    \item We call electric fields on $I$ the set of all vector fields $E$ in $L^p_{loc}(I\times \IR,\IR\times \IR)$, for some $1<p<2/(s+1)$ fixed
\item Let $\xi$ be a finite point configuration in $I$ and $E$ an electric field on $I$. We say that $E$ is compatible with $\xi$ in $I$ provided 
\begin{align}
    -\textup{div}\,\left(\left\lverty\right\rvert^sE\right)=c_s\left(\xi-\delta_{\IR}\right) \text{ in }I\times \IR,
\end{align}
in the sense of distributions. Here  $\delta_{\IR}$ is the Radon measure on $\IR\times \IR$ defined by \begin{align*}
    \int_{\IR^2} f(x,y) d\delta_{\IR}(x,y)=\int_{\IR} f(x,0)dx,\quad f\in C_c(\IR^2,\IR).
\end{align*}
Similarly, in (equation eq:hypersurf of the paper) the point configuration $\xi$ is interpreted as a measure on $\IR^2$ via  
\begin{align*}
    \int_{\IR^2} f(x,y) d\xi(x,y)=\int_{\IR} f(x,0)d\xi(x)\quad f\in C_c(\IR^2,\IR).
\end{align*}
\item If $E$ is compatible with $\xi$ in $I$, for $\eta\in (0,1)$  we define the $\eta$-truncation of the electric field $E$ as
\begin{align*}
    E_{\eta}(x,y):=E(x,y)-\sum_{p\in \xi\cap I}\nabla f_{\eta}((x,y)-(p,0)),
\end{align*}
    where $f_{\eta}$ is the function
    \begin{align*}
        f_{\eta}(x,y):=\left(g(x,y)-g(\eta)\right)_+
    \end{align*}
     and $g(\eta)$ is defined by $g(\eta)=g(\eta,0)$.
\item Let $\xi$ be a point configuration on $\IR$. We define the global electric energy of $\xi$ as
\begin{align*}
     \tilde{\mathcal W}^{elec}(\xi):=\inf_E \left(
    \lim_{\eta\to 0}\left( 
    \limsup_{n\to \infty}\frac{1}{\left\lvert\Lambda_n\right\rvert}\frac{1}{c_s}\int_{\Lambda_n\times \IR}\left\lverty\right\rvert^{s}\norm{E_{\eta}}^2-g(\eta)
    \right)
    \right),
\end{align*}
where the $\inf$ is taken over electric fields $E$ that are compatible with $\xi$ in $\IR$.
\item For $\mathsf{P}\in \mathcal P_{s,1}(\Gamma)$ we set \begin{align*}
    \mathcal W^{elec}(\mathsf{P}):=\int \tilde{\mathcal W}^{elec}(\xi)\mathsf{P}(d\xi).
\end{align*}


\end{enumerate}","status":"unverified"}

