{"assumptions":[],"created_at":"2026-10-27T06:29:21.915986+00:00","domain":"probability theory","id":"claim_9afd085aa5ca2aca390b828f80659d98244133d0b789c117aff5cebc2ff5e4ff","kind":"concept","schema_version":1,"statement":"[Prop 8 of arXiv:2608.01419, 'A model of opinion dynamics evolving via a preferential attachment mechanism involving mul'] _unique_root_examples}
