{"assumptions":[],"created_at":"2026-10-27T12:10:07.472884+00:00","domain":"probability theory","id":"claim_9c9dc91f7e65bf9f3dd7d087871ca20ea68a170ae06f4ecf24689b6d6533897e","kind":"lemma","schema_version":1,"statement":"[Lemma eq:Haar-entry-tail of arXiv:2607.27613, 'Regularized Bulk Universality versus Bounded-Disorder Nonuniversality\\for Annealed Comple'] \label[lemma]{lem:Haar-incoherent}
There are universal constants \(c,C>0\) such that, for Haar \(O\in\mathbb O(N)\),
\begin{equation}
 \mathbb P(\abs{O_{ij}}>t)\le C e^{-cNt^2},
 \qquad 0<t<1.
\end{equation}
Consequently, if \(L>L_0:=\sqrt{3/c}\), then
\begin{equation}
 \nu_N(\mathcal O_{N,L})\longrightarrow1,
 \qquad
 \frac1N\log\nu_N(\mathcal O_{N,L})\longrightarrow0.
\end{equation}
For the point cutoff, however, every fixed \(L>0\) has zero
exponential cost:
\begin{equation}
 \frac1N\log\overline\sigma_{N-1}(D_{N,L})
 \longrightarrow0.
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:33:46.769973+00:00","domain":"probability theory","id":"claim_9ca82c8b6e1eee6869a93dde9711b24d185538f6b44cb2a88ef1e698eecb64ae","kind":"lemma","schema_version":1,"statement":"[Lemma 33 of arXiv:2603.24616, 'Pinning in non-critical half-space geometric last passage percolation'] Let $k, b, \vec{y}, g$ be as in Definition \ref{Def.PinnedBM}. Suppose that $d_n$ is a sequence of positive reals such that $d_n \rightarrow \infty$, and set $T_n = \lceil b d_n \rceil$. Let $g_n: [0, T_n/d_n] \rightarrow [-\infty, \infty)$ be continuous functions such that $g_n \rightarrow g$ uniformly on $[0,b]$. In the case when $g = -\infty$, the last statement means that $g_n = -\infty$ for all large $n$. We also suppose that 
\begin{equation}
\lim_{n \rightarrow \infty} |g_n(T_n/d_n) - g_n(b)| = 0 \mbox{ if } g \neq -\infty.
\end{equation}

Fix $q\in (0,1)$, $c \in [0,1)$, and put $p = \frac{q}{1-q}$, $\sigma = \sqrt{p(1+p)}$. Define $G_n: [0, T_n] \rightarrow [-\infty, \infty)$ through
$$G_n(s) = \sigma d_n^{1/2} \cdot g_n(s/d_n) + p s,$$
and suppose that $Y^n \in \mathfrak{W}_{2k}$ is a sequence such that 
\begin{equation}
 \lim_{n \rightarrow \infty} \sigma^{-1} d_n^{-1/2} \cdot (Y_i^n - p T_n)   = y_i \mbox{ for } i \in \llbracket 1, 2k \rrbracket.
\end{equation}

Then, we have the following statements.
\begin{enumerate}
\item[(a)] There exists $N_0 \in \mathbb{N}$ such that for $n \geq N_0$ the laws $\mathbb{P}_{\ice;q ,c}^{T_n, Y^n,G_n}$ are well-defined, i.e. for some $(\mathfrak{B}^1, \dots, \mathfrak{B}^k) \in  \Omega_{\ice}(T_n, Y^n, G_n)$, we have $\prod_{i = 1}^k W(\mathfrak{B}^i; q,c) > 0$.
\item[(b)] If $\mathfrak{Q}^n = \{Q_i^n\}_{i = 1}^{2k}$ has law $\mathbb{P}_{\ice;q ,c}^{T_n, Y^n,G_n}$, then the sequence of $\llbracket 1,2k \rrbracket$-indexed line ensembles $\mathcal{Q}^n$ on $[0,b]$ defined by
\begin{equation}
\mathcal{Q}_i^n(t) = \sigma^{-1} d_n^{-1/2} \cdot \left( Q^n_i(t d_n) - ptd_n\right) \mbox{ for } n \geq N_0, \hspace{2mm} t \in [0,b] \mbox{ and } i \in \llbracket 1, 2k \rrbracket,
\end{equation}
converges weakly to $\mathbb{P}_{\mathrm{pin}}^{b,\vec{y},g}$ from Definition \ref{Def.PinnedBM} as $n \rightarrow \infty$.
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:21:10.887578+00:00","domain":"probability theory","id":"claim_9cb65750d402d6219338b14fc16bacae386da09dde02b20cebffc0b79fde42b2","kind":"lemma","schema_version":1,"statement":"[Lemma 16 (Properties of Poisson-Voronoi percolation) of arXiv:2504.02435, 'Poisson-Voronoi percolation in higher rank'] Let $G$ be a non-compact connected semisimple real Lie group, $(X,d_X)$ be its symmetric space, $\lambda>0$ and $p\in (0,1)$.
    Then $\omega_p^{(\lambda)}$ defines a random closed subset of $X$ which
    \begin{itemize}
        \item[{\rm (i)}] is $G$-invariant and ergodic, and, moreover, is invariant under all isometries of $(X,d_X)$.
        \item[{\rm (ii)}] satisfies the Harris-FKG-inequality.
        \item[{\rm (iii)}] satisfies $\mathbb P\big(o\in \partial \omega_p^{(\lambda)}\big)=0$.
    \end{itemize}
    Moreover, the Voronoi diagram $\mathrm{Vor}(\mathbf{Y}^{(\lambda)})$ consists of compact subsets of $X$.","status":"unverified"}

