{"assumptions":[],"created_at":"2026-10-26T19:36:44.551584+00:00","domain":"probability theory","id":"claim_a060400e8813d794dbcfd0e6ced5cd1ba1ac97b07acef88bf229492a76a855f1","kind":"concept","schema_version":1,"statement":"[Proposition 18 of arXiv:2604.01978, 'Homogenized Transformers'] Let $X^n = §(x^{n}_1,\ldots, x^{n}_1)$ solve 
\begin{equation*}
\de x^{n}_i(t)=\int_{\Uptheta}G_{\mu^{n}(t)}(x_{i}^n(t);\bm{\theta})\mathsf{W}(\de \bm{\theta}, \de t),
\end{equation*}
with $\mu^n = \mu_{X^n}$. 
Let $(\bar x_1,\ldots,\bar x_n)$ be conditionally i.i.d., given $(\mathscr{F}^{\mathsf W}_t)_{t\geq0}$, copies of the unique solution $x$ of \eqref{eq:non_linear_SDE_common}, driven by the same common noise $\mathsf{W}$, and let $\bar\mu$ be their empirical measure. Then for every $T>0$ there exists $C_T>0$ such that 
\begin{align*}
    \max_{i\in[n]} \E \sup_{t\in[0, T]} \left\|x^{n}_i(t)-\bar x_i(t)\right\|^2 &+ \E \sup_{t\in[0, T]} W_2^2(\mu^n(t), \bar\mu^n(t)) \\
    &\leq  \frac{C_T}{n} \sum_{i=1}^n \E \left\|x^{n,i}(0)-\bar x^i(0)\right\|^2.
\end{align*}
In particular, after choosing an optimal coupling of the initial data, the right hand side may be written as $C_T \E W_2^2(\mu^n(0), \bar \mu^n(0))$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:17:42.314443+00:00","domain":"probability theory","id":"claim_a06e0bc912f8c6e4f48f3db5ee743064f6cc6857c3117d8a95e15d2c657167f1","kind":"theorem","schema_version":1,"statement":"[Proposition 48 of arXiv:2608.05931, 'Effective Lagrangian regularity and the uniqueness threshold for random H\"older velocity '] Suppose $u : \T^d \to \R^d$, $\alpha \in (0,1)$, and $Z := \{u =0\} \subseteq \T^d$ are such that
    \begin{enumerate}
        \item $\nabla \cdot u=0,$
        \item $u \in C^\alpha(\T^d)$,
        \item $\liminf_{r \to 0} r^{-(1-\alpha)} |\{ x \in \T^d : d_{\T^d}(x,Z) \leq r\}| =0$,
        \item and for all $\tau>0, y \in \T^d$, if $X^1, X^2$ are solutions to~\eqref{eq:abstract ode} on $[0,\tau]$ such that for all $t \in [0,\tau]$, $X^1_t, X^2_t \not \in Z$, then $X^1|_{[0,\tau]} = X^2|_{[0,\tau]}$.
    \end{enumerate}
    Then for almost every $y \in \T^d$,~\eqref{eq:abstract ode} admits a unique solution on $[0,\infty)$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:03:39.776338+00:00","domain":"probability theory","id":"claim_a07679977ddd1569156c67917468df12e2e996af2106c00ab20e222132657205","kind":"theorem","schema_version":1,"statement":"[Cor unshuffling-cor of arXiv:2411.03065, 'Growing conditioned BGW trees with\\ log-concave offspring distributions'] Let $\mathbb{X}$ be a set and let $\psi$ be an $\mathbb{X}$-shuffling rule.
	If $\psi$ is $\mathfrak{S}$-equivariant, then for every $T,T'\in\trees$, ${\boldsymbol{x}}\in\mathbb{X}^T$, and ${\boldsymbol{\uppi}}\in\mathfrak{S}_{T'}$, we have
	\begin{align}
	\begin{cases}
	{\boldsymbol{\sigma}}^\psi_{T,{\boldsymbol{x}}}\cdotT=T',\\
	{\boldsymbol{\sigma}}^\psi_{T,{\boldsymbol{x}}}={\boldsymbol{\uppi}}^{-1}
	\end{cases}
	\qquad\iff\qquad
	\begin{cases}
	T={\boldsymbol{\uppi}}\cdotT',\\
	{\boldsymbol{\sigma}}^\psi_{T',{\boldsymbol{\uppi}}^{-1}_*{\boldsymbol{x}}}=\overline{\boldsymbol{\uppi}}.
	\end{cases}
	\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:05:09.628986+00:00","domain":"probability theory","id":"claim_a079279407e9127d6a07dc8c568cf28581b337a644d49973e18eaa788d985205","kind":"concept","schema_version":1,"statement":"[Theorem thm:small_time_domain_stable of arXiv:2411.03609, 'Asymptotically optimal Wasserstein couplings for the small-time stable domain of attractio'] Let $\bm{X}=(\bm{X}_t)_{t \in [0,1]}$ and $\bm{Z}=(\bm{Z}_t)_{t\in [0,1]}$ be L\'evy processes in $\mathbb{R}^d$. The following are equivalent:
\begin{itemize}[leftmargin=.5em, nosep]
\item $(\bm{X}_{st}/g(t))_{s \in [0,1]}\xrightarrow{d} (\bm{Z}_s)_{s\in [0,1]}$ as $t \downarrow 0$ in the Skorokhod space for some normalising function $g:(0,1]\to(0,\infty)$,
\item $\bm{X}_t/g(t)\xrightarrow{d} \bm{Z}_1$  as $t \downarrow 0$ for some normalising function $g:(0,1]\to(0,\infty)$,
\item $\bm{Z}$ is $\alpha$-stable for some $\alpha\in(0,2]$, the function $G:t\mapsto g(t)t^{-1/\alpha}$ is slowly varying at $0$, and the generating triplets $(\bm\gamma_{\bm{X}},\bm{\Sigma_X}\bm{\Sigma}_{\bm{X}}^{\scalebox{0.6}{$\top$}},\nu_{\bm{X}})$ and $(\bm\gamma_{\bm{Z}},\bm{\Sigma_Z}\bm{\Sigma}_{\bm{Z}}^{\scalebox{0.6}{$\top$}},\nu_{\bm{Z}})$ (for the cutoff function $\bm{w} \mapsto \1_{B_{\bm 0}(1)}(\bm{w})$) of $\bm{X}$ and $\bm{Z}$, respectively, are related as follows:
\begin{itemize}[leftmargin=1em, nosep]
\item if $\alpha=2$ (attraction to Brownian motion), then 
\begin{equation}

G(t)^{-2} \bigg(\bm{\Sigma_X}\bm{\Sigma}_{\bm{X}}^{\scalebox{0.6}{$\top$}}
    +\int_{B_{\bm{0}}(g(t))\setminus\{\bm{0}\}}\bm{x}\bm{x}^{\scalebox{0.6}{$\top$}}\nu_{\bm{X}}(\mathrm{d}\bm{x})\bigg)
\to
\bm{\Sigma_Z}\bm{\Sigma}_{\bm{Z}}^{\scalebox{0.6}{$\top$}},\quad\text{as }t\downarrow 0;
\end{equation}
\item if $\alpha\in(1,2)$, we have $\bm{\Sigma_X}=\bm{0}$ and
\begin{equation}

t\nu_{\bm{X}}(\mathscr{L}_{\bm{v}}(g(t)))\to \nu_{\bm{Z}}(\mathscr{L}_{\bm{v}}(1)),
\quad\text{as }t\downarrow 0,\quad\text{for any }\bm{v}\in\mathbb{S}^{d-1};
\end{equation}
    \item if $\alpha=1$ (attraction to Cauchy process), then~(equation eq:jump-stable-limit of the paper) holds,
\begin{equation}

G(t)^{-1}\bigg(\bm{\gamma_X}-\int_{B_{\bm0}(1)\setminus B_{\bm0}(g(t))}\bm{x}\nu(\mathrm{d}\bm{x})\bigg)\to \bm{\gamma_Z},
\quad\text{as }t\downarrow 0,
\end{equation}
and for any $\bm{v}\in\mathbb{S}^{d-1}$ for which $\langle\bm{v},\bm{X}\rangle$ has finite variation (i.e. $\int_{B_{\bm 0}(1)\setminus\{\bm 0\}}\!|\langle\bm{v},\bm{x}\rangle|\nu_{\bm{X}}(\mathrm{d}\bm{x})<\infty$) and $\nu_{\bm{Z}}(\mathscr{L}_{\bm{v}}(1))>0$, the process $\langle\bm{v},\bm{X}\rangle$ has zero natural drift: $\langle\bm{v},\bm{\gamma_X}\rangle=\int_{B_{\bm 0}(1)\setminus\{\bm 0\}}\langle\bm{v},\bm{x}\rangle\nu_{\bm{X}}(\mathrm{d}\bm{x})$.
\item if $\alpha\in(0,1)$, then~(equation eq:jump-stable-limit of the paper) holds, $\bm{X}$ has finite variation (i.e. $\int_{B_{\bm0}(1)\setminus\{\bm0\}}|\bm{x}|\nu_{\bm{X}}(\mathrm{d}\bm{x})<\infty$) and zero natural drift (i.e. $\bm{\gamma_X}=\int_{B_{\bm 0}(1)\setminus\{\bm 0\}}\bm{x}\nu_{\bm{X}}(\mathrm{d}\bm{x})$).
\end{itemize}
\end{itemize}
Moreover,  the function $g$ 
satisfying the weak limit above
is asymptotically unique at $0$: a positive  function $\widetilde{g}$ 
satisfies $(\bm{X}_{st}/\widetilde{g}(t))_{s \in [0,1]}\xrightarrow{d} (\bm{Z}_s)_{s\in [0,1]}$ as $t \downarrow 0$
if and only if $\widetilde{g}(t)/g(t)\to 1$ as $t\downarrow 0$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:51:30.075113+00:00","domain":"probability theory","id":"claim_a083ad505b9245976fb4266c711100599fb78a3c4a3acc3ee66cf52c44a9d5d4","kind":"definition","schema_version":1,"statement":"[Definition 8 of arXiv:2606.02036, 'Self-intersection local times for Volterra Gaussian processes in stochastic flows with int'] The stochastic differential equation
\begin{align}

\begin{cases}
\differential{x}(v,t)=a(x(v,t),\mu_t)\differential{t}+\int_{\mbR^d}b(x(v,t),\mu_t,z)W(\differential{t},\differential{z}), \\	
x(v,0)=v,\ v\in\mbR^d, \\
\mu_t=\mu_0\circ x(\cdot,t)^{-1},\ t\geqslant 0, 
\end{cases}
\end{align}
is said to be the equation with interaction.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:24:10.200103+00:00","domain":"probability theory","id":"claim_a092a0665e17a1d444c2111d51aa3fde7a4573c74ae1f806d5b2d94e73ab3de9","kind":"theorem","schema_version":1,"statement":"[Proposition 12 (Survival condition for correlated catastrophes) of arXiv:2605.04048, 'Catastrophe--dispersion models in random and varying environments across generations'] In Example~\ref{ex:RE-correlated} the process survives with positive probability
