{"assumptions":[],"created_at":"2026-10-27T21:30:14.222180+00:00","domain":"probability theory","id":"claim_a5a5c78391c9dbd565ee80ee66d01126bd15e927b137ea49002663c3062c2fe5","kind":"lemma","schema_version":1,"statement":"[Lemma lem:drift-heat of arXiv:2608.20537, 'Persistent anisotropy in multi-dimensional\\ branching Brownian motion'] Let $v(s, y; t)$ solve 
  \begin{equation*}
    \begin{cases}
      \partial_s v + \partial_y^2  v + \dot{g} \partial_y  v = 0, & s \in (1,t), y > 0,\\
      v(s = t, y) = y,\\
      v(s,0) = 0.
    \end{cases}
  \end{equation*}
  Then there exists $\underline{s}(d) > 0$ such that 
  \begin{equation}

    y \leq v(s, y; t) \leq 2y \quad \text{for all } s \in [\underline{s}, t], y \geq 0.
  \end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:35:05.801627+00:00","domain":"probability theory","id":"claim_a5ac98d53adad89985f974f02c372f96181bb4fb973e42c4095d4509888e3029","kind":"theorem","schema_version":1,"statement":"[Corollary cor:prn_phi of arXiv:2606.23547, 'The location of the largest exponential spacing and Euler’s generalized pentagonal numbers'] For $1\le r\le n$,
