\end{equation} 
for any $t\in [0,T]$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T01:41:54.369629+00:00","domain":"probability theory","id":"claim_ad09279c1e3593e4d882325542552d50c80bbb1c481346afd4fe6dbf025e54d6","kind":"concept","schema_version":1,"statement":"[Propo g of arXiv:2412.01673, 'Spatial SIR epidemic model with varying infectivity without movement of individuals'] For all $\varphi \in C_b(D)$, $\left\{ \overline{\mu}_t^{S,N},\overline{\mu}_t^{\mathfrak{F},N},\overline{\mu}_t^{I,N}, \overline{\mu}_t^{R,N},\ t\ge0\right\}$ satisfies
	\begin{equation}

	\left\lbrace
	\begin{aligned}
	(\overline{\mu}_t^{S,N},\varphi)&= (\overline{\mu}_0^{S,N},\varphi)
	-\frac{1}{N} \sum_{i\in\mathfrak{S}_N}\varphi(X^{i})A^N_i(t),\\
	(\overline{\mu}_t^{\mathfrak{F},N},\varphi) &= \frac{1}{N} \sum_{i\in\mathfrak{I}_N} \lambda_{-i}(t)\varphi({X^{i}}) +\frac{1}{N} \sum_{i\in\mathfrak{S}_N} \lambda_{i}(t- \tau_i^N)\varphi({X^{i}}),\\
	(\overline{\mu}_t^{I,N},\varphi)&= (\overline{\mu}_0^{I,N},\varphi)+\frac{1}{N} \sum_{i\in\mathfrak{S}_N}\varphi(X^{i})A^N_i(t)- \frac{1}{N}\sum_{i\in\mathfrak{I}_N}\varphi(X^{-i})\mathbf{1}_{\eta_{-i}\leq t}\\
	&- \frac{1}{N} \sum_{i\in\mathfrak{S}_N}\varphi(X^{i})\int_0^t\mathbf{1}_{\eta_i\leq t-s}dA^N_i(s),\\
	(\overline{\mu}_t^{R,N},\varphi)&= (\overline{\mu}_0^{R,N},\varphi)+ \frac{1}{N}\sum_{i\in\mathfrak{I}_N}\varphi(X^{-i})\mathbf{1}_{\eta_{-i}\leq t}+\frac{1}{N} \sum_{i\in\mathfrak{S}_N}\varphi(X^{i})\int_0^t\mathbf{1}_{\eta_i\leq t-s}dA^N_i(s)\,.
	\end{aligned}
	\right.
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T17:18:19.443919+00:00","domain":"probability theory","id":"claim_ad0addb7cdb29ce48c4e10b61b00e4e4f563a699352fddcf53c881c1db1a3ef3","kind":"theorem","schema_version":1,"statement":"[Proposition prop:wishart_moment of arXiv:2508.17838, '\bf Edge Universality for Inhomogeneous Random Matrices'] Let $X$ be the real symmetric (or Hermitian) deformed Gaussian IRM–Wishart matrix from (equation eq:deformed-wishart of the paper), and fix nonnegative integers $m_1,\dots,m_s$.  For each face $D_j$, set $n_j \;=\;\sum_{e\in\partial D_j}w_e$,  then
\begin{multline}

\mathbb{E}\Bigl[\prod_{j=1}^s \mathrm{Tr} \big(X^{m_j}\big)\Bigr]
=
\sum_{\Gamma \in \mathscr{D}_{s;\beta}}
\;\sum_{\substack{\eta:V(\Gamma)\to [M]\cup[N]}}
\;\sum_{\substack{w_e \ge 1 \\ \sum_{e \in \partial D_j} w_e = n_j, \ \forall j}}
\;\Biggl[\,
\prod_{j=1}^s C_{\mathrm{MP}}(m_j,n_j)\;\Biggr]
\;\\ \times 
\Biggl[\,
\prod_{e=(x,y)\in E_{\mathrm{int}}}p_{w_e}\bigl(\eta(x),\eta(y)\bigr)
\;\prod_{e=(z,w)\in E_b}(A^{(w_e)})_{\eta(z)\eta(w)}
\Biggr].  
\end{multline}
Here
\begin{itemize}
  \item $E_{\mathrm{int}}$ (resp.\ $E_b$) denotes the set of interior (resp.\ open) edges of~$\Gamma$.
  \item For an open edge $e=(z,w)$, the matrix product $(A^{w_e})_{\eta(z)\eta(w)}$ means
    \begin{equation}
(A^{\,(w_e)})_{\eta(z)\,\eta(w)}
:=
\begin{cases}
(A\,A^*)^{w_e/2}, 
& z,w\in[N],\;w_e\text{ even},\\[6pt]
(A^*\,A)^{w_e/2}, 
& z,w\in[M],\;w_e\text{ even},\\[6pt]
A\,(A^*A)^{\frac{w_e-1}{2}},
& z\in[N],\;w\in[M],\;w_e\text{ odd},\\[6pt]
A^*\,(A\,A^*)^{\frac{w_e-1}{2}},
& z\in[M],\;w\in[N],\;w_e\text{ odd}.
\end{cases}
\end{equation}
  \item With  $\mu_k$ being     the $k$-th moment of the Marchenko–Pastur law  with   $\alpha=M/N$,  
    \begin{equation}
    C_{\mathrm{MP}}(m,n):
    = 
    \begin{cases}
      \mu_m, 
        & n=0, \\[6pt]
      \dfrac{m}{n}
\displaystyle\sum_{\substack{k_1+\cdots+k_n=m\\k_1,\ldots,k_n\ge1}}
      \prod_{i=1}^n \mu_{k_i},
        & 1\le n\le m, \\[6pt]
      0, & n>m.
    \end{cases}
    \end{equation}
\end{itemize}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:57:30.976544+00:00","domain":"probability theory","id":"claim_ad11df89766cc6ff41c580a3eaa64ec455fa1a20b29b11c5d90cdbb9d5e8a717","kind":"lemma","schema_version":1,"statement":"[Lemma 10 of arXiv:2608.12451, '2608.12451'] Let $(X,X')$ be an exchangeable pair with values in $\N_0$
