		\mathbb{E}_{0, 0}\left[ \sum_{i \in \mathrm{JRLC}(n)} \left(\frac{\tilde{\mu}^{(1)}_{i}}{n^{1/2}} \wedge 1\right) \left(\frac{\tilde{\mu}^{(2)}_{i}}{n^{1/2}} \wedge 1\right) \right]\le C n^{-1/2 + \varepsilon}.
	\end{equation*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:51:00.242172+00:00","domain":"probability theory","id":"claim_b5126f214ecefe1a94d14c1ee2a65979d7cce1f32128b3a8a0cc5bbab9cb353e","kind":"theorem","schema_version":1,"statement":"[Prop max_action of arXiv:2604.23751, 'Large deviation principles for pattern-avoiding permutations, and limit shapes for constra'] For any $\beta\in \mathbb R$, the action $A_{\beta}$ has a unique minimizer $(\pi_1^{(\beta)}, \pi_2^{(\beta)})$ in $\mathcal{D}$. For $\beta \leq 0$, we have $\pi_1^{(\beta)}=\pi_2^{(\beta)}=\frac{1}{2}\Leb_{[0,1]}$. 
    For $\beta>0$, the densities of $\pi_1^{(\beta)}$ and $\pi_2^{(\beta)}$ on $[0,1]$ are given by
	\begin{equation}
	    \rho_1^{(\beta)}(x) := \frac{1}{1+\exp\left(\beta(\frac12-x) \right)}, 
        \quad \rho_2^{(\beta)}(x) := \frac{1}{1+\exp\left(\beta(x-\frac12) \right)}.
	\end{equation}
	In particular, both $\pi_1^{(\beta)}$ and $\pi_2^{(\beta)}$ have total mass $\frac{1}{2}$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T08:06:07.090782+00:00","domain":"probability theory","id":"claim_b5195af761284d237979ca936f6eb5d4fa4570a9b2d92ebaeb75db7e7c0d3dc2","kind":"theorem","schema_version":1,"statement":"[Prop 29 of arXiv:2608.28148, 'Flows and homotopies of Banach Lie algebroids'] Let $\mathcal{X}$ be  a vector field on $E_{U}$.  The following properties are equivalent:
\begin{enumerate}
\item[{\rm (i)}] There exists a vector field $X$ on $U$ such that  $(\mathcal{X},X)$ is a linear  local vector field on $E$.
\item[{\rm (ii)}]  When we consider $\mathcal{X}$ as a map from $\mathcal{F}(E_{U})$ to $\mathcal{F}(E_{U})$ then $\mathcal{X}(\mathcal{F}_L(E_{U}))\subset \mathcal{F}_L(E_{U})$ and $\mathcal{X}(\mathcal{F}_\pi(E_{U}))\subset \mathcal{F}_\pi(E_{U})$.
\item[{\rm (iii)}] The local flow $\mathfrak{F}_{\mathcal{X}}^t$ of $\mathcal{X}$ is a local bundle isomorphism for $E$ over the flow $\Fl_X^t$ of  $X$.
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:13:49.973097+00:00","domain":"probability theory","id":"claim_b51d08d06c2b0dcdfd4515e15c1bd6ef8820b15457666cef34880cdd8654febe","kind":"concept","schema_version":1,"statement":"[Theorem thm:sto of arXiv:2411.07157, 'Rough differential equations in the flow approach'] For every smooth, compactly supported $\omega:\R\rightarrow\R$, $P{\geqslant1}$, $\eta>0$ and $c>0$ sufficiently small, we have
\begin{equs}
\E\big[ {\talloblong \omega\xi \talloblong}_{4}^P\big]^{1/P}\lesssim_{P} 1\quad\text{and}\quad\E\big[ {\talloblong \omega\xi \talloblong}_{4,c}^P\big]^{1/P}\lesssim_{P} 1\,,
\end{equs}
where we write $\omega\xi^\tau_{\eps,\mu}(t,s^\tau)\eqdef\omega(t)\xi^\tau_{\eps,\mu}(t,s^\tau)$ (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T02:16:53.572171+00:00","domain":"probability theory","id":"claim_b51e72587d4f021ac903278258b6b1d2103e5da760c377007b8a1af43b2673e1","kind":"concept","schema_version":1,"statement":"[Theorem thm:inv_mp_ex of arXiv:2412.04589, 'Inverting the Markovian projection for pure jump processes'] Let Assumption~(asm:2 of the paper) hold. Suppose that $\Omega$ supports a sequence of i.i.d.\ $\operatorname{Exp}(1)$ random variables $(E_k)_{k \in \mathbb{N}^*}$ and a sequence of i.i.d.\ $\nu$-distributed random variables $(J_k)_{k \in \mathbb{N}^*}$ such that $\mathcal{F}_\infty$, $(E_k)_{k \in \mathbb{N}^*}$ and $(J_k)_{k \in \mathbb{N}^*}$ are independent. Then, there exist an enlarged filtration $\mathbb{G}$ (satisfying the usual conditions) and a $\mathbb{G}$-adapted pure jump process $X$ starting from $0$ whose jump measure has $\mathbb{G}$-compensator
	\begin{equation}
		\frac{\eta_t}{\mathbb{E}[\eta_t \,|\, X_{t-}]} \lambda(t, X_{t-}) \nu(d\xi) dt.
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T11:57:07.196479+00:00","domain":"probability theory","id":"claim_b5331b8b5e2aa63a21b33f727103799f4c86f874b52f141abae002a5b8fa772e","kind":"definition","schema_version":1,"statement":"[Definition eq:SW-length of arXiv:2509.04333, 'The limiting law of the Discrete Gaussian level lines'] Fix $\varepsilon, \delta \in (0, 1)$, and $A, B$ with $B \in \ensuremath{\mathcal Y}_\delta^\blacktriangleleft(A)\setminus \{A\}$. We call $V$ an $\varepsilon$-\emph{nice} domain with respect to $A, B$ if there exists $\beta_0, v_0, \delta_0, c > 0$ such that uniformly over $\beta \geq \beta_0$ and $r \geq 1 + \varepsilon$, we have
		\begin{align}
			Z_V^{\mathsf{SW}}(A, B \mid |S| \geq r\lVertA - B\rVert_1) \leq ce^{-v_0\beta r\lVertA-B\rVert_1}Z_V^{\mathsf{SW}}(A, B)\,,\\
			Z_V^{\mathsf{SW}}(A, B \mid |\mathsf{Cpts}(S)| < 2\delta_0\lVertA-B\rVert_1) \leq ce^{-v_0\beta\lVertA-B\rVert_1}Z_V^{\mathsf{SW}}(A, B)\,.
		\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:37:51.455500+00:00","domain":"probability theory","id":"claim_b539d04e578b6d1678327456d8a5c2b1ca0240a7662c09f23499352b1cffe2c2","kind":"concept","schema_version":1,"statement":"[Thm 6 of arXiv:2604.03777, 'Equilibrium fluctuations for a multi-species particle system with long jumps'] Let $\gamma >0$ and $D_1 \neq 0$. Assume that Hypothesis \ref{hyplin} and \eqref{simp} both hold. Consider the Markov process $\{ \eta_{t}^n : t \in [0,T] \}:=\{ \eta_{t \Theta(n)} : t \in [0,T] \}$  with generator given by \eqref{genABC} with $\Theta(n)$  given by \eqref{timescale} and  suppose that it starts from the invariant state $\nu_{\rho}$. For every $n \in \mathbb{N}_+$, define $ \big( \mathcal{Z}_t^{n,+}, \; \mathcal{Z}_t^{n,-}  \big)_{0 \leq t \leq T}$ by 
\begin{equation} 
\forall t \in [0, T], \; \forall H \in \mathcal{S}(\mathbb{R}), \quad  	\mathcal{Z}_t^{n, \pm}(H):= D_1 \Bigg\{ \mathcal{Y}_t^{n, A} ( T^n_{ t v_n^{\pm} } H ) + \frac{E_A - E_B + \lambda^{\pm}}{E_A-E_C} \mathcal{Y}_t^{n, B} ( T^n_{t v_n^{\pm}} H ) \Bigg\}, 
\end{equation}
where $\lambda^{\pm}$, resp. $v_n^{\pm}$ is given by \eqref{deflambda}, resp. by \eqref{vsdif}. With respect to the Skorohod topology of $ \mcb{D} \big( [0,T], \;  \mathcal{S}'(\mathbb{R}) \times \mathcal{S}'(\mathbb{R}) \big)$, $\big\{ \big( \mathcal{Z}_t^{n,+}, \; \mathcal{Z}_t^{n,-}  \big)_{0 \leq t \leq T}: \; n \in \mathbb{N}_+ \big\}$ converges in distribution to $\big( \mathcal{Z}_t^{+}, \; \mathcal{Z}_t^{-}  \big)_{0 \leq t \leq T}$, where $(\mathcal{Z}_t^{+})_{0 \leq t \leq T}$ and $(\mathcal{Z}_t^{-})_{0 \leq t \leq T}$ are uncorrelated stationary solutions of the Ornstein-Uhlenbeck equations of the form
\begin{equation} 
\dd \mathcal{Z}^{\pm}_t = ( \mathbb{L}^{ \gamma  } + \widehat{\mathbb{L}}_{\lambda^{\pm}}^{ \gamma}) \; \mathcal{Z}_t \; \dd t  + \sqrt{2 D_3^{\pm} \; \mathcal{P}^{\gamma} } \; \dd \mathcal{W}^{\pm}_t.
\end{equation}
In the last display, $D_3^{\pm}$ is given by \eqref{deflambda}, \eqref{defD2pm}, \eqref{simp} and \eqref{defD3}. Moreover, $(\mathcal{W}_t^{+})_{0 \leq t \leq T}$ and $(\mathcal{W}_t^{-})_{0 \leq t \leq T}$ are independent $\mathcal{S}'(\mathbb{R})$-valued Brownian motions with covariances given by
\begin{equation} 
\forall G, H \in \mathcal{S}(\mathbb{R}), \; \forall 0 \leq s \leq t \leq T, \quad \mathbb{E} \big[ \mathcal{W}_t^{\pm}(G) \; \mathcal{W}_t^{\pm}(H)    \big] = s \int_{\mathbb{R}} G(u) \; H(u) \; du.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T00:45:32.074350+00:00","domain":"probability theory","id":"claim_b540088df2ae7185069c8214dbaf548531c3af7e2a2d1a30f1ffa37315cf286a","kind":"concept","schema_version":1,"statement":"[Lemma lem:h:magnetization of arXiv:2411.14111, 'Stochastic processes on preferential attachment models'] Let $\Tbold$ be a multi-type branching process with a general type-space $\Sbold$, and assume that $\Tbold$ is almost surely locally finite. Furthermore, label the nodes of $\Tbold$ using the Ulam-Harris notation. Consider a distributional functional $\h$ as a fixed point solution to the following recursion:
	\begin{equation}
		\h^{(\ell+1)}(\omega) = B + \sum\limits_{i=1}^{D_{\ell}(\omega)} \arctanh\Big( \tanh(\beta)\tanh\big( \h^{(\ell)}(\omega i) \big) \Big),
	\end{equation}
	where $\big(D_{\ell}(\omega)\big)_{\ell\geq1}$ is a sequence of $D(\omega)$, the degree of the node $\omega$ in $\Tbold$, for some $B > 0$ and for all $\omega \in \Sbold$ and $\ell \geq 0$. Then, denoting by $\magn{\omega\to}$ the root magnetisation of $\Tbold$, rooted at $\omega$ under the inverse critical temperature $\beta$ and external magnetic field $B > 0$, for all $\omega \in \Sbold$, we have
	\begin{equation}
		\h(\omega) = \magn{\omega\to},\quad \text{a.s.}
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:27:14.853503+00:00","domain":"probability theory","id":"claim_b541fcc6c9dfee3706f4f45c65188470b34aae12e2481efb7e314691af232aaf","kind":"concept","schema_version":1,"statement":"[Theorem 2 of arXiv:2608.23462, '2608.23462'] Let $p \geq 2$, $x \in \R^{d_1}$ and $y \in \R^{d_2}$. Assume that Assumptions~\ref{assu:regularity} and~\ref{assu:epsilon} hold and let $(X_t,Y_t)_{t\ge 0}$ be the unique solution of \eqref{eq:fastslow0} with initial condition $(X_0,Y_0)=(x,y)$. If the fast variable is $p$-dissipative then, for every $T > 0$, there exists a constant $C \ge 0$ such that for all $T_0 \ge 0$
\[
\E \bigg[ \sup_{t \in [T_0,T_0+T]}|X_t -\mathbf{x}_{t-T_0}(X_{T_0})|^p \bigg] \le C \eps_{T_0}^{p/2}
\]
where, for $\tilde x \in \R^{d_1}$, $(\mathbf x_t(\tilde x))_{t \ge 0}$ denotes the solution of the averaged ODE \eqref{eq:averaged0}. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T05:37:14.890860+00:00","domain":"probability theory","id":"claim_b546ad2d6764f6ac9f96c1b95fbd15fdca750afa736722e5258da928fa3eac23","kind":"concept","schema_version":1,"statement":"[Corollary 11 of arXiv:2607.11608, '2607.11608'] Let  $p$ be as in Proposition \ref{GNS_prop}. Then, $Y \in L^p(\R^d)$. Moreover,  there exists $\gamma=\gamma(d,p)>0$ such that 
\begin{align*}
	\E\Big[\|Y-Y_N\|^p_{L^{p}(\R^d)}\Big]\les_p N^{-\gamma}.
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:13:49.973551+00:00","domain":"probability theory","id":"claim_b548037bd4af1621272e8af2ac9902420d35501dfa43389a6005b85800b3b3a1","kind":"lemma","schema_version":1,"statement":"[Lemma eq:Phi2 of arXiv:2411.07157, 'Rough differential equations in the flow approach'] Let $T\in(0,1]$ be as in Proposition~(eq:prop1 of the paper). 
