{"assumptions":[],"created_at":"2026-10-27T09:52:47.249400+00:00","domain":"probability theory","id":"claim_b55be378888a79c7a49f31080061eabc6f33316ebfeb9a6485a95b79dd720f20","kind":"theorem","schema_version":1,"statement":"[Proposition 10 (Volume doubling) of arXiv:2609.01098, 'Gaussian upper bounds for averaged heat semigroups on graphs'] Let $x\in X$,   {$R_2\geq R_1\geq 4S$}, $n>2$ and $\phi\geq 1$. If for all $r\in[R_1,R_2]$ {and $u\in\cC_{c}(B_x(r))$}, we have
\begin{equation*}
\frac{m(B_x(r))^{\frac{2}{n}}}{\phi r^2}
\Vert u\Vert_{\frac{2n}{n-2}}^2
\leq \cE(u)+\frac{1}{r^2}\Vert u\Vert_2^2,
\end{equation*}
then we have
{\[
\frac{m(B_x(R))}{R^{n}}
\leq {A(n)} \Phi_x(n,r,R)\ \frac{m(B_x(r))}{r^{n}}, \quad R_1\leq r\leq R\leq R_2,
\]
}
where
{
\[
\Phi_x(n,r,R)=\left[1\vee  r^n
{\frac{m(B_x(R))}{m(B_x(R_1))R^n}}
\right]^{ 4\sqrt[n]{S/r}},\quad\mbox{and}\quad A(n)=2^{ 8n^2}\phi^{\frac{n}{2}}(1\vee S)^{4n}.
\]
}
In particular, if $R_2= 2R_1$, we obtain 
\begin{align*}
	m(B_x(R_2))
\leq {A'(n)} \Phi_x(n,R_2) m(B_x(R_2/2)),\qquad A'(n)=2^{ 9n^2}\phi^{\frac{n}{2}}(1\vee S)^{4n}
\end{align*}
where $\Phi_x(n,R_2)=\left[
{\frac{m(B_x(R_2))}{m(B_x(R_2/2))}}
\right]^{ 6\sqrt[n]{S/R_2}}\geq \Phi_x(n,R_2/2,R_2)$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:51:12.739126+00:00","domain":"probability theory","id":"claim_b56118357133bd72893edce550e5e9086f3a9eb219051fe3e5c20fb39d2dd47a","kind":"concept","schema_version":1,"statement":"[Prop 6 of arXiv:2605.02420, '\textbf{Large time behavior of critical marked Hawkes processes with heavy tailed marks an'] a) For any $m\in\N$ and $\theta_1,\ldots, \theta_m, t_1,\ldots, t_m\in (0,\infty)$ we have
\begin{equation}
 E\exp\left\{-\sum_{k=1}^m\theta_k Y_{T}(t_k)\right\}=\exp\left\{-\mu\int_0^\infty g_T(t)dt\right\},

\end{equation}
where
\begin{equation}
  g_{T}(t):=1-Ee^{-\<N^t, f_T\>},

 \end{equation}
 with $f_T$ given by \eqref{e:f_sum} and \eqref{e:fT} and recalling that $N^t$ denotes the empirical measure of a branching particle system starting from a single particle at point $t$ (with no immigration). Moreover, the function $g_T$ satisfies
\begin{align}
  g_{ T}(t)=&1-e^{-f_T(t)}
G\left(1-\int_0^\infty g_{T}(t+s)\varphi(s)ds\right)
 \\
 =& 1-e^{-f_T(t)}+e^{-f_T(t)}\int_0^\infty g_T(t+s)\varphi (s)ds -e^{-f_T(t)}H \left(\int_0^\infty g_T(t+s)\varphi(s) ds\right)
 .
\end{align}
b) Let the function $h_T$ be given by
\begin{equation}h_T(t):=E\<N^t,f_T\>

\end{equation}
Then $h_T$ 
satisfies the equation
\begin{equation}

 h_{T} (t) =  f_T(t)+\int_0^\infty  h_{T}(t+s)\varphi (s)ds.
\end{equation}
Moreover, $h_T$ may be expressed explicitly as
\begin{equation}
 h_T(t)=f_T(t)+\int_0^\infty f_T(t+s) R(s)ds,

\end{equation}
where $R$ is the resolvent defined in \eqref{e:R}.\\
c) The functions $g_T$ and $h_T$ satisfy
\begin{equation}
 0\le g_T(t)\le h_T(t)\qquad t\ge 0.

\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:37:51.456292+00:00","domain":"probability theory","id":"claim_b56b58b5dbc35d337f410f3ef22826797b0d58016a42cdad60758169a94ef453","kind":"lemma","schema_version":1,"statement":"[Lem 15 of arXiv:2604.03777, 'Equilibrium fluctuations for a multi-species particle system with long jumps'] Assume Hypothesis \ref{hyplin}. Then, there exist some $\delta_1 \in (0, \;1]$ and some function $g: \mathbb{N} \mapsto \mathbb{R}$ satisfying $\lim_{n \rightarrow \infty} g(n)=0$, such that
	\begin{align} 
\forall \alpha,\beta \in S, \; \forall n \in \mathbb{N}_+, \; \forall	0 \leq s \leq t \leq T, \quad	\mathbb{E}_{\nu_{\rho}} \big[ \big\{ \mcb{B}_t^{n, \alpha , \beta}(H) - \mcb{B}_s^{n, \alpha , \beta}(H) \big\}^{2} \big] \leq  C (t-s)^{1 + \delta_1} g(n). 
	\end{align}
	In the last line, $C$ is some constant independent of $n$, $s$ and $t$.

	In particular, the sequence of stochastic processes $\big\{ \big( \mcb{B}_t^{n}(H) \; \big)_{0 \leq t \leq T}, \; n \in \mathbb{N}_+ \big\}$ is tight with respect to the uniform topology of $\mathcal{C} \big( [0, T], \mathbb{R} \big)$, due to the Kolmogorov-Centsov Theorem. Moreover, any of its limit points is identically equal to zero.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:09:59.304101+00:00","domain":"probability theory","id":"claim_b57360140013341c6c30908f245f0098d865545930214b4ccf75c1b4725d0eba","kind":"theorem","schema_version":1,"statement":"[Proposition bdry_cov of arXiv:2608.07236, 'Negative association of Busemann functions \\in exponential last-passage percolation'] For any coordinate-wise monotone functions $f$ and $g$ that are monotone in the same direction (that is, either both are increasing or both are decreasing),
it holds that 
\begin{align} 
\textup{$\mathbb{C}$ov}\Big(f\big(G(\mathcal{B})\big), g\big( (G(\mathcal{R}^j_i))_{i,j=1}^{2k} ,(G(\mathcal{G}^j_i))_{i,j=1}^{2k}\big) \Big) \leq 0.
\end{align}
In addition, if we restrict the range of the index $j$, then we have
\begin{align} 
\textup{$\mathbb{C}$ov}\Big(f\big(G(\mathcal{B})\big), g\big( (G(\mathcal{G}^j_i))_{i=1,\dots,2k}^{j=1,\dots,k} , (G(\mathcal{R}^j_i))_{i=1,\dots,2k}^{j=k,\dots,2k} \big) \Big) = 0.
\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T09:43:00.038537+00:00","domain":"probability theory","id":"claim_b576370e114414524caa73939a27b9c0bdf747b104df816801c06c6dcec571df","kind":"concept","schema_version":1,"statement":"[Theorem 1 ($L_p$ Brunn-Minkowski inequality) of arXiv:2609.00743, '$L_p$ Brunn-Minkowski inequality for the eigenvalue of generalized Monge-Ampère equation'] Suppose $k\ge 0$. Let $\Omega_0$ and $\Omega_1$ be bounded, smooth and strictly convex domains containing the origin as an interior point, and $\Omega_\alpha:=(1-\alpha)\Omega_0+_p \alpha\Omega_1$ be the $L_p$-Minkowski addition of $\Omega_0$ and $\Omega_1$, where $p:=k+1\ge 1$ and $\alpha\in[0,1]$. Then
\begin{equation}
    \lambda(\Omega_\alpha)^{-\frac{p}{2n}}\ge (1-\alpha)\lambda(\Omega_0)^{-\frac{p}{2n}}+\alpha\lambda(\Omega_1)^{-\frac{p}{2n}}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:57:07.298606+00:00","domain":"probability theory","id":"claim_b5844465343b476ba70191831a2b61ad375a99cb5057ceb18a9ba656cf03deb6","kind":"concept","schema_version":1,"statement":"[Proposition 3 of arXiv:2606.23383, 'Near-Lipschitz stability of the Kim--Milman flow map'] Assume that $\mu$ satisfies \eqref{theta}. Then, for all $t \ge 0$, $\mathsf T^{\mu}_{t\gets}$ exists and is Lipschitz continuous with constant at most 
\begin{align}
    L_t(\mu) \deq \exp(\textstyle \int_t^\infty \theta_s \dd s)\,.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T17:11:02.381294+00:00","domain":"probability theory","id":"claim_b592d37f3705a85ef422dba8f6dc0c286ba6faef4e75b395733ed99160e1dac3","kind":"concept","schema_version":1,"statement":"[Proposition prop:global_hajek of arXiv:2507.10531, 'Quantitative central limit theorems for exponential random graphs'] As in (equation eq:hatngdef of the paper), let us write
\begin{equation}
    \widehat{\mathsf{N}}_G(x) = \mathsf{N}_G(x) - 2 \mathsf{e} p^{\mathsf{e}-1} n^{\mathsf{v}-2} \mathsf{E}(x).
\end{equation}
Then, for all $\zeta \in (0,1)$, there is some $c > 0$ such that
\begin{equation}
    \mathbb{P}\mleft[\mleft|\widehat{\mathsf{N}}_G(X) - \mathbb{E}\mleft[\widehat{\mathsf{N}}_G(X)\mright]\mright| > n^{\mathsf{v}-1.5+\zeta}\mright] \leq \exp\mleft(-cn^\zeta\mright).
\end{equation}
In particular, for all $\xi > 0$ we have
\begin{equation}
    \operatorname{Var}\mleft[\widehat{\mathsf{N}}_G(X)\mright] \lesssim n^{2\mathsf{v}-3+\xi}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:54:12.532036+00:00","domain":"probability theory","id":"claim_b5aeb6f753a33d5f0bf13bcd16a42a9a71ffe69b9fda9eac0cb036bface5c36c","kind":"definition","schema_version":1,"statement":"[Definition D:horizon-topology of arXiv:2604.10020, 'The directed landscape in half-space'] Let $L$ be an interval in $\mathbb{R}$ and let $J \in \{\mathbb{R}, \mathbb{Z}\}$, and fix a distinguished point $\gamma_0 \in L$. Define $\mathcal{D}(L, J, \gamma_0)$ to be the set of functions $F:L \times J \to \mathbb{R}$, such that (denoting $F_\gamma(j)=F(\gamma,j)$)
\begin{itemize}[nosep]
    \item $F_{\gamma_0}$ is continuous if $J = \mathbb{R}$;
    \item $F_\gamma(0) = 0$ for all $\gamma$;
    \item there is a $\sigma$-finite measure $\mu_F$ on $L \times J$ such that for any $\gamma_1<\gamma_2\in L$ and $j_1<j_2\in J$, we have
    \begin{equation}

        \mu_F((\gamma_1, \gamma_2] \times ((j_1, j_2]\cap J)) = F(\gamma_1, j_1) + F(\gamma_2, j_2) - F(\gamma_1, j_2) - F(\gamma_2, j_1). 
    \end{equation}
\end{itemize}
We say that $F^n \to F$ in $\mathcal{D}(L, J, \gamma_0)$ if $F^n_{\gamma_0} \to F_{\gamma_0}$ in the uniform-on-compact topology, and $\mu_{F^n} \to \mu_F$ vaguely. This turns $\mathcal{D}(L, J, \gamma_0)$ into a Polish space.","status":"unverified"}

