{"assumptions":[],"created_at":"2026-10-27T13:01:22.581396+00:00","domain":"probability theory","id":"claim_b6ef8e1733ce8793a503e408d4e44cfd9266b687b0adfc963cfb6ecb6d4d4e59","kind":"lemma","schema_version":1,"statement":"[Lemma Xn T estimates of arXiv:2605.16963, 'Stochastic Euler Equations with Pseudo-differential Noise: Continuous and Discontinuous Pe'] Let the conditions in Proposition (Proposition-(q u) of the paper) hold and let $\theta\in\left(\frac{d}{2}+p,{s-\max \{3\zeta,1\}}\right)$. Then ${\mathbb P}\text{-}{\rm a.s.}$ the following properties hold:
		\begin{enumerate}[label={\bf (\arabic*)},leftmargin=0.79cm]\setlength\itemsep{0.2em}
			\item  There is a function $\widehat K: [0,\infty)\times [0,\infty)\to (0,\infty)$, increasing in both variables, such that  for any $R\ge1$ and $T>0$,
			\begin{align}
				\sup_{n\ge1}\mathbb E\Big[\sup_{t\in[0,T]}\|X_n^{(R)}(t)\|^2_{\mathbb H^s}\Big|\mathcal F_0\Big] 
				\leq \widehat K(T,2R+\|\Xi\|_{{\mathbb W}^{p,\infty}})(1+\|\Xi\|_{\mathbb H^s}^2). 
			\end{align} 
			\item   Let
			$$\tau_N^{n,m}(R) \triangleq  N\land \inf\big\{t\ge 0: \|X_n^{(R)}(t)\|_{\mathbb H^s}\lor\|X_m^{(R)}(t)\|_{\mathbb H^s}\ge N\big\},\quad n,m\ge 1, \ N\ge1.$$
			Then 
			\begin{equation} 
				\lim_{n\rightarrow\infty}\sup_{m\ge n}
				\mathbb E\left[\sup_{t\in[0,\tau_N^{n,m}(R)]} \|X_n^{(R)}(t)-X_m^{(R)}(t)\|^2_{\mathbb H^\theta}\bigg|\mathcal F_0\right]=0,\quad N>0.
			\end{equation}

			\item  There exists an $\mathcal{F}_t$-progressively measurable $\mathbb H^s$-valued process $X^{(R)}=(X^{(R)}(t))_{t\ge 0}$ satisfying 
			\begin{equation}
				\mathbb E\Big[\sup_{t\in [0,T]} \|X^{(R)}(t)\|_{\mathbb H^s}^2\Big|\mathcal F_0\Big]\le \widehat K(T,2R+\|\Xi\|_{{\mathbb W}^{p,\infty}})(1+\|\Xi\|^2_{\mathbb H^s}),\quad T>0,
			\end{equation} 
			such that for some subsequence of $\{X_n^{(R)}\}_{n\ge1}$ $($still denoted by $\{X_n^{(R)}\}_{n\ge1}$ for simplicity$)$ and for all $s'\in[\theta,s)$,
			\begin{equation}
				\lim_{n\to\infty}\sup_{t\in[0,T]}\|X_n^{(R)}(t)-X^{(R)}(t)\|_{\mathbb H^{s'}}=0\quad \text{and}\quad  X_n^{(R)}\xrightarrow[]{n\to \infty}X^{(R)} \  {\rm in}\ D([0,T];\mathbb H^{s'}),\quad T>0
				\quad {\mathbb P}\text{-}{\rm a.s.}
			\end{equation}

		\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:01:39.420991+00:00","domain":"probability theory","id":"claim_b71f1bcdad639713c63560c0ad87453998996d58f631d1781a7f5ffd66e7e58c","kind":"definition","schema_version":1,"statement":"[Definition of arXiv:2607.22156, 'A random matrix approach to lamplighter groups'] The \emph{traffic distribution} of a family $\mathbf{A}_{N}$ of random matrices is the map
        \begin{equation}
            \Phi_{\mathbf{A}_{N}}:g\in\mathbb{C}\mathcal{G}\langle\mathbf{x},\mathbf{x^*}\rangle\rightarrow\mathbb{E}\left[\frac{1}{N}\tr\left(g(\mathbf{A}_{N})\right)\right].
        \end{equation}
        We say that the family $\mathbf{A}_{N}$ \emph{converges in traffic distribution} if $\Phi_{\mathbf{A}_{N}}$ converges point-wise.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:52:32.331557+00:00","domain":"probability theory","id":"claim_b72292b91783bbc8f9290e3eb3a8f1c3b5cdaa7f7ffa1fa9db0988b9e7084514","kind":"definition","schema_version":1,"statement":"[Definition of arXiv:2609.03959, 'The combinatorial Hopf algebra of signed graphs'] Given a signed graph $\Sigma = (V,E,\sigma)$, define the \textit{chromatic (unsigned) symmetric function of $\Sigma$} as
