{"assumptions":[],"created_at":"2026-10-27T20:29:14.933138+00:00","domain":"probability theory","id":"claim_b8c5417525f3a8cd7bc42726f8817e12a47afa262df9d202385dcd4b70904f10","kind":"concept","schema_version":1,"statement":"[Lemma lem.TransitionGreen of arXiv:2606.13442, 'Scaling limit of additive functionals for reversible non-gradient exclusion process: criti'] The following estimates hold for the transition kernel $\overline{p}_t(\{0,1\},Y)$ and the Green function $\overline{g}_\lambda(Y)$:
		\begin{enumerate}
			\item [LandimGaussian] There exist finite positive constants $C_1,C_2,C_3$ such that for every $t>C_1$ and every $x<y$, the following estimate holds:
			\begin{equation*}
				\overline{p}_t(\{0,1\},\{x,y\})\leqslant \frac{2C_1}{1+t}\left(\exp\left(-\frac{\left\Vert{(x,y)}\right\Vert_{2}^2}{C_2t}\right)+\exp\left(-\frac{\left\Vert{(x,y)}\right\Vert_2}{C_2\log t}\right)\1_{\left\Vert{(x,y)}\right\Vert_2\geqslant \frac{C_3et}{\log t}}\right),
			\end{equation*}
			where the norm $\left\Vert{(x,y)}\right\Vert_2$ is defined as $\left\Vert{(x,y)}\right\Vert_2^2:=x^2+(y-1)^2.$
			\item [CarinciExact]
			The Laplace transform of the transition kernel for every $x<y$ is given by:
			\begin{equation*}
				\overline{g}_\lambda(\{x,y\})\\
				=\frac{1}{8\pi^2\mathbf{D}(\rho)}\int_{\pi}^{\pi}\int_{-\pi}^{\pi}\frac{e^{i(k_1 x+k_2(y-1))}+{\mathsf{A}}(\frac{k_1+k_2}{2},\lambda)e^{i(k_1 y+k_2(x-1))}}{2+\lambda-(\cos k_1+\cos k_2)}\, {\mathrm{d}} k_1\, {\mathrm{d}} k_2,
			\end{equation*}
			where the function ${\mathsf{A}}(k,\lambda)$ is defined as:
			\begin{equation*}
				{\mathsf{A}}(k,\lambda):=2\frac{\cos k\cdot(\xi_{\lambda,k}^{-2}-1)}{\cos k\cdot(\xi_{\lambda,k}^{-2}-1)-2(x_{\lambda,k}-\cos k)}-1,
			\end{equation*}
			with
			\begin{equation*}
				\xi_{\lambda,k}=x_{\lambda,k}-\sqrt{x_{\lambda,k}^2-1},\qquad x_{\lambda,k}=\frac{1}{\cos k}\left(1+\frac{\lambda}{2}\right).
			\end{equation*} 
		\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:31:14.256031+00:00","domain":"probability theory","id":"claim_b8c6ed29af8cd7abdcf4b830f8d10db8ab10fe023112a265c332881c53d69bdc","kind":"concept","schema_version":1,"statement":"[Lem c1 of arXiv:2606.16237, 'The Backward Stochastic Partial Differential Integral Equations: Solvability and Compariso'] Assume that $v,m,v^{*}$ are three processes defined on $\Omega\times[0,T]$ and valued in $V,H,V^{*}$, respectively. For any $\eta\in V$, $v(t), m(t), \langle\eta, v^{*}(t)\rangle$ are $\mathscr{F}_{t}$-measurable for a.e. $t\in[0,T]$, and $m$ is a strongly c\`{a}dl\`{a}g local martingale. If $\varphi\in L_{\mathscr{F}_{T}}^{2}(\Omega;H)$ and for any $\eta\in V$, $(\omega,t)\in\Omega\times[0,T]$, it holds that
\begin{eqnarray*}
    ( \eta,v(t))_H = ( \eta,\varphi)_H
    + \int_{t}^{T} \langle \eta,v^{*}(s) \rangle ds
    + ( \eta, m(T)-m(t) )_H,
\end{eqnarray*}
then there exists a full-measure set $\Omega'\subset \Omega$ and a process $h$ valued in $H$ such that\\
(i) $h(t)$ is $\mathscr{F}_{t}$-measurable for any $t\in[0,T]$ and strongly c\`{a}dl\`{a}g for any $\omega\in\Omega$;\\
(ii) $h(t)=v(t)$ in the space $H$ for a.s. $\omega\in\Omega$ and a.e. $t\in[0,T]$, and $h(T)=\varphi$ for any $\omega\in\Omega'$;\\
(iii) for any $\omega\in \Omega'$ and $t\in[0,T]$,
\begin{eqnarray*}
    \|h(t)\|_{H}^{2} = \|\varphi\|_{H}^{2} + 2\int_{t}^{T}\langle v^{*}(s), v(s)\rangle ds + 2 \int_{t}^{T}( h(s-), d m(s)) - [m ]_{T} + [m]_{t},
\end{eqnarray*}
where $[m]$ denotes the quadratic variation of the $H$-valued martingale. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:25:40.259673+00:00","domain":"probability theory","id":"claim_b8cc32a161c69ca250c6b4115768d0198ecae2c521173324a570e194b4fda9b0","kind":"theorem","schema_version":1,"statement":"[Proposition lem:rho-closed of arXiv:2609.02544, 'A finiteness theorem for geodesic Leech wheels'] Let $w\ge10$ and set
