{"assumptions":[],"created_at":"2026-10-27T15:07:17.278445+00:00","domain":"probability theory","id":"claim_bf943c26fcd11dea6bca7473d990d3a337588f9b901b99146539ed24dc329415","kind":"concept","schema_version":1,"statement":"[Theorem eq:resslim of arXiv:2603.21634, 'Individual-based stochastic model with unbounded growth, birth and death rates: a tightnes'] First, we assume that
\begin{itemize}
\item[$\mathbf{(H0)}$] $\forall x>0, \quad g(x,0) < 0 < g(x,R_{\max})$,
\item [$\mathbf{(H1)}$] $\forall x >0, \displaystyle{\int_{0}^{x} \dfrac{d(t)}{g(t,0)} \mathrm{d}t} = - \infty$.
\end{itemize}
Then, we assume that there exists a weight function $\omega$ such that
\begin{itemize}
\item[$\mathbf{(H2)}$]
$\omega \in \mathcal{C}^{1}(\mathbb{R}^{*}_{+})$ is positive, non-decreasing, Lipschitz continuous on $(1,+\infty)$, and
\begin{itemize}
\item[$\mathbf{(a)}$] $\exists c_{g}>0, \forall x>0, \quad  \sup_{R \in [0,R_{\max}]} |g(x,R)| \leq c_{g}\omega(x)$,
\item[$\mathbf{(b)}$] $\exists c_{b}>0, \forall x>1, \quad b(x) \leq c_{b}\omega(x)$,
\item[$\mathbf{(c)}$] $\exists c_{d}>0, \forall x>0, \quad d(x) \omega(x) \leq c_{d}$.
\end{itemize} 
\end{itemize}
Finally, we assume that the sequence $\left(\left(\mu^{K}_{t},R^{K}_{t}\right)_{t \geq 0}\right)_{K \in \mathbb{N}^{*}}$ of renormalized processes (formally defined in Section (subsec:construcdeux of the paper)) is such that
\begin{itemize}
    \item[$\mathbf{(H3)}$] there exists a random variable $\mu_{0}^{*} \in \mathcal{M}_{\omega}(\mathbb{R}^{*}_{+})$ such that $(\mu_{0}^{K})_{K \in \mathbb{N}^{*}}$ converges in law towards $\mu_{0}^{*}$ in $(\mathcal{M}_{\omega}(\mathbb{R}^{*}_{+}),\mathrm{w})$,
    \item[$\mathbf{(H4)}$] there exists $p>1$ such that 
    \begin{align*}
    \underset{K \in \mathbb{N}^{*}}{\mathrm{sup}} \hspace{0.1 cm} \mathbb{E}\left(\left\langle \mu^{K}_{0}, 1 + \mathrm{Id} + \omega \right\rangle^{p}\right) < + \infty.
    \end{align*}
\end{itemize} 
Under $\mathbf{(H0)}$, $\mathbf{(H1)}$, $\mathbf{(H2)}$, $\mathbf{(H3)}$, $\mathbf{(H4)}$, for all $T \geq 0$, the sequence $\bigg(\left(\mu^{K}_{t},R^{K}_{t}\right)_{t \in [0,T]}\bigg)_{K \in \mathbb{N}^{*}}$ is tight in the Skorokhod space $\mathbb{D}([0,T], (\mathcal{M}_{\omega}(\mathbb{R}^{*}_{+}),\mathrm{w}) \times [0,R_{\max}])$. Any of its accumulation point $(\mu^{*}_{t},R^{*}_{t})_{t \in [0,T]}$ is a continuous process and verifies almost surely, for all $t \in [0,T]$,
\begin{align}
    R^{*}_{t} =  R^{*}_{0} + \displaystyle{\int_{0}^{t}\rho(R^{*}_{s},\mu^{*}_{s})\mathrm{d}s},

\end{align}
     and for every $\varphi :(t,x) \mapsto \varphi(t,x) =: \varphi_{t}(x)$ smooth enough and dominated by $\omega$,
     \begin{multline}
       \langle \mu^{*}_{t}, \varphi_{t} \rangle =  \langle \mu^{*}_{0}, \varphi_{0} \rangle + \displaystyle{\int_{0}^{t} \int_{\mathbb{R}^{*}_{+}} \bigg( \partial_{1}\varphi(s,x) + g(x,R^{*}_{s})\partial_{2}\varphi(s,x) }   \\
     + b(x)(\varphi_{s}(x_{0}) + \varphi_{s}(x-x_{0}) - \varphi_{s}(x)) - d(x)\varphi_{s}(x) \bigg) \mu^{*}_{s}(\mathrm{d}x) \mathrm{d}s,

     \end{multline}
     where $\partial_{1}$, respectively $\partial_{2}$, are the partial derivatives with respect to the first, respectively second, variable. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:23:03.033279+00:00","domain":"probability theory","id":"claim_bfa79862e666fcec8ddd616ff596016a99db1517ba8b96434b3c9aa0d0b2b4eb","kind":"theorem","schema_version":1,"statement":"[Proposition 7 (Fixed-time regularity of functionals of the decoupled flow) of arXiv:2605.03057, 'Uniform-in-time quantitative fluctuations of large scale interacting particle systems'] Let Assumption \ref{ass:flow-smothness} hold. Let $ \varphi \in C_b^7\left( \R^d \right) $.
For $ t \ge 0 $, $ x \in \R^d $, and $ \mu \in \Ptwo $, let $ X_t^{x,\mu} $ be the decoupled flow
associated with the McKean--Vlasov equation, and define
\begin{equation*}
u_t\left( x,\mu \right) = \E\left( \varphi\left( X_t^{x,\mu} \right) \right).
\end{equation*}
Then, for every fixed $ t \ge 0 $, all multi-indices $ \gamma $ and $ \beta $, and
  every integer $ n \ge 0 $ with $1 \le \abs{\gamma} + \abs{\beta} + n
  \le 7$, the mixed derivative
\begin{equation*}
\partial_x^\gamma \partial_v^\beta \partial_\mu^n
u_t\left( x,\mu \right)\left( v_1,\dots,v_n \right)
\end{equation*}
exists and is continuous in $\left( x,\mu,v_1,\dots,v_n \right)$. More precisely, every such derivative is a finite sum of terms of the form
\begin{equation}

\E\left(
\nabla^r \varphi\left( X_t^{x,\mu} \right)
\left[
\partial_x^{\gamma_1} \partial_v^{\beta_1}\partial_\mu^{n_1}
X_t^{x,\mu}\left( \mathbf{v}_1 \right),\dots,
\partial_x^{\gamma_r} \partial_v^{\beta_r}\partial_\mu^{n_r}
X_t^{x,\mu}\left( \mathbf{v}_r \right)
\right]
\right),
\end{equation}
where $ 1 \le r \le 7 $, for each $1 \leq j \leq r$, $\mathbf{v}_j$
denotes an $n_j$-tuple of Lions directions, and each
$\partial_x^{\gamma_j} \partial_v^{\beta_j}\partial_\mu^{n_j}
X_t^{x,\mu}\left( \mathbf{v}_j \right)$
is a mixed derivative of the flow of positive total order $1 \le \abs{\gamma_j} + \abs{\beta_j} + n_j
  \le 7$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:19:47.299921+00:00","domain":"probability theory","id":"claim_bfb6a07f85c6ae395386f5a966c2befa205bff4d44267a4e3ef1d5b387c49410","kind":"theorem","schema_version":1,"statement":"[Theorem thm:CO of arXiv:2601.09976, 'Stochastic Calculus as Operator Factorization:\\ An Operator--Covariant Derivative and Uni'] Let $X$ be a square-integrable process with natural filtration $(\mathcal{F}_t^X)_{t \in [0,T]}$, energy space~$\mathcal{H}_X$, stochastic integral~$\delta_X$, predictable projection~$\Pi_X$, and operator--covariant derivative $D_X = \delta_X^*$. Assume:
\begin{enumerate}[label=\textup{(\roman*)}]
\item \textup{Centered integrals:} $\mathbb{E}[\delta_X(u)] = 0$ for all $u \in \mathcal{H}_X$.
\item \textup{Isometry on predictable processes:} $\mathbb{E}[|\delta_X(u)|^2] = \|u\|_{\mathcal{H}_X}^2$ for predictable $u \in \mathcal{H}_X$.
\item \textup{Representation property:} Every $\mathcal{F}_T^X$-measurable $\tilde{F} \in L^2(\Omega)$ with $\mathbb{E}[\tilde{F}] = 0$ can be written as $\tilde{F} = \delta_X(v)$ for some predictable $v \in \mathcal{H}_X$.
\end{enumerate}
Then for all $\mathcal{F}_T^X$-measurable $F \in L^2(\Omega)$:
\begin{equation}
F \;=\; \mathbb{E}[F] + \delta_X(\Pi_X D_X F) \;=\; \mathbb{E}[F] + \int_0^T (\Pi_X D_X F)_t\, dX_t.
\end{equation}
Equivalently, the operator identity $(\mathrm{Id} - \mathbb{E}) = \delta_X \circ \Pi_X \circ D_X$ holds on $L^2(\Omega, \mathcal{F}_T^X, P)$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T17:18:19.444183+00:00","domain":"probability theory","id":"claim_bfc5ade76c44ad58826c4f40bc97b2e5638c2abe017d57deb60c431e13ce0dbc","kind":"theorem","schema_version":1,"statement":"[Proposition cor:Pn_chebyshev of arXiv:2508.17838, '\bf Edge Universality for Inhomogeneous Random Matrices'] For every integer \(n\ge1\),   \(\mathcal P_n\) defined  in (equation def:Pn of the paper) can be expressed in terms of Chebyshev polynomials of first kind as  
\begin{equation}
\frac{1}{2\,\alpha^{n/2}}\,\mathcal P_n(x)
\;=\;
T_n\!\Bigl(\frac{x - (1+\alpha)}{2\sqrt{\alpha}}\Bigr)
\;-\;
\int T_n\!\Bigl(\frac{t - (1+\alpha)}{2\sqrt{\alpha}}\Bigr)\,d\mu_{\mathrm{MP},\alpha}(t).
\end{equation}
Moreover, it can also  explicitly be    given by  Chebyshev polynomials of second  kind 
\begin{equation}
 U_n\!\bigl(\tfrac{x-(1+\alpha)}{2\sqrt\alpha}\bigr)
   +\sqrt\alpha\,U_{n-1}\!\bigl(\tfrac{x-(1+\alpha)}{2\sqrt\alpha}\bigr)
\;=\;
\sum_{i=0}^{n-1} \frac{1}{2}\alpha^{\lfloor \frac{i}{2}\rfloor-\frac{n}{2}}\;\mathcal P_{\,n-i}(x).
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T10:42:55.314675+00:00","domain":"probability theory","id":"claim_bfca8c93794d618fe79cebea0215cd19b62630eb00f8d490a690f79536a46c5c","kind":"lemma","schema_version":1,"statement":"[Lem 16 of arXiv:2609.02398, '\textbf{Convex Order Comparisons for Sub-Gamma Random Variables}'] For all $p \in (0, 1/2]$,
