{"assumptions":[],"created_at":"2026-10-27T14:24:20.989744+00:00","domain":"probability theory","id":"claim_c4b1fbe38789a55a92a1e8c8fbe8c35c5c45508bb9fceafe473fd18bd2c89e86","kind":"concept","schema_version":1,"statement":"[Theorem thm:main of arXiv:2509.02074, 'On the Kolmogorov-Feller weak law of large numbers for the Fr\'{e}chet mean on non-compact'] Suppose that Condition (C) holds. If either of the following conditions is satisfied, then $\mu_{n} \overset{\mathbb{P}}{\to} \mu$ as $n$ tends to infinity.
\begin{enumerate}
  \item[(i)] For some $\mu_0 \in M$, it holds that $\sum_{i=1}^{n} \mathbb{P}(d(X_i, \mu_0) > n) \underset{n \to \infty}{\to} 0$ and $n^{-2}\sum_{i=1}^{n}\mathbb{E}[d^2\{\overline{X_{n,i}}(\mu_0), \mu_0\}] \underset{n \to \infty}{\to} 0$;

  \item[(ii)] The $X_i$'s are identically distributed and for some $\mu_0 \in M$, $n\mathbb{P}(d(X_1, \mu_0) > n) \underset{n \to \infty}{\to} 0$.
