{"assumptions":[],"created_at":"2026-10-27T07:14:37.625192+00:00","domain":"probability theory","id":"claim_cabf169105e3db669774077c2ba2d9f8b5335f6ea71ab6effc06b6fd6d91878d","kind":"theorem","schema_version":1,"statement":"[Proposition 32 of arXiv:2608.19065, 'Boundedly exchangeable graphs'] Write
