\mathbb {E}\left[T_{N,d}\right]=&\frac{H_N}{A_N}+\frac{B_N}{A_N^2}\nonumber \\
\sim& \frac{N}{d}\log N+\frac{\gamma}{d}N
+\sum_{m=0}^{\infty}\bigl(\lambda_m(d)\log N+\nu_m(d)\bigr)N^{-m},\quad N\rightarrow \infty,

\end{align}
where the coefficients $\lambda_m(d)$ and $\nu_m(d)$ are defined in relations ((33a of the paper))-((38 of the paper)). (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

