{"assumptions":[],"created_at":"2026-10-28T00:55:42.214977+00:00","domain":"probability theory","id":"claim_d619609525d461f36ea1038b083415e2371ba7cc713802a0c86de67496faa353","kind":"concept","schema_version":1,"statement":"[Theorem theo:pdeprobrep of arXiv:2411.16366, 'Connections between sequential Bayesian inference and evolutionary dynamics'] \textbf{Forward representation formula} (Theorem 3.1 in [kunita_stochastic_1982].) Let $u_t(x, \omega)$ for $t \in [0, T]$, $x \in \mathbb{R}^d$ denote a measurable stochastic process on a probability space $(\Omega, \mathcal{F}, \mathbb{P})$ with $\omega \in \Omega$ (from now on we suppress the $\omega$ notation).  Suppose its time evolution is given by 
\begin{align}

\partial_t u_t(x) = \mathcal{L}u_t(x) + \sum_{k=1}^n \mathcal{M}^k u_t(x) \circ dB_t^k, \quad u_0(x) = f(x)
\end{align}
where $B_t^k$ is a Brownian motion wrt $\mathbb{P}$ and $f$ a bounded $C^2$ function with bounded derivatives and 
\begin{align*}
\mathcal{L} &:= \frac{1}{2} \sum_{j=1}^m \left( \sum_{i=1}^m a^{ij}(x) \frac{\partial }{\partial x^i} \right)^2 + \sum_{i=1}^m b^{i}(x) \frac{\partial }{\partial x^i} + c^0 \\
& = \frac{1}{2} \sum_{i=1}^m \sum_{j=1}^m \left( \sum_k a^{ik}a^{jk} \right)  \frac{\partial^2}{\partial x^i \partial x^j} + \frac{1}{2} \sum_{i,j} a^{ij} \sum_k \left( \frac{\partial a^{kj} }{\partial x^i}\right) \frac{\partial}{\partial x^k} + \sum_{i=1}^m b^{i}(x) \frac{\partial }{\partial x^i} + c^0 \\
\mathcal{M}^k &:= \sum_{i=1}^m l^{ik}(x) \frac{\partial }{\partial x^i} + c^k
\end{align*}
with $c^k(x)$ being uniformly bounded $C^2$ functions with bounded derivatives in $x$ and $a^{ij}(x), b^i(x), m^{ik}(x)$ being uniformly bounded $C^4$ functions with bounded first derivatives in $x$.\\  
\\
Then there exists another probability space $(\tilde{\Omega}, \mathcal{B}, \mathbb{Q})$ on which the Brownian motion $W_t = [W_t^1,\dots, W_t^m]^\top$ is defined and an SDE on the product space $(\Omega \otimes \tilde{\Omega}, \mathcal{F} \otimes \mathcal{B}, \mathbb{P} \otimes \mathbb{Q})$ given by 
\begin{align}

d \xi_t(x) =  \sum_{i=1}^d b^{i}(\xi_t(x))  dt + \sum_{j=1}^m   \sum_{i=1}^m a^{ij}(\xi_t(x))  \circ dW_t^j + \sum_{k=1}^n  \sum_{i=1}^m l^{ik}(\xi_t(x)) \frac{\partial \xi_t(x)}{\partial x^i}  \circ dB_t^k 
\end{align}
where the notation $\xi_t(x)$ is used to denote the solution of the SDE with initial condition $\xi_0 = x$ and $t > 0$. The solution of (equation eq:parapde2 of the paper) has the representation 
\begin{align*}
u_t(x) = \mathbb{E}^{\mathbb{Q}} \left[ f(\xi_t(x)) \exp \left( \sum_{k=1}^n \int_0^t c^k(\xi_s(x)) \circ dB_s^k  + \int_0^t c^0(\xi_s(x)) ds\right) \right], \quad x \in \mathbb{R}^m
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T17:18:19.444555+00:00","domain":"probability theory","id":"claim_d629f4d9d466d84a21fb3c1881c0c7cde693e5491cf0f0b7b5a5c743e4e43796","kind":"definition","schema_version":1,"statement":"[Definition ass:ft of arXiv:2508.17838, '\bf Edge Universality for Inhomogeneous Random Matrices'] There exist constants $ \alpha \in (0, 2]$, $c_0 > 0$, $\varepsilon > 0$, and $0 < \rho < 1$ such that the following assumptions are satisfied:
\begin{enumerate}
  \item (normalization) $f$ is a probabiltiy density
  \begin{equation}
    f(x)\ge 0, \quad \int_{\mathbb R^d} f(u)\,du \;=\; 1;
  \end{equation}
  \item (small-frequency control) for all $|\xi|\le \varepsilon$,
  \begin{equation}
    |\widehat f(\xi)| \;\le\; \exp\!\bigl(-c_0 |\xi|^\alpha \bigr);
  \end{equation}
  \item (high-frequency contraction) for all $|\xi| > \varepsilon$,
  \begin{equation}
    |\widehat f(\xi)| \;\le\; \rho < 1;
  \end{equation}
  \item (regularity/decay) $f$ is a continuous function and for some   constants $T, K > d$ and $C_T, C_{K} > 1$,   
  \begin{equation}
      f(x)\le \frac{C_T}{(1+|x|)^{T}},
    \qquad |\widehat f(\xi)| \;\le\; \frac{C_K}{(1+|\xi|)^{K}} 
      \qquad  x,\xi \in \mathbb R^d.
  \end{equation}
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T11:29:35.080482+00:00","domain":"probability theory","id":"claim_d6338b5985780d949f5aa372345776b09007d30016c940486a382657808c92d3","kind":"lemma","schema_version":1,"statement":"[Lemma 18 of arXiv:2609.03793, 'Typical martingale diverges on a co-$\sigma$-porous set'] Let $\f\in\M_\infty$, $m\in\N$, $u\in2^m$ and $n,k\in\N_0$ be arbitrary. Let us further denote
\begin{equation*}
M\coloneqq\bs{v\in2^{l}\cap u\appinf;l\geq m,\forall j\in[m:l]:f_j(v)\geq \f(u)-2^{-n}}
\end{equation*}
and
\begin{equation*}
s\coloneqq\sup\s{\f(v);v\in M}.
\end{equation*}
Then given any $v\in M$ such that $s-\f(v)\leq2^{-k-n}$, it holds that
\begin{equation*}
\forall w\in2^{\leq k}:s-\f(v\app w)\leq2^{-n},\quad\text{in particular}\quad v\app w\in M.
\end{equation*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:32:58.357921+00:00","domain":"probability theory","id":"claim_d6395ca58f9290592d24e8af221738287e4e5ab82d2248fd448b6ed3f538d8b0","kind":"concept","schema_version":1,"statement":"[Pron 3 of arXiv:2506.18834, '\large\bf On the random-time and finite-time ruin probability for widely dependent claim s'] $(1)$ Let $\xi_i,i\geq1$ be WLOD (or WUOD) with common distribution $V$ on $(-\infty,\infty)$. If $f_i(\cdot),i\geq1$ are nondecreasing,
then $f_i(\xi_i),i\geq1$ are still WLOD (or WUOD);
if $f_i(\cdot),i\geq1$ are nonincreasing, then $f_i(\xi_i),i\geq1$ are WUOD (or WLOD).

$(2)$ If $\xi_i,i\geq1$ are nonnegative and WUOD with common distribution $V$ and finite mean,
then for each $n\geq1$,
$$E\prod^{n}_{i=1}\xi_{i} \leq g_{U,V}(n)\prod^{n}_{i=1}E\xi_{i}.$$
Therefore, if $\xi_i,i\geq1$ are WUOD with common distribution $V$ on $(-\infty,\infty)$ satisfying $Ee^{s {\xi_i}}<\infty$
for some $s>0$, then for each $n\geq1$,
$$Ee^{s \sum^{n}_{i=1}\xi_{i}} \leq g_{U,V}(n)\prod^{n}_{i=1}Ee^{s {\xi_i}}.$$ (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T02:16:53.569352+00:00","domain":"probability theory","id":"claim_d63d4291ea8597346592def490a7da0027d5603f7c4450c801f8a773843ba018","kind":"definition","schema_version":1,"statement":"[Definition def:diff_char of arXiv:2412.04589, 'Inverting the Markovian projection for pure jump processes'] Let $X$ be an $\mathbb{R}^d$-valued It\^o semimartingale. The \emph{differential characteristics} of $X$ associated with a truncation function $h: \mathbb{R}^d \to \mathbb{R}^d$ is the triplet $(\beta, \alpha, \kappa)$ consisting in:\footnote{By truncation function, we mean that $h$ is measurable, bounded and $h(x) = x$ in a neighborhood of $0$.}
	\begin{enumerate}[label=(\roman*), nosep]
		\item $\beta$ is an $\mathbb{R}^d$-valued predictable process such that $\int_0^\cdot \beta_s \,ds$ is the predictable finite variation part of the special semimartingale $X^h \coloneqq X - \sum_{s \leq \cdot} (\Delta X_s - h(\Delta X_s))$.

		\item $\alpha$ is an $\mathbb{S}_+^d$-valued predictable process such that $\int_0^\cdot \alpha_s \,ds = \langle X^c, X^c \rangle \coloneqq (\langle X^{i, c}, X^{j, c} \rangle)_{1 \leq i, j \leq d}$, where $X^c = (X^{i, c})_{1 \leq i \leq d}$ is the continuous local martingale part of $X$.

		\item $\kappa$ is a predictable L\'evy transition kernel from $\Omega \times \mathbb{R}_+$ to $\mathbb{R}^d$ such that $\kappa_t(d\xi) dt$ is the compensator of the jump measure $\mu^X$ of $X$, where $\mu^X(dt, d\xi) \coloneqq \sum_{s > 0} \bm{1}_{\{\Delta X_s \neq 0\}} \delta_{(s, \Delta X_s)}(dt, d\xi)$ is an integer-valued random measure on $\mathbb{R}_+ \times \mathbb{R}^d$.\footnote{By L\'evy transition kernel, we mean that $\kappa_{\omega, t}(d\xi)$ is a L\'evy measure on $\mathbb{R}^d$ for each $(\omega, t) \in \Omega \times \mathbb{R}_+$, i.e.\ $\kappa_{\omega, t}(\{0\}) = 0$ and $\int_{\mathbb{R}^d} 1 \land |\xi|^2 \,\kappa_{\omega, t}(d\xi) < \infty$.}
	\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T15:12:20.559499+00:00","domain":"probability theory","id":"claim_d64b1664943796006ef345e365b04aa9f1e6dd75ba81d44da17606c576f80212","kind":"concept","schema_version":1,"statement":"[Theorem thm:discrete-binary of arXiv:2604.04882, 'On a Problem of M. Kac on Laplace Distributions'] Let $L$ be as in Lemma~(lem:discrete-L of the paper), and let $\eta\in\cB$ be indecomposable. Suppose
    $\eta_1,\eta_2\in\cB$, and set $G_j(z)\coloneqq L(\eta_j(1-z)),$ $j=1,2.$ If
    \begin{align}
        \Phi_L(G_1(z),G_2(z))=L(\eta(1-z))
    \end{align}
    for all $z\in[0,1]$, then there exist $a_1,a_2\ge 0$ with $a_1+a_2=1$ such that
    \begin{align}
        G_j(z)=L(a_j\eta(1-z)), \qquad j=1,2.
