{"assumptions":[],"created_at":"2026-10-27T10:51:11.519561+00:00","domain":"probability theory","id":"claim_d862eade45a55d99250d98ad0fe23c1257666290c10264651d2a726f3d69711b","kind":"theorem","schema_version":1,"statement":"[Theorem 12 (Signed canonical factorization) of arXiv:2609.02590, 'Directional Optimal Sub-Gamma Scales for Infinitely Divisible Laws'] For every real $t$,
\begin{equation}
 K_X(t)=\frac{Vt^2}{2}M_{R_X}(t),

\end{equation}
where both sides are interpreted by continuity at $t=0$ and extended values are
allowed away from zero. The law of $R_X$ has an atom of mass $a/V$ at zero. On
the two open half-lines it has the continuous densities
\begin{align}
 q_X(r)&=\frac{2}{V}\int_{(r,\infty)}(x-r)\,\nu(\dd x),
 &&r>0, \\
 q_X(r)&=\frac{2}{V}\int_{(-\infty,r)}(r-x)\,\nu(\dd x),
 &&r<0. 
\end{align}
The pair $(V,\Law(R_X))$ determines $a$, $\nu$, and hence the centered law of
$X$. More precisely,
\begin{equation}
 \nu=\frac{V}{2}q_X''

\end{equation}
in the sense of distributions on each open half-line.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:28:49.113228+00:00","domain":"probability theory","id":"claim_d86cedc17ad5431087784e395941b3c6c40e04464db9da299e2f8c319c87e99b","kind":"lemma","schema_version":1,"statement":"[Lemma lem:weight-removal-interface-match of arXiv:2608.16119, 'Fully nonlinear parabolic equations under a fixed reference diffusion: weighted \texorpdfs'] Put $\chi_{\rm rad}=50r^2/29$ and define
\begin{equation}
 \begin{aligned}
 \varphi_-(r)&=\sum_{n=0}^\infty a_n\chi_{\rm rad}^n,
 &a_0&=1,
 &a_n&=-\frac{3}{n!(2n-1)(2n+1)(2n+3)}\quad(n\geq1),\\
 \varphi_+(r)&=r-\frac{39}{25r}-\frac{507}{625r^3}
                 -\frac{6591}{15625r^5},
 &&& &r>0.
 \end{aligned}

\end{equation}
The two profiles solve
\begin{equation}
 \frac{29}{200}\varphi_-''
 +\left(\frac{29}{50r}-\frac r2\right)\varphi_-'
 +\frac12\varphi_-=0,
 \qquad
 \frac{13}{50}\varphi_+''
 +\left(\frac{39}{25r}-\frac r2\right)\varphi_+'
 +\frac12\varphi_+=0.

\end{equation}
There exist matching parameters
\begin{equation*}
 R_{\mathrm{int}}\in
 \left(\sqrt{\frac{29}{15}},\frac{\sqrt{203}}{10}\right),
 \qquad \mathfrak s_{\mathrm{match}}\ne0,
\end{equation*}
For these parameters, the matched profile
\begin{equation}
 \varphi_{\rm dw}(r)=
 \begin{cases}
  \varphi_-(r),&0\leq r\leq R_{\mathrm{int}},\\
  \mathfrak s_{\mathrm{match}}\varphi_+(r),&r\geq R_{\mathrm{int}}
 \end{cases}

\end{equation}
is $C^1$ and piecewise smooth.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:03:39.775977+00:00","domain":"probability theory","id":"claim_d879c976fbae9187e492cc39afbe26abb1fdfa9460b4582c26959cc56ab6a172","kind":"theorem","schema_version":1,"statement":"[Prop admissibility-vs-shift of arXiv:2411.03065, 'Growing conditioned BGW trees with\\ log-concave offspring distributions'] Let $({\mathbf{a}},{\mathbf{b}})$ be a non-degenerate weight pair.
	\begin{enumerate}
		\item If ${\mathbf{a}}=(a_0,a_1,0,0\dots)$ with $a_0,a_1>0$ then $({\mathbf{a}},{\mathbf{b}})$ is admissible.
		\item If $({\mathbf{a}}^+,{\mathbf{b}})$ is admissible and if the inequalities
		\begin{align}
		\frac{\PFComp{{\mathbf{a}}^+,{\mathbf{b}}}{n+1-m}}{\PFComp{{\mathbf{a}}^+,{\mathbf{b}}}{n-m}}
		\leq
		\frac{\PFComp{{\mathbf{a}},{\mathbf{b}}}{n+1}}{\PFComp{{\mathbf{a}},{\mathbf{b}}}{n}}
		\geq
		\frac{b_{m+1}}{b_m},
		\end{align}
		are satisfied for $m=1,\dots,n$, then $({\mathbf{a}},{\mathbf{b}})$ is admissible.
	\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T09:13:18.537464+00:00","domain":"probability theory","id":"claim_d87b44a7376a8a66d48838aafbd6cac81bacc83fab41f90a1a48717ceb9a2397","kind":"concept","schema_version":1,"statement":"[Lemma 23 (Second overshoot lemma) of arXiv:2608.30668, 'Recurrence and capacity of stable branching random walks'] We assume that there is \(\delta >  d\) such that
