{"assumptions":[],"created_at":"2026-10-27T23:13:49.899681+00:00","domain":"probability theory","id":"claim_e438a98b5169859c0dee1e7405a693efb0476e11d648f9a653a58548600feffd","kind":"theorem","schema_version":1,"statement":"[Prop weighted-graph of arXiv:2411.06861, 'Quenched invariance principle for random walks in random environments admitting a cycle de'] For any $d\geq 2, q\in [1, \infty)$, there exist constants $C_{\mathrm{WS}}, C_{\mathrm{LP}}\in (0, \infty)$ that depend at most on $d, q$ such that for any $x\in \mathbb{Z}^d$ the following holds true: 
\begin{enumerate} [(i)]
    \item (Weighted Sobolev inequality on a large scale) 
    For every function $u: \mathbb{Z}^d \to \mathbb{R}$, and every cut-off function $\eta: \mathbb{Z}^d \to [0,1]$  with $\supp{\eta} \subset B(x, n)$,   
    \begin{align*}
        \norm{(\eta u)}^2_{2\rho, B(x, n)} \leq C_{\mathrm{WS}}\frac{n^2}{\abs{B(x,n)}}\norm{\nu}_{q, B(x,n)} \sum_{\{y,y'\}\in E_d}c(y,y')\abs{\eta u(y)- \eta u(y')}^2.
    \end{align*}
    \item (Local Poincar\'{e} inequality on a large scale) For every function $u: \mathbb{Z}^d \to \mathbb{R}$
    \begin{align*}
        & \norm{u-(u)_{B(x, n)}}^2_{2\rho, B(x, n)} \\
        & \qquad  \leq C_{\mathrm{LP}}\frac{n^{2}}{\abs{B(x,n)}}\norm{\nu}_{q, B(x,n)}  \sum_{\substack{ y,y'\in B(x, n) \\ \{y, y'\}\in E_d }}c(y,y')\abs{ u(y)- u(y')}^2.
    \end{align*}
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:34:45.593655+00:00","domain":"probability theory","id":"claim_e451f79aaaa84563fb2ca6fe4a95172b1ebd59a0ffb3ac237d3a351755afae82","kind":"lemma","schema_version":1,"statement":"[Lemma lem:flags of arXiv:2609.01776, 'On the Cuspidal Cohomology of Iwahori Congruence Subgroups of $\mathrm{SL}(3, \mathbb{Z})$'] Let $\mathbb{F}_p = \mathbb{Z}/p\mathbb{Z}$.  Further, let $\overline{B}$ denote the Borel subgroup of upper triangular matrices in $\overline{G} = \mathrm{SL}(n, \mathbb{F}_p)$.  Let $V = \{v_1, \ldots, v_m\}$ and $W = \{w_1, \ldots, w_m\}$ be two saturated lists in $\mathbb{Z}^n$.  Let $V_i$ and $W_i$ denote the subspaces of $\mathbb{Q}^n$ generated by $\{v_1, \ldots, v_i\}$ and  $\{w_1, \ldots, w_i \}$ respectively. 

    Fix $i_1 < i_2 < \cdots < i_k$ from $\{1, \ldots, m\}$.  Consider the flags $F^V$ and $F^W$, which correspond to a nested sequence of subspaces
    \begin{gather*}
        0 \subsetneq V_{i_1} \subsetneq V_{i_2} \subsetneq \cdots \subsetneq V_{i_k} \subseteq \mathbb{Q}^n, \\
        0 \subsetneq W_{i_1} \subsetneq W_{i_2} \subsetneq \cdots \subsetneq W_{i_k} \subseteq \mathbb{Q}^n.
    \end{gather*}

    Let $\overline{F}^V$ and $\overline{F}^W$ denote the flags 
    \begin{gather*}
        0 \subsetneq \overline{V}_{i_1} \subsetneq \overline{V}_{i_2} \subsetneq \cdots \subsetneq \overline{V}_{i_k} \subseteq \mathbb{F}_p^n, \\
        0 \subsetneq \overline{W}_{i_1} \subsetneq \overline{W}_{i_2} \subsetneq \cdots \subsetneq  \overline{W}_{i_k} \subseteq \mathbb{F}_p^n,
    \end{gather*}
    where $\overline{V}_i = \langle \bar{v}_1, \ldots, \bar{v}_i \rangle$ and $\overline{W}_i = \langle \bar{w}_1, \ldots, \bar{w}_i \rangle$ with 
    $v_j \equiv \bar{v}_j \pmod p$ and $w_j \equiv \bar{w}_j \pmod p$.  Suppose there exists $B_0 \in \overline{B}$ that sends $\overline{F}^V$ to $\overline{F}^W$.  Then, there exists some $\mathcal{I}_0 \in \mathcal{I}(n, p)$ such that $\mathcal{I}_0 \equiv B_0 \pmod p$ and $\mathcal{I}_0$ sends $F^V$ to $F^W$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:32:19.920949+00:00","domain":"probability theory","id":"claim_e453396662df33c4483aefcf7a2e594254a4bc98f9aeb3fbf4e77da5dabee36d","kind":"concept","schema_version":1,"statement":"[Theorem 2 of arXiv:2608.02927, 'Thinning Operation via the Poisson-F\"ollmer Process'] Fix $T>0.$ Let $X$ be a random variable whose density $f : \N \rightarrow (0, \infty) $ with respect to $\pi_{T}$ is ultra log-concave, then we have
