    \bar \tau \ge n, \sigma^{(i)} > n
  \bigr)
  \le
  \exp\Bigl(
    - \frac{ q n ( 1 - e^{ - 1 / 2 } ) }{ 4 }
  \Bigr)
  .
}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:55:18.058430+00:00","domain":"probability theory","id":"claim_e7aa5c6209503c5800e2649a6fa787698068025b87d723f0eb4a7d0bb2c191a8","kind":"definition","schema_version":1,"statement":"[Definition 42 (Balanced comparison structure) of arXiv:2606.16636, 'Free energy of non-convex multi-species spin glasses with centered Ising spins'] We say that $\xi$ is \textbf{balanced} with respect to $\lambda$ if there exists a one-species covariance function $\xi_\star:\R_+\to\R$ such that, for every $r\in\R_+$,
\begin{equation}

    \xi(r\lambda)=\xi_\star(r),
\end{equation}
and, for every $a=(a_s)_{s\in\sS}\in\R_+^\sS$,
\begin{equation}

    \xi(a)\leq \sum_{s\in\sS}\lambda_s\xi_\star\left(\frac{a_s}{\lambda_s}\right).
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:25:12.187508+00:00","domain":"probability theory","id":"claim_e7b01e9b3101a61eb08a08e7dd243a453685566567a0c5c6ca6adf92b3fe1065","kind":"lemma","schema_version":1,"statement":"[Lemma 27 of arXiv:2510.20492, 'Heterochromatic two-arm probabilities for metric graph Gaussian free fields'] For any $d\ge 3$, there exist $C,c>0$ such for any $T>0$, any distinct $v_1,v_2,w_1,w_2\in \widetilde{\mathbb{Z}}^d$ with $|v_1-w_1|\land |v_2-w_2|\ge d$, and any $z\in \{v_1,v_2,w_1,w_2\}$, 
 	 	\begin{equation}
 		\begin{split}
 			\mathbb{P}\big(  \widehat{\mathcal{L}}_{1/2}^{z} \ge T  \mid \{v_1\xleftrightarrow{} w_1\Vert v_2\xleftrightarrow{} w_2 \} \big)\le Ce^{-cT}. 
 		\end{split}
