{"assumptions":[],"created_at":"2026-10-27T21:01:39.423202+00:00","domain":"probability theory","id":"claim_ea914fe12a6d2aecb4c67828041d96a3961c2305c3d10b468d431ad557b417b9","kind":"theorem","schema_version":1,"statement":"[Proposition prop:Phi1-Phi2-fg of arXiv:2607.22156, 'A random matrix approach to lamplighter groups'] Let $f,f'\in L$ and $g,g'\in\Gamma$. We have
    \begin{equation}
        \Phi^{(1)}(U_{f,g})=\tau_{G}(U_{f,g})=\1_{f=e_{L},\;g=e_{\Gamma}}.
    \end{equation}
    Moreover, if $g\neq e_{\Gamma}$ or $g'\neq e_{\Gamma}$,
    \begin{equation}
        \Phi^{(2)}(U_{f,g},U_{f',g'})=0 .
    \end{equation}
    Finally, when $g=g'=e_{\Gamma}$,
    \begin{align}
        \Phi^{(2)}(U_{f,e_{\Gamma}},U_{f',e_{\Gamma}})
        &=\1_{f\neq e_{L}}\1_{f'\neq e_{L}}
        \sum_{h\in\Gamma}
        \Phi^{(1)}\left(U_{f,h}U_{f',h^{-1}}\right)
        \\
        &=\1_{f\neq e_{L}}\1_{f'\neq e_{L}}
        \#\left\{h\in\Gamma:\
        f\cdot(f'\circ h^{-1})=e_{L}\right\}.

    \end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:21:52.422376+00:00","domain":"probability theory","id":"claim_ea970abf4f287cede49d555f066c44b82ea41e7441c24ea9b4ded9ef8efa26b9","kind":"concept","schema_version":1,"statement":"[Proposition 143 of arXiv:2601.16377, '2601.16377'] Assume $\sqrt{2\theta \kappa} < \pi$.  Let $f$ be an analytic test function and denote
\begin{equation}

\sigma(z) = \sqrt{z^2 - \beta^2}\qquad \textnormal{with}\quad \beta = \sqrt{\frac{2\theta}{\kappa}}.
\end{equation}
The random variable
\[
\sum_{i = 1}^{N} f\bigg(\frac{\ell_i}{N}\bigg) - N\int_{-\beta}^{\beta} f(x)\dd\mu(x)
\]
is approximated in the sense of moments as $N \rightarrow \infty$ by a Gaussian random variable, with mean
\begin{equation}

\textnormal{\textsf{Mean}}[f] = \frac{\theta -1}{2\theta}\left(\frac{f(-\beta) + f(\beta)}{2} - \frac{1}{\pi} \int_{-\beta}^{\beta} \frac{f(x) \dd x}{|\sigma(x)|}  - \frac{\kappa}{\pi^2}\cdot \textnormal{p.v.}\int_{-\beta}^{\beta} \int_{-\beta}^{\beta} \frac{f(x) \cdot y \cdot \textnormal{T}\big[\kappa|\sigma(y)|\big]}{(x - y)|\sigma(x)|} \dd x \dd y \right)\!,
\end{equation}
where $\textnormal{T}(u) = u\big(u\frac{\cos(u)}{\sin(u)} - 1\big)$ and p.v. is the Cauchy principal value, and with covariance
\begin{equation}
\begin{split}
\textnormal{\textsf{Cov}}[f,f] & = \oint_{\gamma} \oint_{\gamma} \frac{\dd z_1\dd z_2}{(2\ii\pi)^2} \cdot \frac{f(z_1)f(z_2)}{2\theta (z_1 - z_2)^2}\left(-1 + \frac{z_1z_2 - \beta^2}{\sigma(z_1)\sigma(z_2)}\right) \\
& = \frac{1}{4\pi^2} \int_{-\beta}^{\beta}\int_{-\beta}^{\beta} f'(x_1)f'(x_2) \log\left(\frac{\beta^2 - x_1x_2 - \sqrt{(\beta^2 - x_1^2)(\beta^2 - x_2^2)}}{\beta^2 - x_1x_2  + \sqrt{(\beta^2 - x_1^2)(\beta^2 - x_2^2)}}\right) \dd x_1 \dd x_2.
\end{split}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T17:42:08.413356+00:00","domain":"probability theory","id":"claim_ea99b1601d9670b4471a3b803912c9ae4d9d8c628ebb12bdf3a2191589978412","kind":"concept","schema_version":1,"statement":"[Lemma eq:betaLR1 of arXiv:2511.15893, 'On a Class of Dynamical Poisson-Voronoi Tessellations'] For all non-negative measurable and symmetric functions $f$, we have

