{"assumptions":[],"created_at":"2026-10-27T13:54:12.188351+00:00","domain":"probability theory","id":"claim_ecb6bc86c445bf1b7b9f2f767de1de7dc480a525200ae71074ee908ef76aa401","kind":"definition","schema_version":1,"statement":"[Definition def-condlim of arXiv:2603.01322, 'Gibbs conditioning, atypical consensus and splitting Gibbs measures on random regular grap'] Fix an edge potential $h$, and $c \in \R$, $c \neq \sref.$ Let $\Conset_n(h,c)$ and  $(c_\delta)_{\delta > 0}$ be  as in Definition (\oldref{def-rareevent}) and  (equation sdelta of the paper), respectively. 
\begin{enumerate}
\item Given $\rho^*\in \P(\Gstar[\X])$, we say  that {\em   $U_n$  given $\Conset_n(h,c)$ converges to $\rho^*$ } if  
   \begin{align}
\lim_{\delta\downarrow0}\lim_{n\to \infty}\mathbb{P}(U_n\in \cdot\mid \Conset_n(h, c_\delta))=\delta_{\rho^*}(\cdot).
\end{align}
    \item 
For any $\mathcal{U}\subset \P(\Gstar[\X]),$ we say that {\em  $U_n$ given $\Conset_n(h,c)$ lies in $\mathcal{U}$ asymptotically} if for every open set $U\supset \mathcal{U}$, the following holds:
    \begin{align}
        \lim_{\delta\downarrow 0}\limsup_{n\to \infty}\frac{1}{n}\log\mathbb{P}\left(U_n\notin U\ \vert\ 
        \Conset_n(h,c_\delta) \right)<0.
    \end{align} 
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:11:09.317015+00:00","domain":"probability theory","id":"claim_ecbb67f34c0522aa961ea52e9038780844b6a2f2e30754d14fd180dcf8a2586d","kind":"lemma","schema_version":1,"statement":"[Lemma itolinax of arXiv:2411.06131, 'Non-Markovian dynamics: the memory-dependent probability density evolution equations'] Let $ X_t $ be the solution of ((mSDEline of the paper)). Suppose that $ F(t,x) $ is any twice differentiable function of two variables. If $ A_t, B_t $ and $ C_t $ satisfy the conditions of Lemma (Malianx of the paper), then
	\begin{align}
	\mathrm{d}F(t,X_t)=&\Big(\frac{\partial F}{\partial t}(t,X_t)+\big(A_tX_t+\frac{1}{2}B^2_tX_t+\hat{C}_tX_t\big)\frac{\partial F}{\partial x}(t,X_t) \cr
	&+\big(\frac{1}{2}B^2_tX_t^2+\hat{C}_tX_t^2\big)\frac{\partial^2 F}{\partial x^2}(t,X_t)\Big)\mathrm{d}t+B_tX_t\frac{\partial F}{\partial x}(t,X_t)\mathrm{d}W_t\cr
	&+C_tX_t\frac{\partial F}{\partial x}(t,X_t) \diamond\mathrm{d}B^H_t,
	\end{align}
