{"assumptions":[],"created_at":"2026-10-27T14:49:05.433552+00:00","domain":"probability theory","id":"claim_ed7bb1890869bd051ea6f880e41c35e53de88324b99663aa384858f853518138","kind":"definition","schema_version":1,"statement":"[Define Definition 2.1 of arXiv:2601.09990, 'Remarks on the convex integration technique applied to singular stochastic partial differe'] \rm{(\hspace{1sp}[BV19b])} 
\begin{enumerate}[label=(\roman*)]
\item A vector field $u \in C_{\text{weak}} ([0,\infty); L^{2} (\mathbb{T}^{3})) \cap L^{2} ( 0,\infty; \dot{H}^{1}(\mathbb{T}^{3}))$ is a Leray-Hopf weak solution to the deterministic Navier-Stokes equations if for any $t$, $u(\cdot, t)$ is weakly divergence-free, has zero mean, satisfies the Navier-Stokes equations distributionally, and satisfies the energy inequality 
\begin{equation*}
\frac{1}{2} \lVert u(t) \rVert_{L^{2}}^{2} + \int_{0}^{t} \lVert \nabla u (s) \rVert_{L^{2}}^{2} ds \leq \frac{1}{2} \lVert u(0) \rVert_{L^{2}}^{2}. 
\end{equation*} 
\item A vector field $u \in C([0, \infty); L^{2}(\mathbb{T}^{3}))$ is a weak solution to the deterministic Navier-Stokes equations if for any $t$, $u(\cdot, t)$ is weakly divergence-free, has zero mean, and satisfies the Navier-Stokes equations distributionally. 
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:51:30.069418+00:00","domain":"probability theory","id":"claim_ed7e525f5c64bbf208af6cf4e547e60d5b86e152059ce31ff1ee1f9abd8ce49d","kind":"lemma","schema_version":1,"statement":"[Lemma 12 of arXiv:2606.01742, 'Large deviation principles for SPDEs with locally Lipschitz coefficients'] Assume that Hypotheses \ref{cond-initial}, \ref{cond-dif}  and  \ref{3} hold. If $\sigma:(0,\infty)\times\R\rightarrow\R$ is bounded, then
 \begin{align}
\sup_{N>0}\sup_{x\in \R}\E\left[\left|u_N^{ \varepsilon,h_ \varepsilon}(t,x)\right|^k\right]\leq 2^k\left(4k\e+M^2\right)^{\frac{k}{2}}e^{2L_bkt}\left(\|u_0\|_{L^\infty(\R)}+\|\sigma\|_{L^\infty(\R+\times\R)}t^{\frac{1}{4}}+1\right)^k
