{"assumptions":[],"created_at":"2026-10-27T21:54:18.300311+00:00","domain":"probability theory","id":"claim_ee173dd9257a40bde38db1688e9f6413e40d15764729911426bdfe4f987c1820","kind":"theorem","schema_version":1,"statement":"[Prop prop_ii of arXiv:2608.30382, 'Convergence rates for the RMSprop optimizer with full control of the hyperparameters'] Let $ \beta \in [ \nicefrac{ 1 }{ 2 }, 1 ) $, $ \varepsilon \in [0,\infty) $, $ n \in {\mathbb N} \backslash \{ 1 \} $, $ i \in \{1, \dots, d \} $,
let $ A_n \in \mathcal F_{ n - 1 } $, and let $ C_X^{(2)}, C_v^{(-1)} \in (0,\infty) $.
Assume that
\bas{
{\mathbb E}[(X^{(i)}(\theta_{n-1},U_n))^2|\mathcal F_{n-1}]\le C_X^{(2)}
\qquad\text{on }A_n
}
and
\bas{
{\mathbb E}[\1_{A_n}(v_{n-1}^{(i)})^{-1}]\le C_v^{(-1)}.
}
The negative-moment assumption implies that $v_{n-1}^{(i)}>0$ almost surely
on $A_n$. If $\varepsilon=0$, inverse factors used in the proof are evaluated on
$A_n$ and extended by zero to $A_n^c$.
Then one has
\bas{
{\mathbb E}\Bigl[\1_{A_n}(\sqrt{v_n^{(i)}}+\varepsilon)^{-2}
X^{(i)}(\theta_{n-1},U_n)^2\Bigr]
\le 4 C_X^{(2)} C_v^{(-1)}.
}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:35:05.801424+00:00","domain":"probability theory","id":"claim_ee18cb574b334b833c48a1d6c3eeff0b3ac857372a736654767caab5b1085370","kind":"theorem","schema_version":1,"statement":"[Proposition prop:prn_integral of arXiv:2606.23547, 'The location of the largest exponential spacing and Euler’s generalized pentagonal numbers'] For $1\le r\le n$, the probability $p_{r,n}$ admits the integral representation
\begin{equation}
p_{r,n}
=\int_0^\infty r {\rm e}^{-r t}
\prod_{\substack{1\le k\le n\\k\neq r}}
\bigl(1-{\rm e}^{-k t}\bigr)\,{\rm d}t.
\end{equation}
Equivalently,
\begin{equation}
p_{r,n}
=\int_0^1 r\,u^{r-1}
\prod_{\substack{1\le k\le n\\k\neq r}}
(1-u^k)\,{\rm d}u.
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:45:07.257085+00:00","domain":"probability theory","id":"claim_ee21a4008daf0e24e455a355d28ccbcbbcac2fea9e29dc9060666bcaa5348bf3","kind":"concept","schema_version":1,"statement":"[Proposition 1 of arXiv:2604.19308, '\textbf{On McKean--Vlasov SDEs with polynomial drifts for SIS epidemic models}'] Let $p=1$ and~\eqref{co:1} and~\eqref{co:2} be valid. Then pathwise uniqueness holds for~\eqref{eq:SIS epidemic model}, and any two solutions $I$ and $\tilde{I}$ to~\eqref{eq:SIS epidemic model} satisfy
\begin{equation}
\E\big[|I_{t} - \tilde{I}_{t}|\big] \leq e^{\int_{0}^{t}(\hat{b}_{k+1} + \hat{\lambda}_{k+1})(s,N(s))\,\mathrm{d}s}\E\big[|I_{0} - \tilde{I}_{0}|\big]
\end{equation}
for all $t\geq 0$. In particular, if $(\hat{b}_{k+1} + \hat{\lambda}_{k+1})^{+}(\cdot,N)$ is integrable, then $\sup_{t\geq 0} \E[|I_{t} -\tilde{I}_{t}|]$ is finite. If additionally
\begin{equation*}
\int_{0}^{\infty}(\hat{b}_{k+1}+\hat{\lambda}_{k+1})^{-}(s,N(s))\,\mathrm{d}s = \infty,\quad\text{then}\quad \lim_{t\uparrow\infty} \E\big[|I_{t}-\tilde{I}_{t}|\big] = 0.
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T09:43:00.051383+00:00","domain":"probability theory","id":"claim_ee2bb7f6df64cc1f3e6745e8fd44afb5488f706918c480d357b0df3838ecbe1e","kind":"concept","schema_version":1,"statement":"[Theorem 4 (Decision-boundary representation of the error-rate Hessian) of arXiv:2609.00774, 'Semi-Supervised Classification with Informative Missing Labels in Weibull Mixture Models'] Under \Cref{ass:boundaries}, with $p_Y$ continuous at the boundaries,
\begin{equation*}
 \left.\frac{\partial R(\widetilde\theta;\theta)}
 {\partial\widetilde\theta}\right|_{\widetilde\theta=\theta}=0,
\end{equation*}
and
\begin{equation}
 H_{R}(\theta)
 :=\left.\frac{\partial^2 R(\widetilde\theta;\theta)}
 {\partial\widetilde\theta\partial\widetilde\theta^\top}
 \right|_{\widetilde\theta=\theta}
 =\sum_{j=1}^K
 \frac{p_Y(y_j;\theta)}{2|\delta_y(y_j;\theta)|}
 g(y_j;\theta)g(y_j;\theta)^\top.

\end{equation}
Let $\widehat\theta$ satisfy
\begin{equation}
 \sqrt n(\widehat\theta-\theta)\xrightarrow{d}N(0,V),
 \qquad
 n\E\{(\widehat\theta-\theta)(\widehat\theta-\theta)^\top\}\longrightarrow V,

\end{equation}
and suppose that, for some $\epsilon>0$,
\begin{equation}
 \E\|\sqrt n(\widehat\theta-\theta)\|^{2+\epsilon}=O(1).

\end{equation}
Then
\begin{equation}
 \E\{R(\widehat\theta;\theta)\}-\err(\theta)
 =\frac{1}{4n}\sum_{j=1}^K
 \frac{p_Y(y_j;\theta)}{|\delta_y(y_j;\theta)|}
 g(y_j;\theta)^\top Vg(y_j;\theta)
 +o(n^{-1}).

\end{equation}
For a correctly specified regular maximum-likelihood estimator satisfying the stated moment conditions,
$V=\J(\theta)^{-1}$, so
\begin{equation}
 \E\{R(\widehat\theta;\theta)\}-\err(\theta)
 =\frac{1}{4n}\sum_{j=1}^K
 \frac{p_Y(y_j;\theta)}{|\delta_y(y_j;\theta)|}
 g(y_j;\theta)^\top\J(\theta)^{-1}g(y_j;\theta)
 +o(n^{-1}).

\end{equation}
For the estimator that ignores the missingness mechanism, the same specialisation holds with $\J=\J_{\mathrm{ig}}$ by \Cref{lem:ig-information}. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

