{"assumptions":[],"created_at":"2026-10-26T19:45:07.259037+00:00","domain":"probability theory","id":"claim_eefea7caaab767de4d4abe008840a80260a03af8fec6627d98904433ec8c8022","kind":"lemma","schema_version":1,"statement":"[Lemma 22 of arXiv:2604.19308, '\textbf{On McKean--Vlasov SDEs with polynomial drifts for SIS epidemic models}'] If the following two conditions hold for some $m\in\N$ and $\zeta,\eta\in [\frac{1}{2},\infty[^{d\times m}$, then~\eqref{co:4} is satisfied:
\begin{enumerate}[(i)]
\item There is a measurable and locally square-integrable map $g\colon\R_{+}\rightarrow\R^{d\times m}$ such that $|f_{i}(\cdot,x,y)| \leq |\sum_{j=1}^{m} g_{i,j} x^{\zeta_{i,j}}y^{\eta_{i,j}}|$ for all $i\in\{1,\dots,d\}$ and $x,y\geq 0$.

\item Each $\nu\in\mathcal{P}_{0}(\R)$ satisfies
\begin{align*}
\max_{x\in [0,N]} \frac{1}{2}\sum_{i=1}^{d}\sum_{\substack{j_{1},j_{2}=1,\\ \zeta_{i,j_{1}} + \zeta_{i,j_{2}} < 2}}^{m}g_{i,j_{1}}g_{i,j_{2}}x^{\zeta_{i,j_{1}} + \zeta_{i,j_{2}} - 1}(N-x)^{\eta_{i,j_{1}} + \eta_{i,j_{2}}} &\leq b_{0}(\cdot,N,\nu),\\
\max_{x\in [0,N]}\frac{1}{2}\sum_{i=1}^{d}\sum_{\substack{j_{1},j_{2}=1,\\ \eta_{i,j_{1}} + \eta_{i,j_{2}} < 2}}^{m} g_{i,j_{1}}g_{i,j_{2}} (N-x)^{\zeta_{i,j_{1}} + \zeta_{i,j_{2}}}x^{\eta_{i,j_{1}} + \eta_{i,j_{2}} - 1} &\leq \dot{N} - \sum_{i=0}^{k}b_{i}(\cdot,N,\nu)N^{i}.
\end{align*}
\end{enumerate}","status":"unverified"}

