    Then, for any $j\geq 2$,
	\begin{enumerate}[wide=0em,itemsep=.5em,label={\rm(\roman*)}]

		\item $\lambda_{N_j}=\Lambda_j$, i.e. ${\rm mult}\,\Lambda_j=N_{j}$.
		\item $\#\{k\geq 1\colon \varphi_k\text{ eigenfunction of }-\Delta\text{ with eigenvalue }\lambda_k\leq \Lambda_j,\}=N_{j+1}$.
