	\leq & \widetilde{C} \| \nabla H \|^{2}_{2,n} (t-s)^{1 + \delta} \Bigg( \frac{\big[ \Theta(n) K_n\big]^{\delta+1} }{n^{2}} +  \frac{\big[ \Theta(n) \big]^{1+\delta} (K_n)^2  }{n^{2}}   \ell_n^{2 - 2 \delta} \Bigg)  \big\{ \mathbbm{1}_{ \{ \gamma > 1 \} } + \big[ \log(L_n) \big]^{2} \mathbbm{1}_{ \{ \gamma = 1 \} } \big\}.
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

