\end{equation*}
This is the Green's function for $\partial_\varepsilon u(\varepsilon,x) = \frac{1}{2}\partial_{xx}u(\varepsilon,x)$ on $\R^+$ with $u(\varepsilon,0)=0$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:51:12.738889+00:00","domain":"probability theory","id":"claim_f4eab3a693fcc146cb7f74581cf5926a1a4d7b0b330f8a1e04fb2e0382e7a1ac","kind":"concept","schema_version":1,"statement":"[Thm 3 of arXiv:2605.02420, '\textbf{Large time behavior of critical marked Hawkes processes with heavy tailed marks an'] Suppose that Assumptions \ref{ass:phi_alpha} and \ref{ass:beta_general} are satisfied with $\alpha=\beta<1$ and let $F_T=T^{1+\beta}$ as in \eqref{e:FT}. Then  the process $Y_T$ given by
 \eqref{e:YT} converges in the sense of finite dimensional distributions and in law in $D([0,\infty))$ equipped with $M_1$ topology to a nonnegative process $Y_\infty=(Y_\infty(t))_{t\ge 0}$ whose finite dimensional distributions are such that for any $m\in \N$, $\theta_1, \ldots, \theta_k\ge 0$ and $t_1,\ldots, t_m\ge 0$ we have 
 \begin{equation}
  E \exp\{-\sum_{k=1}^m\theta_kY_{\infty}(t_k)\}=\exp\{-\mu\int_0^\infty v_f(t)dt\},

 \end{equation}
where $v_f$ is a unique nonnegative bounded function with compact support satisfying the equation
\begin{equation}
 v_f(t)=\beta c_{\beta,\varphi}\int_0^\infty \left(f(t+s)-Kv_f^{1+\beta}(t+s)\right)s^{\beta-1} ds,

 \end{equation}
where
 \begin{equation}
  f(t)=\sum_{k=1}^m\theta_k\ind_{[0,t_k]}(t)

 \end{equation}
and $K$ and $c_{\beta,\varphi}$ are given by \eqref{e:H_bound} and \eqref{e:c_alpha}, respectively. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:55:18.057389+00:00","domain":"probability theory","id":"claim_f4ed1785e86e912031f97fe5737c59741dfb0b33f118e2688f94d2c7f0bd3881","kind":"concept","schema_version":1,"statement":"[Theorem 34 (\cite{chen2022hamilton}) of arXiv:2606.16636, 'Free energy of non-convex multi-species spin glasses with centered Ising spins'] Let $\psi:\mcl Q_2^\D\to\R$ be $\Ll(\mcl Q_2^\D\Rr)^*$-increasing and satisfy
\begin{align}
    \Ll|\psi(q)-\psi(q')\Rr|\leq \Ll|q-q'\Rr|_{L^1},\qquad\forall q,q'\in\mcl Q_2^\D.
\end{align}
With initial condition $f(0,\cdot)=\psi$, there exists a viscosity solution $f$ of~\eqref{e.hj}, unique in the class of Lipschitz functions on $\R_+\times\mcl Q_2^\D$. Moreover, if $\psi$ is convex on $\mcl Q_2^\D$, then $f$ admits the Hopf representation
\begin{align}
        f(t,q) = \sup_{p \in \mcl Q_\infty^\D}\inf_{q' \in \mcl Q_\infty^\D}\left\{ \psi(q') + \la q - q', p\ra_\cH +t\int_0^1\xi(p(s))\d s\right\},\quad\forall(t,q)\in\R_+\times\mcl Q_2^\D.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:52:45.029673+00:00","domain":"probability theory","id":"claim_f4ef9d3e5ba4efac67e4dc156bc4a5cf877f1bb53558ca352909571752a5ee4f","kind":"theorem","schema_version":1,"statement":"[Proposition 12 of arXiv:2606.07096, 'Non-Selection of Lagrangian Trajectories in the Zero-Noise Limit for a Class of Stochastic'] For a.e. $x\in \T^2$, it holds that
