\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:53:31.972894+00:00","domain":"probability theory","id":"claim_f69125bc53f072b795c29c778ce1bce33e202abd749a72c3b772fc2cf56ca42c","kind":"concept","schema_version":1,"statement":"[Theorem 1 (\cite{GS18}, Corollary 2.3) of arXiv:2606.10336, 'From Pitman's local times representation to the Gorin-Shkolnikov identity and beyond'] Let $\{e(t)\}_{0 \le t \le 1}$ be a Brownian excursion on $[0,1]$
and $\{l_x\}_{x \ge 0}$ be local times process\footnote{Here $\ell_y$ is the local times of $\{e(t)\}_{0 \le t \le 1}$ at level $y \ge 0$. See e.g., \cite[Chapter VI]{RY} for background.}.
Then:
\begin{equation}

\int_0^1 e(t)dt - \frac{1}{2} \int_0^\infty \ell_x^2 dx \stackrel{d}{=} \mathcal{N}\left(0,\frac{1}{12}\right),
\end{equation}
where $\mathcal{N}(m,\sigma^2)$ denotes a Gaussian random variable with mean $m$ and variance $\sigma^2$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:57:59.858446+00:00","domain":"probability theory","id":"claim_f6a33eb980ab1a9cdf2201a9fdc5dcbdba6b7da0a31237c49f09ff5745a93343","kind":"lemma","schema_version":1,"statement":"[Lemma lem:process_continuity of arXiv:2606.11951, 'On Skorokhod Problems for Reflected and Singular Stochastic Heat Equations'] The process $X^a$ is almost surely continuous in the sense that
	\begin{equation*}
		\mathbb{P}_z[X_t^a \in [C_0] \text{ for a.e. } t\in [0,\infty)] = 1 \quad\text{for all } z\inL.
	\end{equation*}
	The same statement holds for $\mathcal{E}$-q.e.\ $z\inL$ for $X$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T17:38:58.696139+00:00","domain":"probability theory","id":"claim_f6a50ab276e6e20221a5a6eb0c87499f23797c14e1f456c23566f78acb919d31","kind":"theorem","schema_version":1,"statement":"[Theorem thm:lsi of arXiv:2510.22778, 'Free denoising diffusion models'] For every $\mu$ with finite second moment and $\Phi^{*}(\mu)<\infty$,
\begin{align}
  \mathcal{D}(\mu\Vert\gamma)&\le\tfrac12\,I(\mu\Vert\gamma), \\
  W_{2}(\mu,\gamma)^{2}&\le 2\,\mathcal{D}(\mu\Vert\gamma). 
\end{align}
Both are sharp, with equality if and only if $\mu=\gamma$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T17:32:11.126772+00:00","domain":"probability theory","id":"claim_f6ac3785082c9aa39dcfe09cd15c41036d6b2ffe769849058b59a00353edd9ba","kind":"concept","schema_version":1,"statement":"[Proposition prop:multi_extention_Asmussen of arXiv:2510.06891, 'Multivariate CLT for L\'evy processes: convergence rates without moment assumptions'] Let $g: [0,\infty) \to [0,\infty)$ be non-decreasing and absolutely continuous with $g(0)=0$ and a locally finite density $g'\geqslant 0$ satisfying $\int_0^y g'(x)x^{-2}\mathrm{d} x<\infty$ for some $y>0$. Let $\bm{X}$ be a $d$-dimensional L\'evy process with L\'evy measure $\nu$ such that $\mathds{E}[g(60|\bm{X}_1|)]<\infty$ and $\mathds{E}[\bm{X}_1]=0$. Then
\begin{equation}
    \lim_{n\to\infty}n
    \mathds{E}\big[g\big(\big|\bm{X}_{1/n}\big|\big)\big]
=\int_{\mathbb{R}^d}g(|\bm{v}|)\nu(\mathrm{d} \bm{v}).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T08:02:08.121673+00:00","domain":"probability theory","id":"claim_f6b4ce3c89760709a09be5c571a9bd16fb96bc4338894e4429766c1429eafe97","kind":"concept","schema_version":1,"statement":"[Proposition 12 of arXiv:2608.27433, 'Scalar curvature on K\"ahler blow-ups and systolic inequalities'] For all sufficiently small $\eps$, the operator
\[
  \widetilde{\mathcal P}_\eps:
  C^{4,\alpha}_\delta(\widetilde X)\longrightarrow
  C^{0,\alpha}_{\delta-4}(\widetilde X)
\]
is an isomorphism in the following cases:
\begin{enumerate}[label=\textup{(\roman*)}]
\item if $k>2$ and $4-2k<\delta<0$, then
\begin{equation}
  \norm{\phi}_{C^{4,\alpha}_\delta}
  \le C\norm{\widetilde{\mathcal P}_\eps\phi}_{C^{0,\alpha}_{\delta-4}};
\end{equation}
\item if $k=2$ and $-1<\delta<0$, then
\begin{equation}
  \norm{\phi}_{C^{4,\alpha}_\delta}
  \le C\eps^\delta
  \norm{\widetilde{\mathcal P}_\eps\phi}_{C^{0,\alpha}_{\delta-4}}.
\end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:41:03.268121+00:00","domain":"probability theory","id":"claim_f6bb2be19c8f6dba57ccae53c727b8605dce240de5c5c1f50eeba32ccf78cf2d","kind":"concept","schema_version":1,"statement":"[Mylem l2 of arXiv:2411.08430, 'The Restricted Isometry Property of Block Diagonal Matrices Generated by $\varphi$-Sub-Gau'] For any random variable $\xi \in \operatorname{Sub}_{\varphi}(\Omega)$, 
		\begin{equation}
			\textsf{E} \exp \{\lambda \xi\} \leq \exp \left\{\varphi\left(\lambda \tau_{\varphi}(\xi)\right)\right\}, \quad \lambda \in \mathbb{R}
		\end{equation}
		holds, where $$
		\tau_{\varphi}(\xi):=\sup _{\lambda \neq 0} \frac{\varphi^{(-1)}(\log \textsf{E} \exp \{\lambda \xi\})}{|\lambda|},
		$$
		and  $\varphi^{(-1)}(\cdot)$ denotes the inverse function of $\varphi(\cdot)$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:19:47.203530+00:00","domain":"probability theory","id":"claim_f6d6937a94015c824102d8c50864fa78b1dbff2843098abd0ea7b88cd430c237","kind":"concept","schema_version":1,"statement":"[Theorem mainsharpness of arXiv:2512.06640, 'Existence and sharpness of the phase transition for the frog model on transitive graphs'] Let $\vec{G} = (V, \vec{E})$ be a directed vertex-transitive graph. The following statements hold:
    \begin{itemize}[nosep,left=5pt]
        \item[1.] For every $t > 0$, there exists a constant $K_{1}(\lambda_{\mathrm{c}}(t))$ such that for any $\lambda$ in $[\lambda_{\mathrm{c}}(t),2\lambda_{\mathrm{c}}(t)],$ we have
        \begin{align}
            \mathbb P_{\lambda, t}(\mathbf{0} \rightarrow \infty) \geq K _{1}(\lambda - \lambda_{\mathrm{c}}).
        \end{align} 
        \item[2.] For every $\lambda > 0$, there exists a constant $K_{2}(t_{\mathrm{c}}(\lambda)) $ such that for any $t$ in $[t_{\mathrm{c}}(\lambda),2t_{\mathrm{c}}(\lambda)],$ we have
        \begin{align}
            \mathbb P_{\lambda, t}(\mathbf{0} \rightarrow \infty) \geq K_{2} (t - t_{\mathrm{c}}).
        \end{align} 
        \item[3.] For fixed $t>0,$ and $\lambda < \lambda_{\mathrm{c}}(t),$ there exist constants $C,c>0,$ such that
        \begin{equation}
            \mathbb P_{\lambda,t}\left(|\mathcal{C}_{\mathbf{0}}| \geq n\right) \leq Ce^{-cn}, \text{ for every $n\geq0$}. 
        \end{equation}
        \item[4.] For fixed $\lambda > 0,$ and $t < t_{\mathrm{c}}(\lambda),$ there exist constants $C,c>0,$ such that
        \begin{equation}
            \mathbb P_{\lambda,t}\left(|\mathcal{C}_{\mathbf{0}}| \geq n\right) \leq Ce^{-cn}, \text{ for every $n\geq0$}. 
        \end{equation}
    \end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:09:15.344395+00:00","domain":"probability theory","id":"claim_f6e0fba8d36273c78f8a5bf89b2654701c3ff31118f9797c2b5d2605e179008c","kind":"definition","schema_version":1,"statement":"[Definition eqNullset of arXiv:2411.05534, 'Inverse problems for stochastic partial differential equations'] The measure space $ (\Omega, \mathcal{F}, \mu) $ is called complete (and $ \mu $ is said to be complete on $ \mathcal{F} $), if $ \mathcal{F} $ includes all subsets of null sets, i.e., 
    \begin{align}

        \mathcal{N} = \{ G \subset \Omega \mid  G \subset E \text{ for some $ \mu $-null set } G \} \subset \mathcal{F}.
    \end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:37:08.956139+00:00","domain":"probability theory","id":"claim_f6e90bddfd812f29996293e97a31dc192bdb2b9c28174a62321f27969fccc5aa","kind":"theorem","schema_version":1,"statement":"[Proposition prop:sample_mean of arXiv:2609.01581, 'Concentration of additive functionals of Stratonovich-type'] Let the assumptions of Theorems~(thm:explicit_density of the paper),~(thm:explicit_current_1 of the paper)
and~(thm:explicit_current_2 of the paper) hold, with the corresponding sub-gamma parameters
$\tilde\sigma_A^2$ and $c_A$ established there for $\overline{A}_t \in
\{\overline{\rho}_t(V), \overline{J}_t(U)\}$. Then for every $n \geq 1$, $t>0$, and
$a>0$, the sample mean $\widehat{A}_{n,t}$ satisfies the one-sided bound
\begin{align}
  \mathbb{P}^\nu\left(\widehat{A}_{n,t} - \E^\mu[\overline{A}_t] \geq a\right)
  \leq
  N_\nu^{n}
  \exp\left[-nt\frac{\tilde\sigma_A^2}{c_A^2}
  h\left(\frac{c_A a}{\tilde\sigma_A^2}\right)\right],

\end{align}
and the corresponding two-sided bound
\begin{align}
  \mathbb{P}^\nu\left(\left|\widehat{A}_{n,t} 
  - \E^\mu[\overline{A}_t]\right| \geq a\right)
  \leq
  2 N_\nu^{n}
  \exp\left[-nt\frac{\tilde\sigma_A^2}{c_A^2}
  h\left(\frac{c_A a}{\tilde\sigma_A^2}\right)\right].

\end{align}
Here, $\mathbb{P}^\nu$ now denotes the underlying initial law of the $n$ independent trajectories. 
In particular, $\widehat{A}_{n,t}$ obeys the single-trajectory bounds
($n=1$) of Section~(sec:conc_poincare of the paper)
and also Eq.~(equation eq:uq_general of the paper) by replacing $t \to nt$ and $N_\nu \to N_\nu^n$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:36:44.551185+00:00","domain":"probability theory","id":"claim_f6fde9180d22caadf1fcf83ca249bf4c1c45ac7ec025be4e9174d1b11e8df78e","kind":"lemma","schema_version":1,"statement":"[Lemma 13 of arXiv:2604.01978, 'Homogenized Transformers'] Let $\varphi \in C^{4}((\S^{d-1})^{n}).$ There exists a constant $C>0$ such that 
\begin{equation*}
    \max_{x\in(\S^{d-1})^{n}}\left|\E \varphi(X(\eta,x))-\E \varphi(X^{1}(x))\right|\leq C\eta^2\max\left(\eta,\alpha \right).
\end{equation*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:41:29.041240+00:00","domain":"probability theory","id":"claim_f6fffd6d5817acdbf0d2e59adcd401afd4eb4122fa8f35c207a7b97072de5f1e","kind":"lemma","schema_version":1,"statement":"[Lemma 4 of arXiv:2608.26598, 'Pinching cones for positive isotropic curvature in dimensions seven and eight'] Let $n\ge6$ and $S\in\CPIC\cap\CB(\mathbb R^n)$. Then, for every orthonormal frame
    $\{e_1,\dots,e_n\}$:
    \begin{enumerate}
        \item $S_{ijij}+S_{klkl}\ge0$ whenever $\{i,j\}\cap\{k,l\}=\emptyset$;
        \item $\Scal(S)-2\Ric_{kk}=\sum_{i\ne k}\sum_{j\ne k}S_{ijij}\ge0$ for every $k$;
        \item $\sum_{p\ge3}(S_{1p1p}+S_{2p2p})\ge0$; equivalently
        $\Ric_{11}+\Ric_{22}\ge2S_{1212}$;
        \item $\Ric_{11}+\Ric_{22}+\Ric_{33}+\Ric_{44}\ge2(S_{1212}+S_{3434})\ge0$;
        \item $(n^2-7n+14)S_{1212}+(n-5)(\Ric_{11}+\Ric_{22})+\Scal(S)\ge0$; for $n=8$ this reads
        $22S_{1212}+3(\Ric_{11}+\Ric_{22})+\Scal(S)\ge0$, and together with (3) it gives
        $\Ric_{11}+\Ric_{22}\ge-\frac1{14}\Scal(S)$;
        \item for every $\lambda\in[0,1]$ and every $p\ge5$,
        $S_{1313}+\lambda^2S_{1414}+S_{2323}+\lambda^2S_{2424}-2\lambda S_{1234}
        +(1-\lambda^2)(S_{1p1p}+S_{2p2p})\ge0$;
        \item if $\Scal(S)=0$ then $S=0$; equivalently every nonzero
        $S\in\CPIC\cap\CB(\mathbb R^n)$ has positive scalar curvature.
    \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:32:19.939452+00:00","domain":"probability theory","id":"claim_f705b44085fb3027b3432ed7ed37fb8891bfc35c66ce27a92b247129f90fe561","kind":"concept","schema_version":1,"statement":"[Proposition 27 of arXiv:2608.02927, 'Thinning Operation via the Poisson-F\"ollmer Process'] [Variational formula for entropy] 

      Let $(\Omega, \mathcal{F},\mu)$ be a probability space, and let $f : \Omega \rightarrow (0,\infty) $ be a $\mu$--integrable function such that $\int_{\Omega} f \dd \mu = 1.$ Then 
      \begin{displaymath}
          \Ent_{ \mu } (f) = \sup_{g} \Big\{ \int f g \dd \mu - \log \Big( \int e^{g} \dd \mu \Big) \Big\}
      \end{displaymath}
      where the supremum is taken over measurable and bounded functions $g : \Omega \rightarrow \R.$ (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:49:21.122691+00:00","domain":"probability theory","id":"claim_f70c8752fc283a433a9ce4a013de9c39c5c4afab6fd32f657ddc6bbf8985eec8","kind":"theorem","schema_version":1,"statement":"[Prop 24 of arXiv:2608.26642, '2608.26642'] Assume that the pair $(C,f)$ satisfies the Fredholm equation (\ref{main-Fredeq}) with the normalization condition (\ref{main-Frednorm}). Then the function $f$ satisfies the growth condition (\ref{main-SLgrowth}). More precisely, we have
\begin{align}

f(x)= h(x)+C\mp \frac{1}{\P_0[X_1^2]}\int_K yf (y)\,\mu(dy)+o(1)\qquad \text{as}\ x\to \pm \infty.
\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:05:09.629495+00:00","domain":"probability theory","id":"claim_f70dd960efba586de3a8982fd21e0e6897d4b22c059f4fc1f2c610da991198e9","kind":"lemma","schema_version":1,"statement":"[Lemma lem_drift_como_conv of arXiv:2411.03609, 'Asymptotically optimal Wasserstein couplings for the small-time stable domain of attractio'] \noindent\normalfont{(a)} Let $\alpha \in (1,2)$, and $p,\delta>0$ where $p\ne\alpha-1$ and $\delta\ne(\alpha-1)/\alpha$. Then, under Assumptions~(\nameref{asm:S}) \& (\nameref{asm:C}), we have, as $t \downarrow 0$,
    \begin{align*}
        |\bm{\varpi}_{\bm{S}^t}-\bm{\varpi}_{\bm{Z}}|&=\mathcal{O}\big(G_2(t)+t^{1-1/\alpha}G(t)^{-1} 
    +(1+G_1(t))t^{\min\{1-1/\alpha,\delta\}}
    \\
    &\qquad + G(t)^{p}(1+G_1(t))^{1+p}t^{\min\{1-1/\alpha,p/\alpha\}}\big).
    \end{align*}
\noindent\normalfont{(b)} Let $\alpha \in (0,1)$. Then, under Assumptions~(\nameref{asm:S}) \& (\nameref{asm:C}) we have, as $t \downarrow 0$, 
\begin{equation*}
|\bm{\varpi}_{\bm{S}^t}-\bm{\varpi}_{\bm{Z}}|
=\mathcal{O}\big(G_2(t)+t^{p/\alpha}G(t)^{p} +t^{\delta}\big).
\end{equation*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T09:36:31.223215+00:00","domain":"probability theory","id":"claim_f70fbe435a238cf294e14edea7a7bd1b4612de892f6efaea69a8664800350892","kind":"theorem","schema_version":1,"statement":"[Corollary 12 (Parametrization of the unique toroidal limit) of arXiv:2609.00501, 'Uniqueness of Finite-Time Varifold Limits for the M\"obius-Invariant Willmore Flow'] Assume the hypotheses of Corollary~\ref{cor:classification} and suppose that
$\Var_T\neq0$ and $\spt\Var_T$ has genus one.  Then there exists a
uniformly conformal bi-Lipschitz homeomorphism
\[
 f\in W^{2,2}(\Sigma,\R^4)\cap W^{1,\infty}(\Sigma,\R^4),
 \qquad
 f\colon\Sigma\longrightarrow M:=\spt\Var_T,
\]
and there are a smooth zero-scalar-curvature, unit-volume metric
$g_{\mathrm{poin}}$ on $\Sigma$ and a function $u\in L^\infty(\Sigma)$
such that
\begin{equation}

 f^*g_{\mathrm{euc}}=e^{2u}g_{\mathrm{poin}}.
\end{equation}
Moreover,
\begin{equation}

 \Var_T=v(M,1),
\end{equation}
and
\begin{equation}

 \lVert\Var_T\rVert
 =f_\#\mu_{f^*g_{\mathrm{euc}}}
 =\mathcal H^2\llcorner M.
\end{equation}
In particular, formula \eqref{eq:limit-measure} is independent of the sequence
used to construct the parametrization $f$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:00:22.781170+00:00","domain":"probability theory","id":"claim_f71481e9a4b87299c3c4f2780c3e173e7aaacc8c16a06cf6b86e774cc86c1895","kind":"concept","schema_version":1,"statement":"[Lm of arXiv:2411.01633, 'On the Limit of the Tridiagonal Model \\for $\beta$-Dyson Brownian Motion'] For any $f, g\in H_0^{1,1}(0,\infty)$, the quadratic form,
    \begin{equation}
        \langle f, \mathcal{H}_{\beta}(t) g\rangle,
    \end{equation}
    is well defined as $\lim_{n \to \infty } \langle f_n, \mathcal{H}_{\beta}(t) g\rangle$ for any $f_n \in C_c^{\infty}(0,\infty)$ with $f_n \to f.$ (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:43:55.604343+00:00","domain":"probability theory","id":"claim_f715a14a57731219e46d456b51e452581aa41f920b35c40e327e9623164b5550","kind":"theorem","schema_version":1,"statement":"[Proposition p:wagestable of arXiv:2604.03979, 'Stationary Distributions in Monotone Markov Models: Theory and Applications'] If (a:quqe of the paper) holds, then the wage process is globally stable, with
    unique stationary distribution $\phi^*$.  Moreover,

    \begin{equation}
        \beta(\phi P_t, \phi^*) \leq C e^{-\alpha t}
        \quad \text{for all } \phi \in \mathscr{P}(S) \text{ and } t \geq 0,
    \end{equation}

    where 

    \begin{equation}
        C \coloneq 2/(1-\kappa), 
        \quad
        \alpha \coloneq \ln(1/(1-\kappa)),
        \quad \text{and} \quad
