{"assumptions":[],"created_at":"2026-10-26T20:28:53.672058+00:00","domain":"probability theory","id":"claim_f9f9a2012f035382a6ee743938b76700bc0760ce81713e80864fc7adb2908b44","kind":"theorem","schema_version":1,"statement":"[Theorem 11 (transition distribution) of arXiv:2605.13648, 'Sticky CIR process with potential: invariant measure and exact sampling'] For $x>0$, the transition distribution $P_x(u_{T_\alpha}\in\cdot)$
  admits the resolvent representation
  \begin{equation}
    \mathbb{P}(u_{T_\alpha}\in A\mid u_0=x)
    = \frac{\alpha}{\mu}\,G^{\rm sticky}_\alpha(x,0)\,\mathbf{1}_{0\in A}
    + \alpha\int_{A\cap(0,\infty)} G^{\rm sticky}_\alpha(x,y)\,m'(y)\,dy,
  \end{equation}
  equivalent to the three-component mixture
  \begin{equation}
    \mathbb P(u_{T_\alpha}\in A\mid u_0=x)
    = w_0(x)\,\mathbf{1}_{0\in A}
    + w_<(x)\,\nu_<(A)
    + w_>(x)\,\nu_>(A),
  \end{equation}
  where $\nu_<$ and $\nu_>$ are the probability measures with Lebesgue
  densities
  \[
    \frac{d\nu_<(y)}{dy}  \propto  f_0^{\rm sticky}(y)\,m'(y)\,\mathbf{1}_{(0,x)}(y),
    \qquad
    \frac{d\nu_>(y)}{dy}  \propto  U(a,b,z_y)\,m'(y)\,\mathbf{1}_{(x,\infty)}(y),
  \]
  and the weights are
  \begin{align}
    w_0(x) &= -c_\mu\,U(a,b,z_x), \\
    w_<(x) &= \frac{\alpha\,U(a,b,z_x)}{|\mathcal{W}|}
               \int_0^x f_0^{\rm sticky}(y)\,m'(y)\,dy, \\
    w_>(x) &= \frac{\alpha\,f_0^{\rm sticky}(x)}{|\mathcal{W}|}
               \int_x^\infty U(a,b,z_y)\,m'(y)\,dy, 
  \end{align}
  satisfying $w_0(x)+w_<(x)+w_>(x)=1$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:25:44.586120+00:00","domain":"probability theory","id":"claim_f9fd27db0ee2782c89c12c6a678dba0423a5b4507cb981613a94c1133c2b49e1","kind":"theorem","schema_version":1,"statement":"[Thm convnex_entropy of arXiv:2509.08659, 'Gap metrics for stationary point processes and quantitative convexity of the free energy'] Let $\Pi_i\in \mathcal P_{s,1}( \mathsf{S})$, $i=0,1$ and assume that $\mathscr  W_{gap,p}(\Pi_0,\Pi_1)<\infty$ for $p>1$. Then, there exists an optimal coupling  $\mathsf U\in  \mathsf{Cpl}_s(\Pi_0,\Pi_1)$, such that for any $0\leq t\leq 1$ \begin{align}
       \mathcal E^*((T_t)_{\#}\mathsf U) \leq (1-t) \mathcal E^*(\Pi_0)+t\mathcal E^*(\Pi_1).
    \end{align}
    In particular, for $\mathsf{P}_i\in \mathcal P_{s,1}(\Gamma)$ with $\mathscr  W_{p}(\mathsf{P}_0,\mathsf{P}_1)<\infty$ there exists an optimal coupling  $ \mathsf{Q}\in  \mathsf{Cpl}_{s,m}(\mathsf{P}_0,\mathsf{P}_1)$, such that for $\mathsf{P}_t:= \mathsf{gap}^{-1}((T_t)_{\#}\iota( \mathsf{Q}))$ we have \begin{align}
       \mathcal E(\mathsf{P}_t)\leq (1-t)  \mathcal E(\mathsf{P}_0)+t\mathcal E(\mathsf{P}_1)
    \end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T17:11:02.384326+00:00","domain":"probability theory","id":"claim_fa056f96fb64d99fe098ac317664627313375d326f66619abc9512cff8353df0","kind":"concept","schema_version":1,"statement":"[Proposition prop:global_hajek_intro of arXiv:2507.10531, 'Quantitative central limit theorems for exponential random graphs'] Define
\begin{equation}

    \widehat{\mathsf{N}}_G(x) \coloneqq \mathsf{N}_G(x) - 2 \mathsf{e} p^{\mathsf{e}-1} n^{\mathsf{v}-2} \mathsf{E}(x).
\end{equation}
Then, for all $\zeta \in (0,1)$, there is some $c > 0$ such that 
\begin{equation}
    \mathbb{P} \mleft[
        \mleft|
            \widehat{\mathsf{N}}_G(X) - \mathbb{E}\mleft[\widehat{\mathsf{N}}_G(X)\mright]
        \mright| > n^{\mathsf{v}-1.5+\zeta}
    \mright] \leq \exp\mleft(-cn^\zeta\mright).
\end{equation}
In particular, for all $\xi > 0$, we have
\begin{equation}
    \operatorname{Var}\mleft[\widehat{\mathsf{N}}_G(X)\mright] \lesssim n^{2\mathsf{v}-3+\xi}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:28:49.113815+00:00","domain":"probability theory","id":"claim_fa0b790a872b8765485156cc82971edd16356f6448c2b04fc7d52ab0b29d43ae","kind":"lemma","schema_version":1,"statement":"[Lemma lem:pole-short-time-calibration of arXiv:2608.16119, 'Fully nonlinear parabolic equations under a fixed reference diffusion: weighted \texorpdfs'] Assume (equation eq:pole-coefficient-class of the paper), take
$K=K_\theta^\star(a)$, and let
$0\leq\alpha<1/2$ and $0<\theta<1-4/(C_\alpha^{\mathrm{Br}})^2$, with
$\Delta_{\mathrm{hi}}$ as in Theorem~(thm:pole-calibration of the paper).  There are
\begin{equation*}
 \begin{aligned}
 N_{\mathrm H}&=N_{\mathrm H}
   (\lambda,\Lambda,\alpha,\Delta_{\mathrm{hi}}^{-1})\in\mathbb N,\qquad
 r_{\mathrm{loc}}=r_{\mathrm{loc}}
   \bigl(T,\lambda,\Lambda,\alpha,\theta,\Delta_{\mathrm{hi}}^{-1},
                  \mathcal M_d(a)\bigr)\in(0,T],
 \end{aligned}
\end{equation*}
and $C=C\bigl(T,\lambda,\Lambda,\alpha,\theta,\Delta_{\mathrm{hi}}^{-1}\bigr)>0$
such that the following holds.

Let $0<r<r_{\mathrm{loc}}$, $I_r=(0,r)$, and
$F\in\mathfrak D(I_r,\overline w_{\alpha,K})$.  Put $u=S_{I_r}F$ and
\begin{equation*}
 G(s,\xi)=rF(rs,\sqrt{rs}\,\xi),\qquad
 q(s,\xi)=u(rs,\sqrt{rs}\,\xi).
\end{equation*}
Then $\mathcal P_rq=G$ and
\begin{equation}
 \left\lVert \mathcal J_rq\right\rVert_{\mathscr Y_{\alpha,K,r}}
 \leq\bigl(C_\alpha^{\mathrm{Br}}+C\mathcal M_d(a)r\bigr)
       \left\lVert G\right\rVert_{\mathscr X_{\alpha,K,r}}.

\end{equation}
The exact scaling identities are
\begin{equation}
 \left\lVert G\right\rVert_{\mathscr X_{\alpha,K,r}}^2
 =r^{1-\alpha}\left\lVert F\right\rVert_{\overline w_{\alpha,K};I_r}^2,
 \qquad
 \left\lVert \mathcal J_rq\right\rVert_{\mathscr Y_{\alpha,K,r}}^2
 =r^{1-\alpha}\norm{\operatorname{Hess}_gu}_{\overline w_{\alpha,K},g;I_r}^2.

\end{equation}
Consequently, Theorems~(thm:bochner-source-density of the paper)
and~(thm:causal-reweighting of the paper) give
\begin{equation}
 C_{w_{\alpha,K;\kappa},I_r}(X^a)
 \leq C_\alpha^{\mathrm{Br}}+C\mathcal M_d(a)r,
 \qquad 0<r<r_{\mathrm{loc}},\quad \kappa\geq0.

\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T02:31:45.351805+00:00","domain":"probability theory","id":"claim_fa17ea6e75b2f85f702a4a964435aba3d6159473ce25884c33d5e62a941720fd","kind":"theorem","schema_version":1,"statement":"[Corollary of arXiv:2412.06420, 'Accuracy, Estimates, and Representation Results'] If $\mathsf{acc}$ is strictly proper, then 
