{"assumptions":[],"created_at":"2026-10-27T19:38:25.225454+00:00","domain":"probability theory","id":"claim_fc57bbb5a3658d8f6ccf4d402511a0a24cd17213c53a3df27df6d0aa29cd2852","kind":"lemma","schema_version":1,"statement":"[Lemma CC of arXiv:2609.00324, 'Quantitative Stability for Fractional Yamabe minimizers'] Let $(U_k)_{k\in \mathbb{N}}$ be a bounded tight sequence in $W^{1,2}(X,y^a)$ such that $U_k$ converges weakly to $U$ in $W^{1,2}(X,y^a)$. Let $\mu$, $\nu$ be two nonnegative measures on $X$ and $M$ respectively and such that
    \begin{equation*}
        \lim_{k\to \infty} y^a |\nabla U_k|^2 = \mu \, ,
    \end{equation*}
    and
    \begin{align*}
        &\lim_{k\to \infty} |U_k (-,0)|^{2^*} = \nu .
    \end{align*}
    Then, there exists an at most countable set $J$ and three families $\{x_j\}_{j\in J} \subset M, \{\nu_j\}_{j\in J}, \{\mu_j\}_{j\in J} \in \mathbb{R}_+$ such that
    \begin{enumerate}
        \item $\nu = |U(-,0)|^{2^*} + \sum_{j\in J} \nu_j \delta_{x_j}$,
        \item $\mu \geq y^a |\nabla U|^2 + \sum_{j\in J} \mu_j \delta_{ ( x_j , 0 ) }$,
        \item $\mu_j \geq \bar{S}(n,\gamma)^{-1} \nu_j^{2/2^{*}}$ for all $j\in J$.
    \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T05:57:28.240103+00:00","domain":"probability theory","id":"claim_fc58af7a52b85f9aa33b2edb6ba2f85c4602bfe4b65cbe42fdace0c3c301dbe2","kind":"definition","schema_version":1,"statement":"[Definition 57 of arXiv:2607.18104, '2607.18104'] Suppose that we are given a family of $M-1$ ASEPs $(\eta^{(i)}_t)_{t \geq 0}$ for $i\in \lbr M-1\rbr$ on the same graph $G=(V,E)$ such that
\begin{equation}
 \eta^{(M-1)}_0 \succeq  \eta^{(M-2)}_0 \succeq \dots \succeq \eta^{(2)}_0 \succeq \eta^{(1)}_0 
\end{equation} according to the basic coupling $\mathbf{P}$. Then we define the \textbf{colored ASEP} $(\zeta_t)_{t \geq 0}$ for all $t \geq 0$ by
\begin{equation}
\zeta_t(i) := 1+\sum_{j=1}^{M-1} \big(1-\eta^{(j)}_t(i)\big)  
\end{equation}  for all $t \geq 0$ and $i \in  V$. We refer to the particles of colors $1,2,\dots,M-1$ as \textbf{first class particles}, \textbf{second class particles}, and so on, as well as to type $M$ particles as \textbf{empty sites}.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:59:25.042152+00:00","domain":"probability theory","id":"claim_fc5c5098e7053342260df4c846c49284a057c49d9f506b441cde83b94648cb63","kind":"theorem","schema_version":1,"statement":"[Corollary 21 of arXiv:2606.31596, 'The Invariant Measure of Multiscale Markov Chains via Fast Arborescence Factorization'] Let $\left(\mu_y\right)_{y\in Y}$ be an arbitrary collection of probability measures on $X$ and $\bar\mu$ an arbitrary probability measure on $Y$.
Then there exist rates $r_N$ as in \eqref{diffr} such that the limiting invariant measure is the prescribed one:
\begin{equation} 
	\lim_{N\to\infty}\pi_N(x,y) \,=\, \bar\mu(y)\; \mu_y(x)\;,\quad (x,y)\in X\times Y\,.
\end{equation}
More precisely:
\begin{itemize}

\item[i)]  reversible rates $r^y(x,x')$ with respect to the prescribed measure $\mu_y(x)$ can be chosen;\\ 
\item[ii)] 
reversible rates $r_x(y,y')$ with respect to $\nu_x(y)$ can be chosen with respect to the measure $\nu_x(y)$ defined as
\begin{equation}
\nu_x(y) := \frac{1}{Z_x}\;\mu_y(x)\; \bar\mu(y)\;,\quad y\in Y
\end{equation}
where $Z_x:=\sum_{y'\in Y} \mu_{y'}(x)\,\bar\mu(y')$; \\ 
\item[iii)] the effective rates $\bar r$ defined by \eqref{eq:weff2} are reversible with respect to the prescribed measure $\bar \mu(y)$. 

As a consequence, the effective invariant measure
\begin{equation} 
\bar\pi\left(M_y\right) \,=\, \bar\mu(y)\;,\quad y\in Y\,.
\end{equation}
\end{itemize}","status":"unverified"}

